INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('At', 1, 'pt', '[{"numero": 1, "texto": "Eu fiz o primeiro livro, ó Teófilo, sobre todas as coisas que Jesus começou, tanto a fazer como a ensinar;"}, {"numero": 2, "texto": "Até o dia em que ele foi recebido acima, depois de pelo Espírito Santo ter dado mandamentos aos apóstolos que tinha escolhido;"}, {"numero": 3, "texto": "Aos quais também, depois de ter sofrido, apresentou-se vivo com muitas evidências; sendo visto por eles durante quarenta dias, e falando [-lhes] das coisas relativas ao reino de Deus."}, {"numero": 4, "texto": "E, reunindo-os, mandou-lhes que não saíssem de Jerusalém, mas que esperassem a promessa do Pai que (disse ele) de mim ouvistes."}, {"numero": 5, "texto": "Porque João batizou com água, mas vós sereis batizados com o Espírito Santo, não muitos dias depois destes."}, {"numero": 6, "texto": "Então aqueles que tinham se reunido lhe perguntaram, dizendo: Senhor, tu restaurarás neste tempo o Reino a Israel?"}, {"numero": 7, "texto": "E ele lhes disse: Não pertence a vós saber os tempos ou estações que o Pai pôs em sua própria autoridade."}, {"numero": 8, "texto": "Mas vós recebereis poder do Espírito Santo, que virá sobre vós; e vós sereis minhas testemunhas, tanto em Jerusalém como em toda a Judeia, e Samaria, e até ao último [lugar] da terra."}, {"numero": 9, "texto": "E tendo ele dito estas coisas, enquanto eles o viam, ele foi levantado acima, e uma nuvem o tirou dos olhos deles."}, {"numero": 10, "texto": "E enquanto eles estavam com os olhos fixos ao céu, depois dele ter ido, eis que dois homens de roupas brancas se puseram junto a eles;"}, {"numero": 11, "texto": "Os quais também disseram: Homens galileus, por que estais olhando para o céu? Este Jesus, que foi tomado de vós acima ao céu, assim virá, da maneira como o vistes ir ao céu."}, {"numero": 12, "texto": "Então eles voltaram a Jerusalém do monte que se chama das Oliveiras, o qual está perto de Jerusalém [à distância] de um caminho de sábado."}, {"numero": 13, "texto": "E ao entrarem, subiram ao cômodo superior, onde ficaram Pedro, Tiago, João, André, Filipe, Tomé, Bartolomeu, Mateus, Tiago [filho] de Alfeu, Simão Zelote e Judas [irmão] de Tiago."}, {"numero": 14, "texto": "Todos estes perseveravam concordando em orações, e petições, com as mulheres, com Maria a mãe de Jesus, e com os irmãos dele."}, {"numero": 15, "texto": "E em [algum d] aqueles dias, havendo uma multidão reunida de cerca de cento e vinte pessoas, Pedro se levantou no meio dos discípulos e disse:"}, {"numero": 16, "texto": "Homens irmãos, era necessário que se cumprisse a Escritura, que o Espírito Santo, por meio da boca de Davi, predisse quanto a Judas, que foi o guia daqueles que prenderam a Jesus."}, {"numero": 17, "texto": "Porque ele foi contado conosco, e obteve uma porção neste ministério."}, {"numero": 18, "texto": "Este pois, adquiriu um campo por meio do pagamento da maldade, e tendo caído de cabeça para baixo, partiu-se ao meio, e todos os seus órgãos internos caíram para fora."}, {"numero": 19, "texto": "E [isso] foi conhecido por todos os que habitam em Jerusalém, de maneira que aquele campo se chama em sua própria língua Aceldama, isto é, campo de sangue."}, {"numero": 20, "texto": "Porque está escrito no livro dos Salmos: Sua habitação se faça deserta, e não haja quem nela habite; e outro tome seu trabalho de supervisão."}, {"numero": 21, "texto": "Portanto é necessário, que dos homens que nos acompanharam todo o tempo em que o Senhor Jesus entrava e saía conosco,"}, {"numero": 22, "texto": "Começando desde o batismo de João, até o dia em que [diante] de nós ele foi recebido acima, se faça um destes testemunha conosco de sua ressurreição."}, {"numero": 23, "texto": "E apresentaram dois: a José, chamado Barsabás, que tinha por sobrenome [o] Justo; e a Matias."}, {"numero": 24, "texto": "E orando, disseram: Tu, Senhor, conhecedor dos corações de todos, mostra a qual destes dois tu tens escolhido."}, {"numero": 25, "texto": "Para que ele tome parte deste ministério e apostolado, do qual Judas se desviou para ir a seu próprio lugar."}, {"numero": 26, "texto": "E lançaram-lhes as sortes; e caiu a sorte sobre Matias. E ele [passou] a ser contado junto com os onze apóstolos."}]'::jsonb, 'Almeida Livre'),
  ('At', 1, 'en', '[{"numero": 1, "texto": "The former treatise have I made, O Theophilus, of all that Jesus began both to do and teach,"}, {"numero": 2, "texto": "Until the day in which he was taken up, after that he through the Holy Ghost had given commandments unto the apostles whom he had chosen:"}, {"numero": 3, "texto": "To whom also he shewed himself alive after his passion by many infallible proofs, being seen of them forty days, and speaking of the things pertaining to the kingdom of God:"}, {"numero": 4, "texto": "And, being assembled together with them, commanded them that they should not depart from Jerusalem, but wait for the promise of the Father, which, saith he, ye have heard of me."}, {"numero": 5, "texto": "For John truly baptized with water; but ye shall be baptized with the Holy Ghost not many days hence."}, {"numero": 6, "texto": "When they therefore were come together, they asked of him, saying, Lord, wilt thou at this time restore again the kingdom to Israel?"}, {"numero": 7, "texto": "And he said unto them, It is not for you to know the times or the seasons, which the Father hath put in his own power."}, {"numero": 8, "texto": "But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth."}, {"numero": 9, "texto": "And when he had spoken these things, while they beheld, he was taken up; and a cloud received him out of their sight."}, {"numero": 10, "texto": "And while they looked stedfastly toward heaven as he went up, behold, two men stood by them in white apparel;"}, {"numero": 11, "texto": "Which also said, Ye men of Galilee, why stand ye gazing up into heaven? this same Jesus, which is taken up from you into heaven, shall so come in like manner as ye have seen him go into heaven."}, {"numero": 12, "texto": "Then returned they unto Jerusalem from the mount called Olivet, which is from Jerusalem a sabbath day''s journey."}, {"numero": 13, "texto": "And when they were come in, they went up into an upper room, where abode both Peter, and James, and John, and Andrew, Philip, and Thomas, Bartholomew, and Matthew, James the son of Alphaeus, and Simon Zelotes, and Judas the brother of James."}, {"numero": 14, "texto": "These all continued with one accord in prayer and supplication, with the women, and Mary the mother of Jesus, and with his brethren."}, {"numero": 15, "texto": "And in those days Peter stood up in the midst of the disciples, and said, (the number of names together were about an hundred and twenty,)"}, {"numero": 16, "texto": "Men and brethren, this scripture must needs have been fulfilled, which the Holy Ghost by the mouth of David spake before concerning Judas, which was guide to them that took Jesus."}, {"numero": 17, "texto": "For he was numbered with us, and had obtained part of this ministry."}, {"numero": 18, "texto": "Now this man purchased a field with the reward of iniquity; and falling headlong, he burst asunder in the midst, and all his bowels gushed out."}, {"numero": 19, "texto": "And it was known unto all the dwellers at Jerusalem; insomuch as that field is called in their proper tongue, Aceldama, that is to say, The field of blood."}, {"numero": 20, "texto": "For it is written in the book of Psalms, Let his habitation be desolate, and let no man dwell therein: and his bishoprick let another take."}, {"numero": 21, "texto": "Wherefore of these men which have companied with us all the time that the Lord Jesus went in and out among us,"}, {"numero": 22, "texto": "Beginning from the baptism of John, unto that same day that he was taken up from us, must one be ordained to be a witness with us of his resurrection."}, {"numero": 23, "texto": "And they appointed two, Joseph called Barsabas, who was surnamed Justus, and Matthias."}, {"numero": 24, "texto": "And they prayed, and said, Thou, Lord, which knowest the hearts of all men, shew whether of these two thou hast chosen,"}, {"numero": 25, "texto": "That he may take part of this ministry and apostleship, from which Judas by transgression fell, that he might go to his own place."}, {"numero": 26, "texto": "And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles."}]'::jsonb, 'King James Version'),
  ('At', 1, 'fr', '[{"numero": 1, "texto": "Théophile, j''''ai parlé, dans mon premier livre, de tout ce que Jésus a commencé de faire et d''''enseigner dès le commencement"}, {"numero": 2, "texto": "jusqu''''au jour où il fut enlevé au ciel, après avoir donné ses ordres, par le Saint-Esprit, aux apôtres qu''''il avait choisis."}, {"numero": 3, "texto": "Après qu''''il eut souffert, il leur apparut vivant, et leur en donna plusieurs preuves, se montrant à eux pendant quarante jours, et parlant des choses qui concernent le royaume de Dieu."}, {"numero": 4, "texto": "Comme il se trouvait avec eux, il leur recommanda de ne pas s''''éloigner de Jérusalem, mais d''''attendre ce que le Père avait promis, ce que je vous ai annoncé, leur dit-il;"}, {"numero": 5, "texto": "car Jean a baptisé d''''eau, mais vous, dans peu de jours, vous serez baptisés du Saint-Esprit."}, {"numero": 6, "texto": "Alors les apôtres réunis lui demandèrent: Seigneur, est-ce en ce temps que tu rétabliras le royaume d''''Israël?"}, {"numero": 7, "texto": "Il leur répondit: Ce n''''est pas à vous de connaître les temps ou les moments que le Père a fixés de sa propre autorité."}, {"numero": 8, "texto": "Mais vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins à Jérusalem, dans toute la Judée, dans la Samarie, et jusqu''''aux extrémités de la terre."}, {"numero": 9, "texto": "Après avoir dit cela, il fut élevé pendant qu''''ils le regardaient, et une nuée le déroba à leurs yeux."}, {"numero": 10, "texto": "Et comme ils avaient les regards fixés vers le ciel pendant qu''''il s''''en allait, voici, deux hommes vêtus de blanc leur apparurent,"}, {"numero": 11, "texto": "et dirent: Hommes Galiléens, pourquoi vous arrêtez-vous à regarder au ciel? Ce Jésus, qui a été enlevé au ciel du milieu de vous, viendra de la même manière que vous l''''avez vu allant au ciel."}, {"numero": 12, "texto": "Alors ils retournèrent à Jérusalem, de la montagne appelée des oliviers, qui est près de Jérusalem, à la distance d''''un chemin de sabbat."}, {"numero": 13, "texto": "Quand ils furent arrivés, ils montèrent dans la chambre haute où ils se tenaient d''''ordinaire; c''''étaient Pierre, Jean, Jacques, André, Philippe, Thomas, Barthélemy, Matthieu, Jacques, fils d''''Alphée, Simon le Zélote, et Jude, fils de Jacques."}, {"numero": 14, "texto": "Tous d''''un commun accord persévéraient dans la prière, avec les femmes, et Marie, mère de Jésus, et avec les frères de Jésus."}, {"numero": 15, "texto": "En ces jours-là, Pierre se leva au milieu des frères, le nombre des personnes réunies étant d''''environ cent vingt. Et il dit:"}, {"numero": 16, "texto": "Hommes frères, il fallait que s''''accomplît ce que le Saint-Esprit, dans l''''Ecriture, a annoncé d''''avance, par la bouche de David, au sujet de Judas, qui a été le guide de ceux qui ont saisi Jésus."}, {"numero": 17, "texto": "Il était compté parmi nous, et il avait part au même ministère."}, {"numero": 18, "texto": "Cet homme, ayant acquis un champ avec le salaire du crime, est tombé, s''''est rompu par le milieu du corps, et toutes ses entrailles se sont répandues."}, {"numero": 19, "texto": "La chose a été si connue de tous les habitants de Jérusalem que ce champ a été appelé dans leur langue Hakeldama, c''''est-à-dire, champ du sang."}, {"numero": 20, "texto": "Or, il est écrit dans le livre des Psaumes: Que sa demeure devienne déserte, Et que personne ne l''''habite! Et: Qu''''un autre prenne sa charge!"}, {"numero": 21, "texto": "Il faut donc que, parmi ceux qui nous ont accompagnés tout le temps que le Seigneur Jésus a vécu avec nous,"}, {"numero": 22, "texto": "depuis le baptême de Jean jusqu''''au jour où il a été enlevé du milieu de nous, il y en ait un qui nous soit associé comme témoin de sa résurrection."}, {"numero": 23, "texto": "Ils en présentèrent deux: Joseph appelé Barsabbas, surnommé Justus, et Matthias."}, {"numero": 24, "texto": "Puis ils firent cette prière: Seigneur, toi qui connais les coeurs de tous, désigne lequel de ces deux tu as choisi,"}, {"numero": 25, "texto": "afin qu''''il ait part à ce ministère et à cet apostolat, que Judas a abandonné pour aller en son lieu."}, {"numero": 26, "texto": "Ils tirèrent au sort, et le sort tomba sur Matthias, qui fut associé aux onze apôtres."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 1, 'es', '[{"numero": 1, "texto": "EN el primer tratado, oh Teófilo, he hablado de todas las cosas que Jesús comenzó á hacer y á enseñar,"}, {"numero": 2, "texto": "Hasta el día en que, habiendo dado mandamientos por el Espíritu Santo á los apóstoles que escogió, fué recibido arriba;"}, {"numero": 3, "texto": "A los cuales, después de haber padecido, se presentó vivo con muchas pruebas indubitables, apareciéndoles por cuarenta días, y hablándoles del reino de Dios."}, {"numero": 4, "texto": "Y estando juntos, les mandó que no se fuesen de Jerusalem, sino que esperasen la promesa del Padre, que oísteis, dijo, de mí."}, {"numero": 5, "texto": "Porque Juan á la verdad bautizó con agua, mas vosotros seréis bautizados con el Espíritu Santo no muchos días después de estos."}, {"numero": 6, "texto": "Entonces los que se habían juntado le preguntaron, diciendo: Señor, ¿restituirás el reino á Israel en este tiempo?"}, {"numero": 7, "texto": "Y les dijo: No toca á vosotros saber los tiempos ó las sazones que el Padre puso en su sola potestad;"}, {"numero": 8, "texto": "Mas recibiréis la virtud del Espíritu Santo que vendrá sobre vosotros; y me sereís testigos en Jerusalem, y en toda Judea, y Samaria, y hasta lo último de la tierra."}, {"numero": 9, "texto": "Y habiendo dicho estas cosas, viéndolo ellos, fué alzado; y una nube le recibió y le quitó de sus ojos."}, {"numero": 10, "texto": "Y estando con los ojos puestos en el cielo, entre tanto que él iba, he aquí dos varones se pusieron junto á ellos en vestidos blancos;"}, {"numero": 11, "texto": "Los cuales también les dijeron: Varones Galileos, ¿qué estáis mirando al cielo? este mismo Jesús que ha sido tomado desde vosotros arriba en el cielo, así vendrá como le habéis visto ir al cielo."}, {"numero": 12, "texto": "Entonces se volvieron á Jerusalem del monte que se llama del Olivar, el cual está cerca de Jerusalem camino de un sábado."}, {"numero": 13, "texto": "Y entrados, subieron al aposento alto, donde moraban Pedro y Jacobo, y Juan y Andrés, Felipe y Tomás, Bartolomé y Mateo, Jacobo hijo de Alfeo, y Simón Zelotes, y Judas hermano de Jacobo."}, {"numero": 14, "texto": "Todos éstos perseveraban unánimes en oración y ruego, con las mujeres, y con María la madre de Jesús, y con sus hermanos."}, {"numero": 15, "texto": "Y en aquellos días, Pedro, levantándose en medio de los hermanos, dijo (y era la compañía junta como de ciento y veinte en número):"}, {"numero": 16, "texto": "Varones hermanos, convino que se cumpliese la Escritura, la cual dijo antes el Espíritu Santo por la boca de David, de Judas, que fué guía de los que prendieron á Jesús;"}, {"numero": 17, "texto": "El cuál era contado con nosotros, y tenía suerte en este ministerio."}, {"numero": 18, "texto": "Este, pues, adquirió un campo del salario de su iniquidad, y colgándose, reventó por medio, y todas sus entrañas se derramaron."}, {"numero": 19, "texto": "Y fué notorio á todos los moradores de Jerusalem; de tal manera que aquel campo es llamado en su propia lengua, Acéldama, que es, Campo de sangre."}, {"numero": 20, "texto": "Porque está escrito en el libro de los salmos: Sea hecha desierta su habitación, y no haya quien more en ella; y: Tome otro su obispado."}, {"numero": 21, "texto": "Conviene, pues, que de estos hombres que han estado juntos con nosotros todo el tiempo que el Señor Jesús entró y salió entre nosotros,"}, {"numero": 22, "texto": "Comenzando desde el bautismo de Juan, hasta el día que fué recibido arriba de entre nosotros, uno sea hecho testigo con nosotros de su resurrección."}, {"numero": 23, "texto": "Y señalaron á dos: á José, llamado Barsabas, que tenía por sobrenombre Justo, y á Matías."}, {"numero": 24, "texto": "Y orando, dijeron: Tú, Señor, que conoces los corazones de todos, muestra cuál escoges de estos dos,"}, {"numero": 25, "texto": "Para que tome el oficio de este ministerio y apostolado, del cual cayó Judas por transgresión, para irse á su lugar."}, {"numero": 26, "texto": "Y les echaron suertes, y cayó la suerte sobre Matías; y fué contado con los once apóstoles."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 2, 'pt', '[{"numero": 1, "texto": "E ao se cumprir o dia de Pentecostes, estavam todos concordando no mesmo lugar."}, {"numero": 2, "texto": "E de repente houve um ruído do céu, como de um vento forte [e] violento, e encheu toda a casa onde eles estavam sentados."}, {"numero": 3, "texto": "E foram vistas por eles línguas repartidas como que de fogo, e se pôs sobre cada um deles."}, {"numero": 4, "texto": "E eles foram todos cheios do Espírito Santo, e começaram a falar em outras línguas, conforme o Espírito lhes dava a discursarem."}, {"numero": 5, "texto": "E havia judeus que estavam morando em Jerusalém, homens devotos, de toda nação abaixo do céu."}, {"numero": 6, "texto": "E acontecendo esta voz, ajuntou-se a multidão; e ela estava confusa, porque cada um os ouvia falar em sua própria língua."}, {"numero": 7, "texto": "E todos estavam admirados, e se maravilhavam, dizendo uns aos outros: Ora, estes que estão falando, não são todos eles galileus?"}, {"numero": 8, "texto": "E como nós ouvimos cada um [deles] em nossa própria língua, na qual nascemos?"}, {"numero": 9, "texto": "Partos, Medos, Elamitas, os habitantes da Mesopotâmia, da Judeia, Capadócia, Ponto, Ásia,"}, {"numero": 10, "texto": "Frígia, Panfília, Egito e regiões da Líbia perto de Cirene, e romanos estrangeiros, tanto judeus como prosélitos,"}, {"numero": 11, "texto": "Cretenses e Árabes, os ouvimos em nossas próprias línguas eles falarem das grandezas de Deus."}, {"numero": 12, "texto": "E todos estavam admirados e confusos, dizendo uns aos outros: O que isso quer dizer?"}, {"numero": 13, "texto": "E outros, ridicularizando, diziam: Eles estão cheios de vinho doce."}, {"numero": 14, "texto": "Mas Pedro, pondo-se de pé com os onze, levantou sua voz, e lhes falou: Homens judeus, e todos os que habitais em Jerusalém, seja isto conhecido, e ouvi minhas palavras:"}, {"numero": 15, "texto": "Porque estes não estão bêbados, como vós pensais, sendo [ainda] a terceira hora do dia."}, {"numero": 16, "texto": "Mas isto é o que foi dito por meio do profeta Joel:"}, {"numero": 17, "texto": "E será nos últimos dias, diz Deus, que: Eu derramarei do meu Espírito sobre toda carne, e vossos filhos e filhas profetizarão, e vossos rapazes terão visões, e vossos velhos sonharão sonhos;"}, {"numero": 18, "texto": "E também sobre meus servos e sobre minhas servas, naqueles dias eu derramarei do meu Espírito, e profetizarão."}, {"numero": 19, "texto": "E darei milagres acima no céu, e sinais abaixo na terra; sangue, fogo, e vapor de fumaça;"}, {"numero": 20, "texto": "O sol se converterá em trevas, e a lua em sangue, antes que venha o grande e notório dia do Senhor."}, {"numero": 21, "texto": "E será que todo aquele que chamar ao nome do Senhor será salvo."}, {"numero": 22, "texto": "Homens israelitas, ouvi estas palavras: Jesus o nazareno, homem aprovado por Deus entre vós, com maravilhas, milagres e sinais, que Deus fez por meio dele no meio de vós, assim como vós mesmos também sabeis;"}, {"numero": 23, "texto": "Este, sendo entregue pelo determinado conselho e conhecimento prévio de Deus, sendo tomando, pelas mãos de injustos [o] crucificastes e matastes;"}, {"numero": 24, "texto": "Ao qual Deus ressuscitou, tendo soltado as dores da morte; porque não era possível ele ser retido por ela;"}, {"numero": 25, "texto": "Porque Davi diz sobre ele: Eu sempre via ao Senhor diante de mim, porque ele está à minha direita, para que eu não seja abalado."}, {"numero": 26, "texto": "Por isso meu coração está contente, e minha língua se alegra, e até mesmo minha carne repousará em esperança."}, {"numero": 27, "texto": "Pois tu não abandonarás minha alma no Xeol, nem permitirás que o teu santo veja a degradação."}, {"numero": 28, "texto": "Tu tens me feito conhecer os caminhos da vida; tu me encherás de alegria com tua face."}, {"numero": 29, "texto": "Homens irmãos, é lícito eu vos dizer abertamente sobre o patriarca Davi, que morreu, e foi sepultado, e a sepultura dele está conosco até o dia de hoje."}, {"numero": 30, "texto": "Portanto, sendo ele profeta, e sabendo que Deus tinha lhe prometido com juramento que, da sua descendência segundo a carne, levantaria ao Cristo para se sentar no seu trono;"}, {"numero": 31, "texto": "Vendo [-o] com antecedência, falou da ressurreição do Cristo, que a sua alma não foi abandonada no Xeol, nem a sua carne viu a degradação."}, {"numero": 32, "texto": "A este Jesus Deus ressuscitou; do qual todos nós somos testemunhas."}, {"numero": 33, "texto": "Portanto, tendo sido exaltado à direita de Deus, e recebido do Pai a promessa do Espírito Santo, derramou isto que agora estais vendo e ouvindo."}, {"numero": 34, "texto": "Porque Davi não subiu aos céus; mas sim, ele diz: Disse o Senhor a meu Senhor: Senta-te à minha direita,"}, {"numero": 35, "texto": "Até que eu ponha teus inimigos por escabelo de teus pés."}, {"numero": 36, "texto": "Saiba então com certeza toda a casa de Israel, que Deus o fez Senhor e Cristo a este Jesus, que vós crucificastes."}, {"numero": 37, "texto": "E eles, ao ouvirem [estas coisas] , foram afligidos como que perfurados de coração, e disseram a Pedro, e aos outros apóstolos: Que faremos, homens irmãos?"}, {"numero": 38, "texto": "E Pedro lhes disse: Arrependei-vos, e batize-se cada um de vós no nome de Jesus Cristo, para perdão dos pecados; e vós recebereis o dom do Espírito Santo."}, {"numero": 39, "texto": "Porque a promessa é para vós, e para vossos filhos, e para todos que [ainda] estão longe, a tantos quantos Deus, nosso Senhor, chamar."}, {"numero": 40, "texto": "E com muitas outras palavras ele dava testemunho, e exortava, dizendo: Salvai-vos desta geração perversa!"}, {"numero": 41, "texto": "Então os que receberam a palavra dele de boa vontade foram batizados; e foram adicionados naquele dia quase três mil almas."}, {"numero": 42, "texto": "E eles perseveravam na doutrina dos apóstolos, na comunhão, no partir do pão, e nas orações."}, {"numero": 43, "texto": "E houve temor em toda alma; e muitos milagres e sinais foram feitos pelos apóstolos."}, {"numero": 44, "texto": "E todos os que criam estavam juntos, e tinham todas as coisas em comum."}, {"numero": 45, "texto": "E eles vendiam [suas] propriedades e bens, e as repartiam com todos, conforme a necessidade que cada um tinha."}, {"numero": 46, "texto": "E perseverando a cada dia em concordância no Templo, e partindo o pão de casa em casa, comiam juntos com alegria e sinceridade de coração."}, {"numero": 47, "texto": "Louvando a Deus, e tendo graça, [sendo do agrado] de todo o povo. E a cada dia o Senhor acrescentava à igreja aqueles que estavam sendo salvos."}]'::jsonb, 'Almeida Livre'),
  ('At', 2, 'en', '[{"numero": 1, "texto": "And when the day of Pentecost was fully come, they were all with one accord in one place."}, {"numero": 2, "texto": "And suddenly there came a sound from heaven as of a rushing mighty wind, and it filled all the house where they were sitting."}, {"numero": 3, "texto": "And there appeared unto them cloven tongues like as of fire, and it sat upon each of them."}, {"numero": 4, "texto": "And they were all filled with the Holy Ghost, and began to speak with other tongues, as the Spirit gave them utterance."}, {"numero": 5, "texto": "And there were dwelling at Jerusalem Jews, devout men, out of every nation under heaven."}, {"numero": 6, "texto": "Now when this was noised abroad, the multitude came together, and were confounded, because that every man heard them speak in his own language."}, {"numero": 7, "texto": "And they were all amazed and marvelled, saying one to another, Behold, are not all these which speak Galilaeans?"}, {"numero": 8, "texto": "And how hear we every man in our own tongue, wherein we were born?"}, {"numero": 9, "texto": "Parthians, and Medes, and Elamites, and the dwellers in Mesopotamia, and in Judaea, and Cappadocia, in Pontus, and Asia,"}, {"numero": 10, "texto": "Phrygia, and Pamphylia, in Egypt, and in the parts of Libya about Cyrene, and strangers of Rome, Jews and proselytes,"}, {"numero": 11, "texto": "Cretes and Arabians, we do hear them speak in our tongues the wonderful works of God."}, {"numero": 12, "texto": "And they were all amazed, and were in doubt, saying one to another, What meaneth this?"}, {"numero": 13, "texto": "Others mocking said, These men are full of new wine."}, {"numero": 14, "texto": "But Peter, standing up with the eleven, lifted up his voice, and said unto them, Ye men of Judaea, and all ye that dwell at Jerusalem, be this known unto you, and hearken to my words:"}, {"numero": 15, "texto": "For these are not drunken, as ye suppose, seeing it is but the third hour of the day."}, {"numero": 16, "texto": "But this is that which was spoken by the prophet Joel;"}, {"numero": 17, "texto": "And it shall come to pass in the last days, saith God, I will pour out of my Spirit upon all flesh: and your sons and your daughters shall prophesy, and your young men shall see visions, and your old men shall dream dreams:"}, {"numero": 18, "texto": "And on my servants and on my handmaidens I will pour out in those days of my Spirit; and they shall prophesy:"}, {"numero": 19, "texto": "And I will shew wonders in heaven above, and signs in the earth beneath; blood, and fire, and vapour of smoke:"}, {"numero": 20, "texto": "The sun shall be turned into darkness, and the moon into blood, before the great and notable day of the Lord come:"}, {"numero": 21, "texto": "And it shall come to pass, that whosoever shall call on the name of the Lord shall be saved."}, {"numero": 22, "texto": "Ye men of Israel, hear these words; Jesus of Nazareth, a man approved of God among you by miracles and wonders and signs, which God did by him in the midst of you, as ye yourselves also know:"}, {"numero": 23, "texto": "Him, being delivered by the determinate counsel and foreknowledge of God, ye have taken, and by wicked hands have crucified and slain:"}, {"numero": 24, "texto": "Whom God hath raised up, having loosed the pains of death: because it was not possible that he should be holden of it."}, {"numero": 25, "texto": "For David speaketh concerning him, I foresaw the Lord always before my face, for he is on my right hand, that I should not be moved:"}, {"numero": 26, "texto": "Therefore did my heart rejoice, and my tongue was glad; moreover also my flesh shall rest in hope:"}, {"numero": 27, "texto": "Because thou wilt not leave my soul in hell, neither wilt thou suffer thine Holy One to see corruption."}, {"numero": 28, "texto": "Thou hast made known to me the ways of life; thou shalt make me full of joy with thy countenance."}, {"numero": 29, "texto": "Men and brethren, let me freely speak unto you of the patriarch David, that he is both dead and buried, and his sepulchre is with us unto this day."}, {"numero": 30, "texto": "Therefore being a prophet, and knowing that God had sworn with an oath to him, that of the fruit of his loins, according to the flesh, he would raise up Christ to sit on his throne;"}, {"numero": 31, "texto": "He seeing this before spake of the resurrection of Christ, that his soul was not left in hell, neither his flesh did see corruption."}, {"numero": 32, "texto": "This Jesus hath God raised up, whereof we all are witnesses."}, {"numero": 33, "texto": "Therefore being by the right hand of God exalted, and having received of the Father the promise of the Holy Ghost, he hath shed forth this, which ye now see and hear."}, {"numero": 34, "texto": "For David is not ascended into the heavens: but he saith himself, The Lord said unto my Lord, Sit thou on my right hand,"}, {"numero": 35, "texto": "Until I make thy foes thy footstool."}, {"numero": 36, "texto": "Therefore let all the house of Israel know assuredly, that God hath made the same Jesus, whom ye have crucified, both Lord and Christ."}, {"numero": 37, "texto": "Now when they heard this, they were pricked in their heart, and said unto Peter and to the rest of the apostles, Men and brethren, what shall we do?"}, {"numero": 38, "texto": "Then Peter said unto them, Repent, and be baptized every one of you in the name of Jesus Christ for the remission of sins, and ye shall receive the gift of the Holy Ghost."}, {"numero": 39, "texto": "For the promise is unto you, and to your children, and to all that are afar off, even as many as the Lord our God shall call."}, {"numero": 40, "texto": "And with many other words did he testify and exhort, saying, Save yourselves from this untoward generation."}, {"numero": 41, "texto": "Then they that gladly received his word were baptized: and the same day there were added unto them about three thousand souls."}, {"numero": 42, "texto": "And they continued stedfastly in the apostles'' doctrine and fellowship, and in breaking of bread, and in prayers."}, {"numero": 43, "texto": "And fear came upon every soul: and many wonders and signs were done by the apostles."}, {"numero": 44, "texto": "And all that believed were together, and had all things common;"}, {"numero": 45, "texto": "And sold their possessions and goods, and parted them to all men, as every man had need."}, {"numero": 46, "texto": "And they, continuing daily with one accord in the temple, and breaking bread from house to house, did eat their meat with gladness and singleness of heart,"}, {"numero": 47, "texto": "Praising God, and having favour with all the people. And the Lord added to the church daily such as should be saved."}]'::jsonb, 'King James Version'),
  ('At', 2, 'fr', '[{"numero": 1, "texto": "Le jour de la Pentecôte, ils étaient tous ensemble dans le même lieu."}, {"numero": 2, "texto": "Tout à coup il vint du ciel un bruit comme celui d''''un vent impétueux, et il remplit toute la maison où ils étaient assis."}, {"numero": 3, "texto": "Des langues, semblables à des langues de feu, leur apparurent, séparées les unes des autres, et se posèrent sur chacun d''''eux."}, {"numero": 4, "texto": "Et ils furent tous remplis du Saint-Esprit, et se mirent à parler en d''''autres langues, selon que l''''Esprit leur donnait de s''''exprimer."}, {"numero": 5, "texto": "Or, il y avait en séjour à Jérusalem des Juifs, hommes pieux, de toutes les nations qui sont sous le ciel."}, {"numero": 6, "texto": "Au bruit qui eut lieu, la multitude accourut, et elle fut confondue parce que chacun les entendait parler dans sa propre langue."}, {"numero": 7, "texto": "Ils étaient tous dans l''''étonnement et la surprise, et ils se disaient les uns aux autres: Voici, ces gens qui parlent ne sont-ils pas tous Galiléens?"}, {"numero": 8, "texto": "Et comment les entendons-nous dans notre propre langue à chacun, dans notre langue maternelle?"}, {"numero": 9, "texto": "Parthes, Mèdes, Elamites, ceux qui habitent la Mésopotamie, la Judée, la Cappadoce, le Pont, l''''Asie,"}, {"numero": 10, "texto": "la Phrygie, la Pamphylie, l''''Egypte, le territoire de la Libye voisine de Cyrène, et ceux qui sont venus de Rome, Juifs et prosélytes,"}, {"numero": 11, "texto": "Crétois et Arabes, comment les entendons-nous parler dans nos langues des merveilles de Dieu?"}, {"numero": 12, "texto": "Ils étaient tous dans l''''étonnement, et, ne sachant que penser, ils se disaient les uns aux autres: Que veut dire ceci?"}, {"numero": 13, "texto": "Mais d''''autres se moquaient, et disaient: Ils sont pleins de vin doux."}, {"numero": 14, "texto": "Alors Pierre, se présentant avec les onze, éleva la voix, et leur parla en ces termes: Hommes Juifs, et vous tous qui séjournez à Jérusalem, sachez ceci, et prêtez l''''oreille à mes paroles!"}, {"numero": 15, "texto": "Ces gens ne sont pas ivres, comme vous le supposez, car c''''est la troisième heure du jour."}, {"numero": 16, "texto": "Mais c''''est ici ce qui a été dit par le prophète Joël:"}, {"numero": 17, "texto": "Dans les derniers jours, dit Dieu, je répandrai de mon Esprit sur toute chair; Vos fils et vos filles prophétiseront, Vos jeunes gens auront des visions, Et vos vieillards auront des songes."}, {"numero": 18, "texto": "Oui, sur mes serviteurs et sur mes servantes, Dans ces jours-là, je répandrai de mon Esprit; et ils prophétiseront."}, {"numero": 19, "texto": "Je ferai paraître des prodiges en haut dans le ciel et des miracles en bas sur la terre, Du sang, du feu, et une vapeur de fumée;"}, {"numero": 20, "texto": "Le soleil se changera en ténèbres, Et la lune en sang, Avant l''''arrivée du jour du Seigneur, De ce jour grand et glorieux."}, {"numero": 21, "texto": "Alors quiconque invoquera le nom du Seigneur sera sauvé."}, {"numero": 22, "texto": "Hommes Israélites, écoutez ces paroles! Jésus de Nazareth, cet homme à qui Dieu a rendu témoignage devant vous par les miracles, les prodiges et les signes qu''''il a opérés par lui au milieu de vous, comme vous le savez vous-mêmes;"}, {"numero": 23, "texto": "cet homme, livré selon le dessein arrêté et selon la prescience de Dieu, vous l''''avez crucifié, vous l''''avez fait mourir par la main des impies."}, {"numero": 24, "texto": "Dieu l''''a ressuscité, en le délivrant des liens de la mort, parce qu''''il n''''était pas possible qu''''il fût retenu par elle."}, {"numero": 25, "texto": "Car David dit de lui: Je voyais constamment le Seigneur devant moi, Parce qu''''il est à ma droite, afin que je ne sois point ébranlé."}, {"numero": 26, "texto": "Aussi mon coeur est dans la joie, et ma langue dans l''''allégresse; Et même ma chair reposera avec espérance,"}, {"numero": 27, "texto": "Car tu n''''abandonneras pas mon âme dans le séjour des morts, Et tu ne permettras pas que ton Saint voie la corruption."}, {"numero": 28, "texto": "Tu m''''as fait connaître les sentiers de la vie, Tu me rempliras de joie par ta présence."}, {"numero": 29, "texto": "Hommes frères, qu''''il me soit permis de vous dire librement, au sujet du patriarche David, qu''''il est mort, qu''''il a été enseveli, et que son sépulcre existe encore aujourd''''hui parmi nous."}, {"numero": 30, "texto": "Comme il était prophète, et qu''''il savait que Dieu lui avait promis avec serment de faire asseoir un de ses descendants sur son trône,"}, {"numero": 31, "texto": "c''''est la résurrection du Christ qu''''il a prévue et annoncée, en disant qu''''il ne serait pas abandonné dans le séjour des morts et que sa chair ne verrait pas la corruption."}, {"numero": 32, "texto": "C''''est ce Jésus que Dieu a ressuscité; nous en sommes tous témoins."}, {"numero": 33, "texto": "Elevé par la droite de Dieu, il a reçu du Père le Saint-Esprit qui avait été promis, et il l''''a répandu, comme vous le voyez et l''''entendez."}, {"numero": 34, "texto": "Car David n''''est point monté au ciel, mais il dit lui-même: Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite,"}, {"numero": 35, "texto": "Jusqu''''à ce que je fasse de tes ennemis ton marchepied."}, {"numero": 36, "texto": "Que toute la maison d''''Israël sache donc avec certitude que Dieu a fait Seigneur et Christ ce Jésus que vous avez crucifié."}, {"numero": 37, "texto": "Après avoir entendu ce discours, ils eurent le coeur vivement touché, et ils dirent à Pierre et aux autres apôtres: Hommes frères, que ferons-nous?"}, {"numero": 38, "texto": "Pierre leur dit: Repentez-vous, et que chacun de vous soit baptisé au nom de Jésus-Christ, pour le pardon de vos péchés; et vous recevrez le don du Saint-Esprit."}, {"numero": 39, "texto": "Car la promesse est pour vous, pour vos enfants, et pour tous ceux qui sont au loin, en aussi grand nombre que le Seigneur notre Dieu les appellera."}, {"numero": 40, "texto": "Et, par plusieurs autres paroles, il les conjurait et les exhortait, disant: Sauvez-vous de cette génération perverse."}, {"numero": 41, "texto": "Ceux qui acceptèrent sa parole furent baptisés; et, en ce jour-là, le nombre des disciples s''''augmenta d''''environ trois mille âmes."}, {"numero": 42, "texto": "Ils persévéraient dans l''''enseignement des apôtres, dans la communion fraternelle, dans la fraction du pain, et dans les prières."}, {"numero": 43, "texto": "La crainte s''''emparait de chacun, et il se faisait beaucoup de prodiges et de miracles par les apôtres."}, {"numero": 44, "texto": "Tous ceux qui croyaient étaient dans le même lieu, et ils avaient tout en commun."}, {"numero": 45, "texto": "Ils vendaient leurs propriétés et leurs biens, et ils en partageaient le produit entre tous, selon les besoins de chacun."}, {"numero": 46, "texto": "Ils étaient chaque jour tous ensemble assidus au temple, ils rompaient le pain dans les maisons, et prenaient leur nourriture avec joie et simplicité de coeur,"}, {"numero": 47, "texto": "louant Dieu, et trouvant grâce auprès de tout le peuple. Et le Seigneur ajoutait chaque jour à l''''Eglise ceux qui étaient sauvés."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 2, 'es', '[{"numero": 1, "texto": "Y COMO se cumplieron los días de Pentecostés, estaban todos unánimes juntos;"}, {"numero": 2, "texto": "Y de repente vino un estruendo del cielo como de un viento recio que corría, el cual hinchió toda la casa donde estaban sentados;"}, {"numero": 3, "texto": "Y se les aparecieron lenguas repartidas, como de fuego, que se asentó sobre cada uno de ellos."}, {"numero": 4, "texto": "Y fueron todos llenos del Espíritu Santo, y comenzaron á hablar en otras lenguas, como el Espíritu les daba que hablasen."}, {"numero": 5, "texto": "Moraban entonces en Jerusalem Judíos, varones religiosos, de todas las naciones debajo del cielo."}, {"numero": 6, "texto": "Y hecho este estruendo, juntóse la multitud; y estaban confusos, porque cada uno les oía hablar su propia lengua."}, {"numero": 7, "texto": "Y estaban atónitos y maravillados, diciendo: He aquí ¿no son Galileos todos estos que hablan?"}, {"numero": 8, "texto": "¿Cómo, pues, les oímos nosotros hablar cada uno en nuestra lengua en que somos nacidos?"}, {"numero": 9, "texto": "Partos y Medos, y Elamitas, y los que habitamos en Mesopotamia, en Judea y en Capadocia, en el Ponto y en Asia,"}, {"numero": 10, "texto": "En Phrygia y Pamphylia, en Egipto y en las partes de Africa que está de la otra parte de Cirene, y Romanos extranjeros, tanto Judíos como convertidos,"}, {"numero": 11, "texto": "Cretenses y Arabes, les oímos hablar en nuestras lenguas las maravillas de Dios."}, {"numero": 12, "texto": "Y estaban todos atónitos y perplejos, diciendo los unos á los otros: ¿Qué quiere ser esto?"}, {"numero": 13, "texto": "Mas otros burlándose, decían: Que están llenos de mosto."}, {"numero": 14, "texto": "Entonces Pedro, poniéndose en pie con los once, alzó su voz, y hablóles diciendo: Varones Judíos, y todos los que habitáis en Jerusalem, esto os sea notorio, y oid mis palabras."}, {"numero": 15, "texto": "Porque éstos no están borrachos, como vosotros pensáis, siendo la hora tercia del día;"}, {"numero": 16, "texto": "Mas esto es lo que fué dicho por el profeta Joel:"}, {"numero": 17, "texto": "Y será en los postreros días, dice Dios, derramaré de mi Espíritu sobre toda carne, y vuestros hijos y vuestras hijas profetizarán; y vuestros mancebos verán visiones, y vuestros viejos soñarán sueños:"}, {"numero": 18, "texto": "Y de cierto sobre mis siervos y sobre mis siervas en aquellos días derramaré de mi Espíritu, y profetizarán."}, {"numero": 19, "texto": "Y daré prodigios arriba en el cielo, y señales abajo en la tierra, sangre y fuego y vapor de humo:"}, {"numero": 20, "texto": "El sol se volverá en tinieblas, y la luna en sangre, antes que venga el día del Señor, grande y manifiesto;"}, {"numero": 21, "texto": "Y será que todo aquel que invocare el nombre del Señor, será salvo."}, {"numero": 22, "texto": "Varones Israelitas, oid estas palabras: Jesús Nazareno, varón aprobado de Dios entre vosotros en maravillas y prodigios y señales, que Dios hizo por él en medio de vosotros, como también vosotros sabéis;"}, {"numero": 23, "texto": "A éste, entregado por determinado consejo y providencia de Dios, prendisteis y matasteis por manos de los inicuos, crucificándole;"}, {"numero": 24, "texto": "Al cual Dios levantó, sueltos los dolores de la muerte, por cuanto era imposible ser detenido de ella."}, {"numero": 25, "texto": "Porque David dice de él: Veía al Señor siempre delante de mí: porque está á mi diestra, no seré conmovido."}, {"numero": 26, "texto": "Por lo cual mi corazón se alegró, y gozóse mi lengua; y aun mi carne descansará en esperanza;"}, {"numero": 27, "texto": "Que no dejarás mi alma en el infierno, ni darás á tu Santo que vea corrupción."}, {"numero": 28, "texto": "Hicísteme notorios los caminos de la vida; me henchirás de gozo con tu presencia."}, {"numero": 29, "texto": "Varones hermanos, se os puede libremente decir del patriarca David, que murió, y fué sepultado, y su sepulcro está con nosotros hasta del día de hoy."}, {"numero": 30, "texto": "Empero siendo profeta, y sabiendo que con juramento le había Dios jurado que del fruto de su lomo, cuanto á la carne, levantaría al Cristo que se sentaría sobre su trono;"}, {"numero": 31, "texto": "Viéndolo antes, habló de la resurrección de Cristo, que su alma no fué dejada en el infierno, ni su carne vió corrupción."}, {"numero": 32, "texto": "A este Jesús resucitó Dios, de lo cual todos nosotros somos testigos."}, {"numero": 33, "texto": "Así que, levantado por la diestra de Dios, y recibiendo del Padre la promesa del Espíritu Santo, ha derramado esto que vosotros veis y oís."}, {"numero": 34, "texto": "Porque David no subió á los cielos; empero él dice: Dijo el Señor á mi Señor: Siéntate á mi diestra,"}, {"numero": 35, "texto": "Hasta que ponga á tus enemigos por estrado de tus pies."}, {"numero": 36, "texto": "Sepa pues ciertísimamente toda la casa de Israel, que á éste Jesús que vosotros crucificasteis, Dios ha hecho Señor y Cristo."}, {"numero": 37, "texto": "Entonces oído esto, fueron compungidos de corazón, y dijeron á Pedro y á los otros apóstoles: Varones hermanos, ¿qué haremos?"}, {"numero": 38, "texto": "Y Pedro les dice: Arrepentíos, y bautícese cada uno de vosotros en el nombre de Jesucristo para perdón de los pecados; y recibiréis el don del Espíritu Santo."}, {"numero": 39, "texto": "Porque para vosotros es la promesa, y para vuestros hijos, y para todos los que están lejos; para cuantos el Señor nuestro Dios llamare."}, {"numero": 40, "texto": "Y con otras muchas palabras testificaba y exhortaba, diciendo: Sed salvos de esta perversa generación."}, {"numero": 41, "texto": "Así que, los que recibieron su palabra, fueron bautizados: y fueron añadidas á ellos aquel día como tres mil personas."}, {"numero": 42, "texto": "Y perseveraban en la doctrina de los apóstoles, y en la comunión, y en el partimiento del pan, y en las oraciones."}, {"numero": 43, "texto": "Y toda persona tenía temor: y muchas maravillas y señales eran hechas por los apóstoles."}, {"numero": 44, "texto": "Y todos los que creían estaban juntos; y tenían todas las cosas comunes;"}, {"numero": 45, "texto": "Y vendían las posesiones, y las haciendas, y repartíanlas á todos, como cada uno había menester."}, {"numero": 46, "texto": "Y perseverando unánimes cada día en el templo, y partiendo el pan en las casas, comían juntos con alegría y con sencillez de corazón,"}, {"numero": 47, "texto": "Alabando á Dios, y teniendo gracia con todo el pueblo. Y el Señor añadía cada día á la iglesia los que habían de ser salvos."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 3, 'pt', '[{"numero": 1, "texto": "E Pedro e João estavam subindo juntos para o Templo à hora da oração (a nona [hora] );"}, {"numero": 2, "texto": "E um certo homem estava sendo trazido, que era aleijado desde o ventre de sua mãe, ao qual todo dia colocavam à porta do Templo, chamada [Porta] Formosa, para pedir esmola aos que entravam no Templo."}, {"numero": 3, "texto": "O qual, ao ver Pedro e João perto de entrarem no Templo, ele [lhes] pediu uma esmola."}, {"numero": 4, "texto": "E Pedro, olhando fixamente para ele, junto com João, disse: Olha para nós."}, {"numero": 5, "texto": "E [o aleijado] ficou prestando atenção neles, esperando receber deles alguma coisa."}, {"numero": 6, "texto": "E Pedro disse: Prata e ouro eu não tenho; mas o que eu tenho, isso eu te dou: no nome de Jesus Cristo, o nazareno, levanta-te, e anda!"}, {"numero": 7, "texto": "E, tomando-o pela mão direita, levantou [-o] ; e logo os seus pés e tornozelos ficaram firmes."}, {"numero": 8, "texto": "E ele, saltando, pôs-se de pé, e andou, e entrou com eles no Templo, andando, e saltando, e louvando a Deus."}, {"numero": 9, "texto": "E todo o povo o viu andar, e louvar a Deus."}, {"numero": 10, "texto": "E eles o reconheceram, que este era o que se sentava [para pedir] esmola perto da porta formosa do Templo; e ficaram cheios de surpresa e espanto, por causa do que tinha lhe acontecido."}, {"numero": 11, "texto": "E o aleijado que tinha sido curado, tendo se apegado a Pedro e a João, todo o povo correu maravilhado a eles ao pórtico, que se chama de Salomão."}, {"numero": 12, "texto": "Quando Pedro viu [isso] , respondeu ao povo: “Homens israelitas, por que vos maravilhais disto? Ou por que vós olhais tão atentamente para nós, como se por nosso próprio poder ou devoção divina o tivéssemos feito andar?"}, {"numero": 13, "texto": "O Deus de Abraão, e de Isaque, e de Jacó, o Deus de nossos pais, glorificou a seu filho Jesus, ao qual vós entregastes, e diante do rosto de Pilatos o negastes, [mesmo] ele julgando que fosse solto."}, {"numero": 14, "texto": "Mas vós negastes ao santo e justo, e pedistes que um homem assassino fosse vos dado."}, {"numero": 15, "texto": "E vós matastes ao Príncipe da vida, ao qual Deus ressuscitou dos mortos, do que nós somos testemunhas."}, {"numero": 16, "texto": "E pela fé em seu nome, o nome dele deu firmeza a este, que vedes e conheceis; e a fé que é por meio dele deu a este perfeita saúde na presença de todos vós."}, {"numero": 17, "texto": "E agora, irmãos, eu sei que vós fizestes [isso] por ignorância, assim como também vossos líderes."}, {"numero": 18, "texto": "Mas Deus cumpriu assim o que já antes pela boca de todos os seus profetas ele tinha anunciado, que o Cristo tinha de sofrer."}, {"numero": 19, "texto": "Arrependei-vos, pois, e convertei-vos, para que vosso pecados sejam apagados, quando vierem os tempos do refrigério da presença do Senhor."}, {"numero": 20, "texto": "E ele enviar a Jesus Cristo, que já vos foi pregado anteriormente."}, {"numero": 21, "texto": "Ao qual convém que o céu receba até os tempos da restauração de todas as coisas, que Deus falou pela boca de todos os seus santos profetas, desde o princípio."}, {"numero": 22, "texto": "Porque Moisés disse aos [nossos] pais: O Senhor, vosso Deus, levantará dentre vossos irmãos um profeta como eu; a ele ouvireis em tudo o que ele vos falar."}, {"numero": 23, "texto": "E será que toda pessoa que não ouvir este profeta será exterminada do povo."}, {"numero": 24, "texto": "E também todos os profetas, desde Samuel e os posteriores, todos os que falaram, também anunciaram com antecedência destes dias."}, {"numero": 25, "texto": "Vós sois os filhos dos profetas e do pacto que Deus estabeleceu com nossos pais, dizendo a Abraão: E em tua semente serão abençoadas todas as famílias da terra."}, {"numero": 26, "texto": "Deus, ao ressuscitar seu filho Jesus, primeiro o enviou a vós, para que [nisto] vos abençoasse: afastando cada um de vós de vossas maldades”."}]'::jsonb, 'Almeida Livre'),
  ('At', 3, 'en', '[{"numero": 1, "texto": "Now Peter and John went up together into the temple at the hour of prayer, being the ninth hour."}, {"numero": 2, "texto": "And a certain man lame from his mother''s womb was carried, whom they laid daily at the gate of the temple which is called Beautiful, to ask alms of them that entered into the temple;"}, {"numero": 3, "texto": "Who seeing Peter and John about to go into the temple asked an alms."}, {"numero": 4, "texto": "And Peter, fastening his eyes upon him with John, said, Look on us."}, {"numero": 5, "texto": "And he gave heed unto them, expecting to receive something of them."}, {"numero": 6, "texto": "Then Peter said, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk."}, {"numero": 7, "texto": "And he took him by the right hand, and lifted him up: and immediately his feet and ankle bones received strength."}, {"numero": 8, "texto": "And he leaping up stood, and walked, and entered with them into the temple, walking, and leaping, and praising God."}, {"numero": 9, "texto": "And all the people saw him walking and praising God:"}, {"numero": 10, "texto": "And they knew that it was he which sat for alms at the Beautiful gate of the temple: and they were filled with wonder and amazement at that which had happened unto him."}, {"numero": 11, "texto": "And as the lame man which was healed held Peter and John, all the people ran together unto them in the porch that is called Solomon''s, greatly wondering."}, {"numero": 12, "texto": "And when Peter saw it, he answered unto the people, Ye men of Israel, why marvel ye at this? or why look ye so earnestly on us, as though by our own power or holiness we had made this man to walk?"}, {"numero": 13, "texto": "The God of Abraham, and of Isaac, and of Jacob, the God of our fathers, hath glorified his Son Jesus; whom ye delivered up, and denied him in the presence of Pilate, when he was determined to let him go."}, {"numero": 14, "texto": "But ye denied the Holy One and the Just, and desired a murderer to be granted unto you;"}, {"numero": 15, "texto": "And killed the Prince of life, whom God hath raised from the dead; whereof we are witnesses."}, {"numero": 16, "texto": "And his name through faith in his name hath made this man strong, whom ye see and know: yea, the faith which is by him hath given him this perfect soundness in the presence of you all."}, {"numero": 17, "texto": "And now, brethren, I wot that through ignorance ye did it, as did also your rulers."}, {"numero": 18, "texto": "But those things, which God before had shewed by the mouth of all his prophets, that Christ should suffer, he hath so fulfilled."}, {"numero": 19, "texto": "Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of the Lord."}, {"numero": 20, "texto": "And he shall send Jesus Christ, which before was preached unto you:"}, {"numero": 21, "texto": "Whom the heaven must receive until the times of restitution of all things, which God hath spoken by the mouth of all his holy prophets since the world began."}, {"numero": 22, "texto": "For Moses truly said unto the fathers, A prophet shall the Lord your God raise up unto you of your brethren, like unto me; him shall ye hear in all things whatsoever he shall say unto you."}, {"numero": 23, "texto": "And it shall come to pass, that every soul, which will not hear that prophet, shall be destroyed from among the people."}, {"numero": 24, "texto": "Yea, and all the prophets from Samuel and those that follow after, as many as have spoken, have likewise foretold of these days."}, {"numero": 25, "texto": "Ye are the children of the prophets, and of the covenant which God made with our fathers, saying unto Abraham, And in thy seed shall all the kindreds of the earth be blessed."}, {"numero": 26, "texto": "Unto you first God, having raised up his Son Jesus, sent him to bless you, in turning away every one of you from his iniquities."}]'::jsonb, 'King James Version'),
  ('At', 3, 'fr', '[{"numero": 1, "texto": "Pierre et Jean montaient ensemble au temple, à l''''heure de la prière: c''''était la neuvième heure."}, {"numero": 2, "texto": "Il y avait un homme boiteux de naissance, qu''''on portait et qu''''on plaçait tous les jours à la porte du temple appelée la Belle, pour qu''''il demandât l''''aumône à ceux qui entraient dans le temple."}, {"numero": 3, "texto": "Cet homme, voyant Pierre et Jean qui allaient y entrer, leur demanda l''''aumône."}, {"numero": 4, "texto": "Pierre, de même que Jean, fixa les yeux sur lui, et dit: Regarde-nous."}, {"numero": 5, "texto": "Et il les regardait attentivement, s''''attendant à recevoir d''''eux quelque chose."}, {"numero": 6, "texto": "Alors Pierre lui dit: Je n''''ai ni argent, ni or; mais ce que j''''ai, je te le donne: au nom de Jésus-Christ de Nazareth, lève-toi et marche."}, {"numero": 7, "texto": "Et le prenant par la main droite, il le fit lever. Au même instant, ses pieds et ses chevilles devinrent fermes;"}, {"numero": 8, "texto": "d''''un saut il fut debout, et il se mit à marcher. Il entra avec eux dans le temple, marchant, sautant, et louant Dieu."}, {"numero": 9, "texto": "Tout le monde le vit marchant et louant Dieu."}, {"numero": 10, "texto": "Ils reconnaissaient que c''''était celui qui était assis à la Belle porte du temple pour demander l''''aumône, et ils furent remplis d''''étonnement et de surprise au sujet de ce qui lui était arrivé."}, {"numero": 11, "texto": "Comme il ne quittait pas Pierre et Jean, tout le peuple étonné accourut vers eux, au portique dit de Salomon."}, {"numero": 12, "texto": "Pierre, voyant cela, dit au peuple: Hommes Israélites, pourquoi vous étonnez-vous de cela? Pourquoi avez-vous les regards fixés sur nous, comme si c''''était par notre propre puissance ou par notre piété que nous eussions fait marcher cet homme?"}, {"numero": 13, "texto": "Le Dieu d''''Abraham, d''''Isaac et de Jacob, le Dieu de nos pères, a glorifié son serviteur Jésus, que vous avez livré et renié devant Pilate, qui était d''''avis qu''''on le relâchât."}, {"numero": 14, "texto": "Vous avez renié le Saint et le Juste, et vous avez demandé qu''''on vous accordât la grâce d''''un meurtrier."}, {"numero": 15, "texto": "Vous avez fait mourir le Prince de la vie, que Dieu a ressuscité des morts; nous en sommes témoins."}, {"numero": 16, "texto": "C''''est par la foi en son nom que son nom a raffermi celui que vous voyez et connaissez; c''''est la foi en lui qui a donné à cet homme cette entière guérison, en présence de vous tous."}, {"numero": 17, "texto": "Et maintenant, frères, je sais que vous avez agi par ignorance, ainsi que vos chefs."}, {"numero": 18, "texto": "Mais Dieu a accompli de la sorte ce qu''''il avait annoncé d''''avance par la bouche de tous ses prophètes, que son Christ devait souffrir."}, {"numero": 19, "texto": "Repentez-vous donc et convertissez-vous, pour que vos péchés soient effacés, afin que des temps de rafraîchissement viennent de la part du Seigneur,"}, {"numero": 20, "texto": "et qu''''il envoie celui qui vous a été destiné, Jésus-Christ,"}, {"numero": 21, "texto": "que le ciel doit recevoir jusqu''''aux temps du rétablissement de toutes choses, dont Dieu a parlé anciennement par la bouche de ses saints prophètes."}, {"numero": 22, "texto": "Moïse a dit: Le Seigneur votre Dieu vous suscitera d''''entre vos frères un prophète comme moi; vous l''''écouterez dans tout ce qu''''il vous dira,"}, {"numero": 23, "texto": "et quiconque n''''écoutera pas ce prophète sera exterminé du milieu du peuple."}, {"numero": 24, "texto": "Tous les prophètes qui ont successivement parlé, depuis Samuel, ont aussi annoncé ces jours-là."}, {"numero": 25, "texto": "Vous êtes les fils des prophètes et de l''''alliance que Dieu a traitée avec nos pères, en disant à Abraham: Toutes les familles de la terre seront bénies en ta postérité."}, {"numero": 26, "texto": "C''''est à vous premièrement que Dieu, ayant suscité son serviteur, l''''a envoyé pour vous bénir, en détournant chacun de vous de ses iniquités."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 3, 'es', '[{"numero": 1, "texto": "PEDRO y Juan subían juntos al templo á la hora de oración, la de nona."}, {"numero": 2, "texto": "Y un hombre que era cojo desde el vientre de su madre, era traído; al cual ponían cada día á la puerta del templo que se llama la Hermosa, para que pidiese limosna de los que entraban en el templo."}, {"numero": 3, "texto": "Este, como vió á Pedro y á Juan que iban á entrar en el templo, rogaba que le diesen limosna."}, {"numero": 4, "texto": "Y Pedro, con Juan, fijando los ojos en él, dijo: Mira á nosotros."}, {"numero": 5, "texto": "Entonces él estuvo atento á ellos, esperando recibir de ellos algo."}, {"numero": 6, "texto": "Y Pedro dijo: Ni tengo plata ni oro; mas lo que tengo te doy: en el nombre de Jesucristo de Nazaret, levántate y anda."}, {"numero": 7, "texto": "Y tomándole por la mano derecha le levantó: y luego fueron afirmados sus pies y tobillos;"}, {"numero": 8, "texto": "Y saltando, se puso en pie, y anduvo; y entró con ellos en el templo, andando, y saltando, y alabando á Dios."}, {"numero": 9, "texto": "Y todo el pueblo le vió andar y alabar á Dios."}, {"numero": 10, "texto": "Y conocían que él era el que se sentaba á la limosna á la puerta del templo, la Hermosa: y fueron llenos de asombro y de espanto por lo que le había acontecido."}, {"numero": 11, "texto": "Y teniendo á Pedro y á Juan el cojo que había sido sanado, todo el pueblo concurrió á ellos al pórtico que se llama de Salomón, atónitos."}, {"numero": 12, "texto": "Y viendo esto Pedro, respondió al pueblo: Varones Israelitas, ¿por qué os maravilláis de esto? ó ¿por qué ponéis los ojos en nosotros, como si con nuestra virtud ó piedad hubiésemos hecho andar á éste?"}, {"numero": 13, "texto": "El Dios de Abraham, y de Isaac, y de Jacob, el Dios de nuestros padres ha glorificado á su Hijo Jesús, al cual vosotros entregasteis, y negasteis delante de Pilato, juzgando él que había de ser suelto."}, {"numero": 14, "texto": "Mas vosotros al Santo y al Justo negasteis, y pedisteis que se os diese un homicida;"}, {"numero": 15, "texto": "Y matasteis al Autor de la vida, al cual Dios ha resucitado de los muertos; de lo que nosotros somos testigos."}, {"numero": 16, "texto": "Y en la fe de su nombre, á éste que vosotros veis y conocéis, ha confirmado su nombre: y la fe que por él es, ha dado á éste esta completa sanidad en presencia de todos vosotros."}, {"numero": 17, "texto": "Mas ahora, hermanos, sé que por ignorancia lo habéis hecho, como también vuestros príncipes."}, {"numero": 18, "texto": "Empero Dios ha cumplido así lo que había antes anunciado por boca de todos sus profetas, que su Cristo había de padecer."}, {"numero": 19, "texto": "Así que, arrepentíos y convertíos, para que sean borrados vuestros pecados; pues que vendrán los tiempos del refrigerio de la presencia del Señor,"}, {"numero": 20, "texto": "Y enviará á Jesucristo, que os fué antes anunciado:"}, {"numero": 21, "texto": "Al cual de cierto es menester que el cielo tenga hasta los tiempos de la restauración de todas las cosas, que habló Dios por boca de sus santos profetas que han sido desde el siglo."}, {"numero": 22, "texto": "Porque Moisés dijo á los padres: El Señor vuestro Dios os levantará profeta de vuestros hermanos, como yo; á él oiréis en todas las cosas que os hablare."}, {"numero": 23, "texto": "Y será, que cualquiera alma que no oyere á aquel profeta, será desarraigada del pueblo."}, {"numero": 24, "texto": "Y todos los profetas desde Samuel y en adelante, todos los que han hablado, han anunciado estos días."}, {"numero": 25, "texto": "Vosotros sois los hijos de los profetas, y del pacto que Dios concertó con nuestros padres, diciendo á Abraham: Y en tu simiente serán benditas todas las familias de la tierra."}, {"numero": 26, "texto": "A vosotros primeramente, Dios, habiendo levantado á su Hijo, le envió para que os bendijese, á fin de que cada uno se convierta de su maldad."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 4, 'pt', '[{"numero": 1, "texto": "E enquanto eles ainda estavam falando ao povo, vieram sobre eles os sacerdotes, e o oficial do Templo, e os saduceus,"}, {"numero": 2, "texto": "Muito incomodados por eles ensinarem ao povo, e anunciarem no [nome] de Jesus a ressurreição dos mortos."}, {"numero": 3, "texto": "E puseram as mãos sobre eles, e os puseram na prisão até o dia seguinte, porque já era tarde."}, {"numero": 4, "texto": "E muitos dos que ouviram a palavra, creram; e era o número dos homens de cerca de cinco mil."}, {"numero": 5, "texto": "E aconteceu no dia seguinte, que os chefes, e anciãos, e escribas, se reuniram em Jerusalém;"}, {"numero": 6, "texto": "E Anás, o sumo sacerdote, e Caifás, e João, e Alexandre, e todos quantos havia da linhagem do governo sacerdotal."}, {"numero": 7, "texto": "E pondo-os no meio, perguntaram [-lhes] : Por meio de que poder ou por qual nome vós fizestes isto?"}, {"numero": 8, "texto": "Então Pedro, cheio do Espírito Santo, lhes disse: Chefes do povo, e anciões de Israel,"}, {"numero": 9, "texto": "Se hoje somos interrogados quanto a uma boa ação [feita] a um enfermo, pela qual este foi curado;"}, {"numero": 10, "texto": "Seja conhecido a todos vós, e a todos o povo de Israel, que pelo nome de Jesus Cristo, o nazareno, aquele que vós crucificastes, ao qual Deus ressuscitou dos mortos, por ele este [homem] está são diante de vós."}, {"numero": 11, "texto": "Este é a pedra que foi desprezada por vós, edificadores; a qual foi feita por cabeça de esquina."}, {"numero": 12, "texto": "E em nenhum outro há salvação; porque nenhum outro nome há abaixo do céu, dado entre os seres humanos, em quem devemos ser salvos."}, {"numero": 13, "texto": "E eles, ao verem a ousadia de Pedro, e de João; e informados que eles eram homens sem instrução e ordinários, maravilharam-se; e eles sabiam que eles tinham estado com Jesus."}, {"numero": 14, "texto": "E vendo estar com eles o homem que tinha sido curado, nada tinham a dizer contra [eles] ."}, {"numero": 15, "texto": "E mandando-os saírem do supremo conselho, discutiam entre si,"}, {"numero": 16, "texto": "Dizendo: O que faremos a estes homens? Porque um sinal notório foi feito por eles, manifesto a todos os que habitam em Jerusalém, e não podemos negar."}, {"numero": 17, "texto": "Mas para que [esta notícia] não seja ainda mais divulgada entre o povo, façamos sérias ameaças a eles, para que nunca mais falem a ninguém neste nome."}, {"numero": 18, "texto": "E chamando-os, ordenaram-lhes que nunca mais falassem nem ensinassem no nome de Jesus."}, {"numero": 19, "texto": "Mas, respondendo Pedro, e João, disseram-lhes: Julgai se é justo diante de Deus, ouvir a vós mais do que a Deus;"}, {"numero": 20, "texto": "Porque nós não podemos deixar de falar daquilo que temos visto e ouvido."}, {"numero": 21, "texto": "Mas eles, tendo os ameaçado ainda mais, nada acharam [de motivo] para os castigar, e os deixaram ir por causa do povo; porque todos glorificavam a Deus pelo que tinha acontecido."}, {"numero": 22, "texto": "Porque era de mais de quarenta anos o homem em quem este milagre de cura tinha sido feito."}, {"numero": 23, "texto": "E eles, tendo sido soltos, vieram aos seus [companheiros] , e lhes contaram tudo o que os chefes dos sacerdotes e os anciãos tinham lhes dito."}, {"numero": 24, "texto": "E eles, ao ouvirem [isto] , levantaram concordantes a voz a Deus, e disseram: Senhor, tu és o Deus que fizeste o céu, a terra, o mar, e todas as coisas que neles há;"}, {"numero": 25, "texto": "Que pela boca de teu servo Davi disseste: Por que os gentios se irritam, e os povos gastam seus pensamentos em coisas vãs?"}, {"numero": 26, "texto": "Os reis da terra se levantaram, e os príncipes se juntaram em um mesmo [propósito] contra o Senhor, e contra o seu Ungido."}, {"numero": 27, "texto": "Porque verdadeiramente contra teu Santo Filho Jesus, ao qual tu ungiste, se ajuntaram, tanto Herodes, como Pôncio Pilatos, com os gentios e os povos de Israel."}, {"numero": 28, "texto": "Para fazerem tudo o que a tua mão e o teu conselho desde antes tinha determinado para acontecer."}, {"numero": 29, "texto": "E agora, Senhor, observa as ameaças deles, e dá a teus servos, que com toda ousadia falem tua palavra;"}, {"numero": 30, "texto": "Estendendo tua mão para a cura, e que se façam sinais e milagres pelo nome de teu Santo filho Jesus."}, {"numero": 31, "texto": "E tendo orado, agitou-se o lugar em que eles estavam juntos, e foram todos cheios do Espírito Santo, e falavam a palavra de Deus com ousadia."}, {"numero": 32, "texto": "E a multidão dos que criam, era de um só oração e uma só alma; e ninguém dizia ser próprio coisa alguma de seus bens, mas todas as coisas lhes eram comuns."}, {"numero": 33, "texto": "E com grande poder os apóstolos davam testemunho da ressurreição do Senhor Jesus; e em todos eles havia grande graça."}, {"numero": 34, "texto": "Porque também nenhum necessitado havia entre eles; porque todos os que possuíam propriedades de terras, ou casas, vendendo [-as] , traziam o valor das coisas vendidas, e [o] depositavam junto aos pés dos apóstolos."}, {"numero": 35, "texto": "E a cada um se repartia segundo cada qual tinha necessidade."}, {"numero": 36, "texto": "E José, chamado pelos apóstolos pelo sobrenome de Barnabé (que traduzido é filho da consolação), levita, natural do Chipre,"}, {"numero": 37, "texto": "Tendo ele uma propriedade de terra, vendeu [-a] , e trouxe o valor, e [o] depositou junto aos pés dos apóstolos."}]'::jsonb, 'Almeida Livre'),
  ('At', 4, 'en', '[{"numero": 1, "texto": "And as they spake unto the people, the priests, and the captain of the temple, and the Sadducees, came upon them,"}, {"numero": 2, "texto": "Being grieved that they taught the people, and preached through Jesus the resurrection from the dead."}, {"numero": 3, "texto": "And they laid hands on them, and put them in hold unto the next day: for it was now eventide."}, {"numero": 4, "texto": "Howbeit many of them which heard the word believed; and the number of the men was about five thousand."}, {"numero": 5, "texto": "And it came to pass on the morrow, that their rulers, and elders, and scribes,"}, {"numero": 6, "texto": "And Annas the high priest, and Caiaphas, and John, and Alexander, and as many as were of the kindred of the high priest, were gathered together at Jerusalem."}, {"numero": 7, "texto": "And when they had set them in the midst, they asked, By what power, or by what name, have ye done this?"}, {"numero": 8, "texto": "Then Peter, filled with the Holy Ghost, said unto them, Ye rulers of the people, and elders of Israel,"}, {"numero": 9, "texto": "If we this day be examined of the good deed done to the impotent man, by what means he is made whole;"}, {"numero": 10, "texto": "Be it known unto you all, and to all the people of Israel, that by the name of Jesus Christ of Nazareth, whom ye crucified, whom God raised from the dead, even by him doth this man stand here before you whole."}, {"numero": 11, "texto": "This is the stone which was set at nought of you builders, which is become the head of the corner."}, {"numero": 12, "texto": "Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved."}, {"numero": 13, "texto": "Now when they saw the boldness of Peter and John, and perceived that they were unlearned and ignorant men, they marvelled; and they took knowledge of them, that they had been with Jesus."}, {"numero": 14, "texto": "And beholding the man which was healed standing with them, they could say nothing against it."}, {"numero": 15, "texto": "But when they had commanded them to go aside out of the council, they conferred among themselves,"}, {"numero": 16, "texto": "Saying, What shall we do to these men? for that indeed a notable miracle hath been done by them is manifest to all them that dwell in Jerusalem; and we cannot deny it."}, {"numero": 17, "texto": "But that it spread no further among the people, let us straitly threaten them, that they speak henceforth to no man in this name."}, {"numero": 18, "texto": "And they called them, and commanded them not to speak at all nor teach in the name of Jesus."}, {"numero": 19, "texto": "But Peter and John answered and said unto them, Whether it be right in the sight of God to hearken unto you more than unto God, judge ye."}, {"numero": 20, "texto": "For we cannot but speak the things which we have seen and heard."}, {"numero": 21, "texto": "So when they had further threatened them, they let them go, finding nothing how they might punish them, because of the people: for all men glorified God for that which was done."}, {"numero": 22, "texto": "For the man was above forty years old, on whom this miracle of healing was shewed."}, {"numero": 23, "texto": "And being let go, they went to their own company, and reported all that the chief priests and elders had said unto them."}, {"numero": 24, "texto": "And when they heard that, they lifted up their voice to God with one accord, and said, Lord, thou art God, which hast made heaven, and earth, and the sea, and all that in them is:"}, {"numero": 25, "texto": "Who by the mouth of thy servant David hast said, Why did the heathen rage, and the people imagine vain things?"}, {"numero": 26, "texto": "The kings of the earth stood up, and the rulers were gathered together against the Lord, and against his Christ."}, {"numero": 27, "texto": "For of a truth against thy holy child Jesus, whom thou hast anointed, both Herod, and Pontius Pilate, with the Gentiles, and the people of Israel, were gathered together,"}, {"numero": 28, "texto": "For to do whatsoever thy hand and thy counsel determined before to be done."}, {"numero": 29, "texto": "And now, Lord, behold their threatenings: and grant unto thy servants, that with all boldness they may speak thy word,"}, {"numero": 30, "texto": "By stretching forth thine hand to heal; and that signs and wonders may be done by the name of thy holy child Jesus."}, {"numero": 31, "texto": "And when they had prayed, the place was shaken where they were assembled together; and they were all filled with the Holy Ghost, and they spake the word of God with boldness."}, {"numero": 32, "texto": "And the multitude of them that believed were of one heart and of one soul: neither said any of them that ought of the things which he possessed was his own; but they had all things common."}, {"numero": 33, "texto": "And with great power gave the apostles witness of the resurrection of the Lord Jesus: and great grace was upon them all."}, {"numero": 34, "texto": "Neither was there any among them that lacked: for as many as were possessors of lands or houses sold them, and brought the prices of the things that were sold,"}, {"numero": 35, "texto": "And laid them down at the apostles'' feet: and distribution was made unto every man according as he had need."}, {"numero": 36, "texto": "And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus,"}, {"numero": 37, "texto": "Having land, sold it, and brought the money, and laid it at the apostles'' feet."}]'::jsonb, 'King James Version'),
  ('At', 4, 'fr', '[{"numero": 1, "texto": "Tandis que Pierre et Jean parlaient au peuple, survinrent les sacrificateurs, le commandant du temple, et les sadducéens,"}, {"numero": 2, "texto": "mécontents de ce qu''''ils enseignaient le peuple, et annonçaient en la personne de Jésus la résurrection des morts."}, {"numero": 3, "texto": "Ils mirent les mains sur eux, et ils les jetèrent en prison jusqu''''au lendemain; car c''''était déjà le soir."}, {"numero": 4, "texto": "Cependant, beaucoup de ceux qui avaient entendu la parole crurent, et le nombre des hommes s''''éleva à environ cinq mille."}, {"numero": 5, "texto": "Le lendemain, les chefs du peuple, les anciens et les scribes,"}, {"numero": 6, "texto": "s''''assemblèrent à Jérusalem, avec Anne, le souverain sacrificateur, Caïphe, Jean, Alexandre, et tous ceux qui étaient de la race des principaux sacrificateurs."}, {"numero": 7, "texto": "Ils firent placer au milieu d''''eux Pierre et Jean, et leur demandèrent: Par quel pouvoir, ou au nom de qui avez-vous fait cela?"}, {"numero": 8, "texto": "Alors Pierre, rempli du Saint-Esprit, leur dit: Chefs du peuple, et anciens d''''Israël,"}, {"numero": 9, "texto": "puisque nous sommes interrogés aujourd''''hui sur un bienfait accordé à un homme malade, afin que nous disions comment il a été guéri,"}, {"numero": 10, "texto": "sachez-le tous, et que tout le peuple d''''Israël le sache! C''''est par le nom de Jésus-Christ de Nazareth, que vous avez crucifié, et que Dieu a ressuscité des morts, c''''est par lui que cet homme se présente en pleine santé devant vous."}, {"numero": 11, "texto": "Jésus est La pierre rejetée par vous qui bâtissez, Et qui est devenue la principale de l''''angle."}, {"numero": 12, "texto": "Il n''''y a de salut en aucun autre; car il n''''y a sous le ciel aucun autre nom qui ait été donné parmi les hommes, par lequel nous devions être sauvés."}, {"numero": 13, "texto": "Lorsqu''''ils virent l''''assurance de Pierre et de Jean, ils furent étonnés, sachant que c''''étaient des hommes du peuple sans instruction; et ils les reconnurent pour avoir été avec Jésus."}, {"numero": 14, "texto": "Mais comme ils voyaient là près d''''eux l''''homme qui avait été guéri, ils n''''avaient rien à répliquer."}, {"numero": 15, "texto": "Ils leur ordonnèrent de sortir du sanhédrin, et ils délibérèrent entre eux,"}, {"numero": 16, "texto": "disant: Que ferons-nous à ces hommes? Car il est manifeste pour tous les habitants de Jérusalem qu''''un miracle signalé a été accompli par eux, et nous ne pouvons pas le nier."}, {"numero": 17, "texto": "Mais, afin que la chose ne se répande pas davantage parmi le peuple, défendons-leur avec menaces de parler désormais à qui que ce soit en ce nom-là."}, {"numero": 18, "texto": "Et les ayant appelés, ils leur défendirent absolument de parler et d''''enseigner au nom de Jésus."}, {"numero": 19, "texto": "Pierre et Jean leur répondirent: Jugez s''''il est juste, devant Dieu, de vous obéir plutôt qu''''à Dieu;"}, {"numero": 20, "texto": "car nous ne pouvons pas ne pas parler de ce que nous avons vu et entendu."}, {"numero": 21, "texto": "Ils leur firent de nouvelles menaces, et les relâchèrent, ne sachant comment les punir, à cause du peuple, parce que tous glorifiaient Dieu de ce qui était arrivé."}, {"numero": 22, "texto": "Car l''''homme qui avait été l''''objet de cette guérison miraculeuse était âgé de plus de quarante ans."}, {"numero": 23, "texto": "Après avoir été relâchés, ils allèrent vers les leurs, et racontèrent tout ce que les principaux sacrificateurs et les anciens leur avaient dit."}, {"numero": 24, "texto": "Lorsqu''''ils l''''eurent entendu, ils élevèrent à Dieu la voix tous ensemble, et dirent: Seigneur, toi qui as fait le ciel, la terre, la mer, et tout ce qui s''''y trouve,"}, {"numero": 25, "texto": "c''''est toi qui as dit par le Saint-Esprit, par la bouche de notre père, ton serviteur David: Pourquoi ce tumulte parmi les nations, Et ces vaines pensées parmi les peuples?"}, {"numero": 26, "texto": "Les rois de la terre se sont soulevés, Et les princes se sont ligués Contre le Seigneur et contre son Oint."}, {"numero": 27, "texto": "En effet, contre ton saint serviteur Jésus, que tu as oint, Hérode et Ponce Pilate se sont ligués dans cette ville avec les nations et avec les peuples d''''Israël,"}, {"numero": 28, "texto": "pour faire tout ce que ta main et ton conseil avaient arrêté d''''avance."}, {"numero": 29, "texto": "Et maintenant, Seigneur, vois leurs menaces, et donne à tes serviteurs d''''annoncer ta parole avec une pleine assurance,"}, {"numero": 30, "texto": "en étendant ta main, pour qu''''il se fasse des guérisons, des miracles et des prodiges, par le nom de ton saint serviteur Jésus."}, {"numero": 31, "texto": "Quand ils eurent prié, le lieu où ils étaient assemblés trembla; ils furent tous remplis du Saint-Esprit, et ils annonçaient la parole de Dieu avec assurance."}, {"numero": 32, "texto": "La multitude de ceux qui avaient cru n''''était qu''''un coeur et qu''''une âme. Nul ne disait que ses biens lui appartinssent en propre, mais tout était commun entre eux."}, {"numero": 33, "texto": "Les apôtres rendaient avec beaucoup de force témoignage de la résurrection du Seigneur Jésus. Et une grande grâce reposait sur eux tous."}, {"numero": 34, "texto": "Car il n''''y avait parmi eux aucun indigent: tous ceux qui possédaient des champs ou des maisons les vendaient, apportaient le prix de ce qu''''ils avaient vendu,"}, {"numero": 35, "texto": "et le déposaient aux pieds des apôtres; et l''''on faisait des distributions à chacun selon qu''''il en avait besoin."}, {"numero": 36, "texto": "Joseph, surnommé par les apôtres Barnabas, ce qui signifie fils d''''exhortation, Lévite, originaire de Chypre,"}, {"numero": 37, "texto": "vendit un champ qu''''il possédait, apporta l''''argent, et le déposa aux pieds des apôtres."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 4, 'es', '[{"numero": 1, "texto": "Y HABLANDO ellos al pueblo, sobrevinieron los sacerdotes, y el magistrado del templo, y los Saduceos,"}, {"numero": 2, "texto": "Resentidos de que enseñasen al pueblo, y anunciasen en Jesús la resurrección de los muertos."}, {"numero": 3, "texto": "Y les echaron mano, y los pusieron en la cárcel hasta el día siguiente; porque era ya tarde."}, {"numero": 4, "texto": "Mas muchos de los que habían oído la palabra, creyeron; y fué el número de los varones como cinco mil."}, {"numero": 5, "texto": "Y aconteció al día siguiente, que se juntaron en Jerusalem los príncipes de ellos, y los ancianos, y los escribas;"}, {"numero": 6, "texto": "Y Anás, príncipe de los sacerdotes, y Caifás, y Juan y Alejandro, y todos los que eran del linaje sacerdotal;"}, {"numero": 7, "texto": "Y haciéndolos presentar en medio, les preguntaron: ¿Con qué potestad, ó en qué nombre, habéis hecho vosotros esto?"}, {"numero": 8, "texto": "Entonces Pedro, lleno del Espíritu Santo, les dijo: Príncipes del pueblo, y ancianos de Israel:"}, {"numero": 9, "texto": "Pues que somos hoy demandados acerca del beneficio hecho á un hombre enfermo, de qué manera éste haya sido sanado,"}, {"numero": 10, "texto": "Sea notorio á todos vosotros, y á todo el pueblo de Israel, que en el nombre de Jesucristo de Nazaret, al que vosotros crucificasteis y Dios le resucitó de los muertos, por él este hombre está en vuestra presencia sano."}, {"numero": 11, "texto": "Este es la piedra reprobada de vosotros los edificadores, la cual es puesta por cabeza del ángulo."}, {"numero": 12, "texto": "Y en ningún otro hay salud; porque no hay otro nombre debajo del cielo, dado á los hombres, en que podamos ser salvos."}, {"numero": 13, "texto": "Entonces viendo la constancia de Pedro y de Juan, sabido que eran hombres sin letras é ignorantes, se maravillaban; y les conocían que habían estado con Jesús."}, {"numero": 14, "texto": "Y viendo al hombre que había sido sanado, que estaba con ellos, no podían decir nada en contra."}, {"numero": 15, "texto": "Mas les mandaron que se saliesen fuera del concilio; y conferían entre sí,"}, {"numero": 16, "texto": "Diciendo: ¿Qué hemos de hacer á estos hombres? porque de cierto, señal manifiesta ha sido hecha por ellos, notoria á todos los que moran en Jerusalem, y no lo podemos negar."}, {"numero": 17, "texto": "Todavía, porque no se divulgue más por el pueblo, amenacémoslos que no hablen de aquí adelante á hombre alguno en este nombre."}, {"numero": 18, "texto": "Y llamándolos, les intimaron que en ninguna manera hablasen ni enseñasen en el nombre de Jesús."}, {"numero": 19, "texto": "Entonces Pedro y Juan, respondiendo, les dijeron: Juzgad si es justo delante de Dios obedecer antes á vosotros que á Dios:"}, {"numero": 20, "texto": "Porque no podemos dejar de decir lo que hemos visto y oído."}, {"numero": 21, "texto": "Ellos entonces los despacharon amenazándolos, no hallando ningún modo de castigarlos, por causa del pueblo; porque todos glorificaban á Dios de lo que había sido hecho."}, {"numero": 22, "texto": "Porque el hombre en quien había sido hecho este milagro de sanidad, era de más de cuarenta años."}, {"numero": 23, "texto": "Y sueltos, vinieron á los suyos, y contaron todo lo que los príncipes de los sacerdotes y los ancianos les habían dicho."}, {"numero": 24, "texto": "Y ellos, habiéndolo oído, alzaron unánimes la voz á Dios, y dijeron: Señor, tú eres el Dios que hiciste el cielo y la tierra, la mar, y todo lo que en ellos hay;"}, {"numero": 25, "texto": "Que por boca de David, tu siervo, dijiste: ¿Por qué han bramado las gentes, y los pueblos han pensado cosas vanas?"}, {"numero": 26, "texto": "Asistieron los reyes de la tierra, y los príncipes se juntaron en uno contra el Señor, y contra su Cristo."}, {"numero": 27, "texto": "Porque verdaderamente se juntaron en esta ciudad contra tu santo Hijo Jesús, al cual ungiste, Herodes y Poncio Pilato, con los Gentiles y los pueblos de Israel,"}, {"numero": 28, "texto": "Para hacer lo que tu mano y tu consejo habían antes determinado que había de ser hecho."}, {"numero": 29, "texto": "Y ahora, Señor, mira sus amenazas, y da á tus siervos que con toda confianza hablen tu palabra;"}, {"numero": 30, "texto": "Que extiendas tu mano á que sanidades, y milagros, y prodigios sean hechos por el nombre de tu santo Hijo Jesús."}, {"numero": 31, "texto": "Y como hubieron orado, el lugar en que estaban congregados tembló; y todos fueron llenos del Espíritu Santo, y hablaron la palabra de Dios con confianza."}, {"numero": 32, "texto": "Y la multitud de los que habían creído era de un corazón y un alma: y ninguno decía ser suyo algo de lo que poseía; mas todas las cosas les eran comunes."}, {"numero": 33, "texto": "Y los apóstoles daban testimonio de la resurrección del Señor Jesús con gran esfuerzo; y gran gracia era en todos ellos."}, {"numero": 34, "texto": "Que ningún necesitado había entre ellos: porque todos los que poseían heredades ó casas, vendiéndolas, traían el precio de lo vendido,"}, {"numero": 35, "texto": "Y lo ponían á los pies de los apóstoles; y era repartido á cada uno según que había menester."}, {"numero": 36, "texto": "Entonces José, que fué llamado de los apóstoles por sobrenombre, Bernabé, (que es interpretado, Hijo de consolación) Levita, natural de Cipro,"}, {"numero": 37, "texto": "Como tuviese una heredad, la vendió, y trajo el precio, y púsolo á los pies de los apóstoles."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 5, 'pt', '[{"numero": 1, "texto": "E um certo homem, de nome Ananias, com Safira, sua mulher, vendeu uma propriedade de terra."}, {"numero": 2, "texto": "E escondeu [parte] do valor, sabendo também a mulher dele; e trazendo uma certa parte, depositou [-a] junto aos pés dos apóstolos."}, {"numero": 3, "texto": "E Pedro disse: Ananias, por que Satanás encheu teu coração, para que mentisses ao Espírito Santo, e escondesses [parte] do valor da propriedade?"}, {"numero": 4, "texto": "[Se] mantivesses [tua propriedade] , ela não seria mantida contigo? E, tendo sido vendida, [o dinheiro da venda] não estava em teu poder? Por que decidiste [isto] em teu coração? Não mentiste aos seres humanos, mas sim a Deus."}, {"numero": 5, "texto": "E Ananias, ao ouvir estas palavras, caiu e deixou de respirar. E veio um grande temor sobre todos os que ouviram isso."}, {"numero": 6, "texto": "E os rapazes, tendo se levantado, levaram-no fora, e [o] sepultaram."}, {"numero": 7, "texto": "E passando o intervalo de cerca de três horas, entrou também sua mulher, não sabendo o que tinha acontecido."}, {"numero": 8, "texto": "E Pedro disse a ela: Dize-me, vendestes por [aquele] tanto aquela propriedade?E ela disse: Sim, por [aquele] tanto."}, {"numero": 9, "texto": "E Pedro lhe disse: Por que vós fizestes acordo para tentar ao Espírito do Senhor? Eis que [estão] à porta os pés daqueles que sepultaram a teu marido, e eles também [te] levarão."}, {"numero": 10, "texto": "E imediatamente ela caiu junto aos pés deles, e deixou de respirar. E os rapazes, ao entrarem, encontraram-na morta; e levando- [a] fora, sepultaram-na junto ao marido dela."}, {"numero": 11, "texto": "E veio um grande temor em toda a igreja, e em todos que ouviram estas coisas."}, {"numero": 12, "texto": "E pelas mãos dos apóstolos foram feitos muitos sinais e milagres entre o povo. E estavam todos em concordância no pórtico de Salomão."}, {"numero": 13, "texto": "Mas dos outros, ninguém ousava se juntar a eles; porém o povo os estimava grandemente."}, {"numero": 14, "texto": "E cada vez mais os que criam no Senhor se aumentavam, multidões tanto de homens como de mulheres."}, {"numero": 15, "texto": "De maneira que traziam os enfermos às ruas, e os botavam em camas e macas, para que, vindo Pedro, pelo menos a sombra dele cobrisse a alguns deles."}, {"numero": 16, "texto": "E também das cidades vizinhas vinha uma multidão a Jerusalém, trazendo enfermos, e atormentados por espíritos imundos, os quais todos eram curados."}, {"numero": 17, "texto": "E levantando-se o sumo sacerdote, e todos os que estavam com ele (que eram do grupo sectário dos saduceus), eles se encheram de inveja."}, {"numero": 18, "texto": "E puseram suas mãos nos apóstolos, e os colocaram na prisão pública."}, {"numero": 19, "texto": "Mas um anjo do Senhor, durante a noite, abriu as portas da prisão; e levando-os para fora, disse:"}, {"numero": 20, "texto": "Ide; ficai em pé, e falai no Templo ao povo todas as palavras desta vida."}, {"numero": 21, "texto": "E eles, ouvindo [isto] , entraram de manhã cedo no templo, e ensinavam. Mas vindo o sumo sacerdote, e os que estavam com ele, chamaram ao supremo conselho, e a todos os anciãos dos filhos de Israel, e mandaram à prisão, para que os trouxessem."}, {"numero": 22, "texto": "Mas quando os oficiais vieram, não os acharam na prisão; e voltando, anunciaram,"}, {"numero": 23, "texto": "Dizendo: Nós achamos a prisão fechada, em toda segurança, e com os guardas que estavam fora junto às portas; mas quando [as] abrimos, a ninguém achamos dentro."}, {"numero": 24, "texto": "Quando o [sumo] sacerdote, o chefe da guarda do Templo, e os chefes dos sacerdotes ouviram estas palavras, eles duvidaram deles quanto o que aquilo viria a ser."}, {"numero": 25, "texto": "E vindo alguém, anunciou-lhes, dizendo: Eis que os homens que vós pusestes na prisão estão no Templo, e ensinam ao povo."}, {"numero": 26, "texto": "Então foi o chefe da guarda do Templo com os oficiais, e os trouxe, [mas] não com violência, porque temiam ao povo, para que não fossem apedrejados."}, {"numero": 27, "texto": "E quando os trouxeram, apresentaram-nos ao supremo conselho. E o sumo sacerdote perguntou a eles, dizendo:"}, {"numero": 28, "texto": "Não vos ordenamos expressamente para não ensinardes [mais] neste nome? E eis que vós enchestes a Jerusalém com vossa doutrina, e quereis trazer sobre nós o sangue deste homem!"}, {"numero": 29, "texto": "E Pedro, respondendo com os apóstolos, disseram: Maior obrigação é obedecer a Deus do que às pessoas."}, {"numero": 30, "texto": "O Deus de nossos Pais ressuscitou a Jesus, ao qual vós matastes, pendurando [-o] no madeiro."}, {"numero": 31, "texto": "A este Deus exaltou com sua [mão] direita [por] Príncipe e Salvador, para dar a Israel arrependimento e perdão de pecados."}, {"numero": 32, "texto": "E nós somos testemunhas dele quanto a estas palavras, e também o Espírito Santo, o qual Deus tem dado a aqueles que lhe obedecem."}, {"numero": 33, "texto": "E eles, ouvindo [isso] , enfureceram-se grandemente, e planejaram matá-los."}, {"numero": 34, "texto": "Mas, levantando-se no supremo conselho um certo fariseu, de nome Gamaliel, instrutor da Lei, bem honrado por todo o povo, ele mandou levarem aos apóstolos para fora por um pouco [de tempo] ."}, {"numero": 35, "texto": "E lhes disse: Homens israelitas, olhai por vós mesmos, quanto ao que haveis de fazer a estes homens;"}, {"numero": 36, "texto": "Porque antes destes dias se levantou Teudas, dizendo ser alguém; ao qual se ajuntaram cerca de quatrocentos homens; ao qual foi morto, e todos os que acreditavam [nele] foram dispersos, e reduzidos a nada."}, {"numero": 37, "texto": "Depois deste se levantou Judas, o galileu, nos dias do censo; e perverteu muito do povo atrás dele; e este também pereceu, e todos os que acreditavam nele foram dispersos."}, {"numero": 38, "texto": "E agora, eu vos digo, afastai-vos destes homens, e deixai-os; porque se este conselho ou esta obra for humana, ela se desfará."}, {"numero": 39, "texto": "Mas se é de Deus, vós não a podereis desfazer; para que não venhais a ser achados de também lutardes contra Deus."}, {"numero": 40, "texto": "E concordaram com ele. E chamando aos apóstolos, tendo [os] açoitado, mandaram [-lhes] que não [mais] falassem no nome de Jesus; e os deixaram ir."}, {"numero": 41, "texto": "Então eles saíram da presença do supremo conselho, alegres por terem sido considerados dignos de serem humilhados por causa do nome dele."}, {"numero": 42, "texto": "E todos os dias no Templo, e pelas casas, não paravam de ensinar e de anunciar a Jesus Cristo."}]'::jsonb, 'Almeida Livre'),
  ('At', 5, 'en', '[{"numero": 1, "texto": "But a certain man named Ananias, with Sapphira his wife, sold a possession,"}, {"numero": 2, "texto": "And kept back part of the price, his wife also being privy to it, and brought a certain part, and laid it at the apostles'' feet."}, {"numero": 3, "texto": "But Peter said, Ananias, why hath Satan filled thine heart to lie to the Holy Ghost, and to keep back part of the price of the land?"}, {"numero": 4, "texto": "Whiles it remained, was it not thine own? and after it was sold, was it not in thine own power? why hast thou conceived this thing in thine heart? thou hast not lied unto men, but unto God."}, {"numero": 5, "texto": "And Ananias hearing these words fell down, and gave up the ghost: and great fear came on all them that heard these things."}, {"numero": 6, "texto": "And the young men arose, wound him up, and carried him out, and buried him."}, {"numero": 7, "texto": "And it was about the space of three hours after, when his wife, not knowing what was done, came in."}, {"numero": 8, "texto": "And Peter answered unto her, Tell me whether ye sold the land for so much? And she said, Yea, for so much."}, {"numero": 9, "texto": "Then Peter said unto her, How is it that ye have agreed together to tempt the Spirit of the Lord? behold, the feet of them which have buried thy husband are at the door, and shall carry thee out."}, {"numero": 10, "texto": "Then fell she down straightway at his feet, and yielded up the ghost: and the young men came in, and found her dead, and, carrying her forth, buried her by her husband."}, {"numero": 11, "texto": "And great fear came upon all the church, and upon as many as heard these things."}, {"numero": 12, "texto": "And by the hands of the apostles were many signs and wonders wrought among the people; (and they were all with one accord in Solomon''s porch."}, {"numero": 13, "texto": "And of the rest durst no man join himself to them: but the people magnified them."}, {"numero": 14, "texto": "And believers were the more added to the Lord, multitudes both of men and women.)"}, {"numero": 15, "texto": "Insomuch that they brought forth the sick into the streets, and laid them on beds and couches, that at the least the shadow of Peter passing by might overshadow some of them."}, {"numero": 16, "texto": "There came also a multitude out of the cities round about unto Jerusalem, bringing sick folks, and them which were vexed with unclean spirits: and they were healed every one."}, {"numero": 17, "texto": "Then the high priest rose up, and all they that were with him, (which is the sect of the Sadducees,) and were filled with indignation,"}, {"numero": 18, "texto": "And laid their hands on the apostles, and put them in the common prison."}, {"numero": 19, "texto": "But the angel of the Lord by night opened the prison doors, and brought them forth, and said,"}, {"numero": 20, "texto": "Go, stand and speak in the temple to the people all the words of this life."}, {"numero": 21, "texto": "And when they heard that, they entered into the temple early in the morning, and taught. But the high priest came, and they that were with him, and called the council together, and all the senate of the children of Israel, and sent to the prison to have them brought."}, {"numero": 22, "texto": "But when the officers came, and found them not in the prison, they returned and told,"}, {"numero": 23, "texto": "Saying, The prison truly found we shut with all safety, and the keepers standing without before the doors: but when we had opened, we found no man within."}, {"numero": 24, "texto": "Now when the high priest and the captain of the temple and the chief priests heard these things, they doubted of them whereunto this would grow."}, {"numero": 25, "texto": "Then came one and told them, saying, Behold, the men whom ye put in prison are standing in the temple, and teaching the people."}, {"numero": 26, "texto": "Then went the captain with the officers, and brought them without violence: for they feared the people, lest they should have been stoned."}, {"numero": 27, "texto": "And when they had brought them, they set them before the council: and the high priest asked them,"}, {"numero": 28, "texto": "Saying, Did not we straitly command you that ye should not teach in this name? and, behold, ye have filled Jerusalem with your doctrine, and intend to bring this man''s blood upon us."}, {"numero": 29, "texto": "Then Peter and the other apostles answered and said, We ought to obey God rather than men."}, {"numero": 30, "texto": "The God of our fathers raised up Jesus, whom ye slew and hanged on a tree."}, {"numero": 31, "texto": "Him hath God exalted with his right hand to be a Prince and a Saviour, for to give repentance to Israel, and forgiveness of sins."}, {"numero": 32, "texto": "And we are his witnesses of these things; and so is also the Holy Ghost, whom God hath given to them that obey him."}, {"numero": 33, "texto": "When they heard that, they were cut to the heart, and took counsel to slay them."}, {"numero": 34, "texto": "Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;"}, {"numero": 35, "texto": "And said unto them, Ye men of Israel, take heed to yourselves what ye intend to do as touching these men."}, {"numero": 36, "texto": "For before these days rose up Theudas, boasting himself to be somebody; to whom a number of men, about four hundred, joined themselves: who was slain; and all, as many as obeyed him, were scattered, and brought to nought."}, {"numero": 37, "texto": "After this man rose up Judas of Galilee in the days of the taxing, and drew away much people after him: he also perished; and all, even as many as obeyed him, were dispersed."}, {"numero": 38, "texto": "And now I say unto you, Refrain from these men, and let them alone: for if this counsel or this work be of men, it will come to nought:"}, {"numero": 39, "texto": "But if it be of God, ye cannot overthrow it; lest haply ye be found even to fight against God."}, {"numero": 40, "texto": "And to him they agreed: and when they had called the apostles, and beaten them, they commanded that they should not speak in the name of Jesus, and let them go."}, {"numero": 41, "texto": "And they departed from the presence of the council, rejoicing that they were counted worthy to suffer shame for his name."}, {"numero": 42, "texto": "And daily in the temple, and in every house, they ceased not to teach and preach Jesus Christ."}]'::jsonb, 'King James Version'),
  ('At', 5, 'fr', '[{"numero": 1, "texto": "Mais un homme nommé Ananias, avec Saphira sa femme, vendit une propriété,"}, {"numero": 2, "texto": "et retint une partie du prix, sa femme le sachant; puis il apporta le reste, et le déposa aux pieds des apôtres."}, {"numero": 3, "texto": "Pierre lui dit: Ananias, pourquoi Satan a-t-il rempli ton coeur, au point que tu mentes au Saint-Esprit, et que tu aies retenu une partie du prix du champ?"}, {"numero": 4, "texto": "S''''il n''''eût pas été vendu, ne te restait-il pas? Et, après qu''''il a été vendu, le prix n''''était-il pas à ta disposition? Comment as-tu pu mettre en ton coeur un pareil dessein? Ce n''''est pas à des hommes que tu as menti, mais à Dieu."}, {"numero": 5, "texto": "Ananias, entendant ces paroles, tomba, et expira. Une grande crainte saisit tous les auditeurs."}, {"numero": 6, "texto": "Les jeunes gens, s''''étant levés, l''''enveloppèrent, l''''emportèrent, et l''''ensevelirent."}, {"numero": 7, "texto": "Environ trois heures plus tard, sa femme entra, sans savoir ce qui était arrivé."}, {"numero": 8, "texto": "Pierre lui adressa la parole: Dis-moi, est-ce à un tel prix que vous avez vendu le champ? Oui, répondit-elle, c''''est à ce prix-là."}, {"numero": 9, "texto": "Alors Pierre lui dit: Comment vous êtes-vous accordés pour tenter l''''Esprit du Seigneur? Voici, ceux qui ont enseveli ton mari sont à la porte, et ils t''''emporteront."}, {"numero": 10, "texto": "Au même instant, elle tomba aux pieds de l''''apôtre, et expira. Les jeunes gens, étant entrés, la trouvèrent morte; ils l''''emportèrent, et l''''ensevelirent auprès de son mari."}, {"numero": 11, "texto": "Une grande crainte s''''empara de toute l''''assemblée et de tous ceux qui apprirent ces choses."}, {"numero": 12, "texto": "Beaucoup de miracles et de prodiges se faisaient au milieu du peuple par les mains des apôtres. Ils se tenaient tous ensemble au portique de Salomon,"}, {"numero": 13, "texto": "et aucun des autres n''''osait se joindre à eux; mais le peuple les louait hautement."}, {"numero": 14, "texto": "Le nombre de ceux qui croyaient au Seigneur, hommes et femmes, s''''augmentait de plus en plus;"}, {"numero": 15, "texto": "en sorte qu''''on apportait les malades dans les rues et qu''''on les plaçait sur des lits et des couchettes, afin que, lorsque Pierre passerait, son ombre au moins couvrît quelqu''''un d''''eux."}, {"numero": 16, "texto": "La multitude accourait aussi des villes voisines à Jérusalem, amenant des malades et des gens tourmentés par des esprits impurs; et tous étaient guéris."}, {"numero": 17, "texto": "Cependant le souverain sacrificateur et tous ceux qui étaient avec lui, savoir le parti des sadducéens, se levèrent, remplis de jalousie,"}, {"numero": 18, "texto": "mirent les mains sur les apôtres, et les jetèrent dans la prison publique."}, {"numero": 19, "texto": "Mais un ange du Seigneur, ayant ouvert pendant la nuit les portes de la prison, les fit sortir, et leur dit:"}, {"numero": 20, "texto": "Allez, tenez-vous dans le temple, et annoncez au peuple toutes les paroles de cette vie."}, {"numero": 21, "texto": "Ayant entendu cela, ils entrèrent dès le matin dans le temple, et se mirent à enseigner. Le souverain sacrificateur et ceux qui étaient avec lui étant survenus, ils convoquèrent le sanhédrin et tous les anciens des fils d''''Israël, et ils envoyèrent chercher les apôtres à la prison."}, {"numero": 22, "texto": "Les huissiers, à leur arrivée, ne les trouvèrent point dans la prison. Ils s''''en retournèrent, et firent leur rapport,"}, {"numero": 23, "texto": "en disant: Nous avons trouvé la prison soigneusement fermée, et les gardes qui étaient devant les portes; mais, après avoir ouvert, nous n''''avons trouvé personne dedans."}, {"numero": 24, "texto": "Lorsqu''''ils eurent entendu ces paroles, le commandant du temple et les principaux sacrificateurs ne savaient que penser des apôtres et des suites de cette affaire."}, {"numero": 25, "texto": "Quelqu''''un vint leur dire: Voici, les hommes que vous avez mis en prison sont dans le temple, et ils enseignent le peuple."}, {"numero": 26, "texto": "Alors le commandant partit avec les huissiers, et les conduisit sans violence, car ils avaient peur d''''être lapidés par le peuple."}, {"numero": 27, "texto": "Après qu''''ils les eurent amenés en présence du sanhédrin, le souverain sacrificateur les interrogea"}, {"numero": 28, "texto": "en ces termes: Ne vous avons-nous pas défendu expressément d''''enseigner en ce nom-là? Et voici, vous avez rempli Jérusalem de votre enseignement, et vous voulez faire retomber sur nous le sang de cet homme!"}, {"numero": 29, "texto": "Pierre et les apôtres répondirent: Il faut obéir à Dieu plutôt qu''''aux hommes."}, {"numero": 30, "texto": "Le Dieu de nos pères a ressuscité Jésus, que vous avez tué, en le pendant au bois."}, {"numero": 31, "texto": "Dieu l''''a élevé par sa droite comme Prince et Sauveur, pour donner à Israël la repentance et le pardon des péchés."}, {"numero": 32, "texto": "Nous sommes témoins de ces choses, de même que le Saint-Esprit, que Dieu a donné à ceux qui lui obéissent."}, {"numero": 33, "texto": "Furieux de ces paroles, ils voulaient les faire mourir."}, {"numero": 34, "texto": "Mais un pharisien, nommé Gamaliel, docteur de la loi, estimé de tout le peuple, se leva dans le sanhédrin, et ordonna de faire sortir un instant les apôtres."}, {"numero": 35, "texto": "Puis il leur dit: Hommes Israélites, prenez garde à ce que vous allez faire à l''''égard de ces gens."}, {"numero": 36, "texto": "Car, il n''''y a pas longtemps que parut Theudas, qui se donnait pour quelque chose, et auquel se rallièrent environ quatre cents hommes: il fut tué, et tous ceux qui l''''avaient suivi furent mis en déroute et réduits à rien."}, {"numero": 37, "texto": "Après lui, parut Judas le Galiléen, à l''''époque du recensement, et il attira du monde à son parti: il périt aussi, et tous ceux qui l''''avaient suivi furent dispersés."}, {"numero": 38, "texto": "Et maintenant, je vous le dis ne vous occupez plus de ces hommes, et laissez-les aller. Si cette entreprise ou cette oeuvre vient des hommes, elle se détruira;"}, {"numero": 39, "texto": "mais si elle vient de Dieu, vous ne pourrez la détruire. Ne courez pas le risque d''''avoir combattu contre Dieu."}, {"numero": 40, "texto": "Ils se rangèrent à son avis. Et ayant appelé les apôtres, ils les firent battre de verges, ils leur défendirent de parler au nom de Jésus, et ils les relâchèrent."}, {"numero": 41, "texto": "Les apôtres se retirèrent de devant le sanhédrin, joyeux d''''avoir été jugés dignes de subir des outrages pour le nom de Jésus."}, {"numero": 42, "texto": "Et chaque jour, dans le temple et dans les maisons, ils ne cessaient d''''enseigner, et d''''annoncer la bonne nouvelle de Jésus-Christ."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 5, 'es', '[{"numero": 1, "texto": "MAS un varón llamado Ananías, con Safira su mujer, vendió una posesión,"}, {"numero": 2, "texto": "Y defraudó del precio, sabiéndolo también su mujer; y trayendo una parte, púsola á los pies de los apóstoles."}, {"numero": 3, "texto": "Y dijo Pedro: Ananías, ¿por qué ha llenado Satanás tu corazón á que mintieses al Espíritu Santo, y defraudases del precio de la heredad?"}, {"numero": 4, "texto": "Reteniéndola, ¿no se te quedaba á ti? y vendida, ¿no estaba en tu potestad? ¿Por qué pusiste esto en tu corazón? No has mentido á los hombres, sino á Dios."}, {"numero": 5, "texto": "Entonces Ananías, oyendo estas palabras, cayó y espiró. Y vino un gran temor sobre todos los que lo oyeron."}, {"numero": 6, "texto": "Y levantándose los mancebos, le tomaron, y sacándolo, sepultáronlo."}, {"numero": 7, "texto": "Y pasado espacio como de tres horas, sucedió que entró su mujer, no sabiendo lo que había acontecido."}, {"numero": 8, "texto": "Entonces Pedro le dijo: Dime: ¿vendisteis en tanto la heredad? Y ella dijo: Sí, en tanto."}, {"numero": 9, "texto": "Y Pedro le dijo: ¿Por qué os concertasteis para tentar al Espíritu del Señor? He aquí á la puerta los pies de los que han sepultado á tu marido, y te sacarán."}, {"numero": 10, "texto": "Y luego cayó á los pies de él, y espiró: y entrados los mancebos, la hallaron muerta; y la sacaron, y la sepultaron junto á su marido."}, {"numero": 11, "texto": "Y vino un gran temor en toda la iglesia, y en todos los que oyeron estas cosas."}, {"numero": 12, "texto": "Y por las manos de los apóstoles eran hechos muchos milagros y prodigios en el pueblo; y estaban todos unánimes en el pórtico de Salomón."}, {"numero": 13, "texto": "Y de los otros, ninguno osaba juntarse con ellos; mas el pueblo los alababa grandemente."}, {"numero": 14, "texto": "Y los que creían en el Señor se aumentaban más, gran número así de hombres como de mujeres;"}, {"numero": 15, "texto": "Tanto que echaban los enfermos por las calles, y los ponían en camas y en lechos, para que viniendo Pedro, á lo menos su sombra tocase á alguno de ellos."}, {"numero": 16, "texto": "Y aun de las ciudades vecinas concurría multitud á Jerusalem, trayendo enfermos y atormentados de espíritus inmundos; los cuales todos eran curados."}, {"numero": 17, "texto": "Entonces levantándose el príncipe de los sacerdotes, y todos los que estaban con él, que es la secta de los Saduceos, se llenaron de celo;"}, {"numero": 18, "texto": "Y echaron mano á los apóstoles, y pusiéronlos en la cárcel pública."}, {"numero": 19, "texto": "Mas el ángel del Señor, abriendo de noche las puertas de la cárcel, y sacándolos, dijo:"}, {"numero": 20, "texto": "Id, y estando en el templo, hablad al pueblo todas las palabras de esta vida."}, {"numero": 21, "texto": "Y oído que hubieron esto, entraron de mañana en el templo, y enseñaban. Entre tanto, viniendo el príncipe de los sacerdotes, y los que eran con él, convocaron el concilio, y á todos los ancianos de los hijos de Israel, y enviaron á la cárcel para que fuesen traídos."}, {"numero": 22, "texto": "Mas como llegaron los ministros, y no los hallaron en la cárcel, volvieron, y dieron aviso,"}, {"numero": 23, "texto": "Diciendo: Por cierto, la cárcel hemos hallado cerrada con toda seguridad, y los guardas que estaban delante de las puertas; mas cuando abrimos, á nadie hallamos dentro."}, {"numero": 24, "texto": "Y cuando oyeron estas palabras el pontífice y el magistrado del templo y los príncipes de los sacerdotes, dudaban en qué vendría á parar aquello."}, {"numero": 25, "texto": "Pero viniendo uno, dióles esta noticia: He aquí, los varones que echasteis en la cárcel, están en el templo, y enseñan al pueblo."}, {"numero": 26, "texto": "Entonces fué el magistrado con los ministros, y trájolos sin violencia; porque temían del pueblo ser apedreados."}, {"numero": 27, "texto": "Y como los trajeron, los presentaron en el concilio: y el príncipe de los sacerdotes les preguntó,"}, {"numero": 28, "texto": "Diciendo: ¿No os denunciamos estrechamente, que no enseñaseis en este nombre? y he aquí, habéis llenado á Jerusalem de vuestra doctrina, y queréis echar sobre nosotros la sangre de este hombre."}, {"numero": 29, "texto": "Y respondiendo Pedro y los apóstoles, dijeron: Es menester obedecer á Dios antes que á los hombres."}, {"numero": 30, "texto": "El Dios de nuestros padres levantó á Jesús, al cual vosotros matasteis colgándole en un madero."}, {"numero": 31, "texto": "A éste ha Dios ensalzado con su diestra por Príncipe y Salvador, para dar á Israel arrepentimiento y remisión de pecados."}, {"numero": 32, "texto": "Y nosotros somos testigos suyos de estas cosas, y también el Espíritu Santo, el cual ha dado Dios á los que le obedecen."}, {"numero": 33, "texto": "Ellos, oyendo esto, regañaban, y consultaban matarlos."}, {"numero": 34, "texto": "Entonces levantándose en el concilio un Fariseo llamado Gamaliel, doctor de la ley, venerable á todo el pueblo, mandó que sacasen fuera un poco á los apóstoles."}, {"numero": 35, "texto": "Y les dijo: Varones Israelitas, mirad por vosotros acerca de estos hombres en lo que habéis de hacer."}, {"numero": 36, "texto": "Porque antes de estos días se levantó Teudas, diciendo que era alguien; al que se agregó un número de hombres como cuatrocientos: el cual fué matado; y todos los que le creyeron fueron dispersos, y reducidos á nada."}, {"numero": 37, "texto": "Después de éste, se levantó Judas el Galileo en los días del empadronamiento, y llevó mucho pueblo tras sí. Pereció también aquél; y todos los que consintieron con él, fueron derramados."}, {"numero": 38, "texto": "Y ahora os digo: Dejaos de estos hombres, y dejadlos; porque si este consejo ó esta obra es de los hombres, se desvanecerá:"}, {"numero": 39, "texto": "Mas si es de Dios, no la podréis deshacer; no seáis tal vez hallados resistiendo á Dios."}, {"numero": 40, "texto": "Y convinieron con él: y llamando á los apóstoles, después de azotados, les intimaron que no hablasen en el nombre de Jesús, y soltáronlos."}, {"numero": 41, "texto": "Y ellos partieron de delante del concilio, gozosos de que fuesen tenidos por dignos de padecer afrenta por el Nombre."}, {"numero": 42, "texto": "Y todos los días, en el templo y por las casas, no cesaban de enseñar y predicar á Jesucristo."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 6, 'pt', '[{"numero": 1, "texto": "Naqueles dias, ao se multiplicar [o número] de discípulos, houve uma murmuração dos gregos contra os hebreus, de que suas viúvas estavam sendo desprezadas no serviço diário [de entrega de comida] ."}, {"numero": 2, "texto": "E os doze, chamando à multidão dos discípulos, disseram: Não é bom que nós deixemos a palavra de Deus para servirmos às mesas."}, {"numero": 3, "texto": "Portanto, irmãos, buscai sete homens dentre vós, de quem haja [bom] testemunho, cheios do Espírito Santo e de sabedoria, aos quais constituamos sobre esta importante tarefa."}, {"numero": 4, "texto": "Nós, porém, perseveraremos na oração e no serviço da palavra."}, {"numero": 5, "texto": "E esta palavra foi do agrado diante de toda a multidão, e escolheram a Estêvão, homem cheio de fé e do Espírito Santo, e Filipe, Prócoro, Nicanor, Timom, Parmenas e a Nicolão, o prosélito de Antioquia."}, {"numero": 6, "texto": "Aos quais se apresentaram diante dos apóstolos; e eles, orando, puseram as mãos sobre eles."}, {"numero": 7, "texto": "E a palavra de Deus crescia, e o número dos discípulos se multiplicava muito em Jerusalém; e grande multidão dos sacerdotes obedecia à fé."}, {"numero": 8, "texto": "E Estêvão, cheio de fé e poder, fazia milagres e grandes sinais entre o povo."}, {"numero": 9, "texto": "E levantaram-se alguns da sinagoga, [que era] chamada [sinagoga] dos libertos, cireneus, e alexandrinos, e dos [que eram] da Cilícia, e da Ásia, e discutiam contra Estêvão."}, {"numero": 10, "texto": "E eles não podiam resistir à sabedoria e ao Espírito com que ele falava."}, {"numero": 11, "texto": "Então eles subornaram a uns homens, [para que] dissessem: Nós o ouvimos falando palavras blasfemas contra Moisés e [contra] Deus."}, {"numero": 12, "texto": "E incitaram ao povo, aos anciãos e aos escribas; e vieram sobre [Estêvão] , e o detiveram, e o levaram ao supremo conselho."}, {"numero": 13, "texto": "E apresentaram falsas testemunhas, que diziam: Este homem não para de falar palavras blasfemas contra este santo lugar, e [contra] a Lei."}, {"numero": 14, "texto": "Porque nós o ouvimos dizer que este Jesus Nazareno vai destruir este lugar, e mudar os costumes que Moisés nos entregou."}, {"numero": 15, "texto": "Então todos os que estavam sentados no supremo conselho, observando-o com atenção, viram o rosto dele como de um anjo."}]'::jsonb, 'Almeida Livre'),
  ('At', 6, 'en', '[{"numero": 1, "texto": "And in those days, when the number of the disciples was multiplied, there arose a murmuring of the Grecians against the Hebrews, because their widows were neglected in the daily ministration."}, {"numero": 2, "texto": "Then the twelve called the multitude of the disciples unto them, and said, It is not reason that we should leave the word of God, and serve tables."}, {"numero": 3, "texto": "Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business."}, {"numero": 4, "texto": "But we will give ourselves continually to prayer, and to the ministry of the word."}, {"numero": 5, "texto": "And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:"}, {"numero": 6, "texto": "Whom they set before the apostles: and when they had prayed, they laid their hands on them."}, {"numero": 7, "texto": "And the word of God increased; and the number of the disciples multiplied in Jerusalem greatly; and a great company of the priests were obedient to the faith."}, {"numero": 8, "texto": "And Stephen, full of faith and power, did great wonders and miracles among the people."}, {"numero": 9, "texto": "Then there arose certain of the synagogue, which is called the synagogue of the Libertines, and Cyrenians, and Alexandrians, and of them of Cilicia and of Asia, disputing with Stephen."}, {"numero": 10, "texto": "And they were not able to resist the wisdom and the spirit by which he spake."}, {"numero": 11, "texto": "Then they suborned men, which said, We have heard him speak blasphemous words against Moses, and against God."}, {"numero": 12, "texto": "And they stirred up the people, and the elders, and the scribes, and came upon him, and caught him, and brought him to the council,"}, {"numero": 13, "texto": "And set up false witnesses, which said, This man ceaseth not to speak blasphemous words against this holy place, and the law:"}, {"numero": 14, "texto": "For we have heard him say, that this Jesus of Nazareth shall destroy this place, and shall change the customs which Moses delivered us."}, {"numero": 15, "texto": "And all that sat in the council, looking stedfastly on him, saw his face as it had been the face of an angel."}]'::jsonb, 'King James Version'),
  ('At', 6, 'fr', '[{"numero": 1, "texto": "En ce temps-là, le nombre des disciples augmentant, les Hellénistes murmurèrent contre les Hébreux, parce que leurs veuves étaient négligées dans la distribution qui se faisait chaque jour."}, {"numero": 2, "texto": "Les douze convoquèrent la multitude des disciples, et dirent: Il n''''est pas convenable que nous laissions la parole de Dieu pour servir aux tables."}, {"numero": 3, "texto": "C''''est pourquoi, frères, choisissez parmi vous sept hommes, de qui l''''on rende un bon témoignage, qui soient pleins d''''Esprit-Saint et de sagesse, et que nous chargerons de cet emploi."}, {"numero": 4, "texto": "Et nous, nous continuerons à nous appliquer à la prière et au ministère de la parole."}, {"numero": 5, "texto": "Cette proposition plut à toute l''''assemblée. Ils élurent Etienne, homme plein de foi et d''''Esprit-Saint, Philippe, Prochore, Nicanor, Timon, Parménas, et Nicolas, prosélyte d''''Antioche."}, {"numero": 6, "texto": "Ils les présentèrent aux apôtres, qui, après avoir prié, leur imposèrent les mains."}, {"numero": 7, "texto": "La parole de Dieu se répandait de plus en plus, le nombre des disciples augmentait beaucoup à Jérusalem, et une grande foule de sacrificateurs obéissaient à la foi."}, {"numero": 8, "texto": "Etienne, plein de grâce et de puissance, faisait des prodiges et de grands miracles parmi le peuple."}, {"numero": 9, "texto": "Quelques membres de la synagogue dite des Affranchis, de celle des Cyrénéens et de celle des Alexandrins, avec des Juifs de Cilicie et d''''Asie, se mirent à discuter avec lui;"}, {"numero": 10, "texto": "mais ils ne pouvaient résister à sa sagesse et à l''''Esprit par lequel il parlait."}, {"numero": 11, "texto": "Alors ils subornèrent des hommes qui dirent: Nous l''''avons entendu proférer des paroles blasphématoires contre Moïse et contre Dieu."}, {"numero": 12, "texto": "Ils émurent le peuple, les anciens et les scribes, et, se jetant sur lui, ils le saisirent, et l''''emmenèrent au sanhédrin."}, {"numero": 13, "texto": "Ils produisirent de faux témoins, qui dirent: Cet homme ne cesse de proférer des paroles contre le lieu saint et contre la loi;"}, {"numero": 14, "texto": "car nous l''''avons entendu dire que Jésus, ce Nazaréen, détruira ce lieu, et changera les coutumes que Moïse nous a données."}, {"numero": 15, "texto": "Tous ceux qui siégeaient au sanhédrin ayant fixé les regards sur Etienne, son visage leur parut comme celui d''''un ange."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 6, 'es', '[{"numero": 1, "texto": "EN aquellos días, creciendo el número de los discípulos, hubo murmuración de los Griegos contra los Hebreos, de que sus viudas eran menospreciadas en el ministerio cotidiano."}, {"numero": 2, "texto": "Así que, los doce convocaron la multitud de los discípulos, y dijeron: No es justo que nosotros dejemos la palabra de Dios, y sirvamos á las mesas."}, {"numero": 3, "texto": "Buscad pues, hermanos, siete varones de vosotros de buen testimonio, llenos de Espíritu Santo y de sabiduría, los cuales pongamos en esta obra."}, {"numero": 4, "texto": "Y nosotros persistiremos en la oración, y en el ministerio de la palabra."}, {"numero": 5, "texto": "Y plugo el parecer á toda la multitud; y eligieron á Esteban, varón lleno de fe y de Espíritu Santo, y á Felipe, y á Prócoro, y á Nicanor, y á Timón, y á Parmenas, y á Nicolás, prosélito de Antioquía:"}, {"numero": 6, "texto": "A estos presentaron delante de los apóstoles, los cuales orando les pusieron las manos encima."}, {"numero": 7, "texto": "Y crecía la palabra del Señor, y el número de los discípulos se multiplicaba mucho en Jerusalem: también una gran multitud de los sacerdotes obedecía á la fe."}, {"numero": 8, "texto": "Empero Esteban, lleno de gracia y de potencia, hacía prodigios y milagros grandes en el pueblo."}, {"numero": 9, "texto": "Levantáronse entonces unos de la sinagoga que se llama de los Libertinos, y Cireneos, y Alejandrinos, y de los de Cilicia, y de Asia, disputando con Esteban."}, {"numero": 10, "texto": "Mas no podían resistir á la sabiduría y al Espíritu con que hablaba."}, {"numero": 11, "texto": "Entonces sobornaron á unos que dijesen que le habían oído hablar palabras blasfemas contra Moisés y Dios."}, {"numero": 12, "texto": "Y conmovieron al pueblo, y á los ancianos, y á los escribas; y arremetiendo le arrebataron, y le trajeron al concilio."}, {"numero": 13, "texto": "Y pusieron testigos falsos, que dijesen: Este hombre no cesa de hablar palabras blasfemas contra este lugar santo y la ley:"}, {"numero": 14, "texto": "Porque le hemos oído decir, que este Jesús de Nazaret destruirá este lugar, y mudará las ordenanzas que nos dió Moisés."}, {"numero": 15, "texto": "Entonces todos los que estaban sentados en el concilio, puestos los ojos en él, vieron su rostro como el rostro de un ángel."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 7, 'pt', '[{"numero": 1, "texto": "E disse o chefe dos sacerdotes: Por acaso é isto assim?"}, {"numero": 2, "texto": "E ele disse: Homens irmãos e pais, ouvi: o Deus da glória apareceu a nosso pai Abraão, estando ele na Mesopotâmia, antes de habitar em Harã;"}, {"numero": 3, "texto": "E disse-lhe: Sai de tua terra, e de tua parentela, e vem a terra que eu te mostrarei."}, {"numero": 4, "texto": "Então ele saiu da terra dos caldeus, [e] habitou em Harã. E dali, depois que morreu seu pai, ele partiu para esta terra, em que agora vós habitais."}, {"numero": 5, "texto": "E [Deus] não lhe deu herança nela, nem mesmo a pegada de um pé; mas prometeu que a daria a ele em propriedade, e a sua semente depois dele, não tendo ele filho [ainda] ."}, {"numero": 6, "texto": "E Deus falou assim: Tua semente será peregrina em terra alheia, e a escravizarão, e a maltratarão [por] quatrocentos anos."}, {"numero": 7, "texto": "E à nação a quem eles servirem, eu a julgarei, (disse Deus). E depois disso eles sairão, e me servirão neste lugar."}, {"numero": 8, "texto": "E ele lhe deu o pacto da circuncisão; e assim gerou a Isaque, e o circuncidou ao oitavo dia; e Isaque [gerou] a Jacó, e Jacó aos doze patriarcas."}, {"numero": 9, "texto": "E os patriarcas, tendo inveja [de] José, venderam [-no] ao Egito; mas Deus era com ele."}, {"numero": 10, "texto": "E o livrou de todas as suas aflições, e lhe deu graça e sabedoria diante de Faraó, rei do Egito; e o pôs [por] governador sobre o Egito, e toda a sua casa."}, {"numero": 11, "texto": "E veio fome sobre toda a terra do Egito e de Canaã, e grande aflição; e nossos pais não achavam alimentos."}, {"numero": 12, "texto": "Mas Jacó, ao ouvir que havia cereal no Egito, ele enviou nossos pais a primeira vez."}, {"numero": 13, "texto": "E na segunda [vez] ,José foi reconhecido pelos seus irmãos, e a família de José foi conhecia por Faraó."}, {"numero": 14, "texto": "E José mandou chamar a seu pai Jacó, e toda a sua parentela, setenta e cinco almas."}, {"numero": 15, "texto": "E Jacó desceu ao Egito, e morreu; ele, e nossos pais;"}, {"numero": 16, "texto": "E foram levados a Siquém, e postos na sepultura que Abraão, por uma quantia em dinheiro, tinha comprado dos filhos de Emor, [pai] de Siquém."}, {"numero": 17, "texto": "Mas quando chegou perto o tempo da promessa que Deus tinha prometido a Abraão, o povo cresceu e se multiplicou no Egito."}, {"numero": 18, "texto": "Até que se levantou outro rei, que não tinha conhecido a José."}, {"numero": 19, "texto": "Este, usando de astúcia para com nossa parentela, maltratou a nossos pais, até fazendo com que eles rejeitassem suas crianças, para que não sobrevivessem."}, {"numero": 20, "texto": "Naquele tempo nasceu Moisés, e ele era muito formoso para Deus, e ele foi criado por três meses na casa de seu pai."}, {"numero": 21, "texto": "E tendo sido abandonado, a filha de Faraó o tomou, e o criou para si como filho."}, {"numero": 22, "texto": "E Moisés foi instruído em toda a sabedoria dos egípcios; e era poderoso em palavras e ações."}, {"numero": 23, "texto": "E quando lhe foi completado o tempo de quarenta anos [de idade] , veio ao seu coração [o desejo] de visitar a seus irmãos, os filhos de Israel."}, {"numero": 24, "texto": "E vendo um [deles] sofrendo injustamente, defendeu [-o] , e vingou pelo que tinha sido oprimido, matando ao egípcio."}, {"numero": 25, "texto": "E ele pensava que seus irmãos tivessem entendido que Deus ia lhes dar liberdade por meio da mão dele; mas eles não entenderam."}, {"numero": 26, "texto": "E no dia seguinte, estando [uns deles] lutando, ele foi visto por eles, e ordenou-lhes [fazerem] as pazes, dizendo: Homens, vós sois irmãos, por que fazeis mal um ao outro?"}, {"numero": 27, "texto": "Mas aquele que maltratava a seu próximo empurrou-o, dizendo: Quem te pôs por chefe e juiz sobre nós?"}, {"numero": 28, "texto": "Queres tu [também] matar a mim, assim como ontem mataste ao egípcio?"}, {"numero": 29, "texto": "E com esta palavra Moisés fugiu, e foi peregrino na terra de Midiã, onde ele gerou dois filhos."}, {"numero": 30, "texto": "E completados quarenta anos, um anjo do Senhor lhe apareceu no deserto do monte Sinai, em uma sarça inflamada."}, {"numero": 31, "texto": "Moisés, ao ver [isso] ,maravilhou-se da visão; e ao aproximar-se para ver, veio até ele a voz do Senhor,"}, {"numero": 32, "texto": "[Dizendo] : Eu [sou] o Deus de teus pais, o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó. E Moisés, estando tremendo, não ousava olhar com atenção."}, {"numero": 33, "texto": "E o Senhor lhe disse: Descalça-te as sandálias de teus pés, porque o lugar em que estás é terra santa."}, {"numero": 34, "texto": "Eu tenho visto com atenção a aflição de meu povo que [está] no Egito, e ouvi o gemido deles, e eu desci para livrá-los; então vem agora, eu te enviarei ao Egito."}, {"numero": 35, "texto": "A este Moisés, ao qual tinham negado, dizendo: Quem te pôs por chefe e juiz, A este Deus enviou por chefe e libertador, pela mão do anjo que lhe apareceu na sarça."}, {"numero": 36, "texto": "Este os levou para fora, fazendo milagres e sinais na terra do Egito, e no mar Vermelho, e no deserto, [por] quarenta anos."}, {"numero": 37, "texto": "Este é o Moisés que disse aos filhos de Israel: O Senhor, vosso Deus, vos levantará um profeta dentre vossos irmãos, como a mim; a ele ouvireis."}, {"numero": 38, "texto": "Este é aquele que esteve na congregação [do povo] no deserto com o anjo que tinha lhe falado no monte Sinai, e [com] nossos pais; o qual recebeu as palavras vivas, para dar a nós;"}, {"numero": 39, "texto": "Ao qual nossos pais não quiseram obedecer; mas [o] rejeitaram, e seus corações voltaram ao Egito;"}, {"numero": 40, "texto": "Ao dizerem a Arão: Faz-nos deuses, que irão adiante de nós; porque [quanto a] este Moisés, que nos levou para fora da terra do Egito, nós não sabemos o que aconteceu com ele."}, {"numero": 41, "texto": "E naqueles dias eles fizeram o bezerro, o ofereceram sacrifício ao ídolo, e se alegraram nas obras de suas [próprias] mãos."}, {"numero": 42, "texto": "E Deus se afastou[deles] , e os entregou, para que servissem ao exército do céu, como está escrito no livro dos profetas: Ó casa de Israel, acaso foi a mim que oferecestes animais sacrificados, e ofertas no deserto por quarenta anos?"}, {"numero": 43, "texto": "Porém tomastes [para si] a tenda de Moloque, e a estrela de vosso Deus Renfã, figuras que vós fizeste para adorá-las; e eu [por isso] vos expulsarei para além da Babilônia."}, {"numero": 44, "texto": "No deserto estava entre nossos pais o Tabernáculo do testemunho, assim como ele tinha ordenado, falando a Moisés, que o fizesse segundo o modelo que tinha visto."}, {"numero": 45, "texto": "O qual, recebendo [-o] também nossos Pais, eles levaram com Josué para a possessão dos gentios que Deus expulsou diante de nossos Pais, até os dias de Davi;"}, {"numero": 46, "texto": "O qual foi do agrado diante de Deus, e pediu para achar um tabernáculo para o Deus de Jacó."}, {"numero": 47, "texto": "E Salomão lhe construiu uma casa."}, {"numero": 48, "texto": "Mas o Altíssimo não habita em templos feitos por mãos, assim como o profeta diz:"}, {"numero": 49, "texto": "O céu é o meu trono, e a terra [é] o estrado dos meus pés; que casa vós construireis para mim?, diz o Senhor; ou Qual é o lugar do meu repouso?"}, {"numero": 50, "texto": "Por acaso não [foi] minhão mão [que] fez todas estas coisas?"}, {"numero": 51, "texto": "Vós, obstinados e incircuncisos de coração e de ouvidos! Vós sempre resistis ao Espírito Santo! Tal como vossos pais [foram] , assim também [sois] vós!"}, {"numero": 52, "texto": "Qual dos profetas vossos pais não perseguiram? E eles mataram a todos os que anunciaram com antecedência a vinda do Justo, do qual agora vós tendes sido traidores e homicidas;"}, {"numero": 53, "texto": "Que recebestes a Lei por ordem de anjos, e não [a] guardastes."}, {"numero": 54, "texto": "Eles, ao ouvirem estas coisas, retalharam-se de raiva em seus corações, e rangiam os dentes contra ele."}, {"numero": 55, "texto": "Mas ele, estando cheio do Espírito Santo, olhando firmemente para o céu, viu à glória de Deus, e a Jesus, que estava à direita de Deus."}, {"numero": 56, "texto": "E disse: Eis que vejo os céus abertos, e o Filho do homem, que está a direita de Deus!"}, {"numero": 57, "texto": "Mas eles, clamando com alta voz, taparam seus próprios ouvidos, e correram juntos contra ele;"}, {"numero": 58, "texto": "E, lançando [-o] fora da cidade, [o] apedrejaram; e as testemunhas puseram as roupas deles junto aos pés de um rapaz chamado Saulo."}, {"numero": 59, "texto": "E apedrejaram a Estêvão, que estava clamando e dizendo: Senhor Jesus, recebe o meu espírito."}, {"numero": 60, "texto": "E pondo-se de joelhos, clamou com alta voz: Senhor, não os culpes por este pecado.E tendo dito isto, morreu."}]'::jsonb, 'Almeida Livre'),
  ('At', 7, 'en', '[{"numero": 1, "texto": "Then said the high priest, Are these things so?"}, {"numero": 2, "texto": "And he said, Men, brethren, and fathers, hearken; The God of glory appeared unto our father Abraham, when he was in Mesopotamia, before he dwelt in Charran,"}, {"numero": 3, "texto": "And said unto him, Get thee out of thy country, and from thy kindred, and come into the land which I shall shew thee."}, {"numero": 4, "texto": "Then came he out of the land of the Chaldaeans, and dwelt in Charran: and from thence, when his father was dead, he removed him into this land, wherein ye now dwell."}, {"numero": 5, "texto": "And he gave him none inheritance in it, no, not so much as to set his foot on: yet he promised that he would give it to him for a possession, and to his seed after him, when as yet he had no child."}, {"numero": 6, "texto": "And God spake on this wise, That his seed should sojourn in a strange land; and that they should bring them into bondage, and entreat them evil four hundred years."}, {"numero": 7, "texto": "And the nation to whom they shall be in bondage will I judge, said God: and after that shall they come forth, and serve me in this place."}, {"numero": 8, "texto": "And he gave him the covenant of circumcision: and so Abraham begat Isaac, and circumcised him the eighth day; and Isaac begat Jacob; and Jacob begat the twelve patriarchs."}, {"numero": 9, "texto": "And the patriarchs, moved with envy, sold Joseph into Egypt: but God was with him,"}, {"numero": 10, "texto": "And delivered him out of all his afflictions, and gave him favour and wisdom in the sight of Pharaoh king of Egypt; and he made him governor over Egypt and all his house."}, {"numero": 11, "texto": "Now there came a dearth over all the land of Egypt and Chanaan, and great affliction: and our fathers found no sustenance."}, {"numero": 12, "texto": "But when Jacob heard that there was corn in Egypt, he sent out our fathers first."}, {"numero": 13, "texto": "And at the second time Joseph was made known to his brethren; and Joseph''s kindred was made known unto Pharaoh."}, {"numero": 14, "texto": "Then sent Joseph, and called his father Jacob to him, and all his kindred, threescore and fifteen souls."}, {"numero": 15, "texto": "So Jacob went down into Egypt, and died, he, and our fathers,"}, {"numero": 16, "texto": "And were carried over into Sychem, and laid in the sepulchre that Abraham bought for a sum of money of the sons of Emmor the father of Sychem."}, {"numero": 17, "texto": "But when the time of the promise drew nigh, which God had sworn to Abraham, the people grew and multiplied in Egypt,"}, {"numero": 18, "texto": "Till another king arose, which knew not Joseph."}, {"numero": 19, "texto": "The same dealt subtilly with our kindred, and evil entreated our fathers, so that they cast out their young children, to the end they might not live."}, {"numero": 20, "texto": "In which time Moses was born, and was exceeding fair, and nourished up in his father''s house three months:"}, {"numero": 21, "texto": "And when he was cast out, Pharaoh''s daughter took him up, and nourished him for her own son."}, {"numero": 22, "texto": "And Moses was learned in all the wisdom of the Egyptians, and was mighty in words and in deeds."}, {"numero": 23, "texto": "And when he was full forty years old, it came into his heart to visit his brethren the children of Israel."}, {"numero": 24, "texto": "And seeing one of them suffer wrong, he defended him, and avenged him that was oppressed, and smote the Egyptian:"}, {"numero": 25, "texto": "For he supposed his brethren would have understood how that God by his hand would deliver them: but they understood not."}, {"numero": 26, "texto": "And the next day he shewed himself unto them as they strove, and would have set them at one again, saying, Sirs, ye are brethren; why do ye wrong one to another?"}, {"numero": 27, "texto": "But he that did his neighbour wrong thrust him away, saying, Who made thee a ruler and a judge over us?"}, {"numero": 28, "texto": "Wilt thou kill me, as thou diddest the Egyptian yesterday?"}, {"numero": 29, "texto": "Then fled Moses at this saying, and was a stranger in the land of Madian, where he begat two sons."}, {"numero": 30, "texto": "And when forty years were expired, there appeared to him in the wilderness of mount Sina an angel of the Lord in a flame of fire in a bush."}, {"numero": 31, "texto": "When Moses saw it, he wondered at the sight: and as he drew near to behold it, the voice of the Lord came unto him,"}, {"numero": 32, "texto": "Saying, I am the God of thy fathers, the God of Abraham, and the God of Isaac, and the God of Jacob. Then Moses trembled, and durst not behold."}, {"numero": 33, "texto": "Then said the Lord to him, Put off thy shoes from thy feet: for the place where thou standest is holy ground."}, {"numero": 34, "texto": "I have seen, I have seen the affliction of my people which is in Egypt, and I have heard their groaning, and am come down to deliver them. And now come, I will send thee into Egypt."}, {"numero": 35, "texto": "This Moses whom they refused, saying, Who made thee a ruler and a judge? the same did God send to be a ruler and a deliverer by the hand of the angel which appeared to him in the bush."}, {"numero": 36, "texto": "He brought them out, after that he had shewed wonders and signs in the land of Egypt, and in the Red sea, and in the wilderness forty years."}, {"numero": 37, "texto": "This is that Moses, which said unto the children of Israel, A prophet shall the Lord your God raise up unto you of your brethren, like unto me; him shall ye hear."}, {"numero": 38, "texto": "This is he, that was in the church in the wilderness with the angel which spake to him in the mount Sina, and with our fathers: who received the lively oracles to give unto us:"}, {"numero": 39, "texto": "To whom our fathers would not obey, but thrust him from them, and in their hearts turned back again into Egypt,"}, {"numero": 40, "texto": "Saying unto Aaron, Make us gods to go before us: for as for this Moses, which brought us out of the land of Egypt, we wot not what is become of him."}, {"numero": 41, "texto": "And they made a calf in those days, and offered sacrifice unto the idol, and rejoiced in the works of their own hands."}, {"numero": 42, "texto": "Then God turned, and gave them up to worship the host of heaven; as it is written in the book of the prophets, O ye house of Israel, have ye offered to me slain beasts and sacrifices by the space of forty years in the wilderness?"}, {"numero": 43, "texto": "Yea, ye took up the tabernacle of Moloch, and the star of your god Remphan, figures which ye made to worship them: and I will carry you away beyond Babylon."}, {"numero": 44, "texto": "Our fathers had the tabernacle of witness in the wilderness, as he had appointed, speaking unto Moses, that he should make it according to the fashion that he had seen."}, {"numero": 45, "texto": "Which also our fathers that came after brought in with Jesus into the possession of the Gentiles, whom God drave out before the face of our fathers, unto the days of David;"}, {"numero": 46, "texto": "Who found favour before God, and desired to find a tabernacle for the God of Jacob."}, {"numero": 47, "texto": "But Solomon built him an house."}, {"numero": 48, "texto": "Howbeit the most High dwelleth not in temples made with hands; as saith the prophet,"}, {"numero": 49, "texto": "Heaven is my throne, and earth is my footstool: what house will ye build me? saith the Lord: or what is the place of my rest?"}, {"numero": 50, "texto": "Hath not my hand made all these things?"}, {"numero": 51, "texto": "Ye stiffnecked and uncircumcised in heart and ears, ye do always resist the Holy Ghost: as your fathers did, so do ye."}, {"numero": 52, "texto": "Which of the prophets have not your fathers persecuted? and they have slain them which shewed before of the coming of the Just One; of whom ye have been now the betrayers and murderers:"}, {"numero": 53, "texto": "Who have received the law by the disposition of angels, and have not kept it."}, {"numero": 54, "texto": "When they heard these things, they were cut to the heart, and they gnashed on him with their teeth."}, {"numero": 55, "texto": "But he, being full of the Holy Ghost, looked up stedfastly into heaven, and saw the glory of God, and Jesus standing on the right hand of God,"}, {"numero": 56, "texto": "And said, Behold, I see the heavens opened, and the Son of man standing on the right hand of God."}, {"numero": 57, "texto": "Then they cried out with a loud voice, and stopped their ears, and ran upon him with one accord,"}, {"numero": 58, "texto": "And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man''s feet, whose name was Saul."}, {"numero": 59, "texto": "And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit."}, {"numero": 60, "texto": "And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge. And when he had said this, he fell asleep."}]'::jsonb, 'King James Version'),
  ('At', 7, 'fr', '[{"numero": 1, "texto": "Le souverain sacrificateur dit: Les choses sont-elles ainsi?"}, {"numero": 2, "texto": "Etienne répondit: Hommes frères et pères, écoutez! Le Dieu de gloire apparut à notre père Abraham, lorsqu''''il était en Mésopotamie, avant qu''''il s''''établît à Charran;"}, {"numero": 3, "texto": "et il lui dit: Quitte ton pays et ta famille, et va dans le pays que je te montrerai."}, {"numero": 4, "texto": "Il sortit alors du pays des Chaldéens, et s''''établit à Charran. De là, après la mort de son père, Dieu le fit passer dans ce pays que vous habitez maintenant;"}, {"numero": 5, "texto": "il ne lui donna aucune propriété en ce pays, pas même de quoi poser le pied, mais il promit de lui en donner la possession, et à sa postérité après lui, quoiqu''''il n''''eût point d''''enfant."}, {"numero": 6, "texto": "Dieu parla ainsi: Sa postérité séjournera dans un pays étranger; on la réduira en servitude et on la maltraitera pendant quatre cents ans."}, {"numero": 7, "texto": "Mais la nation à laquelle ils auront été asservis, c''''est moi qui la jugerai, dit Dieu. Après cela, ils sortiront, et ils me serviront dans ce lieu-ci."}, {"numero": 8, "texto": "Puis Dieu donna à Abraham l''''alliance de la circoncision; et ainsi, Abraham, ayant engendré Isaac, le circoncit le huitième jour; Isaac engendra et circoncit Jacob, et Jacob les douze patriarches."}, {"numero": 9, "texto": "Les patriarches, jaloux de Joseph, le vendirent pour être emmené en Egypte. Mais Dieu fut avec lui,"}, {"numero": 10, "texto": "et le délivra de toutes ses tribulations; il lui donna de la sagesse et lui fit trouver grâce devant Pharaon, roi d''''Egypte, qui l''''établit gouverneur d''''Egypte et de toute sa maison."}, {"numero": 11, "texto": "Il survint une famine dans tout le pays d''''Egypte, et dans celui de Canaan. La détresse était grande, et nos pères ne trouvaient pas de quoi se nourrir."}, {"numero": 12, "texto": "Jacob apprit qu''''il y avait du blé en Egypte, et il y envoya nos pères une première fois."}, {"numero": 13, "texto": "Et la seconde fois, Joseph fut reconnu par ses frères, et Pharaon sut de quelle famille il était."}, {"numero": 14, "texto": "Puis Joseph envoya chercher son père Jacob, et toute sa famille, composée de soixante-quinze personnes."}, {"numero": 15, "texto": "Jacob descendit en Egypte, où il mourut, ainsi que nos pères;"}, {"numero": 16, "texto": "et ils furent transportés à Sichem, et déposés dans le sépulcre qu''''Abraham avait acheté, à prix d''''argent, des fils d''''Hémor, père de Sichem."}, {"numero": 17, "texto": "Le temps approchait où devait s''''accomplir la promesse que Dieu avait faite à Abraham, et le peuple s''''accrut et se multiplia en Egypte,"}, {"numero": 18, "texto": "jusqu''''à ce que parut un autre roi, qui n''''avait pas connu Joseph."}, {"numero": 19, "texto": "Ce roi, usant d''''artifice contre notre race, maltraita nos pères, au point de leur faire exposer leurs enfants, pour qu''''ils ne vécussent pas."}, {"numero": 20, "texto": "A cette époque, naquit Moïse, qui était beau aux yeux de Dieu. Il fut nourri trois mois dans la maison de son père;"}, {"numero": 21, "texto": "et, quand il eut été exposé, la fille de Pharaon le recueillit, et l''''éleva comme son fils."}, {"numero": 22, "texto": "Moïse fut instruit dans toute la sagesse des Egyptiens, et il était puissant en paroles et en oeuvres."}, {"numero": 23, "texto": "Il avait quarante ans, lorsqu''''il lui vint dans le coeur de visiter ses frères, les fils d''''Israël."}, {"numero": 24, "texto": "Il en vit un qu''''on outrageait, et, prenant sa défense, il vengea celui qui était maltraité, et frappa l''''Egyptien."}, {"numero": 25, "texto": "Il pensait que ses frères comprendraient que Dieu leur accordait la délivrance par sa main; mais ils ne comprirent pas."}, {"numero": 26, "texto": "Le jour suivant, il parut au milieu d''''eux comme ils se battaient, et il les exhorta à la paix: Hommes, dit-il, vous êtes frères; pourquoi vous maltraitez-vous l''''un l''''autre?"}, {"numero": 27, "texto": "Mais celui qui maltraitait son prochain le repoussa, en disant: Qui t''''a établi chef et juge sur nous?"}, {"numero": 28, "texto": "Veux-tu me tuer, comme tu as tué hier l''''Egyptien?"}, {"numero": 29, "texto": "A cette parole, Moïse prit la fuite, et il alla séjourner dans le pays de Madian, où il engendra deux fils."}, {"numero": 30, "texto": "Quarante ans plus tard, un ange lui apparut, au désert de la montagne de Sinaï, dans la flamme d''''un buisson en feu."}, {"numero": 31, "texto": "Moïse, voyant cela, fut étonné de cette apparition; et, comme il s''''approchait pour examiner, la voix du Seigneur se fit entendre:"}, {"numero": 32, "texto": "Je suis le Dieu de tes pères, le Dieu d''''Abraham, d''''Isaac et de Jacob. Et Moïse, tout tremblant, n''''osait regarder."}, {"numero": 33, "texto": "Le Seigneur lui dit: Ote tes souliers de tes pieds, car le lieu sur lequel tu te tiens est une terre sainte."}, {"numero": 34, "texto": "J''''ai vu la souffrance de mon peuple qui est en Egypte, j''''ai entendu ses gémissements, et je suis descendu pour le délivrer. Maintenant, va, je t''''enverrai en Egypte."}, {"numero": 35, "texto": "Ce Moïse, qu''''ils avaient renié, en disant: Qui t''''a établi chef et juge? c''''est lui que Dieu envoya comme chef et comme libérateur avec l''''aide de l''''ange qui lui était apparu dans le buisson."}, {"numero": 36, "texto": "C''''est lui qui les fit sortir d''''Egypte, en opérant des prodiges et des miracles au pays d''''Egypte, au sein de la mer Rouge, et au désert, pendant quarante ans."}, {"numero": 37, "texto": "C''''est ce Moïse qui dit aux fils d''''Israël: Dieu vous suscitera d''''entre vos frères un prophète comme moi."}, {"numero": 38, "texto": "C''''est lui qui, lors de l''''assemblée au désert, étant avec l''''ange qui lui parlait sur la montagne de Sinaï et avec nos pères, reçut des oracles vivants, pour nous les donner."}, {"numero": 39, "texto": "Nos pères ne voulurent pas lui obéir, ils le repoussèrent, et ils tournèrent leur coeur vers l''''Egypte,"}, {"numero": 40, "texto": "en disant à Aaron: Fais-nous des dieux qui marchent devant nous; car ce Moïse qui nous a fait sortir du pays d''''Egypte, nous ne savons ce qu''''il est devenu."}, {"numero": 41, "texto": "Et, en ces jours-là, ils firent un veau, ils offrirent un sacrifice à l''''idole, et se réjouirent de l''''oeuvre de leurs mains."}, {"numero": 42, "texto": "Alors Dieu se détourna, et les livra au culte de l''''armée du ciel, selon qu''''il est écrit dans le livre des prophètes: M''''avez-vous offert des victimes et des sacrifices Pendant quarante ans au désert, maison d''''Israël?..."}, {"numero": 43, "texto": "Vous avez porté la tente de Moloch Et l''''étoile du dieu Remphan, Ces images que vous avez faites pour les adorer! Aussi vous transporterai-je au delà de Babylone."}, {"numero": 44, "texto": "Nos pères avaient au désert le tabernacle du témoignage, comme l''''avait ordonné celui qui dit à Moïse de le faire d''''après le modèle qu''''il avait vu."}, {"numero": 45, "texto": "Et nos pères, l''''ayant reçu, l''''introduisirent, sous la conduite de Josué, dans le pays qui était possédé par les nations que Dieu chassa devant eux, et il y resta jusqu''''aux jours de David."}, {"numero": 46, "texto": "David trouva grâce devant Dieu, et demanda d''''élever une demeure pour le Dieu de Jacob;"}, {"numero": 47, "texto": "et ce fut Salomon qui lui bâtit une maison."}, {"numero": 48, "texto": "Mais le Très-Haut n''''habite pas dans ce qui est fait de main d''''homme, comme dit le prophète:"}, {"numero": 49, "texto": "Le ciel est mon trône, Et la terre mon marchepied. Quelle maison me bâtirez-vous, dit le Seigneur, Ou quel sera le lieu de mon repos?"}, {"numero": 50, "texto": "N''''est-ce pas ma main qui a fait toutes ces choses?..."}, {"numero": 51, "texto": "Hommes au cou raide, incirconcis de coeur et d''''oreilles! vous vous opposez toujours au Saint-Esprit. Ce que vos pères ont été, vous l''''êtes aussi."}, {"numero": 52, "texto": "Lequel des prophètes vos pères n''''ont-ils pas persécuté? Ils ont tué ceux qui annonçaient d''''avance la venue du Juste, que vous avez livré maintenant, et dont vous avez été les meurtriers,"}, {"numero": 53, "texto": "vous qui avez reçu la loi d''''après des commandements d''''anges, et qui ne l''''avez point gardée!..."}, {"numero": 54, "texto": "En entendant ces paroles, ils étaient furieux dans leur coeur, et ils grinçaient des dents contre lui."}, {"numero": 55, "texto": "Mais Etienne, rempli du Saint-Esprit, et fixant les regards vers le ciel, vit la gloire de Dieu et Jésus debout à la droite de Dieu."}, {"numero": 56, "texto": "Et il dit: Voici, je vois les cieux ouverts, et le Fils de l''''homme debout à la droite de Dieu."}, {"numero": 57, "texto": "Ils poussèrent alors de grands cris, en se bouchant les oreilles, et ils se précipitèrent tous ensemble sur lui,"}, {"numero": 58, "texto": "le traînèrent hors de la ville, et le lapidèrent. Les témoins déposèrent leurs vêtements aux pieds d''''un jeune homme nommé Saul."}, {"numero": 59, "texto": "Et ils lapidaient Etienne, qui priait et disait: Seigneur Jésus, reçois mon esprit!"}, {"numero": 60, "texto": "Puis, s''''étant mis à genoux, il s''''écria d''''une voix forte: Seigneur, ne leur impute pas ce péché! Et, après ces paroles, il s''''endormit."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 7, 'es', '[{"numero": 1, "texto": "EL príncipe de los sacerdotes dijo entonces: ¿Es esto así?"}, {"numero": 2, "texto": "Y él dijo: Varones hermanos y padres, oid: El Dios de la gloria apareció á nuestro padre Abraham, estando en Mesopotamia, antes que morase en Chârán,"}, {"numero": 3, "texto": "Y le dijo: Sal de tu tierra y de tu parentela, y ven á la tierra que te mostraré."}, {"numero": 4, "texto": "Entonces salió de la tierra de los Caldeos, y habitó en Chârán: y de allí, muerto su padre, le traspasó á esta tierra, en la cual vosotros habitáis ahora;"}, {"numero": 5, "texto": "Y no le dió herencia en ella, ni aun para asentar un pie: mas le prometió que se la daría en posesión, y á su simiente después de él, no teniendo hijo."}, {"numero": 6, "texto": "Y hablóle Dios así: Que su simiente sería extranjera en tierra ajena, y que los reducirían á servidumbre y maltratarían, por cuatrocientos años."}, {"numero": 7, "texto": "Mas yo juzgaré, dijo Dios, la nación á la cual serán siervos: y después de esto saldrán y me servirán en este lugar."}, {"numero": 8, "texto": "Y dióle el pacto de la circuncisión: y así Abraham engendró á Isaac, y le circuncidó al octavo día; é Isaac á Jacob, y Jacob á los doce patriarcas."}, {"numero": 9, "texto": "Y los patriarcas, movidos de envidia, vendieron á José para Egipto; mas Dios era con él,"}, {"numero": 10, "texto": "Y le libró de todas sus tribulaciones, y le dió gracia y sabiduría en la presencia de Faraón, rey de Egipto, el cual le puso por gobernador sobre Egipto, y sobre toda su casa."}, {"numero": 11, "texto": "Vino entonces hambre en toda la tierra de Egipto y de Canaán, y grande tribulación; y nuestros padres no hallaban alimentos."}, {"numero": 12, "texto": "Y como oyese Jacob que había trigo en Egipto, envió á nuestros padres la primera vez."}, {"numero": 13, "texto": "Y en la segunda, José fué conocido de sus hermanos, y fué sabido de Faraón el linaje de José."}, {"numero": 14, "texto": "Y enviando José, hizo venir á su padre Jacob, y á toda su parentela, en número de setenta y cinco personas."}, {"numero": 15, "texto": "Así descendió Jacob á Egipto, donde murió él y nuestros padres;"}, {"numero": 16, "texto": "Los cuales fueron trasladados á Sichêm, y puestos en el sepulcro que compró Abraham á precio de dinero de los hijos de Hemor de Sichêm."}, {"numero": 17, "texto": "Mas como se acercaba el tiempo de la promesa, la cual Dios había jurado á Abraham, el pueblo creció y multiplicóse en Egipto,"}, {"numero": 18, "texto": "Hasta que se levantó otro rey en Egipto que no conocía á José."}, {"numero": 19, "texto": "Este, usando de astucia con nuestro linaje, maltrató á nuestros padres, á fin de que pusiesen á peligro de muerte sus niños, para que cesase la generación."}, {"numero": 20, "texto": "En aquel mismo tiempo nació Moisés, y fué agradable á Dios: y fué criado tres meses en casa de su padre."}, {"numero": 21, "texto": "Mas siendo puesto al peligro, la hija de Faraón le tomó, y le crió como á hijo suyo."}, {"numero": 22, "texto": "Y fué enseñado Moisés en toda la sabiduría de los egipcios; y era poderoso en sus dichos y hechos."}, {"numero": 23, "texto": "Y cuando hubo cumplido la edad de cuarenta años, le vino voluntad de visitar á sus hermanos los hijos de Israel."}, {"numero": 24, "texto": "Y como vió á uno que era injuriado, defendióle, é hiriendo al Egipcio, vengó al injuriado."}, {"numero": 25, "texto": "Pero él pensaba que sus hermanos entendían que Dios les había de dar salud por su mano; mas ellos no lo habían entendido."}, {"numero": 26, "texto": "Y al día siguiente, riñendo ellos, se les mostró, y los ponía en paz, diciendo: Varones, hermanos sois, ¿por qué os injuriáis los unos á los otros?"}, {"numero": 27, "texto": "Entonces el que injuriaba á su prójimo, le rempujó, diciendo: ¿Quién te ha puesto por príncipe y juez sobre nosotros?"}, {"numero": 28, "texto": "¿Quieres tú matarme, como mataste ayer al Egipcio?"}, {"numero": 29, "texto": "A esta palabra Moisés huyó, y se hizo extranjero en tierra de Madián, donde engendró dos hijos."}, {"numero": 30, "texto": "Y cumplidos cuarenta años, un ángel le apareció en el desierto del monte Sina, en fuego de llama de una zarza."}, {"numero": 31, "texto": "Entonces Moisés mirando, se maravilló de la visión: y llegándose para considerar, fué hecha á él voz del Señor:"}, {"numero": 32, "texto": "Yo soy el Dios de tus padres, el Dios de Abraham, y el Dios de Isaac, y el Dios de Jacob. Mas Moisés, temeroso, no osaba mirar."}, {"numero": 33, "texto": "Y le dijo el Señor: Quita los zapatos de tus pies, porque el lugar en que estás es tierra santa."}, {"numero": 34, "texto": "He visto, he visto la aflicción de mi pueblo que está en Egipto, y he oído el gemido de ellos, y he descendido para librarlos. Ahora pues, ven, te enviaré á Egipto."}, {"numero": 35, "texto": "A este Moisés, al cual habían rehusado, diciendo: ¿Quién te ha puesto por príncipe y juez? á éste envió Dios por príncipe y redentor con la mano del ángel que le apareció en la zarza."}, {"numero": 36, "texto": "Este los sacó, habiendo hecho prodigios y milagros en la tierra de Egipto, y en el mar Bermejo, y en el desierto por cuarenta años."}, {"numero": 37, "texto": "Este es el Moisés, el cual dijo á los hijos de Israel: Profeta os levantará el Señor Dios vuestro de vuestros hermanos, como yo; á él oiréis."}, {"numero": 38, "texto": "Este es aquél que estuvo en la congregación en el desierto con el ángel que le hablaba en el monte Sina, y con nuestros padres; y recibió las palabras de vida para darnos:"}, {"numero": 39, "texto": "Al cual nuestros padres no quisieron obedecer; antes le desecharon, y se apartaron de corazón á Egipto,"}, {"numero": 40, "texto": "Diciendo á Aarón: Haznos dioses que vayan delante de nosotros; porque á este Moisés, que nos sacó de tierra de Egipto, no sabemos qué le ha acontecido."}, {"numero": 41, "texto": "Y entonces hicieron un becerro, y ofrecieron sacrificio al ídolo, y en las obras de sus manos se holgaron."}, {"numero": 42, "texto": "Y Dios se apartó, y los entregó que sirviesen al ejército del cielo; como está escrito en el libro de los profetas: ¿Me ofrecisteis víctimas y sacrificios en el desierto por cuarenta años, casa de Israel?"}, {"numero": 43, "texto": "Antes, trajisteis el tabernáculo de Moloch, y la estrella de vuestro dios Remphan: figuras que os hicisteis para adorarlas: os transportaré pues, más allá de Babilonia."}, {"numero": 44, "texto": "Tuvieron nuestros padres el tabernáculo del testimonio en el desierto, como había ordenado Dios, hablando á Moisés que lo hiciese según la forma que había visto."}, {"numero": 45, "texto": "El cual recibido, metieron también nuestros padres con Josué en la posesión de los Gentiles, que Dios echó de la presencia de nuestros padres, hasta los días de David;"}, {"numero": 46, "texto": "El cual halló gracia delante de Dios, y pidió hallar tabernáculo para el Dios de Jacob."}, {"numero": 47, "texto": "Mas Salomón le edificó casa."}, {"numero": 48, "texto": "Si bien el Altísimo no habita en templos hechos de mano; como el profeta dice:"}, {"numero": 49, "texto": "El cielo es mi trono, y la tierra es el estrado de mis pies. ¿Qué casa me edificaréis? dice el Señor; ¿ó cuál es el lugar de mi reposo?"}, {"numero": 50, "texto": "¿No hizo mi mano todas estas cosas?"}, {"numero": 51, "texto": "Duros de cerviz, é incircuncisos de corazón y de oídos, vosotros resistís siempre al Espíritu Santo: como vuestros padres, así también vosotros."}, {"numero": 52, "texto": "¿A cuál de los profetas no persiguieron vuestros padres? y mataron á los que antes anunciaron la venida del Justo, del cual vosotros ahora habéis sido entregadores y matadores;"}, {"numero": 53, "texto": "Que recibisteis la ley por disposición de ángeles, y no la guardasteis."}, {"numero": 54, "texto": "Y oyendo estas cosas, regañaban de sus corazones, y crujían los dientes contra él."}, {"numero": 55, "texto": "Mas él, estando lleno de Espíritu Santo, puestos los ojos en el cielo, vió la gloria de Dios, y á Jesús que estaba á la diestra de Dios,"}, {"numero": 56, "texto": "Y dijo: He aquí, veo los cielos abiertos, y al Hijo del hombre que está á la diestra de Dios."}, {"numero": 57, "texto": "Entonces dando grandes voces, se taparon sus oídos, y arremetieron unánimes contra él;"}, {"numero": 58, "texto": "Y echándolo fuera de la ciudad, le apedreaban: y los testigos pusieron sus vestidos á los pies de un mancebo que se llamaba Saulo."}, {"numero": 59, "texto": "Y apedrearon á Esteban, invocando él y diciendo: Señor Jesús, recibe mi espíritu."}, {"numero": 60, "texto": "Y puesto de rodillas, clamó á gran voz: Señor, no les imputes este pecado. Y habiendo dicho esto, durmió."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 8, 'pt', '[{"numero": 1, "texto": "E Saulo também consentia na morte dele. E naquele dia foi feita uma grande perseguição contra a igreja que estava em Jerusalém; e todos foram dispersos pelas regiões da Judeia, e de Samaria, exceto os apóstolos."}, {"numero": 2, "texto": "E [alguns] homens devotos levaram juntos a Estêvão [para enterrá-lo] ,e fizeram grande pranto por causa dele."}, {"numero": 3, "texto": "E Saulo tentava destruir a igreja, entrando nas casas, e puxando a homens e mulheres, entregava-os à prisão."}, {"numero": 4, "texto": "Os que, pois, estavam dispersos, passavam anunciando a palavra."}, {"numero": 5, "texto": "E Filipe, tendo descido à cidade de Samaria, pregava-lhes a Cristo."}, {"numero": 6, "texto": "E as multidões prestavam atenção em concordância às coisas que eram ditas por Filipe, ao ouvirem e verem os sinais que ele fazia."}, {"numero": 7, "texto": "Porque os espíritos imundos, clamando em alta voz, saíam de muitos que os tinham; e muitos paralíticos e aleijados foram curados."}, {"numero": 8, "texto": "E havia grande alegria naquela cidade."}, {"numero": 9, "texto": "E havia um certo homem, de nome Simão, que antes naquela cidade usava de magia, e fazia o povo de Samaria ficar admirado, dizendo de si mesmo ser alguém grande;"}, {"numero": 10, "texto": "A quem eles todos davam atenção, desde o menor até o maior, diziam: Este é o grande poder de Deus."}, {"numero": 11, "texto": "E davam atenção a ele, porque com suas magias ele há muito tempo tinha lhes causado admiração."}, {"numero": 12, "texto": "Mas quando creram em Filipe, que lhes anunciava o Evangelho do Reino de Deus, e o nome de Jesus Cristo, eles foram batizados, tanto homens como mulheres."}, {"numero": 13, "texto": "E até mesmo Simão creu; e tendo sido batizado, ele continuou com Filipe; e vendo os sinais e maravilhas que eram feitas, ele ficou admirado."}, {"numero": 14, "texto": "E os apóstolos que estavam em Jerusalém, ao ouvirem que Samaria tinha recebido a palavra de Deus, enviaram-lhes a Pedro e a João."}, {"numero": 15, "texto": "Os quais, tendo descido, oraram por eles, para que recebessem ao Espírito Santo."}, {"numero": 16, "texto": "(Porque ainda sobre nenhum deles tinha descido; mas somente tinham sido batizados no nome do Senhor Jesus)."}, {"numero": 17, "texto": "Então puseram as mãos sobre eles, e receberam o Espírito Santo."}, {"numero": 18, "texto": "E Simão ao ver que pela imposição das mãos dos apóstolos se dava o Espírito Santo, ofereceu-lhes dinheiro,"}, {"numero": 19, "texto": "Dizendo: Dai também a mim este poder, que sobre qualquer um em quem eu puser as mãos, receba o Espírito Santo."}, {"numero": 20, "texto": "Mas Pedro lhe disse: Teu dinheiro seja contigo para perdição, porque pensaste que o dom de Deus [pudesse] ser obtido por meio de dinheiro."}, {"numero": 21, "texto": "Tu não tens parte nem porção nesta palavra; porque teu coração não é correto diante de Deus."}, {"numero": 22, "texto": "Arrepende-te, pois, desta tua maldade, e ora a Deus, para que talvez este pensamento de teu coração te seja perdoado;"}, {"numero": 23, "texto": "Porque eu vejo que tu estás em fel amargo, e atado em injustiça."}, {"numero": 24, "texto": "Mas respondendo Simão, disse: Orai vós por mim ao Senhor, para que nada do que dissestes venha sobre mim."}, {"numero": 25, "texto": "Tendo eles pois dado testemunho e falado a palavra do Senhor, voltaram a Jerusalém, e em muitas aldeias dos samaritanos anunciaram o Evangelho."}, {"numero": 26, "texto": "E um anjo do Senhor falou a Filipe, dizendo: Levanta-te, e vai para o sul, ao caminho que desce de Jerusalém para Gaza, que é deserto."}, {"numero": 27, "texto": "E ele levantou-se, e foi, e eis que um homem etíope, eunuco, administrador [subordinado] a Candace, a rainha dos etíopes, que estava sobre [o controle] de todos os bens dela, tinha vindo a Jerusalém para adorar;"}, {"numero": 28, "texto": "E ele estava voltando, sentado em sua carruagem, [e] lia ao profeta Isaías."}, {"numero": 29, "texto": "E o Espírito disse a Filipe: Aproxima-te, e ajunta-te a esta carruagem."}, {"numero": 30, "texto": "E Filipe, correndo, ouviu que ele estava lendo ao profeta Isaías, e disse: Tu entendes o que estás lendo?"}, {"numero": 31, "texto": "E ele disse: Como eu poderia, se alguém não me ensinar? E pediu a Filipe que subisse e se sentasse com ele."}, {"numero": 32, "texto": "E o lugar da Escritura que ele estava lendo era este: Como ovelha ele foi levado ao matadouro, e como um cordeiro mudo fica diante do que o tosquia, assim [também] ele não abriu sua boca."}, {"numero": 33, "texto": "Em sua humilhação foi tirado seu julgamento; e quem anunciará sua geração? Porque da terra sua vida é tirada."}, {"numero": 34, "texto": "E respondendo o eunuco a Filipe, disse: Eu te rogo, de quem o profeta diz isto? De si mesmo, ou de alguém outro?"}, {"numero": 35, "texto": "E Filipe, abrindo sua boca, e começando desta escritura, anunciou-lhe o Evangelho [de] Jesus."}, {"numero": 36, "texto": "E enquanto eles iam caminhando, chegaram a uma certa [porção] de água; e o eunuco disse: Eis aqui água; o que me impede de ser batizado?"}, {"numero": 37, "texto": "E Filipe disse: Se tu crês de todo coração, [então] é lícito;E respondendo ele, disse: Creio que Jesus Cristo é o Filho de Deus."}, {"numero": 38, "texto": "E ele mandou parar a carruagem; e desceram ambos à água, tanto Filipe como o eunuco; e ele o batizou."}, {"numero": 39, "texto": "E quando eles subiram da água, o Espírito do Senhor arrebatou a Filipe, e o eunuco não mais o viu, porque ele foi [em] seu caminho com alegria."}, {"numero": 40, "texto": "Mas Filipe se achou em Azoto; e passando, anunciava ao Evangelho [em] todas as cidades, até que veio a Cesareia."}]'::jsonb, 'Almeida Livre'),
  ('At', 8, 'en', '[{"numero": 1, "texto": "And Saul was consenting unto his death. And at that time there was a great persecution against the church which was at Jerusalem; and they were all scattered abroad throughout the regions of Judaea and Samaria, except the apostles."}, {"numero": 2, "texto": "And devout men carried Stephen to his burial, and made great lamentation over him."}, {"numero": 3, "texto": "As for Saul, he made havock of the church, entering into every house, and haling men and women committed them to prison."}, {"numero": 4, "texto": "Therefore they that were scattered abroad went every where preaching the word."}, {"numero": 5, "texto": "Then Philip went down to the city of Samaria, and preached Christ unto them."}, {"numero": 6, "texto": "And the people with one accord gave heed unto those things which Philip spake, hearing and seeing the miracles which he did."}, {"numero": 7, "texto": "For unclean spirits, crying with loud voice, came out of many that were possessed with them: and many taken with palsies, and that were lame, were healed."}, {"numero": 8, "texto": "And there was great joy in that city."}, {"numero": 9, "texto": "But there was a certain man, called Simon, which beforetime in the same city used sorcery, and bewitched the people of Samaria, giving out that himself was some great one:"}, {"numero": 10, "texto": "To whom they all gave heed, from the least to the greatest, saying, This man is the great power of God."}, {"numero": 11, "texto": "And to him they had regard, because that of long time he had bewitched them with sorceries."}, {"numero": 12, "texto": "But when they believed Philip preaching the things concerning the kingdom of God, and the name of Jesus Christ, they were baptized, both men and women."}, {"numero": 13, "texto": "Then Simon himself believed also: and when he was baptized, he continued with Philip, and wondered, beholding the miracles and signs which were done."}, {"numero": 14, "texto": "Now when the apostles which were at Jerusalem heard that Samaria had received the word of God, they sent unto them Peter and John:"}, {"numero": 15, "texto": "Who, when they were come down, prayed for them, that they might receive the Holy Ghost:"}, {"numero": 16, "texto": "(For as yet he was fallen upon none of them: only they were baptized in the name of the Lord Jesus.)"}, {"numero": 17, "texto": "Then laid they their hands on them, and they received the Holy Ghost."}, {"numero": 18, "texto": "And when Simon saw that through laying on of the apostles'' hands the Holy Ghost was given, he offered them money,"}, {"numero": 19, "texto": "Saying, Give me also this power, that on whomsoever I lay hands, he may receive the Holy Ghost."}, {"numero": 20, "texto": "But Peter said unto him, Thy money perish with thee, because thou hast thought that the gift of God may be purchased with money."}, {"numero": 21, "texto": "Thou hast neither part nor lot in this matter: for thy heart is not right in the sight of God."}, {"numero": 22, "texto": "Repent therefore of this thy wickedness, and pray God, if perhaps the thought of thine heart may be forgiven thee."}, {"numero": 23, "texto": "For I perceive that thou art in the gall of bitterness, and in the bond of iniquity."}, {"numero": 24, "texto": "Then answered Simon, and said, Pray ye to the Lord for me, that none of these things which ye have spoken come upon me."}, {"numero": 25, "texto": "And they, when they had testified and preached the word of the Lord, returned to Jerusalem, and preached the gospel in many villages of the Samaritans."}, {"numero": 26, "texto": "And the angel of the Lord spake unto Philip, saying, Arise, and go toward the south unto the way that goeth down from Jerusalem unto Gaza, which is desert."}, {"numero": 27, "texto": "And he arose and went: and, behold, a man of Ethiopia, an eunuch of great authority under Candace queen of the Ethiopians, who had the charge of all her treasure, and had come to Jerusalem for to worship,"}, {"numero": 28, "texto": "Was returning, and sitting in his chariot read Esaias the prophet."}, {"numero": 29, "texto": "Then the Spirit said unto Philip, Go near, and join thyself to this chariot."}, {"numero": 30, "texto": "And Philip ran thither to him, and heard him read the prophet Esaias, and said, Understandest thou what thou readest?"}, {"numero": 31, "texto": "And he said, How can I, except some man should guide me? And he desired Philip that he would come up and sit with him."}, {"numero": 32, "texto": "The place of the scripture which he read was this, He was led as a sheep to the slaughter; and like a lamb dumb before his shearer, so opened he not his mouth:"}, {"numero": 33, "texto": "In his humiliation his judgment was taken away: and who shall declare his generation? for his life is taken from the earth."}, {"numero": 34, "texto": "And the eunuch answered Philip, and said, I pray thee, of whom speaketh the prophet this? of himself, or of some other man?"}, {"numero": 35, "texto": "Then Philip opened his mouth, and began at the same scripture, and preached unto him Jesus."}, {"numero": 36, "texto": "And as they went on their way, they came unto a certain water: and the eunuch said, See, here is water; what doth hinder me to be baptized?"}, {"numero": 37, "texto": "And Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God."}, {"numero": 38, "texto": "And he commanded the chariot to stand still: and they went down both into the water, both Philip and the eunuch; and he baptized him."}, {"numero": 39, "texto": "And when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing."}, {"numero": 40, "texto": "But Philip was found at Azotus: and passing through he preached in all the cities, till he came to Caesarea."}]'::jsonb, 'King James Version'),
  ('At', 8, 'fr', '[{"numero": 1, "texto": "Saul avait approuvé le meurtre d''''Etienne. Il y eut, ce jour-là, une grande persécution contre l''''Eglise de Jérusalem; et tous, excepté les apôtres, se dispersèrent dans les contrées de la Judée et de la Samarie."}, {"numero": 2, "texto": "Des hommes pieux ensevelirent Etienne, et le pleurèrent à grand bruit."}, {"numero": 3, "texto": "Saul, de son côté, ravageait l''''Eglise; pénétrant dans les maisons, il en arrachait hommes et femmes, et les faisait jeter en prison."}, {"numero": 4, "texto": "Ceux qui avaient été dispersés allaient de lieu en lieu, annonçant la bonne nouvelle de la parole."}, {"numero": 5, "texto": "Philippe, étant descendu dans la ville de Samarie, y prêcha le Christ."}, {"numero": 6, "texto": "Les foules tout entières étaient attentives à ce que disait Philippe, lorsqu''''elles apprirent et virent les miracles qu''''il faisait."}, {"numero": 7, "texto": "Car des esprits impurs sortirent de plusieurs démoniaques, en poussant de grands cris, et beaucoup de paralytiques et de boiteux furent guéris."}, {"numero": 8, "texto": "Et il y eut une grande joie dans cette ville."}, {"numero": 9, "texto": "Il y avait auparavant dans la ville un homme nommé Simon, qui, se donnant pour un personnage important, exerçait la magie et provoquait l''''étonnement du peuple de la Samarie."}, {"numero": 10, "texto": "Tous, depuis le plus petit jusqu''''au plus grand, l''''écoutaient attentivement, et disaient: Celui-ci est la puissance de Dieu, celle qui s''''appelle la grande."}, {"numero": 11, "texto": "Ils l''''écoutaient attentivement, parce qu''''il les avait longtemps étonnés par ses actes de magie."}, {"numero": 12, "texto": "Mais, quand ils eurent cru à Philippe, qui leur annonçait la bonne nouvelle du royaume de Dieu et du nom de Jésus-Christ, hommes et femmes se firent baptiser."}, {"numero": 13, "texto": "Simon lui-même crut, et, après avoir été baptisé, il ne quittait plus Philippe, et il voyait avec étonnement les miracles et les grands prodiges qui s''''opéraient."}, {"numero": 14, "texto": "Les apôtres, qui étaient à Jérusalem, ayant appris que la Samarie avait reçu la parole de Dieu, y envoyèrent Pierre et Jean."}, {"numero": 15, "texto": "Ceux-ci, arrivés chez les Samaritains, prièrent pour eux, afin qu''''ils reçussent le Saint-Esprit."}, {"numero": 16, "texto": "Car il n''''était encore descendu sur aucun d''''eux; ils avaient seulement été baptisés au nom du Seigneur Jésus."}, {"numero": 17, "texto": "Alors Pierre et Jean leur imposèrent les mains, et ils reçurent le Saint-Esprit."}, {"numero": 18, "texto": "Lorsque Simon vit que le Saint-Esprit était donné par l''''imposition des mains des apôtres, il leur offrit de l''''argent,"}, {"numero": 19, "texto": "en disant: Accordez-moi aussi ce pouvoir, afin que celui à qui j''''imposerai les mains reçoive le Saint-Esprit."}, {"numero": 20, "texto": "Mais Pierre lui dit: Que ton argent périsse avec toi, puisque tu as cru que le don de Dieu s''''acquérait à prix d''''argent!"}, {"numero": 21, "texto": "Il n''''y a pour toi ni part ni lot dans cette affaire, car ton coeur n''''est pas droit devant Dieu."}, {"numero": 22, "texto": "Repens-toi donc de ta méchanceté, et prie le Seigneur pour que la pensée de ton coeur te soit pardonnée, s''''il est possible;"}, {"numero": 23, "texto": "car je vois que tu es dans un fiel amer et dans les liens de l''''iniquité."}, {"numero": 24, "texto": "Simon répondit: Priez vous-mêmes le Seigneur pour moi, afin qu''''il ne m''''arrive rien de ce que vous avez dit."}, {"numero": 25, "texto": "Après avoir rendu témoignage à la parole du Seigneur, et après l''''avoir prêchée, Pierre et Jean retournèrent à Jérusalem, en annonçant la bonne nouvelle dans plusieurs villages des Samaritains."}, {"numero": 26, "texto": "Un ange du Seigneur, s''''adressant à Philippe, lui dit: Lève-toi, et va du côté du midi, sur le chemin qui descend de Jérusalem à Gaza, celui qui est désert."}, {"numero": 27, "texto": "Il se leva, et partit. Et voici, un Ethiopien, un eunuque, ministre de Candace, reine d''''Ethiopie, et surintendant de tous ses trésors, venu à Jérusalem pour adorer,"}, {"numero": 28, "texto": "s''''en retournait, assis sur son char, et lisait le prophète Esaïe."}, {"numero": 29, "texto": "L''''Esprit dit à Philippe: Avance, et approche-toi de ce char."}, {"numero": 30, "texto": "Philippe accourut, et entendit l''''Ethiopien qui lisait le prophète Esaïe. Il lui dit: Comprends-tu ce que tu lis?"}, {"numero": 31, "texto": "Il répondit: Comment le pourrais-je, si quelqu''''un ne me guide? Et il invita Philippe à monter et à s''''asseoir avec lui."}, {"numero": 32, "texto": "Le passage de l''''Ecriture qu''''il lisait était celui-ci: Il a été mené comme une brebis à la boucherie; Et, comme un agneau muet devant celui qui le tond, Il n''''a point ouvert la bouche."}, {"numero": 33, "texto": "Dans son humiliation, son jugement a été levé. Et sa postérité, qui la dépeindra? Car sa vie a été retranchée de la terre."}, {"numero": 34, "texto": "L''''eunuque dit à Philippe: Je te prie, de qui le prophète parle-t-il ainsi? Est-ce de lui-même, ou de quelque autre?"}, {"numero": 35, "texto": "Alors Philippe, ouvrant la bouche et commençant par ce passage, lui annonça la bonne nouvelle de Jésus."}, {"numero": 36, "texto": "Comme ils continuaient leur chemin, ils rencontrèrent de l''''eau. Et l''''eunuque dit: Voici de l''''eau; qu''''est-ce qui empêche que je sois baptisé?"}, {"numero": 37, "texto": "Philippe dit: Si tu crois de tout ton coeur, cela est possible. L''''eunuque répondit: Je crois que Jésus-Christ est le Fils de Dieu."}, {"numero": 38, "texto": "Il fit arrêter le char; Philippe et l''''eunuque descendirent tous deux dans l''''eau, et Philippe baptisa l''''eunuque."}, {"numero": 39, "texto": "Quand ils furent sortis de l''''eau, l''''Esprit du Seigneur enleva Philippe, et l''''eunuque ne le vit plus. Tandis que, joyeux, il poursuivait sa route,"}, {"numero": 40, "texto": "Philippe se trouva dans Azot, d''''où il alla jusqu''''à Césarée, en évangélisant toutes les villes par lesquelles il passait."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 8, 'es', '[{"numero": 1, "texto": "Y SAULO consentía en su muerte. Y en aquel día se hizo una grande persecución en la iglesia que estaba en Jerusalem; y todos fueron esparcidos por las tierras de Judea y de Samaria, salvo los apóstoles."}, {"numero": 2, "texto": "Y llevaron á enterrar á Esteban varones piadosos, é hicieron gran llanto sobre él."}, {"numero": 3, "texto": "Entonces Saulo asolaba la iglesia, entrando por las casas: y trayendo hombres y mujeres, los entregaba en la cárcel."}, {"numero": 4, "texto": "Mas los que fueron esparcidos, iban por todas partes anunciando la palabra."}, {"numero": 5, "texto": "Entonces Felipe, descendiendo á la ciudad de Samaria, les predicaba á Cristo."}, {"numero": 6, "texto": "Y las gentes escuchaban atentamente unánimes las cosas que decía Felipe, oyendo y viendo las señales que hacía."}, {"numero": 7, "texto": "Porque de muchos que tenían espíritus inmundos, salían éstos dando grandes voces; y muchos paralíticos y cojos eran sanados:"}, {"numero": 8, "texto": "Así que había gran gozo en aquella ciudad."}, {"numero": 9, "texto": "Y había un hombre llamado Simón, el cual había sido antes mágico en aquella ciudad, y había engañado la gente de Samaria, diciéndose ser algún grande:"}, {"numero": 10, "texto": "Al cual oían todos atentamente desde el más pequeño hasta el más grande, diciendo: Este es la gran virtud de Dios."}, {"numero": 11, "texto": "Y le estaban atentos, porque con sus artes mágicas los había embelesado mucho tiempo."}, {"numero": 12, "texto": "Mas cuando creyeron á Felipe, que anunciaba el evangelio del reino de Dios y el nombre de Jesucristo, se bautizaban hombres y mujeres."}, {"numero": 13, "texto": "El mismo Simón creyó también entonces, y bautizándose, se llegó á Felipe: y viendo los milagros y grandes maravillas que se hacían, estaba atónito."}, {"numero": 14, "texto": "Y los apóstoles que estaban en Jerusalem, habiendo oído que Samaria había recibido la palabra de Dios, les enviaron á Pedro y á Juan:"}, {"numero": 15, "texto": "Los cuales venidos, oraron por ellos, para que recibiesen el Espíritu Santo;"}, {"numero": 16, "texto": "(Porque aun no había descendido sobre ninguno de ellos, mas solamente eran bautizados en el nombre de Jesús.)"}, {"numero": 17, "texto": "Entonces les impusieron las manos, y recibieron el Espíritu Santo."}, {"numero": 18, "texto": "Y como vió Simón que por la imposición de las manos de los apóstoles se daba el Espíritu Santo, les ofreció dinero,"}, {"numero": 19, "texto": "Diciendo: Dadme también á mí esta potestad, que á cualquiera que pusiere las manos encima, reciba el Espíritu Santo."}, {"numero": 20, "texto": "Entonces Pedro le dijo: Tu dinero perezca contigo, que piensas que el don de Dios se gane por dinero."}, {"numero": 21, "texto": "No tienes tú parte ni suerte en este negocio; porque tu corazón no es recto delante de Dios."}, {"numero": 22, "texto": "Arrepiéntete pues de esta tu maldad, y ruega á Dios, si quizás te será perdonado el pensamiento de tu corazón."}, {"numero": 23, "texto": "Porque en hiel de amargura y en prisión de maldad veo que estás."}, {"numero": 24, "texto": "Respondiendo entonces Simón, dijo: Rogad vosotros por mí al Señor, que ninguna cosa de estas que habéis dicho, venga sobre mí."}, {"numero": 25, "texto": "Y ellos, habiendo testificado y hablado la palabra de Dios, se volvieron á Jerusalem, y en muchas tierras de los Samaritanos anunciaron el evangelio."}, {"numero": 26, "texto": "Empero el ángel del Señor habló á Felipe, diciendo: Levántate y ve hacia el mediodía, al camino que desciende de Jerusalem á Gaza, el cual es desierto."}, {"numero": 27, "texto": "Entonces él se levantó, y fué: y he aquí un Etiope, eunuco, gobernador de Candace, reina de los Etiopes, el cual era puesto sobre todos sus tesoros, y había venido á adorar á Jerusalem,"}, {"numero": 28, "texto": "Se volvía sentado en su carro, y leyendo el profeta Isaías."}, {"numero": 29, "texto": "Y el Espíritu dijo á Felipe: Llégate, y júntate á este carro."}, {"numero": 30, "texto": "Y acudiendo Felipe, le oyó que leía el profeta Isaías, y dijo: Mas ¿entiendes lo que lees?"}, {"numero": 31, "texto": "Y él dijo: ¿Y cómo podré, si alguno no me enseñare? Y rogó á Felipe que subiese, y se sentase con él."}, {"numero": 32, "texto": "Y el lugar de la Escritura que leía, era éste: Como oveja á la muerte fué llevado; y como cordero mudo delante del que le trasquila, así no abrió su boca:"}, {"numero": 33, "texto": "En su humillación su juicio fué quitado: mas su generación, ¿quién la contará? porque es quitada de la tierra su vida."}, {"numero": 34, "texto": "Y respondiendo el eunuco á Felipe, dijo: Ruégote ¿de quién el profeta dice esto? ¿de sí, ó de otro alguno?"}, {"numero": 35, "texto": "Entonces Felipe, abriendo su boca, y comenzando desde esta escritura, le anunció el evangelio de Jesús."}, {"numero": 36, "texto": "Y yendo por el camino, llegaron á cierta agua; y dijo el eunuco: He aquí agua; ¿qué impide que yo sea bautizado?"}, {"numero": 37, "texto": "Y Felipe dijo: Si crees de todo corazón, bien puedes. Y respondiendo, dijo: Creo que Jesucristo es el Hijo de Dios."}, {"numero": 38, "texto": "Y mandó parar el carro: y descendieron ambos al agua, Felipe y el eunuco; y bautizóle."}, {"numero": 39, "texto": "Y como subieron del agua, el Espíritu del Señor arrebató á Felipe; y no le vió más el eunuco, y se fué por su camino gozoso."}, {"numero": 40, "texto": "Felipe empero se halló en Azoto: y pasando, anunciaba el evangelio en todas las ciudades, hasta que llegó á Cesarea."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 9, 'pt', '[{"numero": 1, "texto": "E Saulo, ainda assoprando ameaças e mortes contra os discípulos do Senhor, foi ao chefe dos sacerdotes."}, {"numero": 2, "texto": "E pediu-lhe cartas para Damasco, para as sinagogas, para que se achasse alguns deste caminho, tanto homens como mulheres, ele [os] trouxesse presos a Jerusalém."}, {"numero": 3, "texto": "E indo, aconteceu que chegando perto de Damasco, repentinamente brilhou ao redor dele uma luz do céu."}, {"numero": 4, "texto": "E caindo em terra, ouviu ma voz lhe dizendo: Saulo, Saulo, por que me persegues?"}, {"numero": 5, "texto": "E ele disse: Quem és, Senhor?E o Senhor disse: Eu sou Jesus, a quem tu persegues; duro é para ti dar coices contra os aguilhões."}, {"numero": 6, "texto": "E ele, tremendo e atônito, disse: Senhor, que queres que eu faça?E o Senhor lhe [disse] : Levanta-te, e entra na cidade; e [ali] te será dito o que deves fazer."}, {"numero": 7, "texto": "E os homens que viajavam com ele pararam emudecidos, ouvindo, de fato, a voz, porém não vendo ninguém."}, {"numero": 8, "texto": "E Saulo se levantou da terra e, tendo aberto seus olhos, não via ninguém; e sendo guiado pela mão, levaram-no a Damasco."}, {"numero": 9, "texto": "E ele estava três dias sem ver; e não comeu, nem bebeu."}, {"numero": 10, "texto": "E havia em Damasco um certo discípulo, de nome Ananias; e disse-lhe o Senhor em visão: Ananias!E ele respondeu: Eis-me aqui, Senhor!"}, {"numero": 11, "texto": "E o Senhor lhe [disse] : Levanta-te, e vai a rua chamada Direita, e pergunta na casa de Judas por um chamado Saulo, de Tarso; porque que ele ora."}, {"numero": 12, "texto": "E ele viu em visão que um homem, de nome Ananias, entrava, e sobre ele punha a mão, para que voltasse a ver."}, {"numero": 13, "texto": "E Ananias respondeu: Senhor, eu ouvi de muitos sobre este homem, quantos males ele tem feito aos teus santos em Jerusalém;"}, {"numero": 14, "texto": "E aqui ele tem poder dos chefes dos sacerdotes para prender a todos os que invocam o teu nome."}, {"numero": 15, "texto": "Mas o Senhor lhe disse: Vai, porque este me é um vaso escolhido para levar meu nome diante dos gentios, e dos reis, e dos filhos de Israel;"}, {"numero": 16, "texto": "Porque eu mostrarei a ele o quanto ele deve sofrer por causa do meu nome."}, {"numero": 17, "texto": "E Ananias foi, e entrou na casa; e pondo as mãos sobre ele, disse: Irmão Saulo, o Senhor, [que é] Jesus, aquele que apareceu a ti no caminho, me enviou para que tu voltes a ver, e sejas cheio do Espírito Santo."}, {"numero": 18, "texto": "E logo lhe caíram como que escamas dos olhos, e imediatamente voltou a ver; e levantando-se, foi batizado."}, {"numero": 19, "texto": "E ao comer, ele se fortaleceu. E Saulo ficou alguns dias com os discípulos [que estavam] em Damasco."}, {"numero": 20, "texto": "E logo nas sinagogas pregava a Cristo, [dizendo] que aquele era o Filho de Deus."}, {"numero": 21, "texto": "E todos os que o ouviam ficavam admirados, e diziam: Não é este aquele que em Jerusalém tentava destruir aos que invocavam este nome? E [não foi] para isso [que] ele veio aqui, para os levar presos aos chefes dos sacerdotes?"}, {"numero": 22, "texto": "Mas Saulo se esforçava muito mais, e confundia aos judeus que habitavam em Damasco, provando que aquele era o Cristo."}, {"numero": 23, "texto": "E passados vários dias, os judeus tiveram conselho entre si para o matarem."}, {"numero": 24, "texto": "Mas as ciladas deles foram conhecidas por Saulo; e eles vigiavam as portas, tanto de dia como de noite, para poderem matá-lo."}, {"numero": 25, "texto": "Porém os discípulos, tomando-o de noite, levaram-no abaixo pelo muro em um cesto."}, {"numero": 26, "texto": "E Saulo, tendo vindo a Jerusalém, procurava se juntar aos discípulos; mas todos tinham medo dele, não crendo que fosse discípulo."}, {"numero": 27, "texto": "Mas Barnabás, tomando-o consigo, trouxe [-o] aos apóstolos, e contou-lhes como no caminho tinha visto ao Senhor, e tinha lhe falado, e como em Damasco tinha falado ousadamente no nome de Jesus."}, {"numero": 28, "texto": "E ele estava junto deles, entrando e saindo em Jerusalém;"}, {"numero": 29, "texto": "E falando ousadamente no nome do Senhor Jesus; falava e discutia também contra os gregos; mas eles procuravam matá-lo."}, {"numero": 30, "texto": "E os irmãos, ao perceberem [isto] , o levaram até Cesareia, e o enviaram a Tarso."}, {"numero": 31, "texto": "Então as igrejas por toda a Judeia, e Galileia, e Samaria, tinham paz, e eram edificadas; e andando no temor do Senhor, e [na] consolação do Espírito Santo, se multiplicavam."}, {"numero": 32, "texto": "E aconteceu que, Pedro, passando por todos [os lugares] , veio também aos santos que habitavam em Lida."}, {"numero": 33, "texto": "E ali ele achou a um certo homem chamado Enéas, que havia oito anos que jazia numa cama, que era paralítico."}, {"numero": 34, "texto": "E Pedro lhe disse: Enéas, Jesus Cristo te cura; levanta-te, e faz tua cama. E logo ele se levantou."}, {"numero": 35, "texto": "E todos os que habitavam em Lida e Sarona o viram, os quais se converteram ao Senhor."}, {"numero": 36, "texto": "E havia em Jope uma certa discípula, de nome Tabita, que traduzido se diz Dorcas. Esta estava cheia de boas obras e doações que ela fazia [aos necessitados] ."}, {"numero": 37, "texto": "E aconteceu naqueles dias, que tendo ela ficado doente, morreu; e tendo a lavado, puseram-na no compartimento superior."}, {"numero": 38, "texto": "E como Lida era perto de Jope, os discípulos, ao ouvirem que Pedro estava ali, mandaram-lhe dois homens, rogando [-lhe] que não demorasse a vir a eles."}, {"numero": 39, "texto": "E Pedro, tendo se levantado, foi com eles; o qual chegou, e [o] levaram ao compartimento superior, e todas as viúvas o rodearam, chorando, e mostrando [-lhe] as túnicas e roupas que Dorcas tinha feito quando estava com elas."}, {"numero": 40, "texto": "Mas Pedro, pondo para fora a todas; pôs-se de joelhos, e orou; e virando-se para o corpo, disse: Tabita, levanta-te;E ela abriu seus olhos, e vendo a Pedro, sentou-se."}, {"numero": 41, "texto": "E ele, dando-lhe a mão, levantou-a; e tendo chamado aos santos, e às viúvas, apresentou-a viva."}, {"numero": 42, "texto": "E isto ficou conhecido por toda Jope, e muitos creram no Senhor."}, {"numero": 43, "texto": "E aconteceu que ele ficou muitos dias em Jope, com um certo Simão curtidor."}]'::jsonb, 'Almeida Livre'),
  ('At', 9, 'en', '[{"numero": 1, "texto": "And Saul, yet breathing out threatenings and slaughter against the disciples of the Lord, went unto the high priest,"}, {"numero": 2, "texto": "And desired of him letters to Damascus to the synagogues, that if he found any of this way, whether they were men or women, he might bring them bound unto Jerusalem."}, {"numero": 3, "texto": "And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven:"}, {"numero": 4, "texto": "And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?"}, {"numero": 5, "texto": "And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks."}, {"numero": 6, "texto": "And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do."}, {"numero": 7, "texto": "And the men which journeyed with him stood speechless, hearing a voice, but seeing no man."}, {"numero": 8, "texto": "And Saul arose from the earth; and when his eyes were opened, he saw no man: but they led him by the hand, and brought him into Damascus."}, {"numero": 9, "texto": "And he was three days without sight, and neither did eat nor drink."}, {"numero": 10, "texto": "And there was a certain disciple at Damascus, named Ananias; and to him said the Lord in a vision, Ananias. And he said, Behold, I am here, Lord."}, {"numero": 11, "texto": "And the Lord said unto him, Arise, and go into the street which is called Straight, and enquire in the house of Judas for one called Saul, of Tarsus: for, behold, he prayeth,"}, {"numero": 12, "texto": "And hath seen in a vision a man named Ananias coming in, and putting his hand on him, that he might receive his sight."}, {"numero": 13, "texto": "Then Ananias answered, Lord, I have heard by many of this man, how much evil he hath done to thy saints at Jerusalem:"}, {"numero": 14, "texto": "And here he hath authority from the chief priests to bind all that call on thy name."}, {"numero": 15, "texto": "But the Lord said unto him, Go thy way: for he is a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel:"}, {"numero": 16, "texto": "For I will shew him how great things he must suffer for my name''s sake."}, {"numero": 17, "texto": "And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost."}, {"numero": 18, "texto": "And immediately there fell from his eyes as it had been scales: and he received sight forthwith, and arose, and was baptized."}, {"numero": 19, "texto": "And when he had received meat, he was strengthened. Then was Saul certain days with the disciples which were at Damascus."}, {"numero": 20, "texto": "And straightway he preached Christ in the synagogues, that he is the Son of God."}, {"numero": 21, "texto": "But all that heard him were amazed, and said; Is not this he that destroyed them which called on this name in Jerusalem, and came hither for that intent, that he might bring them bound unto the chief priests?"}, {"numero": 22, "texto": "But Saul increased the more in strength, and confounded the Jews which dwelt at Damascus, proving that this is very Christ."}, {"numero": 23, "texto": "And after that many days were fulfilled, the Jews took counsel to kill him:"}, {"numero": 24, "texto": "But their laying await was known of Saul. And they watched the gates day and night to kill him."}, {"numero": 25, "texto": "Then the disciples took him by night, and let him down by the wall in a basket."}, {"numero": 26, "texto": "And when Saul was come to Jerusalem, he assayed to join himself to the disciples: but they were all afraid of him, and believed not that he was a disciple."}, {"numero": 27, "texto": "But Barnabas took him, and brought him to the apostles, and declared unto them how he had seen the Lord in the way, and that he had spoken to him, and how he had preached boldly at Damascus in the name of Jesus."}, {"numero": 28, "texto": "And he was with them coming in and going out at Jerusalem."}, {"numero": 29, "texto": "And he spake boldly in the name of the Lord Jesus, and disputed against the Grecians: but they went about to slay him."}, {"numero": 30, "texto": "Which when the brethren knew, they brought him down to Caesarea, and sent him forth to Tarsus."}, {"numero": 31, "texto": "Then had the churches rest throughout all Judaea and Galilee and Samaria, and were edified; and walking in the fear of the Lord, and in the comfort of the Holy Ghost, were multiplied."}, {"numero": 32, "texto": "And it came to pass, as Peter passed throughout all quarters, he came down also to the saints which dwelt at Lydda."}, {"numero": 33, "texto": "And there he found a certain man named Aeneas, which had kept his bed eight years, and was sick of the palsy."}, {"numero": 34, "texto": "And Peter said unto him, Aeneas, Jesus Christ maketh thee whole: arise, and make thy bed. And he arose immediately."}, {"numero": 35, "texto": "And all that dwelt at Lydda and Saron saw him, and turned to the Lord."}, {"numero": 36, "texto": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did."}, {"numero": 37, "texto": "And it came to pass in those days, that she was sick, and died: whom when they had washed, they laid her in an upper chamber."}, {"numero": 38, "texto": "And forasmuch as Lydda was nigh to Joppa, and the disciples had heard that Peter was there, they sent unto him two men, desiring him that he would not delay to come to them."}, {"numero": 39, "texto": "Then Peter arose and went with them. When he was come, they brought him into the upper chamber: and all the widows stood by him weeping, and shewing the coats and garments which Dorcas made, while she was with them."}, {"numero": 40, "texto": "But Peter put them all forth, and kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up."}, {"numero": 41, "texto": "And he gave her his hand, and lifted her up, and when he had called the saints and widows, presented her alive."}, {"numero": 42, "texto": "And it was known throughout all Joppa; and many believed in the Lord."}, {"numero": 43, "texto": "And it came to pass, that he tarried many days in Joppa with one Simon a tanner."}]'::jsonb, 'King James Version'),
  ('At', 9, 'fr', '[{"numero": 1, "texto": "Cependant Saul, respirant encore la menace et le meurtre contre les disciples du Seigneur, se rendit chez le souverain sacrificateur,"}, {"numero": 2, "texto": "et lui demanda des lettres pour les synagogues de Damas, afin que, s''''il trouvait des partisans de la nouvelle doctrine, hommes ou femmes, il les amenât liés à Jérusalem."}, {"numero": 3, "texto": "Comme il était en chemin, et qu''''il approchait de Damas, tout à coup une lumière venant du ciel resplendit autour de lui."}, {"numero": 4, "texto": "Il tomba par terre, et il entendit une voix qui lui disait: Saul, Saul, pourquoi me persécutes-tu?"}, {"numero": 5, "texto": "Il répondit: Qui es-tu, Seigneur? Et le Seigneur dit: Je suis Jésus que tu persécutes. Il te serait dur de regimber contre les aiguillons."}, {"numero": 6, "texto": "Tremblant et saisi d''''effroi, il dit: Seigneur, que veux-tu que je fasse? Et le Seigneur lui dit: Lève-toi, entre dans la ville, et on te dira ce que tu dois faire."}, {"numero": 7, "texto": "Les hommes qui l''''accompagnaient demeurèrent stupéfaits; ils entendaient bien la voix, mais ils ne voyaient personne."}, {"numero": 8, "texto": "Saul se releva de terre, et, quoique ses yeux fussent ouverts, il ne voyait rien; on le prit par la main, et on le conduisit à Damas."}, {"numero": 9, "texto": "Il resta trois jours sans voir, et il ne mangea ni ne but."}, {"numero": 10, "texto": "Or, il y avait à Damas un disciple nommé Ananias. Le Seigneur lui dit dans une vision: Ananias! Il répondit: Me voici, Seigneur!"}, {"numero": 11, "texto": "Et le Seigneur lui dit: Lève-toi, va dans la rue qu''''on appelle la droite, et cherche, dans la maison de Judas, un nommé Saul de Tarse. Car il prie,"}, {"numero": 12, "texto": "et il a vu en vision un homme du nom d''''Ananias, qui entrait, et qui lui imposait les mains, afin qu''''il recouvrât la vue."}, {"numero": 13, "texto": "Ananias répondit: Seigneur, j''''ai appris de plusieurs personnes tous les maux que cet homme a faits à tes saints dans Jérusalem;"}, {"numero": 14, "texto": "et il a ici des pouvoirs, de la part des principaux sacrificateurs, pour lier tous ceux qui invoquent ton nom."}, {"numero": 15, "texto": "Mais le Seigneur lui dit: Va, car cet homme est un instrument que j''''ai choisi, pour porter mon nom devant les nations, devant les rois, et devant les fils d''''Israël;"}, {"numero": 16, "texto": "et je lui montrerai tout ce qu''''il doit souffrir pour mon nom."}, {"numero": 17, "texto": "Ananias sortit; et, lorsqu''''il fut arrivé dans la maison, il imposa les mains à Saul, en disant: Saul, mon frère, le Seigneur Jésus, qui t''''est apparu sur le chemin par lequel tu venais, m''''a envoyé pour que tu recouvres la vue et que tu sois rempli du Saint-Esprit."}, {"numero": 18, "texto": "Au même instant, il tomba de ses yeux comme des écailles, et il recouvra la vue. Il se leva, et fut baptisé;"}, {"numero": 19, "texto": "et, après qu''''il eut pris de la nourriture, les forces lui revinrent. Saul resta quelques jours avec les disciples qui étaient à Damas."}, {"numero": 20, "texto": "Et aussitôt il prêcha dans les synagogues que Jésus est le Fils de Dieu."}, {"numero": 21, "texto": "Tous ceux qui l''''entendaient étaient dans l''''étonnement, et disaient: N''''est-ce pas celui qui persécutait à Jérusalem ceux qui invoquent ce nom, et n''''est-il pas venu ici pour les emmener liés devant les principaux sacrificateurs?"}, {"numero": 22, "texto": "Cependant Saul se fortifiait de plus en plus, et il confondait les Juifs qui habitaient Damas, démontrant que Jésus est le Christ."}, {"numero": 23, "texto": "Au bout d''''un certain temps, les Juifs se concertèrent pour le tuer,"}, {"numero": 24, "texto": "et leur complot parvint à la connaissance de Saul. On gardait les portes jour et nuit, afin de lui ôter la vie."}, {"numero": 25, "texto": "Mais, pendant une nuit, les disciples le prirent, et le descendirent par la muraille, dans une corbeille."}, {"numero": 26, "texto": "Lorsqu''''il se rendit à Jérusalem, Saul tâcha de se joindre à eux; mais tous le craignaient, ne croyant pas qu''''il fût un disciple."}, {"numero": 27, "texto": "Alors Barnabas, l''''ayant pris avec lui, le conduisit vers les apôtres, et leur raconta comment sur le chemin Saul avait vu le Seigneur, qui lui avait parlé, et comment à Damas il avait prêché franchement au nom de Jésus."}, {"numero": 28, "texto": "Il allait et venait avec eux dans Jérusalem,"}, {"numero": 29, "texto": "et s''''exprimait en toute assurance au nom du Seigneur. Il parlait aussi et disputait avec les Hellénistes; mais ceux-ci cherchaient à lui ôter la vie."}, {"numero": 30, "texto": "Les frères, l''''ayant su, l''''emmenèrent à Césarée, et le firent partir pour Tarse."}, {"numero": 31, "texto": "L''''Eglise était en paix dans toute la Judée, la Galilée et la Samarie, s''''édifiant et marchant dans la crainte du Seigneur, et elle s''''accroissait par l''''assistance du Saint-Esprit."}, {"numero": 32, "texto": "Comme Pierre visitait tous les saints, il descendit aussi vers ceux qui demeuraient à Lydde."}, {"numero": 33, "texto": "Il y trouva un homme nommé Enée, couché sur un lit depuis huit ans, et paralytique."}, {"numero": 34, "texto": "Pierre lui dit: Enée, Jésus-Christ te guérit; lève-toi, et arrange ton lit. Et aussitôt il se leva."}, {"numero": 35, "texto": "Tous les habitants de Lydde et du Saron le virent, et ils se convertirent au Seigneur."}, {"numero": 36, "texto": "Il y avait à Joppé, parmi les disciples, une femme nommée Tabitha, ce qui signifie Dorcas: elle faisait beaucoup de bonnes oeuvres et d''''aumônes."}, {"numero": 37, "texto": "Elle tomba malade en ce temps-là, et mourut. Après l''''avoir lavée, on la déposa dans une chambre haute."}, {"numero": 38, "texto": "Comme Lydde est près de Joppé, les disciples, ayant appris que Pierre s''''y trouvait, envoyèrent deux hommes vers lui, pour le prier de venir chez eux sans tarder."}, {"numero": 39, "texto": "Pierre se leva, et partit avec ces hommes. Lorsqu''''il fut arrivé, on le conduisit dans la chambre haute. Toutes les veuves l''''entourèrent en pleurant, et lui montrèrent les tuniques et les vêtements que faisait Dorcas pendant qu''''elle était avec elles."}, {"numero": 40, "texto": "Pierre fit sortir tout le monde, se mit à genoux, et pria; puis, se tournant vers le corps, il dit: Tabitha, lève-toi! Elle ouvrit les yeux, et ayant vu Pierre, elle s''''assit."}, {"numero": 41, "texto": "Il lui donna la main, et la fit lever. Il appela ensuite les saints et les veuves, et la leur présenta vivante."}, {"numero": 42, "texto": "Cela fut connu de tout Joppé, et beaucoup crurent au Seigneur."}, {"numero": 43, "texto": "Pierre demeura quelque temps à Joppé, chez un corroyeur nommé Simon."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 9, 'es', '[{"numero": 1, "texto": "Y SAULO, respirando aún amenazas y muerte contra los discípulos del Señor, vino al príncipe de los sacerdotes,"}, {"numero": 2, "texto": "Y demandó de él letras para Damasco á las sinagogas, para que si hallase algunos hombres ó mujeres de esta secta, los trajese presos á Jerusalem."}, {"numero": 3, "texto": "Y yendo por el camino, aconteció que llegando cerca de Damasco, súbitamente le cercó un resplandor de luz del cielo;"}, {"numero": 4, "texto": "Y cayendo en tierra, oyó una voz que le decía: Saulo, Saulo, ¿por qué me persigues?"}, {"numero": 5, "texto": "Y él dijo: ¿Quién eres, Señor? Y él dijo: Yo soy Jesús á quien tú persigues: dura cosa te es dar coces contra el aguijón."}, {"numero": 6, "texto": "El, temblando y temeroso, dijo: Señor, ¿qué quieres que haga? Y el Señor le dice: Levántate y entra en la ciudad, y se te dirá lo que te conviene hacer."}, {"numero": 7, "texto": "Y los hombres que iban con Saulo, se pararon atónitos, oyendo á la verdad la voz, mas no viendo á nadie."}, {"numero": 8, "texto": "Entonces Saulo se levantó de tierra, y abriendo los ojos, no veía á nadie: así que, llevándole por la mano, metiéronle en Damasco;"}, {"numero": 9, "texto": "Donde estuvo tres días sin ver, y no comió, ni bebió."}, {"numero": 10, "texto": "Había entonces un discípulo en Damasco llamado Ananías, al cual el Señor dijo en visión: Ananías. Y él respondió: Heme aquí, Señor."}, {"numero": 11, "texto": "Y el Señor le dijo: Levántate, y ve á la calle que se llama la Derecha, y busca en casa de Judas á uno llamado Saulo, de Tarso: porque he aquí, él ora;"}, {"numero": 12, "texto": "Y ha visto en visión un varón llamado Ananías, que entra y le pone la mano encima, para que reciba la vista."}, {"numero": 13, "texto": "Entonces Ananías respondió: Señor, he oído á muchos acerca de este hombre, cuántos males ha hecho á tus santos en Jerusalem:"}, {"numero": 14, "texto": "Y aun aquí tiene facultad de los príncipes de los sacerdotes de prender á todos los que invocan tu nombre."}, {"numero": 15, "texto": "Y le dijo el Señor: Ve: porque instrumento escogido me es éste, para que lleve mi nombre en presencia de los Gentiles, y de reyes, y de los hijos de Israel:"}, {"numero": 16, "texto": "Porque yo le mostraré cuánto le sea menester que padezca por mi nombre."}, {"numero": 17, "texto": "Ananías entonces fué, y entró en la casa, y poniéndole las manos encima, dijo: Saulo hermano, el Señor Jesús, que te apareció en el camino por donde venías, me ha enviado para que recibas la vista y seas lleno de Espíritu Santo."}, {"numero": 18, "texto": "Y luego le cayeron de los ojos como escamas, y recibió al punto la vista: y levantándose, fué bautizado."}, {"numero": 19, "texto": "Y como comió, fué confortado. Y estuvo Saulo por algunos días con los discípulos que estaban en Damasco."}, {"numero": 20, "texto": "Y luego en las sinagogas predicaba á Cristo, diciendo que éste era el Hijo de Dios."}, {"numero": 21, "texto": "Y todos los que le oían estaban atónitos, y decían: ¿No es éste el que asolaba en Jerusalem á los que invocaban este nombre, y á eso vino acá, para llevarlos presos á los príncipes de los sacerdotes?"}, {"numero": 22, "texto": "Empero Saulo mucho más se esforzaba, y confundía á los Judíos que moraban en Damasco, afirmando que éste es el Cristo."}, {"numero": 23, "texto": "Y como pasaron muchos días, los Judíos hicieron entre sí consejo de matarle;"}, {"numero": 24, "texto": "Mas las asechanzas de ellos fueron entendidas de Saulo. Y ellos guardaban las puertas de día y de noche para matarle."}, {"numero": 25, "texto": "Entonces los discípulos, tomándole de noche, le bajaron por el muro en una espuerta."}, {"numero": 26, "texto": "Y como vino á Jerusalem, tentaba de juntarse con los discípulos; mas todos tenían miedo de él, no creyendo que era discípulo."}, {"numero": 27, "texto": "Entonces Bernabé, tomándole, lo trajo á los apóstoles, y contóles cómo había visto al Señor en el camino, y que le había hablado, y cómo en Damasco había hablado confiadamente en el nombre de Jesús."}, {"numero": 28, "texto": "Y entraba y salía con ellos en Jerusalem;"}, {"numero": 29, "texto": "Y hablaba confiadamente en el nombre del Señor: y disputaba con los Griegos; mas ellos procuraban matarle."}, {"numero": 30, "texto": "Lo cual, como los hermanos entendieron, le acompañaron hasta Cesarea, y le enviaron á Tarso."}, {"numero": 31, "texto": "Las iglesias entonces tenían paz por toda Judea y Galilea y Samaria, y eran edificadas, andando en el temor del Señor; y con consuelo del Espíritu Santo eran multiplicadas."}, {"numero": 32, "texto": "Y aconteció que Pedro, andándolos á todos, vino también á los santos que habitaban en Lydda."}, {"numero": 33, "texto": "Y halló allí á uno que se llamaba Eneas, que hacía ocho años que estaba en cama, que era paralítico."}, {"numero": 34, "texto": "Y le dijo Pedro: Eneas, Jesucristo te sana; levántate, y hazte tu cama. Y luego se levantó."}, {"numero": 35, "texto": "Y viéronle todos los que habitaban en Lydda y en Sarona, los cuales se convirtieron al Señor."}, {"numero": 36, "texto": "Entonces en Joppe había una discípula llamada Tabita, que si lo declaras, quiere decir Dorcas. Esta era llena de buenas obras y de limosnas que hacía."}, {"numero": 37, "texto": "Y aconteció en aquellos días que enfermando, murió; á la cual, después de lavada, pusieron en una sala."}, {"numero": 38, "texto": "Y como Lydda estaba cerca de Joppe, los discípulos, oyendo que Pedro estaba allí, le enviaron dos hombres, rogándole: No te detengas en venir hasta nosotros."}, {"numero": 39, "texto": "Pedro entonces levantándose, fué con ellos: y llegado que hubo, le llevaron á la sala, donde le rodearon todas las viudas, llorando y mostrando las túnicas y los vestidos que Dorcas hacía cuando estaba con ellas."}, {"numero": 40, "texto": "Entonces echados fuera todos, Pedro puesto de rodillas, oró; y vuelto al cuerpo, dijo: Tabita, levántate. Y ella abrió los ojos, y viendo á Pedro, incorporóse."}, {"numero": 41, "texto": "Y él le dió la mano, y levantóla: entonces llamando á los santos y las viudas, la presentó viva."}, {"numero": 42, "texto": "Esto fué notorio por toda Joppe; y creyeron muchos en el Señor."}, {"numero": 43, "texto": "Y aconteció que se quedó muchos días en Joppe en casa de un cierto Simón, curtidor."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 10, 'pt', '[{"numero": 1, "texto": "E havia um certo homem em Cesareia, de nome Cornélio, centurião, do esquadrão chamado Italiano;"}, {"numero": 2, "texto": "Devoto, e temente a Deus, com toda a sua casa; e que fazia muitas doações ao povo, e continuamente orava a Deus."}, {"numero": 3, "texto": "Ele viu claramente em visão, cerca da hora nona do dia, a um anjo de Deus, que vinha a ele, e lhe dizia: Cornélio!"}, {"numero": 4, "texto": "E ele, olhando-lhe atentamente, e muito atemorizado, disse: O que é, Senhor?E disse-lhe: Tuas orações e doações subiram à memória diante de Deus."}, {"numero": 5, "texto": "E agora envia homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro."}, {"numero": 6, "texto": "Este está hospedado na casa de um Simão curtidor, cuja casa é junto ao mar; este te dirá o que deves fazer."}, {"numero": 7, "texto": "E tendo partido o anjo que falava com Cornélio, ele chamou a dois de seus servos, e a um soldado devoto, dos que permaneciam continuamente com ele."}, {"numero": 8, "texto": "E tendo lhes contado tudo, enviou-os a Jope."}, {"numero": 9, "texto": "E no dia seguinte, enquanto estes iam pelo caminho, e chegando perto da cidade, Pedro subiu ao telhado para orar, quase à hora sexta."}, {"numero": 10, "texto": "E tendo ele fome, quis comer; [e] enquanto estavam [lhe] preparando, caiu sobre ele um êxtase."}, {"numero": 11, "texto": "E ele viu o céu aberto, e descia a ele um certo objeto, como um grande lençol, amarrado pelas quatro pontas, e abaixando-se à terra;"}, {"numero": 12, "texto": "Em que havia de todos os animais quadrúpedes da terra, e animais selvagens, e répteis, e aves do céu."}, {"numero": 13, "texto": "E veio-lhe uma voz, [dizendo] : Pedro, mata e come."}, {"numero": 14, "texto": "Mas Pedro disse: De maneira nenhuma, Senhor; porque nunca comi coisa alguma ordinária ou impura."}, {"numero": 15, "texto": "E a voz voltou a [dizer] ,pela segunda vez: O que Deus purificou, não faças tu [como se fosse] ordinário."}, {"numero": 16, "texto": "E isto aconteceu três vezes; e o objeto voltou a ser recolhido acima ao céu."}, {"numero": 17, "texto": "E enquanto Pedro estava pensando perplexo consigo mesmo o que seria aquela visão que ele tinha visto, eis que os homens que tinham sido enviados por Cornélio, perguntando pela casa de Simão, pararam à porta."}, {"numero": 18, "texto": "E chamando, perguntaram se Simão, que tinha por sobrenome Pedro, estava hospedado ali."}, {"numero": 19, "texto": "E estando Pedro pensando naquela visão, o Espírito lhe disse: Eis que três homens te buscam."}, {"numero": 20, "texto": "Então levanta-te, desce, e vai com eles, sem duvidar; porque eu os enviei."}, {"numero": 21, "texto": "E Pedro, tendo descido aos homens que tinham lhe sido enviados por Cornélio, disse: Eis que eu sou a quem buscais; qual é o motivo pelo qual estais aqui?"}, {"numero": 22, "texto": "E eles disseram: Cornélio, [que é] centurião, homem justo e temente a Deus, [e] que tem [bom] testemunho de toda a nação dos judeus, foi revelado por um santo anjo para te chamar até a casa dele, e ouvir de tuas palavras."}, {"numero": 23, "texto": "Então chamando-os para dentro, recebeu-os em casa. Mas no dia seguinte, Pedro foi com eles; e foram com ele alguns dos irmãos de Jope."}, {"numero": 24, "texto": "E no dia seguinte chegaram a Cesareia. E Cornélio estava esperando por eles, tendo chamado a seus parentes e amigos mais íntimos."}, {"numero": 25, "texto": "E sucedeu que, ao Pedro entrar, Cornélio se encontrou com ele, e caindo aos pés dele, adorou-o."}, {"numero": 26, "texto": "Mas Pedro o levantou, dizendo: Levanta-te; eu mesmo também sou um ser humano."}, {"numero": 27, "texto": "E tendo conversado com ele, entrou; e achou a muitos que [ali] tinham se reunido."}, {"numero": 28, "texto": "E disse-lhes: Vós sabeis como não é lícito a um homem judeu juntar-se de estrangeiros, ou aproximar-se deles; mas Deus me mostrou que a ninguém chame de ordinário ou impuro."}, {"numero": 29, "texto": "Portanto eu, tendo sido chamado, vim sem qualquer oposição [de minha parte] . Então eu pergunto: por que motivo me mandastes chamar?"}, {"numero": 30, "texto": "E Cornélio disse: Há quatro dias que, até esta hora eu estava jejuando, e orava à hora nona em minha casa."}, {"numero": 31, "texto": "E eis que um homem se pôs diante de mim com uma roupa brilhante, e disse: Cornélio, tura oração tem sido ouvida, e tuas doações têm sido lembradas diante de Deus."}, {"numero": 32, "texto": "Envia pois a Jope, e manda chamar a Simão, que tem por sobrenome Pedro; este se hospeda na casa de Simão o curtidor, junto ao mar; quando ele vier, falará contigo."}, {"numero": 33, "texto": "Então logo eu enviei a ti; e bem fizeste em vir até aqui; agora pois estamos todos [aqui] presentes diante de Deus, para ouvir tudo quanto Deus tem te ordenado."}, {"numero": 34, "texto": "E Pedro, abrindo a boca, disse: Reconheço que é verdade que Deus não faz acepção de pessoas."}, {"numero": 35, "texto": "Mas sim, em toda nação, aquele que o teme, e pratica a justiça, [este] lhe é agradável."}, {"numero": 36, "texto": "A palavra que Deus enviou aos filhos de Israel, anunciando o Evangelho da paz por meio de Jesus Cristo; este é o Senhor de todos."}, {"numero": 37, "texto": "Vós sabeis da palavra que veio por toda a Judeia, começando desde a Galileia, depois do batismo que João pregou."}, {"numero": 38, "texto": "[E] sobre Jesus de Nazaré; como Deus o ungiu com o Espírito Santo, e com poder; o qual percorreu [os lugares] fazendo o bem, e curando a todos os oprimidos pelo diabo; porque Deus era com ele."}, {"numero": 39, "texto": "E nós somos testemunhas de todas as coisas que ele fez; tanto na terra dos judeus, como em Jerusalém; ao qual mataram, pendurando [-o] em um madeiro."}, {"numero": 40, "texto": "A este Deus ressuscitou ao terceiro dia, e fez com que fosse manifesto;"}, {"numero": 41, "texto": "Não a todo o povo, mas sim a testemunhas determinadas por Deus com antecedência: a nós, que juntamente com ele comemos e bebemos, depois dele ter ressuscitado dos mortos."}, {"numero": 42, "texto": "E ele nos mandou pregar ao povo, e dar testemunho de que ele é o que foi ordenado por Deus [para ser] Juiz dos vivos e dos mortos."}, {"numero": 43, "texto": "A este todos os profetas dão testemunho, de que todos os que nele crerem receberão perdão dos pecados por meio do seu nome."}, {"numero": 44, "texto": "E estando Pedro ainda falando estas palavras, o Espírito Santo caiu sobre todos os que ouviam a palavra."}, {"numero": 45, "texto": "E os crentes que eram da circuncisão, tantos quantos tinham vindo com Pedro, ficaram muito admirados de que também sobre os gentios fosse derramado o dom do Espírito Santo."}, {"numero": 46, "texto": "Porque eles os ouviam falar em [diversas] línguas, e a engrandecer a Deus. Então Pedro respondeu:"}, {"numero": 47, "texto": "Por acaso pode alguém impedir a água, para que não sejam batizados estes, que também, assim como nós, receberam o Espírito Santo?"}, {"numero": 48, "texto": "E mandou que fossem batizados no nome do Senhor. Então lhe pediram que continuasse [com eles] por alguns dias."}]'::jsonb, 'Almeida Livre'),
  ('At', 10, 'en', '[{"numero": 1, "texto": "There was a certain man in Caesarea called Cornelius, a centurion of the band called the Italian band,"}, {"numero": 2, "texto": "A devout man, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway."}, {"numero": 3, "texto": "He saw in a vision evidently about the ninth hour of the day an angel of God coming in to him, and saying unto him, Cornelius."}, {"numero": 4, "texto": "And when he looked on him, he was afraid, and said, What is it, Lord? And he said unto him, Thy prayers and thine alms are come up for a memorial before God."}, {"numero": 5, "texto": "And now send men to Joppa, and call for one Simon, whose surname is Peter:"}, {"numero": 6, "texto": "He lodgeth with one Simon a tanner, whose house is by the sea side: he shall tell thee what thou oughtest to do."}, {"numero": 7, "texto": "And when the angel which spake unto Cornelius was departed, he called two of his household servants, and a devout soldier of them that waited on him continually;"}, {"numero": 8, "texto": "And when he had declared all these things unto them, he sent them to Joppa."}, {"numero": 9, "texto": "On the morrow, as they went on their journey, and drew nigh unto the city, Peter went up upon the housetop to pray about the sixth hour:"}, {"numero": 10, "texto": "And he became very hungry, and would have eaten: but while they made ready, he fell into a trance,"}, {"numero": 11, "texto": "And saw heaven opened, and a certain vessel descending upon him, as it had been a great sheet knit at the four corners, and let down to the earth:"}, {"numero": 12, "texto": "Wherein were all manner of fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air."}, {"numero": 13, "texto": "And there came a voice to him, Rise, Peter; kill, and eat."}, {"numero": 14, "texto": "But Peter said, Not so, Lord; for I have never eaten any thing that is common or unclean."}, {"numero": 15, "texto": "And the voice spake unto him again the second time, What God hath cleansed, that call not thou common."}, {"numero": 16, "texto": "This was done thrice: and the vessel was received up again into heaven."}, {"numero": 17, "texto": "Now while Peter doubted in himself what this vision which he had seen should mean, behold, the men which were sent from Cornelius had made enquiry for Simon''s house, and stood before the gate,"}, {"numero": 18, "texto": "And called, and asked whether Simon, which was surnamed Peter, were lodged there."}, {"numero": 19, "texto": "While Peter thought on the vision, the Spirit said unto him, Behold, three men seek thee."}, {"numero": 20, "texto": "Arise therefore, and get thee down, and go with them, doubting nothing: for I have sent them."}, {"numero": 21, "texto": "Then Peter went down to the men which were sent unto him from Cornelius; and said, Behold, I am he whom ye seek: what is the cause wherefore ye are come?"}, {"numero": 22, "texto": "And they said, Cornelius the centurion, a just man, and one that feareth God, and of good report among all the nation of the Jews, was warned from God by an holy angel to send for thee into his house, and to hear words of thee."}, {"numero": 23, "texto": "Then called he them in, and lodged them. And on the morrow Peter went away with them, and certain brethren from Joppa accompanied him."}, {"numero": 24, "texto": "And the morrow after they entered into Caesarea. And Cornelius waited for them, and he had called together his kinsmen and near friends."}, {"numero": 25, "texto": "And as Peter was coming in, Cornelius met him, and fell down at his feet, and worshipped him."}, {"numero": 26, "texto": "But Peter took him up, saying, Stand up; I myself also am a man."}, {"numero": 27, "texto": "And as he talked with him, he went in, and found many that were come together."}, {"numero": 28, "texto": "And he said unto them, Ye know how that it is an unlawful thing for a man that is a Jew to keep company, or come unto one of another nation; but God hath shewed me that I should not call any man common or unclean."}, {"numero": 29, "texto": "Therefore came I unto you without gainsaying, as soon as I was sent for: I ask therefore for what intent ye have sent for me?"}, {"numero": 30, "texto": "And Cornelius said, Four days ago I was fasting until this hour; and at the ninth hour I prayed in my house, and, behold, a man stood before me in bright clothing,"}, {"numero": 31, "texto": "And said, Cornelius, thy prayer is heard, and thine alms are had in remembrance in the sight of God."}, {"numero": 32, "texto": "Send therefore to Joppa, and call hither Simon, whose surname is Peter; he is lodged in the house of one Simon a tanner by the sea side: who, when he cometh, shall speak unto thee."}, {"numero": 33, "texto": "Immediately therefore I sent to thee; and thou hast well done that thou art come. Now therefore are we all here present before God, to hear all things that are commanded thee of God."}, {"numero": 34, "texto": "Then Peter opened his mouth, and said, Of a truth I perceive that God is no respecter of persons:"}, {"numero": 35, "texto": "But in every nation he that feareth him, and worketh righteousness, is accepted with him."}, {"numero": 36, "texto": "The word which God sent unto the children of Israel, preaching peace by Jesus Christ: (he is Lord of all:)"}, {"numero": 37, "texto": "That word, I say, ye know, which was published throughout all Judaea, and began from Galilee, after the baptism which John preached;"}, {"numero": 38, "texto": "How God anointed Jesus of Nazareth with the Holy Ghost and with power: who went about doing good, and healing all that were oppressed of the devil; for God was with him."}, {"numero": 39, "texto": "And we are witnesses of all things which he did both in the land of the Jews, and in Jerusalem; whom they slew and hanged on a tree:"}, {"numero": 40, "texto": "Him God raised up the third day, and shewed him openly;"}, {"numero": 41, "texto": "Not to all the people, but unto witnesses chosen before God, even to us, who did eat and drink with him after he rose from the dead."}, {"numero": 42, "texto": "And he commanded us to preach unto the people, and to testify that it is he which was ordained of God to be the Judge of quick and dead."}, {"numero": 43, "texto": "To him give all the prophets witness, that through his name whosoever believeth in him shall receive remission of sins."}, {"numero": 44, "texto": "While Peter yet spake these words, the Holy Ghost fell on all them which heard the word."}, {"numero": 45, "texto": "And they of the circumcision which believed were astonished, as many as came with Peter, because that on the Gentiles also was poured out the gift of the Holy Ghost."}, {"numero": 46, "texto": "For they heard them speak with tongues, and magnify God. Then answered Peter,"}, {"numero": 47, "texto": "Can any man forbid water, that these should not be baptized, which have received the Holy Ghost as well as we?"}, {"numero": 48, "texto": "And he commanded them to be baptized in the name of the Lord. Then prayed they him to tarry certain days."}]'::jsonb, 'King James Version'),
  ('At', 10, 'fr', '[{"numero": 1, "texto": "Il y avait à Césarée un homme nommé Corneille, centenier dans la cohorte dite italienne."}, {"numero": 2, "texto": "Cet homme était pieux et craignait Dieu, avec toute sa maison; il faisait beaucoup d''''aumônes au peuple, et priait Dieu continuellement."}, {"numero": 3, "texto": "Vers la neuvième heure du jour, il vit clairement dans une vision un ange de Dieu qui entra chez lui, et qui lui dit: Corneille!"}, {"numero": 4, "texto": "Les regards fixés sur lui, et saisi d''''effroi, il répondit: Qu''''est-ce, Seigneur? Et l''''ange lui dit: Tes prières et tes aumônes sont montées devant Dieu, et il s''''en est souvenu."}, {"numero": 5, "texto": "Envoie maintenant des hommes à Joppé, et fais venir Simon, surnommé Pierre;"}, {"numero": 6, "texto": "il est logé chez un certain Simon, corroyeur, dont la maison est près de la mer."}, {"numero": 7, "texto": "Dès que l''''ange qui lui avait parlé fut parti, Corneille appela deux de ses serviteurs, et un soldat pieux d''''entre ceux qui étaient attachés à sa personne;"}, {"numero": 8, "texto": "et, après leur avoir tout raconté, il les envoya à Joppé."}, {"numero": 9, "texto": "Le lendemain, comme ils étaient en route, et qu''''ils approchaient de la ville, Pierre monta sur le toit, vers la sixième heure, pour prier."}, {"numero": 10, "texto": "Il eut faim, et il voulut manger. Pendant qu''''on lui préparait à manger, il tomba en extase."}, {"numero": 11, "texto": "Il vit le ciel ouvert, et un objet semblable à une grande nappe attachée par les quatre coins, qui descendait et s''''abaissait vers la terre,"}, {"numero": 12, "texto": "et où se trouvaient tous les quadrupèdes et les reptiles de la terre et les oiseaux du ciel."}, {"numero": 13, "texto": "Et une voix lui dit: Lève-toi, Pierre, tue et mange."}, {"numero": 14, "texto": "Mais Pierre dit: Non, Seigneur, car je n''''ai jamais rien mangé de souillé ni d''''impur."}, {"numero": 15, "texto": "Et pour la seconde fois la voix se fit encore entendre à lui: Ce que Dieu a déclaré pur, ne le regarde pas comme souillé."}, {"numero": 16, "texto": "Cela arriva jusqu''''à trois fois; et aussitôt après, l''''objet fut retiré dans le ciel."}, {"numero": 17, "texto": "Tandis que Pierre ne savait en lui-même que penser du sens de la vision qu''''il avait eue, voici, les hommes envoyés par Corneille, s''''étant informés de la maison de Simon, se présentèrent à la porte,"}, {"numero": 18, "texto": "et demandèrent à haute voix si c''''était là que logeait Simon, surnommé Pierre."}, {"numero": 19, "texto": "Et comme Pierre était à réfléchir sur la vision, l''''Esprit lui dit: Voici, trois hommes te demandent;"}, {"numero": 20, "texto": "lève-toi, descends, et pars avec eux sans hésiter, car c''''est moi qui les ai envoyés."}, {"numero": 21, "texto": "Pierre donc descendit, et il dit à ces hommes: Voici, je suis celui que vous cherchez; quel est le motif qui vous amène?"}, {"numero": 22, "texto": "Ils répondirent: Corneille, centenier, homme juste et craignant Dieu, et de qui toute la nation des Juifs rend un bon témoignage, a été divinement averti par un saint ange de te faire venir dans sa maison et d''''entendre tes paroles."}, {"numero": 23, "texto": "Pierre donc les fit entrer, et les logea. Le lendemain, il se leva, et partit avec eux. Quelques-uns des frères de Joppé l''''accompagnèrent."}, {"numero": 24, "texto": "Ils arrivèrent à Césarée le jour suivant. Corneille les attendait, et avait invité ses parents et ses amis intimes."}, {"numero": 25, "texto": "Lorsque Pierre entra, Corneille, qui était allé au-devant de lui, tomba à ses pieds et se prosterna."}, {"numero": 26, "texto": "Mais Pierre le releva, en disant: Lève-toi; moi aussi, je suis un homme."}, {"numero": 27, "texto": "Et conversant avec lui, il entra, et trouva beaucoup de personnes réunies."}, {"numero": 28, "texto": "Vous savez, leur dit-il, qu''''il est défendu à un Juif de se lier avec un étranger ou d''''entrer chez lui; mais Dieu m''''a appris à ne regarder aucun homme comme souillé et impur."}, {"numero": 29, "texto": "C''''est pourquoi je n''''ai pas eu d''''objection à venir, puisque vous m''''avez appelé; je vous demande donc pour quel motif vous m''''avez envoyé chercher."}, {"numero": 30, "texto": "Corneille dit: Il y a quatre jours, à cette heure-ci, je priais dans ma maison à la neuvième heure; et voici, un homme vêtu d''''un habit éclatant se présenta devant moi,"}, {"numero": 31, "texto": "et dit: Corneille, ta prière a été exaucée, et Dieu s''''est souvenu de tes aumônes."}, {"numero": 32, "texto": "Envoie donc à Joppé, et fais venir Simon, surnommé Pierre; il est logé dans la maison de Simon, corroyeur, près de la mer."}, {"numero": 33, "texto": "Aussitôt j''''ai envoyé vers toi, et tu as bien fait de venir. Maintenant donc nous sommes tous devant Dieu, pour entendre tout ce que le Seigneur t''''a ordonné de nous dire."}, {"numero": 34, "texto": "Alors Pierre, ouvrant la bouche, dit: En vérité, je reconnais que Dieu ne fait point acception de personnes,"}, {"numero": 35, "texto": "mais qu''''en toute nation celui qui le craint et qui pratique la justice lui est agréable."}, {"numero": 36, "texto": "Il a envoyé la parole aux fils d''''Israël, en leur annonçant la paix par Jésus-Christ, qui est le Seigneur de tous."}, {"numero": 37, "texto": "Vous savez ce qui est arrivé dans toute la Judée, après avoir commencé en Galilée, à la suite du baptême que Jean a prêché;"}, {"numero": 38, "texto": "vous savez comment Dieu a oint du Saint-Esprit et de force Jésus de Nazareth, qui allait de lieu en lieu faisant du bien et guérissant tous ceux qui étaient sous l''''empire du diable, car Dieu était avec lui."}, {"numero": 39, "texto": "Nous sommes témoins de tout ce qu''''il a fait dans le pays des Juifs et à Jérusalem. Ils l''''ont tué, en le pendant au bois."}, {"numero": 40, "texto": "Dieu l''''a ressuscité le troisième jour, et il a permis qu''''il apparût,"}, {"numero": 41, "texto": "non à tout le peuple, mais aux témoins choisis d''''avance par Dieu, à nous qui avons mangé et bu avec lui, après qu''''il fut ressuscité des morts."}, {"numero": 42, "texto": "Et Jésus nous a ordonné de prêcher au peuple et d''''attester que c''''est lui qui a été établi par Dieu juge des vivants et des morts."}, {"numero": 43, "texto": "Tous les prophètes rendent de lui le témoignage que quiconque croit en lui reçoit par son nom le pardon des péchés."}, {"numero": 44, "texto": "Comme Pierre prononçait encore ces mots, le Saint-Esprit descendit sur tous ceux qui écoutaient la parole."}, {"numero": 45, "texto": "Tous les fidèles circoncis qui étaient venus avec Pierre furent étonnés de ce que le don du Saint-Esprit était aussi répandu sur les païens."}, {"numero": 46, "texto": "Car ils les entendaient parler en langues et glorifier Dieu. Alors Pierre dit:"}, {"numero": 47, "texto": "Peut-on refuser l''''eau du baptême à ceux qui ont reçu le Saint-Esprit aussi bien que nous?"}, {"numero": 48, "texto": "Et il ordonna qu''''ils fussent baptisés au nom du Seigneur. Sur quoi ils le prièrent de rester quelques jours auprès d''''eux."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 10, 'es', '[{"numero": 1, "texto": "Y HABÍA un varón en Cesarea llamado Cornelio, centurión de la compañía que se llamaba la Italiana,"}, {"numero": 2, "texto": "Pío y temeroso de Dios con toda su casa, y que hacía muchas limosnas al pueblo, y oraba á Dios siempre."}, {"numero": 3, "texto": "Este vió en visión manifiestamente, como á la hora nona del día, que un ángel de Dios entraba á él, y le decía: Cornelio."}, {"numero": 4, "texto": "Y él, puestos en él los ojos, espantado, dijo: ¿Qué es, Señor? Y díjole: Tus oraciones y tus limosnas han subido en memoria á la presencia de Dios."}, {"numero": 5, "texto": "Envía pues ahora hombres á Joppe, y haz venir á un Simón, que tiene por sobrenombre Pedro."}, {"numero": 6, "texto": "Este posa en casa de un Simón, curtidor, que tiene su casa junto á la mar: él te dirá lo que te conviene hacer."}, {"numero": 7, "texto": "E ido el ángel que hablaba con Cornelio, llamó dos de sus criados, y un devoto soldado de los que le asistían;"}, {"numero": 8, "texto": "A los cuales, después de habérselo contado todo, los envió á Joppe."}, {"numero": 9, "texto": "Y al día siguiente, yendo ellos su camino, y llegando cerca de la ciudad, Pedro subió á la azotea á orar, cerca de la hora de sexta;"}, {"numero": 10, "texto": "Y aconteció que le vino una grande hambre, y quiso comer; pero mientras disponían, sobrevínole un éxtasis;"}, {"numero": 11, "texto": "Y vió el cielo abierto, y que descendía un vaso, como un gran lienzo, que atado de los cuatro cabos era bajado á la tierra;"}, {"numero": 12, "texto": "En el cual había de todos los animales cuadrúpedos de la tierra, y reptiles, y aves del cielo."}, {"numero": 13, "texto": "Y le vino una voz: Levántate, Pedro, mata y come."}, {"numero": 14, "texto": "Entonces Pedro dijo: Señor, no; porque ninguna cosa común é inmunda he comido jamás."}, {"numero": 15, "texto": "Y volvió la voz hacia él la segunda vez: Lo que Dios limpió, no lo llames tú común."}, {"numero": 16, "texto": "Y esto fué hecho por tres veces; y el vaso volvió á ser recogido en el cielo."}, {"numero": 17, "texto": "Y estando Pedro dudando dentro de sí qué sería la visión que había visto, he aquí, los hombres que habían sido enviados por Cornelio, que, preguntando por la casa de Simón, llegaron á la puerta."}, {"numero": 18, "texto": "Y llamando, preguntaron si un Simón que tenía por sobrenombre Pedro, posaba allí."}, {"numero": 19, "texto": "Y estando Pedro pensando en la visión, le dijo el Espíritu: He aquí, tres hombres te buscan."}, {"numero": 20, "texto": "Levántate, pues, y desciende, y no dudes ir con ellos; porque yo los he enviado."}, {"numero": 21, "texto": "Entonces Pedro, descendiendo á los hombres que eran enviados por Cornelio, dijo: He aquí, yo soy el que buscáis: ¿cuál es la causa por la que habéis venido?"}, {"numero": 22, "texto": "Y ellos dijeron: Cornelio, el centurión, varón justo y temeroso de Dios, y que tiene testimonio de toda la nación de los Judíos, ha recibido respuesta por un santo ángel, de hacerte venir á su casa, y oir de ti palabras."}, {"numero": 23, "texto": "Entonces metiéndolos dentro, los hospedó. Y al día siguiente, levantándose, se fué con ellos; y le acompañaron algunos de los hermanos de Joppe."}, {"numero": 24, "texto": "Y al otro día entraron en Cesarea. Y Cornelio los estaba esperando, habiendo llamado á sus parientes y los amigos más familiares."}, {"numero": 25, "texto": "Y como Pedro entró, salió Cornelio á recibirle; y derribándose á sus pies, adoró."}, {"numero": 26, "texto": "Mas Pedro le levantó, diciendo: Levántate; yo mismo también soy hombre."}, {"numero": 27, "texto": "Y hablando con él, entró, y halló á muchos que se habían juntado."}, {"numero": 28, "texto": "Y les dijo: Vosotros sabéis que es abominable á un varón Judío juntarse ó llegarse á extranjero; mas me ha mostrado Dios que á ningún hombre llame común ó inmundo;"}, {"numero": 29, "texto": "Por lo cual, llamado, he venido sin dudar. Así que pregunto: ¿por qué causa me habéis hecho venir?"}, {"numero": 30, "texto": "Entonces Cornelio dijo: Cuatro días ha que á esta hora yo estaba ayuno; y á la hora de nona estando orando en mi casa, he aquí, un varón se puso delante de mí en vestido resplandeciente."}, {"numero": 31, "texto": "Y dijo: Cornelio, tu oración es oída, y tus limosnas han venido en memoria en la presencia de Dios."}, {"numero": 32, "texto": "Envía pues á Joppe, y haz venir á un Simón, que tiene por sobrenombre Pedro; éste posa en casa de Simón, curtidor, junto á la mar; el cual venido, te hablará."}, {"numero": 33, "texto": "Así que, luego envié á ti; y tú has hecho bien en venir. Ahora pues, todos nosotros estamos aquí en la presencia de Dios, para oir todo lo que Dios te ha mandado."}, {"numero": 34, "texto": "Entonces Pedro, abriendo su boca, dijo: Por verdad hallo que Dios no hace acepción de personas;"}, {"numero": 35, "texto": "Sino que de cualquiera nación que le teme y obra justicia, se agrada."}, {"numero": 36, "texto": "Envió palabra Dios á los hijos de Israel, anunciando la paz por Jesucristo; éste es el Señor de todos."}, {"numero": 37, "texto": "Vosotros sabéis lo que fué divulgado por toda Judea; comenzando desde Galilea después del bautismo que Juan predicó,"}, {"numero": 38, "texto": "Cuanto á Jesús de Nazaret; cómo le ungió Dios de Espíritu Santo y de potencia; el cual anduvo haciendo bienes, y sanando á todos los oprimidos del diablo; porque Dios era con él."}, {"numero": 39, "texto": "Y nosotros somos testigos de todas las cosas que hizo en la tierra de Judea, y en Jerusalem; al cual mataron colgándole en un madero."}, {"numero": 40, "texto": "A éste levantó Dios al tercer día, é hizo que apareciese manifiesto,"}, {"numero": 41, "texto": "No á todo el pueblo, sino á los testigos que Dios antes había ordenado, es á saber, á nosotros que comimos y bebimos con él, después que resucitó de los muertos."}, {"numero": 42, "texto": "Y nos mandó que predicásemos al pueblo, y testificásemos que él es el que Dios ha puesto por Juez de vivos y muertos."}, {"numero": 43, "texto": "A éste dan testimonio todos los profetas, de que todos los que en él creyeren, recibirán perdón de pecados por su nombre."}, {"numero": 44, "texto": "Estando aún hablando Pedro estas palabras, el Espíritu Santo cayó sobre todos los que oían el sermón."}, {"numero": 45, "texto": "Y se espantaron los fieles que eran de la circuncisión, que habían venido con Pedro, de que también sobre los Gentiles se derramase el don del Espíritu Santo."}, {"numero": 46, "texto": "Porque los oían que hablaban en lenguas, y que magnificaban á Dios."}, {"numero": 47, "texto": "Entonces respondió Pedro: ¿Puede alguno impedir el agua, para que no sean bautizados éstos que han recibido el Espíritu Santo también como nosotros?"}, {"numero": 48, "texto": "Y les mandó bautizar en el nombre del Señor Jesús. Entonces le rogaron que se quedase por algunos días."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 11, 'pt', '[{"numero": 1, "texto": "E os apóstolos, e os irmãos que estavam na Judeia, ouviram que também os gentios receberam a palavra de Deus."}, {"numero": 2, "texto": "E quando Pedro subiu a Jerusalém, discutiam contra ele os que eram da circuncisão;"}, {"numero": 3, "texto": "Dizendo: Tu entraste [na casa] de homens incircuncisos, e comeste com eles."}, {"numero": 4, "texto": "Mas Pedro começou a lhes explicar [tudo] em ordem, dizendo:"}, {"numero": 5, "texto": "Eu estava orando na cidade de Jope, e vi em êxtase uma visão: um certo objeto que descia como um grande lençol, pelas quatro pontas abaixado desde o céu, e vinha até mim."}, {"numero": 6, "texto": "No qual, olhando eu com atenção, considerei e vi quatro quadrúpedes da terra, e animais selvagens, e répteis, e aves do céu."}, {"numero": 7, "texto": "E eu ouvi uma voz que me dizia: Levanta-te Pedro, mata e come."}, {"numero": 8, "texto": "Mas eu disse: De maneira nenhuma, Senhor; porque nunca comi coisa alguma ordinária, nem coisa imunda entrou em minha boca."}, {"numero": 9, "texto": "E a voz me respondeu do céu pela segunda vez: O que Deus purificou, não o faças tu [como] ordinário."}, {"numero": 10, "texto": "E isto aconteceu por três vezes; e voltou-se tudo a recolher acima ao céu."}, {"numero": 11, "texto": "E eis que logo três homens, enviados a mim de Cesareia, pararam junto à casa onde eu estava."}, {"numero": 12, "texto": "E o Espírito me disse que eu fosse com eles, sem duvidar; e também estes seis irmãos foram comigo, e entramos na casa daquele homem."}, {"numero": 13, "texto": "E ele nos contou como tinha visto um anjo estar em sua casa, e tinha lhe dito: Envia [alguns] homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro;"}, {"numero": 14, "texto": "O qual te falará palavras, em que tu sejas salvo, e [também] toda a tua casa."}, {"numero": 15, "texto": "E quando comecei a falar, caiu o Espírito Santo sobre eles, assim como também no princípio [tinha caído] sobre nós."}, {"numero": 16, "texto": "E eu me lembrei da palavra do Senhor, como ele tinha dito: Verdadeiramente João batizou com água, mas vós sereis batizados com o Espírito Santo."}, {"numero": 17, "texto": "Portanto, se Deus deu a eles igual dom, assim como também a nós, que temos crido no Senhor Jesus Cristo; quem era eu, pois, para que pudesse proibir a Deus?"}, {"numero": 18, "texto": "E ao ouvirem estas coisas, se acalmaram, e glorificavam a Deus, dizendo: Portanto também aos gentios Deus deu arrependimento para a vida."}, {"numero": 19, "texto": "E os que foram dispersos por causa da perseguição que aconteceu por causa de Estêvão, passaram até a Fenícia, e Chipre, e Antioquia; não falando a ninguém a palavra, a não ser somente aos judeus."}, {"numero": 20, "texto": "E havia deles alguns homens cipriotas e cirenenses, os quais ao entrarem em Antioquia, falaram aos gregos, anunciando o Evangelho do Senhor Jesus."}, {"numero": 21, "texto": "E a mão do Senhor era com eles, e um grande número creu, e se converteu ao Senhor."}, {"numero": 22, "texto": "E esta notícia sobre eles chegou aos ouvidos da igreja que estava em Jerusalém; e enviaram a Barnabé, para ir até Antioquia."}, {"numero": 23, "texto": "O qual, ao chegar [lá] ,e tendo visto a graça de Deus, alegrou-se; e exortou a todos, para que com o propósito do coração permanecessem no Senhor."}, {"numero": 24, "texto": "Porque ele era um bom homem, e cheio do Espírito Santo, e de fé; e uma grande multidão foi acrescentada ao Senhor."}, {"numero": 25, "texto": "E Barnabé foi para Tarso, para buscar a Saulo; e achando-o, trouxe-o a Antioquia."}, {"numero": 26, "texto": "E sucedeu que, [durante] um ano completo eles se congregaram naquela igreja, e ensinavam a uma grande multidão; e em Antioquia os discípulos foram chamados pela primeira vez de cristãos."}, {"numero": 27, "texto": "E naqueles dias desceram de Jerusalém [alguns] profetas a Antioquia."}, {"numero": 28, "texto": "E levantando-se um deles, por nome Ágabo, declarou pelo Espírito, que estava para haver uma grande fome em todo o mundo; que veio a acontecer no tempo de Cláudio César."}, {"numero": 29, "texto": "E os discípulos determinaram de cada um, conforme o que pudesse, mandar algum [socorro] para serviço dos irmãos que habitavam na Judeia."}, {"numero": 30, "texto": "O que também fizeram, enviando [-o] aos anciãos pela mão de Barnabé e de Saulo."}]'::jsonb, 'Almeida Livre'),
  ('At', 11, 'en', '[{"numero": 1, "texto": "And the apostles and brethren that were in Judaea heard that the Gentiles had also received the word of God."}, {"numero": 2, "texto": "And when Peter was come up to Jerusalem, they that were of the circumcision contended with him,"}, {"numero": 3, "texto": "Saying, Thou wentest in to men uncircumcised, and didst eat with them."}, {"numero": 4, "texto": "But Peter rehearsed the matter from the beginning, and expounded it by order unto them, saying,"}, {"numero": 5, "texto": "I was in the city of Joppa praying: and in a trance I saw a vision, A certain vessel descend, as it had been a great sheet, let down from heaven by four corners; and it came even to me:"}, {"numero": 6, "texto": "Upon the which when I had fastened mine eyes, I considered, and saw fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air."}, {"numero": 7, "texto": "And I heard a voice saying unto me, Arise, Peter; slay and eat."}, {"numero": 8, "texto": "But I said, Not so, Lord: for nothing common or unclean hath at any time entered into my mouth."}, {"numero": 9, "texto": "But the voice answered me again from heaven, What God hath cleansed, that call not thou common."}, {"numero": 10, "texto": "And this was done three times: and all were drawn up again into heaven."}, {"numero": 11, "texto": "And, behold, immediately there were three men already come unto the house where I was, sent from Caesarea unto me."}, {"numero": 12, "texto": "And the Spirit bade me go with them, nothing doubting. Moreover these six brethren accompanied me, and we entered into the man''s house:"}, {"numero": 13, "texto": "And he shewed us how he had seen an angel in his house, which stood and said unto him, Send men to Joppa, and call for Simon, whose surname is Peter;"}, {"numero": 14, "texto": "Who shall tell thee words, whereby thou and all thy house shall be saved."}, {"numero": 15, "texto": "And as I began to speak, the Holy Ghost fell on them, as on us at the beginning."}, {"numero": 16, "texto": "Then remembered I the word of the Lord, how that he said, John indeed baptized with water; but ye shall be baptized with the Holy Ghost."}, {"numero": 17, "texto": "Forasmuch then as God gave them the like gift as he did unto us, who believed on the Lord Jesus Christ; what was I, that I could withstand God?"}, {"numero": 18, "texto": "When they heard these things, they held their peace, and glorified God, saying, Then hath God also to the Gentiles granted repentance unto life."}, {"numero": 19, "texto": "Now they which were scattered abroad upon the persecution that arose about Stephen travelled as far as Phenice, and Cyprus, and Antioch, preaching the word to none but unto the Jews only."}, {"numero": 20, "texto": "And some of them were men of Cyprus and Cyrene, which, when they were come to Antioch, spake unto the Grecians, preaching the Lord Jesus."}, {"numero": 21, "texto": "And the hand of the Lord was with them: and a great number believed, and turned unto the Lord."}, {"numero": 22, "texto": "Then tidings of these things came unto the ears of the church which was in Jerusalem: and they sent forth Barnabas, that he should go as far as Antioch."}, {"numero": 23, "texto": "Who, when he came, and had seen the grace of God, was glad, and exhorted them all, that with purpose of heart they would cleave unto the Lord."}, {"numero": 24, "texto": "For he was a good man, and full of the Holy Ghost and of faith: and much people was added unto the Lord."}, {"numero": 25, "texto": "Then departed Barnabas to Tarsus, for to seek Saul:"}, {"numero": 26, "texto": "And when he had found him, he brought him unto Antioch. And it came to pass, that a whole year they assembled themselves with the church, and taught much people. And the disciples were called Christians first in Antioch."}, {"numero": 27, "texto": "And in these days came prophets from Jerusalem unto Antioch."}, {"numero": 28, "texto": "And there stood up one of them named Agabus, and signified by the Spirit that there should be great dearth throughout all the world: which came to pass in the days of Claudius Caesar."}, {"numero": 29, "texto": "Then the disciples, every man according to his ability, determined to send relief unto the brethren which dwelt in Judaea:"}, {"numero": 30, "texto": "Which also they did, and sent it to the elders by the hands of Barnabas and Saul."}]'::jsonb, 'King James Version'),
  ('At', 11, 'fr', '[{"numero": 1, "texto": "Les apôtres et les frères qui étaient dans la Judée apprirent que les païens avaient aussi reçu la parole de Dieu."}, {"numero": 2, "texto": "Et lorsque Pierre fut monté à Jérusalem, les fidèles circoncis lui adressèrent des reproches,"}, {"numero": 3, "texto": "en disant: Tu es entré chez des incirconcis, et tu as mangé avec eux."}, {"numero": 4, "texto": "Pierre se mit à leur exposer d''''une manière suivie ce qui s''''était passé. Il dit:"}, {"numero": 5, "texto": "J''''étais dans la ville de Joppé, et, pendant que je priais, je tombai en extase et j''''eus une vision: un objet, semblable à une grande nappe attachée par les quatre coins, descendait du ciel et vint jusqu''''à moi."}, {"numero": 6, "texto": "Les regards fixés sur cette nappe, j''''examinai, et je vis les quadrupèdes de la terre, les bêtes sauvages, les reptiles, et les oiseaux du ciel."}, {"numero": 7, "texto": "Et j''''entendis une voix qui me disait: Lève-toi, Pierre, tue et mange."}, {"numero": 8, "texto": "Mais je dis: Non, Seigneur, car jamais rien de souillé ni d''''impur n''''est entré dans ma bouche."}, {"numero": 9, "texto": "Et pour la seconde fois la voix se fit entendre du ciel: Ce que Dieu a déclaré pur, ne le regarde pas comme souillé."}, {"numero": 10, "texto": "Cela arriva jusqu''''à trois fois; puis tout fut retiré dans le ciel."}, {"numero": 11, "texto": "Et voici, aussitôt trois hommes envoyés de Césarée vers moi se présentèrent devant la porte de la maison où j''''étais."}, {"numero": 12, "texto": "L''''Esprit me dit de partir avec eux sans hésiter. Les six hommes que voici m''''accompagnèrent, et nous entrâmes dans la maison de Corneille."}, {"numero": 13, "texto": "Cet homme nous raconta comment il avait vu dans sa maison l''''ange se présentant à lui et disant: Envoie à Joppé, et fais venir Simon, surnommé Pierre,"}, {"numero": 14, "texto": "qui te dira des choses par lesquelles tu seras sauvé, toi et toute ta maison."}, {"numero": 15, "texto": "Lorsque je me fus mis à parler, le Saint-Esprit descendit sur eux, comme sur nous au commencement."}, {"numero": 16, "texto": "Et je me souvins de cette parole du Seigneur: Jean a baptisé d''''eau, mais vous, vous serez baptisés du Saint-Esprit."}, {"numero": 17, "texto": "Or, puisque Dieu leur a accordé le même don qu''''à nous qui avons cru au Seigneur Jésus-Christ, pouvais-je, moi, m''''opposer à Dieu?"}, {"numero": 18, "texto": "Après avoir entendu cela, ils se calmèrent, et ils glorifièrent Dieu, en disant: Dieu a donc accordé la repentance aussi aux païens, afin qu''''ils aient la vie."}, {"numero": 19, "texto": "Ceux qui avaient été dispersés par la persécution survenue à l''''occasion d''''Etienne allèrent jusqu''''en Phénicie, dans l''''île de Chypre, et à Antioche, annonçant la parole seulement aux Juifs."}, {"numero": 20, "texto": "Il y eut cependant parmi eux quelques hommes de Chypre et de Cyrène, qui, étant venus à Antioche, s''''adressèrent aussi aux Grecs, et leur annoncèrent la bonne nouvelle du Seigneur Jésus."}, {"numero": 21, "texto": "La main du Seigneur était avec eux, et un grand nombre de personnes crurent et se convertirent au Seigneur."}, {"numero": 22, "texto": "Le bruit en parvint aux oreilles des membres de l''''Eglise de Jérusalem, et ils envoyèrent Barnabas jusqu''''à Antioche."}, {"numero": 23, "texto": "Lorsqu''''il fut arrivé, et qu''''il eut vu la grâce de Dieu, il s''''en réjouit, et il les exhorta tous à rester d''''un coeur ferme attachés au Seigneur."}, {"numero": 24, "texto": "Car c''''était un homme de bien, plein d''''Esprit-Saint et de foi. Et une foule assez nombreuse se joignit au Seigneur."}, {"numero": 25, "texto": "Barnabas se rendit ensuite à Tarse, pour chercher Saul;"}, {"numero": 26, "texto": "et, l''''ayant trouvé, il l''''amena à Antioche. Pendant toute une année, ils se réunirent aux assemblées de l''''Eglise, et ils enseignèrent beaucoup de personnes. Ce fut à Antioche que, pour la première fois, les disciples furent appelés chrétiens."}, {"numero": 27, "texto": "En ce temps-là, des prophètes descendirent de Jérusalem à Antioche."}, {"numero": 28, "texto": "L''''un d''''eux, nommé Agabus, se leva, et annonça par l''''Esprit qu''''il y aurait une grande famine sur toute la terre. Elle arriva, en effet, sous Claude."}, {"numero": 29, "texto": "Les disciples résolurent d''''envoyer, chacun selon ses moyens, un secours aux frères qui habitaient la Judée."}, {"numero": 30, "texto": "Ils le firent parvenir aux anciens par les mains de Barnabas et de Saul."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 11, 'es', '[{"numero": 1, "texto": "Y OYERON los apóstoles y los hermanos que estaban en Judea, que también los Gentiles habían recibido la palabra de Dios."}, {"numero": 2, "texto": "Y como Pedro subió á Jerusalem, contendían contra él los que eran de la circuncisión,"}, {"numero": 3, "texto": "Diciendo: ¿Por qué has entrado á hombres incircuncisos, y has comido con ellos?"}, {"numero": 4, "texto": "Entonces comenzando Pedro, les declaró por orden lo pasado, diciendo:"}, {"numero": 5, "texto": "Estaba yo en la ciudad de Joppe orando, y vi en rapto de entendimiento una visión: un vaso, como un gran lienzo, que descendía, que por los cuatro cabos era abajado del cielo, y venía hasta mí."}, {"numero": 6, "texto": "En el cual como puse los ojos, consideré y vi animales terrestres de cuatro pies, y fieras, y reptiles, y aves del cielo."}, {"numero": 7, "texto": "Y oí una voz que me decía: Levántate, Pedro, mata y come."}, {"numero": 8, "texto": "Y dije: Señor, no; porque ninguna cosa común ó inmunda entró jamás en mi boca."}, {"numero": 9, "texto": "Entonces la voz me respondió del cielo segunda vez: Lo que Dios limpió, no lo llames tú común."}, {"numero": 10, "texto": "Y esto fué hecho por tres veces: y volvió todo á ser tomado arriba en el cielo."}, {"numero": 11, "texto": "Y he aquí, luego sobrevinieron tres hombres á la casa donde yo estaba, enviados á mí de Cesarea."}, {"numero": 12, "texto": "Y el Espíritu me dijo que fuese con ellos sin dudar. Y vinieron también conmigo estos seis hermanos, y entramos en casa de un varón,"}, {"numero": 13, "texto": "El cual nos contó cómo había visto un ángel en su casa, que se paró, y le dijo: Envía á Joppe, y haz venir á un Simón que tiene por sobrenombre Pedro;"}, {"numero": 14, "texto": "El cual te hablará palabras por las cuales serás salvo tú, y toda tu casa."}, {"numero": 15, "texto": "Y como comencé á hablar, cayó el Espíritu Santo sobre ellos también, como sobre nosotros al principio."}, {"numero": 16, "texto": "Entonces me acordé del dicho del Señor, como dijo: Juan ciertamente bautizó en agua; mas vosotros seréis bautizados en Espíritu Santo."}, {"numero": 17, "texto": "Así que, si Dios les dió el mismo don también como á nosotros que hemos creído en el Señor Jesucristo, ¿quién era yo que pudiese estorbar á Dios?"}, {"numero": 18, "texto": "Entonces, oídas estas cosas, callaron, y glorificaron á Dios, diciendo: De manera que también á los Gentiles ha dado Dios arrepentimiento para vida."}, {"numero": 19, "texto": "Y los que habían sido esparcidos por causa de la tribulación que sobrevino en tiempo de Esteban, anduvieron hasta Fenicia, y Cipro, y Antioquía, no hablando á nadie la palabra, sino sólo á los Judíos."}, {"numero": 20, "texto": "Y de ellos había unos varones Ciprios y Cirenenses, los cuales como entraron en Antioquía, hablaron á los Griegos, anunciando el evangelio del Señor Jesús."}, {"numero": 21, "texto": "Y la mano del Señor era con ellos: y creyendo, gran número se convirtió al Señor."}, {"numero": 22, "texto": "Y llegó la fama de estas cosas á oídos de la iglesia que estaba en Jerusalem: y enviaron á Bernabé que fuese hasta Antioquía."}, {"numero": 23, "texto": "El cual, como llegó, y vió la gracia de Dios, regocijóse; y exhortó á todos á que permaneciesen en el propósito del corazón en el Señor."}, {"numero": 24, "texto": "Porque era varón bueno, y lleno de Espíritu Santo y de fe: y mucha compañía fué agregada al Señor."}, {"numero": 25, "texto": "Después partió Bernabé á Tarso á buscar á Saulo; y hallado, le trajo á Antioquía."}, {"numero": 26, "texto": "Y conversaron todo un año allí con la iglesia, y enseñaron á mucha gente; y los discípulos fueron llamados Cristianos primeramente en Antioquía."}, {"numero": 27, "texto": "Y en aquellos días descendieron de Jerusalem profetas á Antioquía."}, {"numero": 28, "texto": "Y levantándose uno de ellos, llamado Agabo, daba á entender por Espíritu, que había de haber una grande hambre en toda la tierra habitada: la cual hubo en tiempo de Claudio."}, {"numero": 29, "texto": "Entonces los discípulos, cada uno conforme á lo que tenía, determinaron enviar subsidio á los hermanos que habitaban en Judea:"}, {"numero": 30, "texto": "Lo cual asimismo hicieron, enviándolo á los ancianos por mano de Bernabé y de Saulo."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 12, 'pt', '[{"numero": 1, "texto": "E por aquele mesmo tempo o rei Herodes pôs as mãos para maltratar a alguns da igreja."}, {"numero": 2, "texto": "E matou a Tiago, o irmão de João, pela espada."}, {"numero": 3, "texto": "E vendo que isto agradava aos judeus, ele fez ainda mais, para também prender a Pedro (e eram os dias dos [pães] sem fermento)."}, {"numero": 4, "texto": "Do qual, também detendo, lançou-o na prisão, entregando [-o] a quatro quaternos de soldados, que o guardassem; pretendendo tirá-lo [para mostrá-lo] ao povo depois da Páscoa."}, {"numero": 5, "texto": "Então Pedro era mantido na prisão; mas a igreja fazia fervorosa oração a Deus por ele."}, {"numero": 6, "texto": "E quando Herodes estava para tirá-lo [para apresentá-lo] ,naquela mesma noite Pedro estava dormindo entre dois soldados, acorrentado com duas correntes; e os guardas diante da porta guardavam a prisão."}, {"numero": 7, "texto": "E eis que veio acima um anjo do Senhor, e uma luz brilhou na prisão; e tocando em Pedro em sua lateral, despertou-o, dizendo; Levanta-te, depressa!E as correntes caíram de suas mãos."}, {"numero": 8, "texto": "E o anjo lhe disse: Arruma-te, e amarra as tuas sandálias.E ele fez assim. E disse-lhe: Põe tua capa sobre ti, e segue-me."}, {"numero": 9, "texto": "E saindo, o seguia; e não sabia que era verdade o que se fazia pelo anjo, mas pensava que estava tendo alguma visão."}, {"numero": 10, "texto": "E ao passarem a primeira e a segunda guarda, chegaram à porta de ferro, que leva à cidade, a qual foi aberta por si mesma; e tendo saído, foram a uma rua, e logo o anjo partiu dele."}, {"numero": 11, "texto": "E tendo Pedro voltado a si, disse: Agora eu sei verdadeiramente que o Senhor enviou a seu anjo, e me livrou da mão de Herodes, e de toda a expectativa do povo dos judeus."}, {"numero": 12, "texto": "E ele, reconhecendo [isto] ,foi à casa de Maria, a mãe de João, que tinha por sobrenome Marcos, onde muitos estavam juntos, e oravam."}, {"numero": 13, "texto": "E Pedro, tendo batido a porta da entrada,veio uma moça de nome Rode, para escutar."}, {"numero": 14, "texto": "E ela, reconhecendo a voz de Pedro, de alegria não abriu a porta da entrada, em vez disso ela correu para dentro, e anunciou que Pedro estava fora à porta da entrada."}, {"numero": 15, "texto": "E lhe disseram: Tu estás delirando.Mas ela, insistindo que assim era. E eles diziam: É o anjo dele."}, {"numero": 16, "texto": "Mas Pedro continuava a bater; e ao abrirem, viram-no, e ficaram espantados."}, {"numero": 17, "texto": "Mas ele, fazendo-lhes gestos para que calassem, contou-lhes como o Senhor tinha lhe tirado da prisão, e disse: Anunciai isto a Tiago e aos irmãos.E tendo saído, foi para outro lugar."}, {"numero": 18, "texto": "E vindo o dia, havia não pouca perturbação entre os soldados, sobre o que, pois, tinha acontecido com Pedro."}, {"numero": 19, "texto": "E quando Herodes o buscou, e não o achou, tendo investigado aos guardas, mandou que eles fossem levados [para serem mortos] . E partindo da Judeia para Cesareia, ficou [ali] ."}, {"numero": 20, "texto": "E Herodes estava extremamente irritado com os de Tiro e de Sidom; porém eles, vindo em concordância até ele, e persuadindo a Blasto, que era o camareiro do rei, pediram paz, porque a terra deles dependia dos alimentos da terra do rei [Herodes] ."}, {"numero": 21, "texto": "E num dia marcado, Herodes vestiu roupas reais, e sentando no tribunal, fez-lhes um discurso."}, {"numero": 22, "texto": "E o povo exclamava: Voz de deus, e não de homem!"}, {"numero": 23, "texto": "E no mesmo instante um anjo do Senhor o feriu, porque ele não deu a glória a Deus; e tendo sido comido por vermes, deixou de respirar."}, {"numero": 24, "texto": "E a palavra de Deus crescia, e se multiplicava."}, {"numero": 25, "texto": "E Barnabé e Saulo, tendo cumprido aquele serviço, voltaram a Jerusalém, tomando também consigo a João, o que tinha por sobrenome Marcos."}]'::jsonb, 'Almeida Livre'),
  ('At', 12, 'en', '[{"numero": 1, "texto": "Now about that time Herod the king stretched forth his hands to vex certain of the church."}, {"numero": 2, "texto": "And he killed James the brother of John with the sword."}, {"numero": 3, "texto": "And because he saw it pleased the Jews, he proceeded further to take Peter also. (Then were the days of unleavened bread.)"}, {"numero": 4, "texto": "And when he had apprehended him, he put him in prison, and delivered him to four quaternions of soldiers to keep him; intending after Easter to bring him forth to the people."}, {"numero": 5, "texto": "Peter therefore was kept in prison: but prayer was made without ceasing of the church unto God for him."}, {"numero": 6, "texto": "And when Herod would have brought him forth, the same night Peter was sleeping between two soldiers, bound with two chains: and the keepers before the door kept the prison."}, {"numero": 7, "texto": "And, behold, the angel of the Lord came upon him, and a light shined in the prison: and he smote Peter on the side, and raised him up, saying, Arise up quickly. And his chains fell off from his hands."}, {"numero": 8, "texto": "And the angel said unto him, Gird thyself, and bind on thy sandals. And so he did. And he saith unto him, Cast thy garment about thee, and follow me."}, {"numero": 9, "texto": "And he went out, and followed him; and wist not that it was true which was done by the angel; but thought he saw a vision."}, {"numero": 10, "texto": "When they were past the first and the second ward, they came unto the iron gate that leadeth unto the city; which opened to them of his own accord: and they went out, and passed on through one street; and forthwith the angel departed from him."}, {"numero": 11, "texto": "And when Peter was come to himself, he said, Now I know of a surety, that the Lord hath sent his angel, and hath delivered me out of the hand of Herod, and from all the expectation of the people of the Jews."}, {"numero": 12, "texto": "And when he had considered the thing, he came to the house of Mary the mother of John, whose surname was Mark; where many were gathered together praying."}, {"numero": 13, "texto": "And as Peter knocked at the door of the gate, a damsel came to hearken, named Rhoda."}, {"numero": 14, "texto": "And when she knew Peter''s voice, she opened not the gate for gladness, but ran in, and told how Peter stood before the gate."}, {"numero": 15, "texto": "And they said unto her, Thou art mad. But she constantly affirmed that it was even so. Then said they, It is his angel."}, {"numero": 16, "texto": "But Peter continued knocking: and when they had opened the door, and saw him, they were astonished."}, {"numero": 17, "texto": "But he, beckoning unto them with the hand to hold their peace, declared unto them how the Lord had brought him out of the prison. And he said, Go shew these things unto James, and to the brethren. And he departed, and went into another place."}, {"numero": 18, "texto": "Now as soon as it was day, there was no small stir among the soldiers, what was become of Peter."}, {"numero": 19, "texto": "And when Herod had sought for him, and found him not, he examined the keepers, and commanded that they should be put to death. And he went down from Judaea to Caesarea, and there abode."}, {"numero": 20, "texto": "And Herod was highly displeased with them of Tyre and Sidon: but they came with one accord to him, and, having made Blastus the king''s chamberlain their friend, desired peace; because their country was nourished by the king''s country."}, {"numero": 21, "texto": "And upon a set day Herod, arrayed in royal apparel, sat upon his throne, and made an oration unto them."}, {"numero": 22, "texto": "And the people gave a shout, saying, It is the voice of a god, and not of a man."}, {"numero": 23, "texto": "And immediately the angel of the Lord smote him, because he gave not God the glory: and he was eaten of worms, and gave up the ghost."}, {"numero": 24, "texto": "But the word of God grew and multiplied."}, {"numero": 25, "texto": "And Barnabas and Saul returned from Jerusalem, when they had fulfilled their ministry, and took with them John, whose surname was Mark."}]'::jsonb, 'King James Version'),
  ('At', 12, 'fr', '[{"numero": 1, "texto": "Vers le même temps, le roi Hérode se mit à maltraiter quelques membres de l''''Eglise,"}, {"numero": 2, "texto": "et il fit mourir par l''''épée Jacques, frère de Jean."}, {"numero": 3, "texto": "Voyant que cela était agréable aux Juifs, il fit encore arrêter Pierre. -C''''était pendant les jours des pains sans levain. -"}, {"numero": 4, "texto": "Après l''''avoir saisi et jeté en prison, il le mit sous la garde de quatre escouades de quatre soldats chacune, avec l''''intention de le faire comparaître devant le peuple après la Pâque."}, {"numero": 5, "texto": "Pierre donc était gardé dans la prison; et l''''Eglise ne cessait d''''adresser pour lui des prières à Dieu."}, {"numero": 6, "texto": "La nuit qui précéda le jour où Hérode allait le faire comparaître, Pierre, lié de deux chaînes, dormait entre deux soldats; et des sentinelles devant la porte gardaient la prison."}, {"numero": 7, "texto": "Et voici, un ange du Seigneur survint, et une lumière brilla dans la prison. L''''ange réveilla Pierre, en le frappant au côté, et en disant: Lève-toi promptement! Les chaînes tombèrent de ses mains."}, {"numero": 8, "texto": "Et l''''ange lui dit: Mets ta ceinture et tes sandales. Et il fit ainsi. L''''ange lui dit encore: Enveloppe-toi de ton manteau, et suis-moi."}, {"numero": 9, "texto": "Pierre sortit, et le suivit, ne sachant pas que ce qui se faisait par l''''ange fût réel, et s''''imaginant avoir une vision."}, {"numero": 10, "texto": "Lorsqu''''ils eurent passé la première garde, puis la seconde, ils arrivèrent à la porte de fer qui mène à la ville, et qui s''''ouvrit d''''elle-même devant eux; ils sortirent, et s''''avancèrent dans une rue. Aussitôt l''''ange quitta Pierre."}, {"numero": 11, "texto": "Revenu à lui-même, Pierre dit: Je vois maintenant d''''une manière certaine que le Seigneur a envoyé son ange, et qu''''il m''''a délivré de la main d''''Hérode et de tout ce que le peuple juif attendait."}, {"numero": 12, "texto": "Après avoir réfléchi, il se dirigea vers la maison de Marie, mère de Jean, surnommé Marc, où beaucoup de personnes étaient réunies et priaient."}, {"numero": 13, "texto": "Il frappa à la porte du vestibule, et une servante, nommée Rhode, s''''approcha pour écouter."}, {"numero": 14, "texto": "Elle reconnut la voix de Pierre; et, dans sa joie, au lieu d''''ouvrir, elle courut annoncer que Pierre était devant la porte."}, {"numero": 15, "texto": "Ils lui dirent: Tu es folle. Mais elle affirma que la chose était ainsi. Et ils dirent: C''''est son ange."}, {"numero": 16, "texto": "Cependant Pierre continuait à frapper. Ils ouvrirent, et furent étonnés de le voir."}, {"numero": 17, "texto": "Pierre, leur ayant de la main fait signe de se taire, leur raconta comment le Seigneur l''''avait tiré de la prison, et il dit: Annoncez-le à Jacques et aux frères. Puis il sortit, et s''''en alla dans un autre lieu."}, {"numero": 18, "texto": "Quand il fit jour, les soldats furent dans une grande agitation, pour savoir ce que Pierre était devenu."}, {"numero": 19, "texto": "Hérode, s''''étant mis à sa recherche et ne l''''ayant pas trouvé, interrogea les gardes, et donna l''''ordre de les mener au supplice. Ensuite il descendit de la Judée à Césarée, pour y séjourner."}, {"numero": 20, "texto": "Hérode avait des dispositions hostiles à l''''égard des Tyriens et des Sidoniens. Mais ils vinrent le trouver d''''un commun accord; et, après avoir gagné Blaste, son chambellan, ils sollicitèrent la paix, parce que leur pays tirait sa subsistance de celui du roi."}, {"numero": 21, "texto": "A un jour fixé, Hérode, revêtu de ses habits royaux, et assis sur son trône, les harangua publiquement."}, {"numero": 22, "texto": "Le peuple s''''écria: Voix d''''un dieu, et non d''''un homme!"}, {"numero": 23, "texto": "Au même instant, un ange du Seigneur le frappa, parce qu''''il n''''avait pas donné gloire à Dieu. Et il expira, rongé des vers."}, {"numero": 24, "texto": "Cependant la parole de Dieu se répandait de plus en plus, et le nombre des disciples augmentait."}, {"numero": 25, "texto": "Barnabas et Saul, après s''''être acquittés de leur message, s''''en retournèrent de Jérusalem, emmenant avec eux Jean, surnommé Marc."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 12, 'es', '[{"numero": 1, "texto": "Y EN el mismo tiempo el rey Herodes echó mano á maltratar algunos de la iglesia."}, {"numero": 2, "texto": "Y mató á cuchillo á Jacobo, hermano de Juan."}, {"numero": 3, "texto": "Y viendo que había agradado á los Judíos, pasó adelante para prender también á Pedro. Eran entonces los días de los ázimos."}, {"numero": 4, "texto": "Y habiéndole preso, púsole en la cárcel, entregándole á cuatro cuaterniones de soldados que le guardasen; queriendo sacarle al pueblo después de la Pascua."}, {"numero": 5, "texto": "Así que, Pedro era guardado en la cárcel; y la iglesia hacía sin cesar oración á Dios por él."}, {"numero": 6, "texto": "Y cuando Herodes le había de sacar, aquella misma noche estaba Pedro durmiendo entre dos soldados, preso con dos cadenas, y los guardas delante de la puerta, que guardaban la cárcel."}, {"numero": 7, "texto": "Y he aquí, el ángel del Señor sobrevino, y una luz resplandeció en la cárcel; é hiriendo á Pedro en el lado, le despertó, diciendo: Levántate prestamente. Y las cadenas se le cayeron de las manos."}, {"numero": 8, "texto": "Y le dijo el ángel: Cíñete, y átate tus sandalias. Y lo hizo así. Y le dijo: Rodéate tu ropa, y sígueme."}, {"numero": 9, "texto": "Y saliendo, le seguía; y no sabía que era verdad lo que hacía el ángel, mas pensaba que veía visión."}, {"numero": 10, "texto": "Y como pasaron la primera y la segunda guardia, vinieron á la puerta de hierro que va á la ciudad, la cual se les abrió de suyo: y salidos, pasaron una calle; y luego el ángel se apartó de él."}, {"numero": 11, "texto": "Entonces Pedro, volviendo en sí, dijo: Ahora entiendo verdaderamente que el Señor ha enviado su ángel, y me ha librado de la mano de Herodes, y de todo el pueblo de los Judíos que me esperaba."}, {"numero": 12, "texto": "Y habiendo considerado esto, llegó á casa de María la madre de Juan, el que tenía por sobrenombre Marcos, donde muchos estaban juntos orando."}, {"numero": 13, "texto": "Y tocando Pedro á la puerta del patio, salió una muchacha, para escuchar, llamada Rhode:"}, {"numero": 14, "texto": "La cual como conoció la voz de Pedro, de gozo no abrió el postigo, sino corriendo adentro, dió nueva de que Pedro estaba al postigo."}, {"numero": 15, "texto": "Y ellos le dijeron: Estás loca. Mas ella afirmaba que así era. Entonces ellos decían: Su ángel es."}, {"numero": 16, "texto": "Mas Pedro perseveraba en llamar: y cuando abrieron, viéronle, y se espantaron."}, {"numero": 17, "texto": "Mas él haciéndoles con la mano señal de que callasen, les contó cómo el Señor le había sacado de la cárcel. Y dijo: Haced saber esto á Jacobo y á los hermanos. Y salió, y partió á otro lugar."}, {"numero": 18, "texto": "Luego que fué de día, hubo no poco alboroto entre los soldados sobre qué se había hecho de Pedro."}, {"numero": 19, "texto": "Mas Herodes, como le buscó y no le halló, hecha inquisición de los guardas, los mandó llevar. Después descendiendo de Judea á Cesarea, se quedó allí."}, {"numero": 20, "texto": "Y Herodes estaba enojado contra los de Tiro y los de Sidón: mas ellos vinieron concordes á él, y sobornado Blasto, que era el camarero del rey, pedían paz; porque las tierras de ellos eran abastecidas por las del rey."}, {"numero": 21, "texto": "Y un día señalado, Herodes vestido de ropa real, se sentó en el tribunal, y arengóles."}, {"numero": 22, "texto": "Y el pueblo aclamaba: Voz de Dios, y no de hombre."}, {"numero": 23, "texto": "Y luego el ángel del Señor le hirió, por cuanto no dió la gloria á Dios; y espiró comido de gusanos."}, {"numero": 24, "texto": "Mas la palabra del Señor crecía y era multiplicada."}, {"numero": 25, "texto": "Y Bernabé y Saulo volvieron de Jerusalem cumplido su servicio, tomando también consigo á Juan, el que tenía por sobrenombre Marcos."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 13, 'pt', '[{"numero": 1, "texto": "E havia em Antioquia, na igreja que estava [ali] , alguns profetas e mestres: Barnabé e Simeão, chamado Níger, e Lúcio cireneu, e Manaem, que tinha sido criado na infância junto com Herodes o Tetrarca, e Saulo."}, {"numero": 2, "texto": "E tendo eles prestado serviço ao Senhor, e jejuado, o Espirito Santo disse: Separai-me a Barnabé e a Saulo, para a obra para a qual eu os tenho chamado."}, {"numero": 3, "texto": "Então jejuando, e orando, e pondo as mãos sobre eles, [os] despediram."}, {"numero": 4, "texto": "Portanto estes, enviados pelo Espírito Santo, desceram a Selêucia, e dali navegaram para o Chipre."}, {"numero": 5, "texto": "E tendo chegado a Salamina, anunciavam a palavra de Deus nas sinagogas dos judeus; e também tinham a João como trabalhador [para os auxiliar] ."}, {"numero": 6, "texto": "E tendo eles atravessado a Ilha até Pafo, acharam a um certo mago, falso profeta, judeu, cujo nome era Barjesus."}, {"numero": 7, "texto": "O qual estava com o procônsul Sérgio Paulo, homem prudente. Este, tendo chamado a si a Barnabé, e a Saulo, procurava muito ouvir a palavra de Deus."}, {"numero": 8, "texto": "Mas resistia-lhes Elimas, o mago (que assim significa seu nome), procurando afastar o procônsul da fé."}, {"numero": 9, "texto": "Mas Saulo, que também [se chama] Paulo, cheio do Espírito Santo, e olhando fixamente para ele, disse:"}, {"numero": 10, "texto": "Ó filho do diabo, cheio de toda enganação e toda malícia, inimigo de toda justiça, não cessarás de perverter os corretos caminhos do Senhor?"}, {"numero": 11, "texto": "E agora, eis que a mão do Senhor [está] contra ti, e serás cego, não vendo o sol por algum tempo.E no mesmo instante caiu sobre ele um embaçamento, e trevas; e ele, andando ao redor, procurava alguém que o guiasse pela mão."}, {"numero": 12, "texto": "Então o procônsul, vendo o que tinha acontecido, creu, espantado pela doutrina do Senhor."}, {"numero": 13, "texto": "E tendo partido de Pafo, Paulo e os que estavam com ele foram a Perges, [cidade] da Panfília. Mas João, separando-se deles, voltou a Jerusalém."}, {"numero": 14, "texto": "E eles, tendo passado de Perges, vieram a Antioquia, [cidade] da Pisídia; e ao entrarem na sinagoga [n] um dia de sábado, sentaram-se."}, {"numero": 15, "texto": "E depois da leitura da Lei e dos profetas, os chefes da sinagoga lhes mandaram, dizendo: Homens irmãos, se em vós há [alguma] palavra de exortação ao povo, dizei."}, {"numero": 16, "texto": "E Paulo, levantando-se e fazendo gesto com a mão, disse: Homens israelitas, e [vós] os que temeis a Deus, ouvi:"}, {"numero": 17, "texto": "O Deus deste povo de Israel escolheu a nossos pais, e exaltou ao povo, sendo eles estrangeiros na terra do Egito, e com o braço levantando, ele os tirou dela."}, {"numero": 18, "texto": "E pelo tempo de cerca de quarenta anos, ele suportou os costumes deles no deserto."}, {"numero": 19, "texto": "E tendo destruído a sete nações na terra de Canaã, repartiu-lhes as terras por sorte."}, {"numero": 20, "texto": "E depois disto, cerca de quatrocentos e cinquenta anos, ele [lhes] deu juízes, até o profeta Samuel."}, {"numero": 21, "texto": "E depois disto, pediram a um Rei, e ele lhes deu a Saul, filho de Quis, homem da tribo de Benjamim, [durante] quarenta anos."}, {"numero": 22, "texto": "E tirando a este, levantou-lhes por rei a Davi, ao qual também deu testemunho, e disse: Eu achei a Davi, [filho] de Jessé, um homem conforme o meu coração, que fará toda a minha vontade."}, {"numero": 23, "texto": "Da descendência deste, conforme a promessa, Deus levantou a Jesus por Salvador de Israel;"}, {"numero": 24, "texto": "Tendo João primeiro, antes de sua vinda, pregado o batismo de arrependimento a todo o povo de Israel."}, {"numero": 25, "texto": "Mas quando João cumpriu [sua] carreira, disse: Quem vós pensais que eu sou? Eu não sou o [Cristo] ,mas eis que após mim vem aquele, cujas sandálias dos pés eu não sou digno de desatar."}, {"numero": 26, "texto": "Homens irmãos, filhos da descendência de Abraão, e os que dentre vós temem a Deus, a vós é enviada a palavra desta salvação."}, {"numero": 27, "texto": "Porque os que habitavam em Jerusalém, e seus líderes, não conhecendo a este, ao condenarem [-no] ,cumpriram as vozes dos profetas, que são lidas todos os sábados."}, {"numero": 28, "texto": "E [mesmo] achando nenhum motivo para morte, pediram a Pilatos que fosse morto."}, {"numero": 29, "texto": "E tendo eles cumprido todas as coisas que estavam escritas sobre ele, tirando [-o] do madeiro, puseram [-no] na sepultura."}, {"numero": 30, "texto": "Mas Deus o ressuscitou dos mortos."}, {"numero": 31, "texto": "O qual foi visto durante muitos dias pelos que haviam subido com ele da Galileia, que são suas testemunhas para com o povo."}, {"numero": 32, "texto": "E nós vos anunciamos o Evangelho da promessa que foi feita aos pais; ao qual Deus já nos cumpriu a nós, filhos deles, ressuscitando a Jesus."}, {"numero": 33, "texto": "Assim como está escrito no salmo segundo: Tu és meu Filho, hoje eu te gerei."}, {"numero": 34, "texto": "E [quanto a] que o ressuscitasse dos mortos, para nunca mais voltar à degradação, assim disse: Eu vos darei as fiéis beneficências de Davi."}, {"numero": 35, "texto": "Por isso que também em outro [salmo] ele diz: Não permitirás que teu Santo veja degradação."}, {"numero": 36, "texto": "Porque, na verdade, tendo Davi servido ao conselho de Deus, morreu, foi posto junto a seus pais, e viu degradação."}, {"numero": 37, "texto": "Mas aquele a quem Deus ressuscitou nenhuma degradação viu."}, {"numero": 38, "texto": "Seja-vos pois conhecido, homens irmãos, que por este vos é anunciado o perdão dos pecados."}, {"numero": 39, "texto": "E de tudo o que pela lei de Moisés não pudestes ser justificados, neste é justificado todo aquele que crê."}, {"numero": 40, "texto": "Então vede, para que não venha sobre vós o que está escrito nos [livros dos] profetas:"}, {"numero": 41, "texto": "[Vós] desprezadores, vede e espantai-vos, e desaparecei-vos; porque eu opero obra em vossos dias, obra na qual não crereis, se alguém vos contar."}, {"numero": 42, "texto": "E tendo os judeus saído da sinagoga,os gentios rogaram [-lhes] que no sábado seguinte eles lhes falassem estas palavras."}, {"numero": 43, "texto": "E tendo terminado [a reunião] da sinagoga, muitos dos judeus, e dos religiosos prosélitos, seguiram a Paulo e a Barnabé; os quais, falando-lhes, exortavam-nos a permanecerem na graça de Deus."}, {"numero": 44, "texto": "E no sábado seguinte ajuntou-se quase toda a cidade para ouvir a palavra de Deus."}, {"numero": 45, "texto": "Mas os Judeus, ao verem as multidões, ficaram cheios de inveja, e falavam contrariamente ao que Paulo dizia, falando contrariamente e blasfemando."}, {"numero": 46, "texto": "Mas Paulo e Barnabé, usando de ousadia, disseram: Era necessário que a palavra de Deus fosse primeiro falada a vós; mas já que a rejeitais, e não vos julgais dignos da vida eterna, eis que nós nos viramos [em direção] aos gentios."}, {"numero": 47, "texto": "Porque assim o Senhor nos mandou, [dizendo] : Eu te pus como luz para os gentios, para que tu sejas como salvação até às extremidades da terra."}, {"numero": 48, "texto": "E os gentios, tendo ouvido [isto] ,alegraram-se, e glorificavam ao Senhor; e creram todos quantos estavam determinados para a vida eterna."}, {"numero": 49, "texto": "E a palavra do Senhor era divulgada por toda aquela região."}, {"numero": 50, "texto": "Mas os judeus incitaram algumas mulheres devotas e honradas, e aos líderes da cidade, e levantaram perseguição contra Paulo e Barnabé, e os expulsaram de seus limites."}, {"numero": 51, "texto": "Mas eles, sacudindo contra eles o pó dos seus pés, vieram a Icônio."}, {"numero": 52, "texto": "E os discípulos se enchiam de alegria e do Espírito Santo."}]'::jsonb, 'Almeida Livre'),
  ('At', 13, 'en', '[{"numero": 1, "texto": "Now there were in the church that was at Antioch certain prophets and teachers; as Barnabas, and Simeon that was called Niger, and Lucius of Cyrene, and Manaen, which had been brought up with Herod the tetrarch, and Saul."}, {"numero": 2, "texto": "As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them."}, {"numero": 3, "texto": "And when they had fasted and prayed, and laid their hands on them, they sent them away."}, {"numero": 4, "texto": "So they, being sent forth by the Holy Ghost, departed unto Seleucia; and from thence they sailed to Cyprus."}, {"numero": 5, "texto": "And when they were at Salamis, they preached the word of God in the synagogues of the Jews: and they had also John to their minister."}, {"numero": 6, "texto": "And when they had gone through the isle unto Paphos, they found a certain sorcerer, a false prophet, a Jew, whose name was Barjesus:"}, {"numero": 7, "texto": "Which was with the deputy of the country, Sergius Paulus, a prudent man; who called for Barnabas and Saul, and desired to hear the word of God."}, {"numero": 8, "texto": "But Elymas the sorcerer (for so is his name by interpretation) withstood them, seeking to turn away the deputy from the faith."}, {"numero": 9, "texto": "Then Saul, (who also is called Paul,) filled with the Holy Ghost, set his eyes on him."}, {"numero": 10, "texto": "And said, O full of all subtilty and all mischief, thou child of the devil, thou enemy of all righteousness, wilt thou not cease to pervert the right ways of the Lord?"}, {"numero": 11, "texto": "And now, behold, the hand of the Lord is upon thee, and thou shalt be blind, not seeing the sun for a season. And immediately there fell on him a mist and a darkness; and he went about seeking some to lead him by the hand."}, {"numero": 12, "texto": "Then the deputy, when he saw what was done, believed, being astonished at the doctrine of the Lord."}, {"numero": 13, "texto": "Now when Paul and his company loosed from Paphos, they came to Perga in Pamphylia: and John departing from them returned to Jerusalem."}, {"numero": 14, "texto": "But when they departed from Perga, they came to Antioch in Pisidia, and went into the synagogue on the sabbath day, and sat down."}, {"numero": 15, "texto": "And after the reading of the law and the prophets the rulers of the synagogue sent unto them, saying, Ye men and brethren, if ye have any word of exhortation for the people, say on."}, {"numero": 16, "texto": "Then Paul stood up, and beckoning with his hand said, Men of Israel, and ye that fear God, give audience."}, {"numero": 17, "texto": "The God of this people of Israel chose our fathers, and exalted the people when they dwelt as strangers in the land of Egypt, and with an high arm brought he them out of it."}, {"numero": 18, "texto": "And about the time of forty years suffered he their manners in the wilderness."}, {"numero": 19, "texto": "And when he had destroyed seven nations in the land of Chanaan, he divided their land to them by lot."}, {"numero": 20, "texto": "And after that he gave unto them judges about the space of four hundred and fifty years, until Samuel the prophet."}, {"numero": 21, "texto": "And afterward they desired a king: and God gave unto them Saul the son of Cis, a man of the tribe of Benjamin, by the space of forty years."}, {"numero": 22, "texto": "And when he had removed him, he raised up unto them David to be their king; to whom also he gave their testimony, and said, I have found David the son of Jesse, a man after mine own heart, which shall fulfil all my will."}, {"numero": 23, "texto": "Of this man''s seed hath God according to his promise raised unto Israel a Saviour, Jesus:"}, {"numero": 24, "texto": "When John had first preached before his coming the baptism of repentance to all the people of Israel."}, {"numero": 25, "texto": "And as John fulfilled his course, he said, Whom think ye that I am? I am not he. But, behold, there cometh one after me, whose shoes of his feet I am not worthy to loose."}, {"numero": 26, "texto": "Men and brethren, children of the stock of Abraham, and whosoever among you feareth God, to you is the word of this salvation sent."}, {"numero": 27, "texto": "For they that dwell at Jerusalem, and their rulers, because they knew him not, nor yet the voices of the prophets which are read every sabbath day, they have fulfilled them in condemning him."}, {"numero": 28, "texto": "And though they found no cause of death in him, yet desired they Pilate that he should be slain."}, {"numero": 29, "texto": "And when they had fulfilled all that was written of him, they took him down from the tree, and laid him in a sepulchre."}, {"numero": 30, "texto": "But God raised him from the dead:"}, {"numero": 31, "texto": "And he was seen many days of them which came up with him from Galilee to Jerusalem, who are his witnesses unto the people."}, {"numero": 32, "texto": "And we declare unto you glad tidings, how that the promise which was made unto the fathers,"}, {"numero": 33, "texto": "God hath fulfilled the same unto us their children, in that he hath raised up Jesus again; as it is also written in the second psalm, Thou art my Son, this day have I begotten thee."}, {"numero": 34, "texto": "And as concerning that he raised him up from the dead, now no more to return to corruption, he said on this wise, I will give you the sure mercies of David."}, {"numero": 35, "texto": "Wherefore he saith also in another psalm, Thou shalt not suffer thine Holy One to see corruption."}, {"numero": 36, "texto": "For David, after he had served his own generation by the will of God, fell on sleep, and was laid unto his fathers, and saw corruption:"}, {"numero": 37, "texto": "But he, whom God raised again, saw no corruption."}, {"numero": 38, "texto": "Be it known unto you therefore, men and brethren, that through this man is preached unto you the forgiveness of sins:"}, {"numero": 39, "texto": "And by him all that believe are justified from all things, from which ye could not be justified by the law of Moses."}, {"numero": 40, "texto": "Beware therefore, lest that come upon you, which is spoken of in the prophets;"}, {"numero": 41, "texto": "Behold, ye despisers, and wonder, and perish: for I work a work in your days, a work which ye shall in no wise believe, though a man declare it unto you."}, {"numero": 42, "texto": "And when the Jews were gone out of the synagogue, the Gentiles besought that these words might be preached to them the next sabbath."}, {"numero": 43, "texto": "Now when the congregation was broken up, many of the Jews and religious proselytes followed Paul and Barnabas: who, speaking to them, persuaded them to continue in the grace of God."}, {"numero": 44, "texto": "And the next sabbath day came almost the whole city together to hear the word of God."}, {"numero": 45, "texto": "But when the Jews saw the multitudes, they were filled with envy, and spake against those things which were spoken by Paul, contradicting and blaspheming."}, {"numero": 46, "texto": "Then Paul and Barnabas waxed bold, and said, It was necessary that the word of God should first have been spoken to you: but seeing ye put it from you, and judge yourselves unworthy of everlasting life, lo, we turn to the Gentiles."}, {"numero": 47, "texto": "For so hath the Lord commanded us, saying, I have set thee to be a light of the Gentiles, that thou shouldest be for salvation unto the ends of the earth."}, {"numero": 48, "texto": "And when the Gentiles heard this, they were glad, and glorified the word of the Lord: and as many as were ordained to eternal life believed."}, {"numero": 49, "texto": "And the word of the Lord was published throughout all the region."}, {"numero": 50, "texto": "But the Jews stirred up the devout and honourable women, and the chief men of the city, and raised persecution against Paul and Barnabas, and expelled them out of their coasts."}, {"numero": 51, "texto": "But they shook off the dust of their feet against them, and came unto Iconium."}, {"numero": 52, "texto": "And the disciples were filled with joy, and with the Holy Ghost."}]'::jsonb, 'King James Version'),
  ('At', 13, 'fr', '[{"numero": 1, "texto": "Il y avait dans l''''Eglise d''''Antioche des prophètes et des docteurs: Barnabas, Siméon appelé Niger, Lucius de Cyrène, Manahen, qui avait été élevé avec Hérode le tétrarque, et Saul."}, {"numero": 2, "texto": "Pendant qu''''ils servaient le Seigneur dans leur ministère et qu''''ils jeûnaient, le Saint-Esprit dit: Mettez-moi à part Barnabas et Saul pour l''''oeuvre à laquelle je les ai appelés."}, {"numero": 3, "texto": "Alors, après avoir jeûné et prié, ils leur imposèrent les mains, et les laissèrent partir."}, {"numero": 4, "texto": "Barnabas et Saul, envoyés par le Saint-Esprit, descendirent à Séleucie, et de là ils s''''embarquèrent pour l''''île de Chypre."}, {"numero": 5, "texto": "Arrivés à Salamine, ils annoncèrent la parole de Dieu dans les synagogues des Juifs. Ils avaient Jean pour aide."}, {"numero": 6, "texto": "Ayant ensuite traversé toute l''''île jusqu''''à Paphos, ils trouvèrent un certain magicien, faux prophète juif, nommé Bar-Jésus,"}, {"numero": 7, "texto": "qui était avec le proconsul Sergius Paulus, homme intelligent. Ce dernier fit appeler Barnabas et Saul, et manifesta le désir d''''entendre la parole de Dieu."}, {"numero": 8, "texto": "Mais Elymas, le magicien, -car c''''est ce que signifie son nom, -leur faisait opposition, cherchant à détourner de la foi le proconsul."}, {"numero": 9, "texto": "Alors Saul, appelé aussi Paul, rempli du Saint-Esprit, fixa les regards sur lui,"}, {"numero": 10, "texto": "et dit: Homme plein de toute espèce de ruse et de fraude, fils du diable, ennemi de toute justice, ne cesseras-tu point de pervertir les voies droites du Seigneur?"}, {"numero": 11, "texto": "Maintenant voici, la main du Seigneur est sur toi, tu seras aveugle, et pour un temps tu ne verras pas le soleil. Aussitôt l''''obscurité et les ténèbres tombèrent sur lui, et il cherchait, en tâtonnant, des personnes pour le guider."}, {"numero": 12, "texto": "Alors le proconsul, voyant ce qui était arrivé, crut, étant frappé de la doctrine du Seigneur."}, {"numero": 13, "texto": "Paul et ses compagnons, s''''étant embarqués à Paphos, se rendirent à Perge en Pamphylie. Jean se sépara d''''eux, et retourna à Jérusalem."}, {"numero": 14, "texto": "De Perge ils poursuivirent leur route, et arrivèrent à Antioche de Pisidie. Etant entrés dans la synagogue le jour du sabbat, ils s''''assirent."}, {"numero": 15, "texto": "Après la lecture de la loi et des prophètes, les chefs de la synagogue leur envoyèrent dire: Hommes frères, si vous avez quelque exhortation à adresser au peuple, parlez."}, {"numero": 16, "texto": "Paul se leva, et, ayant fait signe de la main, il dit: Hommes Israélites, et vous qui craignez Dieu, écoutez!"}, {"numero": 17, "texto": "Le Dieu de ce peuple d''''Israël a choisi nos pères. Il mit ce peuple en honneur pendant son séjour au pays d''''Egypte, et il l''''en fit sortir par son bras puissant."}, {"numero": 18, "texto": "Il les nourrit près de quarante ans dans le désert;"}, {"numero": 19, "texto": "et, ayant détruit sept nations au pays de Canaan, il leur en accorda le territoire comme propriété."}, {"numero": 20, "texto": "Après cela, durant quatre cent cinquante ans environ, il leur donna des juges, jusqu''''au prophète Samuel."}, {"numero": 21, "texto": "Ils demandèrent alors un roi. Et Dieu leur donna, pendant quarante ans, Saül, fils de Kis, de la tribu de Benjamin;"}, {"numero": 22, "texto": "puis, l''''ayant rejeté, il leur suscita pour roi David, auquel il a rendu ce témoignage: J''''ai trouvé David, fils d''''Isaï, homme selon mon coeur, qui accomplira toutes mes volontés."}, {"numero": 23, "texto": "C''''est de la postérité de David que Dieu, selon sa promesse, a suscité à Israël un Sauveur, qui est Jésus."}, {"numero": 24, "texto": "Avant sa venue, Jean avait prêché le baptême de repentance à tout le peuple d''''Israël."}, {"numero": 25, "texto": "Et lorsque Jean achevait sa course, il disait: Je ne suis pas celui que vous pensez; mais voici, après moi vient celui des pieds duquel je ne suis pas digne de délier les souliers."}, {"numero": 26, "texto": "Hommes frères, fils de la race d''''Abraham, et vous qui craignez Dieu, c''''est à vous que cette parole de salut a été envoyée."}, {"numero": 27, "texto": "Car les habitants de Jérusalem et leurs chefs ont méconnu Jésus, et, en le condamnant, ils ont accompli les paroles des prophètes qui se lisent chaque sabbat."}, {"numero": 28, "texto": "Quoiqu''''ils ne trouvassent en lui rien qui fût digne de mort, ils ont demandé à Pilate de le faire mourir."}, {"numero": 29, "texto": "Et, après qu''''ils eurent accompli tout ce qui est écrit de lui, ils le descendirent de la croix et le déposèrent dans un sépulcre."}, {"numero": 30, "texto": "Mais Dieu l''''a ressuscité des morts."}, {"numero": 31, "texto": "Il est apparu pendant plusieurs jours à ceux qui étaient montés avec lui de la Galilée à Jérusalem, et qui sont maintenant ses témoins auprès du peuple."}, {"numero": 32, "texto": "Et nous, nous vous annonçons cette bonne nouvelle que la promesse faite à nos pères,"}, {"numero": 33, "texto": "Dieu l''''a accomplie pour nous leurs enfants, en ressuscitant Jésus, selon ce qui est écrit dans le Psaume deuxième: Tu es mon Fils, Je t''''ai engendré aujourd''''hui."}, {"numero": 34, "texto": "Qu''''il l''''ait ressuscité des morts, de telle sorte qu''''il ne retournera pas à la corruption, c''''est ce qu''''il a déclaré, en disant: Je vous donnerai Les grâces saintes promises à David, ces grâces qui sont assurées."}, {"numero": 35, "texto": "C''''est pourquoi il dit encore ailleurs: Tu ne permettras pas que ton Saint voie la corruption."}, {"numero": 36, "texto": "Or, David, après avoir en son temps servi au dessein de Dieu, est mort, a été réuni à ses pères, et a vu la corruption."}, {"numero": 37, "texto": "Mais celui que Dieu a ressuscité n''''a pas vu la corruption."}, {"numero": 38, "texto": "Sachez donc, hommes frères, que c''''est par lui que le pardon des péchés vous est annoncé,"}, {"numero": 39, "texto": "et que quiconque croit est justifié par lui de toutes les choses dont vous ne pouviez être justifiés par la loi de Moïse."}, {"numero": 40, "texto": "Ainsi, prenez garde qu''''il ne vous arrive ce qui est dit dans les prophètes:"}, {"numero": 41, "texto": "Voyez, contempteurs, Soyez étonnés et disparaissez; Car je vais faire en vos jours une oeuvre, Une oeuvre que vous ne croiriez pas si on vous la racontait."}, {"numero": 42, "texto": "Lorsqu''''ils sortirent, on les pria de parler le sabbat suivant sur les mêmes choses;"}, {"numero": 43, "texto": "et, à l''''issue de l''''assemblée, beaucoup de Juifs et de prosélytes pieux suivirent Paul et Barnabas, qui s''''entretinrent avec eux, et les exhortèrent à rester attachés à la grâce de Dieu."}, {"numero": 44, "texto": "Le sabbat suivant, presque toute la ville se rassembla pour entendre la parole de Dieu."}, {"numero": 45, "texto": "Les Juifs, voyant la foule, furent remplis de jalousie, et ils s''''opposaient à ce que disait Paul, en le contredisant et en l''''injuriant."}, {"numero": 46, "texto": "Paul et Barnabas leur dirent avec assurance: C''''est à vous premièrement que la parole de Dieu devait être annoncée; mais, puisque vous la repoussez, et que vous vous jugez vous-mêmes indignes de la vie éternelle, voici, nous nous tournons vers les païens."}, {"numero": 47, "texto": "Car ainsi nous l''''a ordonné le Seigneur: Je t''''ai établi pour être la lumière des nations, Pour porter le salut jusqu''''aux extrémités de la terre."}, {"numero": 48, "texto": "Les païens se réjouissaient en entendant cela, ils glorifiaient la parole du Seigneur, et tous ceux qui étaient destinés à la vie éternelle crurent."}, {"numero": 49, "texto": "La parole du Seigneur se répandait dans tout le pays."}, {"numero": 50, "texto": "Mais les Juifs excitèrent les femmes dévotes de distinction et les principaux de la ville; ils provoquèrent une persécution contre Paul et Barnabas, et ils les chassèrent de leur territoire."}, {"numero": 51, "texto": "Paul et Barnabas secouèrent contre eux la poussière de leurs pieds, et allèrent à Icone,"}, {"numero": 52, "texto": "tandis que les disciples étaient remplis de joie et du Saint-Esprit."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 13, 'es', '[{"numero": 1, "texto": "HABÍA entonces en la iglesia que estaba en Antioquía, profetas y doctores: Bernabé, y Simón el que se llamaba Niger, y Lucio Cireneo, y Manahén, que había sido criado con Herodes el tetrarca, y Saulo."}, {"numero": 2, "texto": "Ministrando pues éstos al Señor, y ayunando, dijo el Espíritu Santo: Apartadme á Bernabé y á Saulo para la obra para la cual los he llamado."}, {"numero": 3, "texto": "Entonces habiendo ayunado y orado, y puesto las manos encima de ellos, despidiéronlos."}, {"numero": 4, "texto": "Y ellos, enviados así por el Espíritu Santo, descendieron á Seleucia; y de allí navegaron á Cipro."}, {"numero": 5, "texto": "Y llegados á Salamina, anunciaban la palabra de Dios en las sinagogas de los Judíos: y tenían también á Juan en el ministerio."}, {"numero": 6, "texto": "Y habiendo atravesado toda la isla hasta Papho, hallaron un hombre mago, falso profeta, Judío, llamado Barjesús;"}, {"numero": 7, "texto": "El cual estaba con el procónsul Sergio Paulo, varón prudente. Este, llamando á Bernabé y á Saulo, deseaba oir la palabra de Dios."}, {"numero": 8, "texto": "Mas les resistía Elimas el encantador (que así se interpreta su nombre), procurando apartar de la fe al procónsul."}, {"numero": 9, "texto": "Entonces Saulo, que también es Pablo, lleno del Espíritu Santo, poniendo en él los ojos,"}, {"numero": 10, "texto": "Dijo: Oh, lleno de todo engaño y de toda maldad, hijo del diablo, enemigo de toda justicia, ¿no cesarás de trastornar los caminos rectos del Señor?"}, {"numero": 11, "texto": "Ahora pues, he aquí la mano del Señor es contra ti, y serás ciego, que no veas el sol por tiempo. Y luego cayeron en él obscuridad y tinieblas; y andando alrededor, buscaba quién le condujese por la mano."}, {"numero": 12, "texto": "Entonces el procónsul, viendo lo que había sido hecho, creyó, maravillado de la doctrina del Señor."}, {"numero": 13, "texto": "Y partidos de Papho, Pablo y sus compañeros arribaron á Perge de Pamphylia: entonces Juan, apartándose de ellos, se volvió á Jerusalem."}, {"numero": 14, "texto": "Y ellos pasando de Perge, llegaron á Antioquía de Pisidia, y entrando en la sinagoga un día de sábado, sentáronse."}, {"numero": 15, "texto": "Y después de la lectura de la ley y de los profetas, los príncipes de la sinagoga enviaron á ellos, diciendo: Varones hermanos, si tenéis alguna palabra de exhortación para el pueblo, hablad."}, {"numero": 16, "texto": "Entonces Pablo, levantándose, hecha señal de silencio con la mano, dice: Varones Israelitas, y los que teméis á Dios, oid:"}, {"numero": 17, "texto": "El Dios del pueblo de Israel escogió á nuestros padres, y ensalzó al pueblo, siendo ellos extranjeros en la tierra de Egipto, y con brazo levantado los sacó de ella."}, {"numero": 18, "texto": "Y por tiempo como de cuarenta años soportó sus costumbres en el desierto;"}, {"numero": 19, "texto": "Y destruyendo siete naciones en la tierra de Canaán, les repartió por suerte la tierra de ellas."}, {"numero": 20, "texto": "Y después, como por cuatrocientos y cincuenta años, dióles jueces hasta el profeta Samuel."}, {"numero": 21, "texto": "Y entonces demandaron rey; y les dió Dios á Saúl, hijo de Cis, varón de la tribu de Benjamín, por cuarenta años."}, {"numero": 22, "texto": "Y quitado aquél, levantóles por rey á David, al que dió también testimonio, diciendo: He hallado á David, hijo de Jessé, varón conforme á mi corazón, el cual hará todo lo que yo quiero."}, {"numero": 23, "texto": "De la simiente de éste, Dios, conforme á la promesa, levantó á Jesús por Salvador á Israel;"}, {"numero": 24, "texto": "Predicando Juan delante de la faz de su venida el bautismo de arrepentimiento á todo el pueblo de Israel."}, {"numero": 25, "texto": "Mas como Juan cumpliese su carrera, dijo: ¿Quién pensáis que soy? No soy yo él; mas he aquí, viene tras mí uno, cuyo calzado de los pies no soy digno de desatar."}, {"numero": 26, "texto": "Varones hermanos, hijos del linaje de Abraham, y los que entre vosotros temen á Dios, á vosotros es enviada la palabra de esta salud."}, {"numero": 27, "texto": "Porque los que habitaban en Jerusalem, y sus príncipes, no conociendo á éste, y las voces de los profetas que se leen todos los sábados, condenándole, las cumplieron."}, {"numero": 28, "texto": "Y sin hallar en él causa de muerte, pidieron á Pilato que le matasen."}, {"numero": 29, "texto": "Y habiendo cumplido todas las cosas que de él estaban escritas, quitándolo del madero, lo pusieron en el sepulcro."}, {"numero": 30, "texto": "Mas Dios le levantó de los muertos."}, {"numero": 31, "texto": "Y él fué visto por muchos días de los que habían subido juntamente con él de Galilea á Jerusalem, los cuales son sus testigos al pueblo."}, {"numero": 32, "texto": "Y nosotros también os anunciamos el evangelio de aquella promesa que fué hecha á los padres,"}, {"numero": 33, "texto": "La cual Dios ha cumplido á los hijos de ellos, á nosotros, resucitando á Jesús: como también en el salmo segundo está escrito: Mi hijo eres tú, yo te he engendrado hoy."}, {"numero": 34, "texto": "Y que le levantó de los muertos para nunca más volver á corrupción, así lo dijo: Os daré las misericordias fieles de David."}, {"numero": 35, "texto": "Por eso dice también en otro lugar: No permitirás que tu Santo vea corrupción."}, {"numero": 36, "texto": "Porque á la verdad David, habiendo servido en su edad á la voluntad de Dios, durmió, y fué juntado con sus padres, y vió corrupción:"}, {"numero": 37, "texto": "Mas aquel que Dios levantó, no vió corrupción."}, {"numero": 38, "texto": "Séaos pues notorio, varones hermanos, que por éste os es anunciada remisión de pecados;"}, {"numero": 39, "texto": "Y de todo lo que por la ley de Moisés no pudisteis ser justificados, en éste es justificado todo aquel que creyere."}, {"numero": 40, "texto": "Mirad, pues, que no venga sobre vosotros lo que está dicho en los profetas;"}, {"numero": 41, "texto": "Mirad, oh menospreciadores, y entonteceos, y desvaneceos; porque yo obro una obra en vuestros días, obra que no creeréis, si alguien os la contare."}, {"numero": 42, "texto": "Y saliendo ellos de la sinagoga de los Judíos, los Gentiles les rogaron que el sábado siguiente les hablasen estas palabras."}, {"numero": 43, "texto": "Y despedida la congregación, muchos de los Judíos y de los religiosos prosélitos siguieron á Pablo y á Bernabé; los cuales hablándoles, les persuadían que permaneciesen en la gracia de Dios."}, {"numero": 44, "texto": "Y el sábado siguiente se juntó casi toda la ciudad á oir la palabra de Dios."}, {"numero": 45, "texto": "Mas los Judíos, visto el gentío, llenáronse de celo, y se oponían á lo que Pablo decía, contradiciendo y blasfemando."}, {"numero": 46, "texto": "Entonces Pablo y Bernabé, usando de libertad, dijeron: A vosotros á la verdad era menester que se os hablase la palabra de Dios; mas pues que la desecháis, y os juzgáis indignos de la vida eterna, he aquí, nos volvemos á los Gentiles."}, {"numero": 47, "texto": "Porque así nos ha mandado el Señor, diciendo: Te he puesto para luz de los Gentiles, para que seas salud hasta lo postrero de la tierra."}, {"numero": 48, "texto": "Y los Gentiles oyendo esto, fueron gozosos, y glorificaban la palabra del Señor: y creyeron todos los que estaban ordenados para vida eterna."}, {"numero": 49, "texto": "Y la palabra del Señor era sembrada por toda aquella provincia."}, {"numero": 50, "texto": "Mas los Judíos concitaron mujeres pías y honestas, y á los principales de la ciudad, y levantaron persecución contra Pablo y Bernabé, y los echaron de sus términos."}, {"numero": 51, "texto": "Ellos entonces sacudiendo en ellos el polvo de sus pies, vinieron á Iconio."}, {"numero": 52, "texto": "Y los discípulos estaban llenos de gozo, y del Espíritu Santo."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 14, 'pt', '[{"numero": 1, "texto": "E aconteceu em Icônio, que entraram juntos na sinagoga dos judeus, e falaram de tal maneira que creu uma grande multidão, tanto de judeus como de gregos."}, {"numero": 2, "texto": "Mas os judeus incrédulos incitaram e irritaram os ânimos dos gentios contra os irmãos."}, {"numero": 3, "texto": "Então eles ficaram [ali] por muito tempo, falando ousadamente no Senhor, o qual dava testemunho à palavra de sua graça, concedendo [que] sinais e milagres fossem feitos pelas mãos deles."}, {"numero": 4, "texto": "E a multidão da cidade se dividiu; e uns eram a favor dos judeus, e outros a favor dos apóstolos."}, {"numero": 5, "texto": "E fazendo-se uma rebelião, tanto de judeus como de gentios, juntos com seus líderes, para falarem mal deles, e os apedrejarem."}, {"numero": 6, "texto": "E eles, sabendo [disto] ,fugiram para as cidades da Licaônia, [chamadas] Listra e Derbe; e à região ao redor."}, {"numero": 7, "texto": "E ali eles anunciavam ao Evangelho."}, {"numero": 8, "texto": "E um certo homem em Listra estava sentado, tendo incapacidade nos pés, aleijado desde o ventre de sua mãe, que nunca tinha andado."}, {"numero": 9, "texto": "Este ouviu Paulo falando; o qual, olhando com atenção, e vendo que ele tinha fé para ser curado,"}, {"numero": 10, "texto": "Disse em alta voz: Levanta-te direito sobre teus pés.E ele saltou e andou."}, {"numero": 11, "texto": "E as multidões, vendo o que Paulo tinha feito, levantaram suas vozes, dizendo em [língua] licaônica: Os deuses se fizeram semelhantes a homens, e desceram até nós."}, {"numero": 12, "texto": "E chamaram a Barnabé de Júpiter; e a Paulo, de Mercúrio; porque este era o líder ao falar."}, {"numero": 13, "texto": "E o sacerdote de Júpiter, que estava diante da cidade deles, trazendo touros e grinaldas à entrada da porta, ele, junto com as companhias, queria oferecer sacrifício [a eles] ."}, {"numero": 14, "texto": "Mas os apóstolos Barnabé e Paulo, ao ouvirem [isto] ,rasgaram suas roupas, e saltaram entre a multidão, clamando,"}, {"numero": 15, "texto": "E dizendo: Homens, por que fazeis estais coisas? Também nós somos homens como vós, sujeitos às mesmas emoções; e vos anunciamos o Evangelho para que vos convertais destas vaidades para o Deus vivo, que fez o céu, a terra, o mar, e tudo quanto neles há."}, {"numero": 16, "texto": "O qual nas gerações passadas deixou os os gentios andarem seus [próprios] caminhos."}, {"numero": 17, "texto": "Ainda que, contudo, não tenha deixado a si mesmo sem testemunho, fazendo o bem desde o céu, dando-nos chuvas, e tempos frutíferos, [e] enchendo nossos corações de alimento e alegria."}, {"numero": 18, "texto": "E tendo disto isto, apenas detiveram as multidões de que não fizessem sacrifícios a eles."}, {"numero": 19, "texto": "Mas vieram [alguns] judeus de Antioquia, e de Icônio, e persuadiram a multidão; e apedrejando a Paulo, arrastaram [-no] para fora da cidade, pensando que ele estivesse morto."}, {"numero": 20, "texto": "Mas, tendo os discípulos ficado ao seu redor, ele se levantou, e entrou na cidade; e no dia seguinte saiu com Barnabé para Derbe."}, {"numero": 21, "texto": "E tendo anunciado o Evangelho àquela cidade, e feito muitos discípulos, eles voltaram a Listra, e a Icônio, e a Antioquia,"}, {"numero": 22, "texto": "Confirmando os ânimos dos discípulos, e exortando-os para que permanecessem na fé, e que nos é necessário entrar no Reino de Deus por meio de muitas aflições."}, {"numero": 23, "texto": "E tendo escolhido por votação anciãos para cada igreja, orando com jejuns, eles foram enviados ao Senhor, no qual tinham crido."}, {"numero": 24, "texto": "E tendo passado por Pisídia, vieram à Panfília."}, {"numero": 25, "texto": "E tendo falado a palavra em Perges, desceram a Atália."}, {"numero": 26, "texto": "E dali navegaram para Antioquia, onde tinham sido encomendados à graça de Deus para a obra que eles [já] tinham cumprido."}, {"numero": 27, "texto": "E ao chegarem, e reunirem a igreja, relataram quão grandes coisas Deus tinha feito com eles; e como ele tinha aberto a porta da fé aos gentios."}, {"numero": 28, "texto": "E eles ficaram ali não pouco tempo com os discípulos."}]'::jsonb, 'Almeida Livre'),
  ('At', 14, 'en', '[{"numero": 1, "texto": "And it came to pass in Iconium, that they went both together into the synagogue of the Jews, and so spake, that a great multitude both of the Jews and also of the Greeks believed."}, {"numero": 2, "texto": "But the unbelieving Jews stirred up the Gentiles, and made their minds evil affected against the brethren."}, {"numero": 3, "texto": "Long time therefore abode they speaking boldly in the Lord, which gave testimony unto the word of his grace, and granted signs and wonders to be done by their hands."}, {"numero": 4, "texto": "But the multitude of the city was divided: and part held with the Jews, and part with the apostles."}, {"numero": 5, "texto": "And when there was an assault made both of the Gentiles, and also of the Jews with their rulers, to use them despitefully, and to stone them,"}, {"numero": 6, "texto": "They were ware of it, and fled unto Lystra and Derbe, cities of Lycaonia, and unto the region that lieth round about:"}, {"numero": 7, "texto": "And there they preached the gospel."}, {"numero": 8, "texto": "And there sat a certain man at Lystra, impotent in his feet, being a cripple from his mother''s womb, who never had walked:"}, {"numero": 9, "texto": "The same heard Paul speak: who stedfastly beholding him, and perceiving that he had faith to be healed,"}, {"numero": 10, "texto": "Said with a loud voice, Stand upright on thy feet. And he leaped and walked."}, {"numero": 11, "texto": "And when the people saw what Paul had done, they lifted up their voices, saying in the speech of Lycaonia, The gods are come down to us in the likeness of men."}, {"numero": 12, "texto": "And they called Barnabas, Jupiter; and Paul, Mercurius, because he was the chief speaker."}, {"numero": 13, "texto": "Then the priest of Jupiter, which was before their city, brought oxen and garlands unto the gates, and would have done sacrifice with the people."}, {"numero": 14, "texto": "Which when the apostles, Barnabas and Paul, heard of, they rent their clothes, and ran in among the people, crying out,"}, {"numero": 15, "texto": "And saying, Sirs, why do ye these things? We also are men of like passions with you, and preach unto you that ye should turn from these vanities unto the living God, which made heaven, and earth, and the sea, and all things that are therein:"}, {"numero": 16, "texto": "Who in times past suffered all nations to walk in their own ways."}, {"numero": 17, "texto": "Nevertheless he left not himself without witness, in that he did good, and gave us rain from heaven, and fruitful seasons, filling our hearts with food and gladness."}, {"numero": 18, "texto": "And with these sayings scarce restrained they the people, that they had not done sacrifice unto them."}, {"numero": 19, "texto": "And there came thither certain Jews from Antioch and Iconium, who persuaded the people, and having stoned Paul, drew him out of the city, supposing he had been dead."}, {"numero": 20, "texto": "Howbeit, as the disciples stood round about him, he rose up, and came into the city: and the next day he departed with Barnabas to Derbe."}, {"numero": 21, "texto": "And when they had preached the gospel to that city, and had taught many, they returned again to Lystra, and to Iconium, and Antioch,"}, {"numero": 22, "texto": "Confirming the souls of the disciples, and exhorting them to continue in the faith, and that we must through much tribulation enter into the kingdom of God."}, {"numero": 23, "texto": "And when they had ordained them elders in every church, and had prayed with fasting, they commended them to the Lord, on whom they believed."}, {"numero": 24, "texto": "And after they had passed throughout Pisidia, they came to Pamphylia."}, {"numero": 25, "texto": "And when they had preached the word in Perga, they went down into Attalia:"}, {"numero": 26, "texto": "And thence sailed to Antioch, from whence they had been recommended to the grace of God for the work which they fulfilled."}, {"numero": 27, "texto": "And when they were come, and had gathered the church together, they rehearsed all that God had done with them, and how he had opened the door of faith unto the Gentiles."}, {"numero": 28, "texto": "And there they abode long time with the disciples."}]'::jsonb, 'King James Version'),
  ('At', 14, 'fr', '[{"numero": 1, "texto": "A Icone, Paul et Barnabas entrèrent ensemble dans la synagogue des Juifs, et ils parlèrent de telle manière qu''''une grande multitude de Juifs et de Grecs crurent."}, {"numero": 2, "texto": "Mais ceux des Juifs qui ne crurent point excitèrent et aigrirent les esprits des païens contre les frères."}, {"numero": 3, "texto": "Ils restèrent cependant assez longtemps à Icone, parlant avec assurance, appuyés sur le Seigneur, qui rendait témoignage à la parole de sa grâce et permettait qu''''il se fît par leurs mains des prodiges et des miracles."}, {"numero": 4, "texto": "La population de la ville se divisa: les uns étaient pour les Juifs, les autres pour les apôtres."}, {"numero": 5, "texto": "Et comme les païens et les Juifs, de concert avec leurs chefs, se mettaient en mouvement pour les outrager et les lapider,"}, {"numero": 6, "texto": "Paul et Barnabas, en ayant eu connaissance, se réfugièrent dans les villes de la Lycaonie, à Lystre et à Derbe, et dans la contrée d''''alentour."}, {"numero": 7, "texto": "Et ils y annoncèrent la bonne nouvelle."}, {"numero": 8, "texto": "A Lystre, se tenait assis un homme impotent des pieds, boiteux de naissance, et qui n''''avait jamais marché."}, {"numero": 9, "texto": "Il écoutait parler Paul. Et Paul, fixant les regards sur lui et voyant qu''''il avait la foi pour être guéri,"}, {"numero": 10, "texto": "dit d''''une voix forte: Lève-toi droit sur tes pieds. Et il se leva d''''un bond et marcha."}, {"numero": 11, "texto": "A la vue de ce que Paul avait fait, la foule éleva la voix, et dit en langue lycaonienne: Les dieux sous une forme humaine sont descendus vers nous."}, {"numero": 12, "texto": "Ils appelaient Barnabas Jupiter, et Paul Mercure, parce que c''''était lui qui portait la parole."}, {"numero": 13, "texto": "Le prêtre de Jupiter, dont le temple était à l''''entrée de la ville, amena des taureaux avec des bandelettes vers les portes, et voulait, de même que la foule, offrir un sacrifice."}, {"numero": 14, "texto": "Les apôtres Barnabas et Paul, ayant appris cela, déchirèrent leurs vêtements, et se précipitèrent au milieu de la foule,"}, {"numero": 15, "texto": "en s''''écriant: O hommes, pourquoi agissez-vous de la sorte? Nous aussi, nous sommes des hommes de la même nature que vous; et, vous apportant une bonne nouvelle, nous vous exhortons à renoncer à ces choses vaines, pour vous tourner vers le Dieu vivant, qui a fait le ciel, la terre, la mer, et tout ce qui s''''y trouve."}, {"numero": 16, "texto": "Ce Dieu, dans les âges passés, a laissé toutes les nations suivre leurs propres voies,"}, {"numero": 17, "texto": "quoiqu''''il n''''ait cessé de rendre témoignage de ce qu''''il est, en faisant du bien, en vous dispensant du ciel les pluies et les saisons fertiles, en vous donnant la nourriture avec abondance et en remplissant vos coeurs de joie."}, {"numero": 18, "texto": "A peine purent-ils, par ces paroles, empêcher la foule de leur offrir un sacrifice."}, {"numero": 19, "texto": "Alors survinrent d''''Antioche et d''''Icone des Juifs qui gagnèrent la foule, et qui, après avoir lapidé Paul, le traînèrent hors de la ville, pensant qu''''il était mort."}, {"numero": 20, "texto": "Mais, les disciples l''''ayant entouré, il se leva, et entra dans la ville. Le lendemain, il partit pour Derbe avec Barnabas."}, {"numero": 21, "texto": "Quand ils eurent évangélisé cette ville et fait un certain nombre de disciples, ils retournèrent à Lystre, à Icone et à Antioche,"}, {"numero": 22, "texto": "fortifiant l''''esprit des disciples, les exhortant à persévérer dans la foi, et disant que c''''est par beaucoup de tribulations qu''''il nous faut entrer dans le royaume de Dieu."}, {"numero": 23, "texto": "Ils firent nommer des anciens dans chaque Eglise, et, après avoir prié et jeûné, ils les recommandèrent au Seigneur, en qui ils avaient cru."}, {"numero": 24, "texto": "Traversant ensuite la Pisidie, ils vinrent en Pamphylie,"}, {"numero": 25, "texto": "annoncèrent la parole à Perge, et descendirent à Attalie."}, {"numero": 26, "texto": "De là ils s''''embarquèrent pour Antioche, d''''où ils avaient été recommandés à la grâce de Dieu pour l''''oeuvre qu''''ils venaient d''''accomplir."}, {"numero": 27, "texto": "Après leur arrivée, ils convoquèrent l''''Eglise, et ils racontèrent tout ce que Dieu avait fait avec eux, et comment il avait ouvert aux nations la porte de la foi."}, {"numero": 28, "texto": "Et ils demeurèrent assez longtemps avec les disciples."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 14, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ en Iconio, que entrados juntamente en la sinagoga de los Judíos, hablaron de tal manera, que creyó una grande multitud de Judíos, y asimismo de Griegos."}, {"numero": 2, "texto": "Mas los Judíos que fueron incrédulos, incitaron y corrompieron los ánimos de los Gentiles contra los hermanos."}, {"numero": 3, "texto": "Con todo eso se detuvieron allí mucho tiempo, confiados en el Señor, el cual daba testimonio á la palabra de su gracia, dando que señales y milagros fuesen hechos por las manos de ellos."}, {"numero": 4, "texto": "Mas el vulgo de la ciudad estaba dividido; y unos eran con los Judíos, y otros con los apóstoles."}, {"numero": 5, "texto": "Y haciendo ímpetu los Judíos y los Gentiles juntamente con sus príncipes, para afrentarlos y apedrearlos,"}, {"numero": 6, "texto": "Habiéndolo entendido, huyeron á Listra y Derbe, ciudades de Licaonia, y por toda la tierra alrededor."}, {"numero": 7, "texto": "Y allí predicaban el evangelio."}, {"numero": 8, "texto": "Y un hombre de Listra, impotente de los pies, estaba sentado, cojo desde el vientre de su madre, que jamás había andado."}, {"numero": 9, "texto": "Este oyó hablar á Pablo; el cual, como puso los ojos en él, y vió que tenía fe para ser sano,"}, {"numero": 10, "texto": "Dijo á gran voz: Levántate derecho sobre tus pies. Y saltó, y anduvo."}, {"numero": 11, "texto": "Entonces las gentes, visto lo que Pablo había hecho, alzaron la voz, diciendo en lengua licaónica: Dioses semejantes á hombres han descendido á nosotros."}, {"numero": 12, "texto": "Y á Bernabé llamaban Júpiter, y á Pablo, Mercurio, porque era el que llevaba la palabra."}, {"numero": 13, "texto": "Y el sacerdote de Júpiter, que estaba delante de la ciudad de ellos, trayendo toros y guirnaldas delante de las puertas, quería con el pueblo sacrificar."}, {"numero": 14, "texto": "Y como lo oyeron los apóstoles Bernabé y Pablo, rotas sus ropas, se lanzaron al gentío, dando voces,"}, {"numero": 15, "texto": "Y diciendo: Varones, ¿por qué hacéis esto? Nosotros también somos hombres semejantes á vosotros, que os anunciamos que de estas vanidades os convirtáis al Dios vivo, que hizo el cielo y la tierra, y la mar, y todo lo que está en ellos:"}, {"numero": 16, "texto": "El cual en las edades pasadas ha dejado á todas las gentes andar en sus caminos;"}, {"numero": 17, "texto": "Si bien no se dejó á sí mismo sin testimonio, haciendo bien, dándonos lluvias del cielo y tiempos fructíferos, hinchiendo de mantenimiento y de alegría nuestros corazones."}, {"numero": 18, "texto": "Y diciendo estas cosas, apenas apaciguaron el pueblo, para que no les ofreciesen sacrificio."}, {"numero": 19, "texto": "Entonces sobrevinieron unos Judíos de Antioquía y de Iconio, que persuadieron á la multitud, y habiendo apedreado á Pablo, le sacaron fuera de la ciudad, pensando que estaba muerto."}, {"numero": 20, "texto": "Mas rodeándole los discípulos, se levantó y entró en la ciudad; y un día después, partió con Bernabé á Derbe."}, {"numero": 21, "texto": "Y como hubieron anunciado el evangelio á aquella ciudad, y enseñado á muchos, volvieron á Listra, y á Iconio, y á Antioquía,"}, {"numero": 22, "texto": "Confirmando los ánimos de los discípulos, exhortándoles á que permaneciesen en la fe, y que es menester que por muchas tribulaciones entremos en el reino de Dios."}, {"numero": 23, "texto": "Y habiéndoles constituído ancianos en cada una de las iglesias, y habiendo orado con ayunos, los encomendaron al Señor en el cual habían creído."}, {"numero": 24, "texto": "Y pasando por Pisidia vinieron á Pamphylia."}, {"numero": 25, "texto": "Y habiendo predicado la palabra en Perge, descendieron á Atalia;"}, {"numero": 26, "texto": "Y de allí navegaron á Antioquía, donde habían sido encomendados á la gracia de Dios para la obra que habían acabado."}, {"numero": 27, "texto": "Y habiendo llegado, y reunido la iglesia, relataron cuán grandes cosas había Dios hecho con ellos, y cómo había abierto á los Gentiles la puerta de la fe."}, {"numero": 28, "texto": "Y se quedaron allí mucho tiempo con los discípulos."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 15, 'pt', '[{"numero": 1, "texto": "E alguns que tinham descido da Judeia ensinavam aos irmãos, [dizendo] : Se vós não vos circuncidardes conforme o costume de Moisés, não podeis ser salvos."}, {"numero": 2, "texto": "Então, havendo não pequena resistência e confronto de Paulo e Barnabé contra eles, ordenaram que Paulo, Barnabé e alguns outros deles subissem aos apóstolos e aos anciãos a Jerusalém sobre esta questão."}, {"numero": 3, "texto": "Então sendo eles preparados para a viagem e despedidos pela igreja, passaram pela Fenícia e Samaria, contando [sobre] a conversão dos gentios; e davam grande alegria a todos os irmãos."}, {"numero": 4, "texto": "E tendo chegado a Jerusalém, eles foram recebidos pela igreja, e pelos apóstolos e anciãos; e lhes anunciaram quão grandes coisas Deus tinha feito com eles;"}, {"numero": 5, "texto": "Mas [que] alguns do grupo dos fariseus que tinham crido, levantaram-se, dizendo que era necessário circuncidá-los, e mandar [-lhes] que guardem a Lei de Moisés."}, {"numero": 6, "texto": "E os apóstolos e anciãos se reuniram para dar atenção a este assunto."}, {"numero": 7, "texto": "E havendo muita discussão, Pedro se levantou, e lhes disse: Homens irmãos, vós sabeis que há muito tempo Deus [meu] escolheu entre nós, para que por minha boca os gentios ouvissem a palavra do Evangelho, e cressem."}, {"numero": 8, "texto": "E Deus, que conhece os corações, deu-lhes testemunho, dando-lhes o Espírito Santo, assim como também a nós."}, {"numero": 9, "texto": "E nenhuma diferença fez entre nós e eles, purificando seus corações pela fé."}, {"numero": 10, "texto": "Então agora, por que tentais a Deus, pondo um jugo sobre o pescoço dos discípulos; que nem nossos pais, nem nós podemos levar?"}, {"numero": 11, "texto": "Mas cremos que, pela graça do Senhor Jesus Cristo, nós somos salvos, assim como também eles."}, {"numero": 12, "texto": "E toda a multidão se calou; e ouviram a Barnabé e a Paulo, que contavam quão grandes sinais e milagres Deus tinha feito por meio deles entre os gentios."}, {"numero": 13, "texto": "E tendo estes se calado, Tiago respondeu, dizendo: Homens irmãos, ouvi-me:"}, {"numero": 14, "texto": "Simão informou como primeiro Deus visitou aos gentios, para tomar [deles] um povo para seu nome."}, {"numero": 15, "texto": "E com isso concordam as palavras dos profetas, como está escrito:"}, {"numero": 16, "texto": "Depois disto eu voltarei, e reconstruirei o tabernáculo de Davi, que caído está; e reconstruirei [de] suas ruínas, e voltarei a levantá-lo;"}, {"numero": 17, "texto": "Para que o resto da humanidade busque ao Senhor, e todos os gentios sobre os quais meu nome é invocado, diz o Senhor, que faz todas estas coisas."}, {"numero": 18, "texto": "São conhecidas por Deus desde a antiguidade todas as suas obras."}, {"numero": 19, "texto": "Portanto eu julgo que aqueles que dos gentios se convertem a Deus não devem ser perturbados."}, {"numero": 20, "texto": "Mas [que] lhes escrevamos para que se abstenham das contaminações dos ídolos, e do pecado sexual, e da [carne] sufocada, e do sangue."}, {"numero": 21, "texto": "Porque Moisés, desde as gerações antigas, tem em cada cidade quem o pregue nas sinagogas, sendo lido todo sábado."}, {"numero": 22, "texto": "Então pareceu bem aos apóstolos, e aos anciãos, com toda a igreja, eleger deles [alguns] homens, para serem enviados com Paulo e Barnabé a Antioquia: Judas, que tinha por sobrenome Barsabás; e a Silas, homens líderes entre os irmãos."}, {"numero": 23, "texto": "E escreveram por meio deles o seguinte: Os apóstolos e os anciãos, e os irmãos – para os irmãos dentre os gentios, que [estão] em Antioquia, Síria e Cilícia; saudações."}, {"numero": 24, "texto": "Dado que ouvimos que alguns dos que saíram de nós vos perturbaram com palavras, [e] causaram incômodo a vossas almas, dizendo que deveis vos circuncidar e guardar a Lei, aos quais não mandamos;"}, {"numero": 25, "texto": "Pareceu-nos bem, reunidos em concordância, escolher [alguns] homens, e enviá-los até vós, com nossos amados Barnabé e Paulo."}, {"numero": 26, "texto": "Homens que têm arriscado suas vidas pelo nome de nosso Senhor Jesus Cristo."}, {"numero": 27, "texto": "Então enviamos a Judas e a Silas, os quais [vos] dirão as mesmas coisas pessoalmente."}, {"numero": 28, "texto": "Porque pareceu bem ao Espírito Santo e a nós, de nenhuma carga a mais vos impor, a não ser estas coisas necessárias:"}, {"numero": 29, "texto": "Que vos abstenhais das coisas sacrificadas aos ídolos, do sangue, da [carne] sufocada, e do pecado sexual; das quais, se vos guardardes, fareis bem. Que o bem vos suceda."}, {"numero": 30, "texto": "Sendo, pois, eles despedidos, vieram a Antioquia, e reunindo a multidão, entregaram a carta."}, {"numero": 31, "texto": "E ao lerem, alegraram-se pela consolação."}, {"numero": 32, "texto": "E então Judas e Silas, sendo também profetas, com muitas palavras exortaram e firmaram aos irmãos."}, {"numero": 33, "texto": "E ficando [ali] por algum tempo, permitiram que voltassem em paz dos irmãos para os apóstolos."}, {"numero": 34, "texto": "Mas a Silas pareceu bem continuar ali."}, {"numero": 35, "texto": "E Paulo e Barnabé ficaram em Antioquia, ensinando e evangelizando, com também muitos outros, a palavra do Senhor."}, {"numero": 36, "texto": "E depois de alguns dias, Paulo disse a Barnabé: Voltemos a visitar a nossos irmãos em cada cidade onde tenhamos anunciado a palavra do Senhor, [para ver] como estão."}, {"numero": 37, "texto": "E Barnabé aconselhou para que tomassem consigo a João, chamado Marcos."}, {"numero": 38, "texto": "Mas Paulo achou adequado que não tomassem consigo a aquele que desde a Panfília tinha se separado deles, e não tinha ido com eles para [aquela] obra."}, {"numero": 39, "texto": "Houve então [entre eles] tal discórdia, que eles se separaram um do outro; e Barnabé, tomando consigo a Marcos, navegou para o Chipre."}, {"numero": 40, "texto": "Mas Paulo, escolhendo a Silas, partiu-se, enviado pelos irmãos para a graça de Deus."}, {"numero": 41, "texto": "E ele passou pela Síria e Cilícia, firmando as igrejas."}]'::jsonb, 'Almeida Livre'),
  ('At', 15, 'en', '[{"numero": 1, "texto": "And certain men which came down from Judaea taught the brethren, and said, Except ye be circumcised after the manner of Moses, ye cannot be saved."}, {"numero": 2, "texto": "When therefore Paul and Barnabas had no small dissension and disputation with them, they determined that Paul and Barnabas, and certain other of them, should go up to Jerusalem unto the apostles and elders about this question."}, {"numero": 3, "texto": "And being brought on their way by the church, they passed through Phenice and Samaria, declaring the conversion of the Gentiles: and they caused great joy unto all the brethren."}, {"numero": 4, "texto": "And when they were come to Jerusalem, they were received of the church, and of the apostles and elders, and they declared all things that God had done with them."}, {"numero": 5, "texto": "But there rose up certain of the sect of the Pharisees which believed, saying, That it was needful to circumcise them, and to command them to keep the law of Moses."}, {"numero": 6, "texto": "And the apostles and elders came together for to consider of this matter."}, {"numero": 7, "texto": "And when there had been much disputing, Peter rose up, and said unto them, Men and brethren, ye know how that a good while ago God made choice among us, that the Gentiles by my mouth should hear the word of the gospel, and believe."}, {"numero": 8, "texto": "And God, which knoweth the hearts, bare them witness, giving them the Holy Ghost, even as he did unto us;"}, {"numero": 9, "texto": "And put no difference between us and them, purifying their hearts by faith."}, {"numero": 10, "texto": "Now therefore why tempt ye God, to put a yoke upon the neck of the disciples, which neither our fathers nor we were able to bear?"}, {"numero": 11, "texto": "But we believe that through the grace of the Lord Jesus Christ we shall be saved, even as they."}, {"numero": 12, "texto": "Then all the multitude kept silence, and gave audience to Barnabas and Paul, declaring what miracles and wonders God had wrought among the Gentiles by them."}, {"numero": 13, "texto": "And after they had held their peace, James answered, saying, Men and brethren, hearken unto me:"}, {"numero": 14, "texto": "Simeon hath declared how God at the first did visit the Gentiles, to take out of them a people for his name."}, {"numero": 15, "texto": "And to this agree the words of the prophets; as it is written,"}, {"numero": 16, "texto": "After this I will return, and will build again the tabernacle of David, which is fallen down; and I will build again the ruins thereof, and I will set it up:"}, {"numero": 17, "texto": "That the residue of men might seek after the Lord, and all the Gentiles, upon whom my name is called, saith the Lord, who doeth all these things."}, {"numero": 18, "texto": "Known unto God are all his works from the beginning of the world."}, {"numero": 19, "texto": "Wherefore my sentence is, that we trouble not them, which from among the Gentiles are turned to God:"}, {"numero": 20, "texto": "But that we write unto them, that they abstain from pollutions of idols, and from fornication, and from things strangled, and from blood."}, {"numero": 21, "texto": "For Moses of old time hath in every city them that preach him, being read in the synagogues every sabbath day."}, {"numero": 22, "texto": "Then pleased it the apostles and elders with the whole church, to send chosen men of their own company to Antioch with Paul and Barnabas; namely, Judas surnamed Barsabas and Silas, chief men among the brethren:"}, {"numero": 23, "texto": "And they wrote letters by them after this manner; The apostles and elders and brethren send greeting unto the brethren which are of the Gentiles in Antioch and Syria and Cilicia."}, {"numero": 24, "texto": "Forasmuch as we have heard, that certain which went out from us have troubled you with words, subverting your souls, saying, Ye must be circumcised, and keep the law: to whom we gave no such commandment:"}, {"numero": 25, "texto": "It seemed good unto us, being assembled with one accord, to send chosen men unto you with our beloved Barnabas and Paul,"}, {"numero": 26, "texto": "Men that have hazarded their lives for the name of our Lord Jesus Christ."}, {"numero": 27, "texto": "We have sent therefore Judas and Silas, who shall also tell you the same things by mouth."}, {"numero": 28, "texto": "For it seemed good to the Holy Ghost, and to us, to lay upon you no greater burden than these necessary things;"}, {"numero": 29, "texto": "That ye abstain from meats offered to idols, and from blood, and from things strangled, and from fornication: from which if ye keep yourselves, ye shall do well. Fare ye well."}, {"numero": 30, "texto": "So when they were dismissed, they came to Antioch: and when they had gathered the multitude together, they delivered the epistle:"}, {"numero": 31, "texto": "Which when they had read, they rejoiced for the consolation."}, {"numero": 32, "texto": "And Judas and Silas, being prophets also themselves, exhorted the brethren with many words, and confirmed them."}, {"numero": 33, "texto": "And after they had tarried there a space, they were let go in peace from the brethren unto the apostles."}, {"numero": 34, "texto": "Notwithstanding it pleased Silas to abide there still."}, {"numero": 35, "texto": "Paul also and Barnabas continued in Antioch, teaching and preaching the word of the Lord, with many others also."}, {"numero": 36, "texto": "And some days after Paul said unto Barnabas, Let us go again and visit our brethren in every city where we have preached the word of the Lord, and see how they do."}, {"numero": 37, "texto": "And Barnabas determined to take with them John, whose surname was Mark."}, {"numero": 38, "texto": "But Paul thought not good to take him with them, who departed from them from Pamphylia, and went not with them to the work."}, {"numero": 39, "texto": "And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus;"}, {"numero": 40, "texto": "And Paul chose Silas, and departed, being recommended by the brethren unto the grace of God."}, {"numero": 41, "texto": "And he went through Syria and Cilicia, confirming the churches."}]'::jsonb, 'King James Version'),
  ('At', 15, 'fr', '[{"numero": 1, "texto": "Quelques hommes, venus de la Judée, enseignaient les frères, en disant: Si vous n''''êtes circoncis selon le rite de Moïse, vous ne pouvez être sauvés."}, {"numero": 2, "texto": "Paul et Barnabas eurent avec eux un débat et une vive discussion; et les frères décidèrent que Paul et Barnabas, et quelques-uns des leurs, monteraient à Jérusalem vers les apôtres et les anciens, pour traiter cette question."}, {"numero": 3, "texto": "Après avoir été accompagnés par l''''Eglise, ils poursuivirent leur route à travers la Phénicie et la Samarie, racontant la conversion des païens, et ils causèrent une grande joie à tous les frères."}, {"numero": 4, "texto": "Arrivés à Jérusalem, ils furent reçus par l''''Eglise, les apôtres et les anciens, et ils racontèrent tout ce que Dieu avait fait avec eux."}, {"numero": 5, "texto": "Alors quelques-uns du parti des pharisiens, qui avaient cru, se levèrent, en disant qu''''il fallait circoncire les païens et exiger l''''observation de la loi de Moïse."}, {"numero": 6, "texto": "Les apôtres et les anciens se réunirent pour examiner cette affaire."}, {"numero": 7, "texto": "Une grande discussion s''''étant engagée, Pierre se leva, et leur dit: Hommes frères, vous savez que dès longtemps Dieu a fait un choix parmi vous, afin que, par ma bouche, les païens entendissent la parole de l''''Evangile et qu''''ils crussent."}, {"numero": 8, "texto": "Et Dieu, qui connaît les coeurs, leur a rendu témoignage, en leur donnant le Saint-Esprit comme à nous;"}, {"numero": 9, "texto": "il n''''a fait aucune différence entre nous et eux, ayant purifié leurs coeurs par la foi."}, {"numero": 10, "texto": "Maintenant donc, pourquoi tentez-vous Dieu, en mettant sur le cou des disciples un joug que ni nos pères ni nous n''''avons pu porter?"}, {"numero": 11, "texto": "Mais c''''est par la grâce du Seigneur Jésus que nous croyons être sauvés, de la même manière qu''''eux."}, {"numero": 12, "texto": "Toute l''''assemblée garda le silence, et l''''on écouta Barnabas et Paul, qui racontèrent tous les miracles et les prodiges que Dieu avait faits par eux au milieu des païens."}, {"numero": 13, "texto": "Lorsqu''''ils eurent cessé de parler, Jacques prit la parole, et dit: Hommes frères, écoutez-moi!"}, {"numero": 14, "texto": "Simon a raconté comment Dieu a d''''abord jeté les regards sur les nations pour choisir du milieu d''''elles un peuple qui portât son nom."}, {"numero": 15, "texto": "Et avec cela s''''accordent les paroles des prophètes, selon qu''''il est écrit:"}, {"numero": 16, "texto": "Après cela, je reviendrai, et je relèverai de sa chute la tente de David, J''''en réparerai les ruines, et je la redresserai,"}, {"numero": 17, "texto": "Afin que le reste des hommes cherche le Seigneur, Ainsi que toutes les nations sur lesquelles mon nom est invoqué, Dit le Seigneur, qui fait ces choses,"}, {"numero": 18, "texto": "Et à qui elles sont connues de toute éternité."}, {"numero": 19, "texto": "C''''est pourquoi je suis d''''avis qu''''on ne crée pas des difficultés à ceux des païens qui se convertissent à Dieu,"}, {"numero": 20, "texto": "mais qu''''on leur écrive de s''''abstenir des souillures des idoles, de l''''impudicité, des animaux étouffés et du sang."}, {"numero": 21, "texto": "Car, depuis bien des générations, Moïse a dans chaque ville des gens qui le prêchent, puisqu''''on le lit tous les jours de sabbat dans les synagogues."}, {"numero": 22, "texto": "Alors il parut bon aux apôtres et aux anciens, et à toute l''''Eglise, de choisir parmi eux et d''''envoyer à Antioche, avec Paul et Barnabas, Jude appelé Barsabas et Silas, hommes considérés entre les frères."}, {"numero": 23, "texto": "Ils les chargèrent d''''une lettre ainsi conçue: Les apôtres, les anciens, et les frères, aux frères d''''entre les païens, qui sont à Antioche, en Syrie, et en Cilicie, salut!"}, {"numero": 24, "texto": "Ayant appris que quelques hommes partis de chez nous, et auxquels nous n''''avions donné aucun ordre, vous ont troublés par leurs discours et ont ébranlé vos âmes,"}, {"numero": 25, "texto": "nous avons jugé à propos, après nous être réunis tous ensemble, de choisir des délégués et de vous les envoyer avec nos bien-aimés Barnabas et Paul,"}, {"numero": 26, "texto": "ces hommes qui ont exposé leur vie pour le nom de notre Seigneur Jésus-Christ."}, {"numero": 27, "texto": "Nous avons donc envoyé Jude et Silas, qui vous annonceront de leur bouche les mêmes choses."}, {"numero": 28, "texto": "Car il a paru bon au Saint-Esprit et à nous de ne vous imposer d''''autre charge que ce qui est nécessaire,"}, {"numero": 29, "texto": "savoir, de vous abstenir des viandes sacrifiées aux idoles, du sang, des animaux étouffés, et de l''''impudicité, choses contre lesquelles vous vous trouverez bien de vous tenir en garde. Adieu."}, {"numero": 30, "texto": "Eux donc, ayant pris congé de l''''Eglise, allèrent à Antioche, où ils remirent la lettre à la multitude assemblée."}, {"numero": 31, "texto": "Après l''''avoir lue, les frères furent réjouis de l''''encouragement qu''''elle leur apportait."}, {"numero": 32, "texto": "Jude et Silas, qui étaient eux-mêmes prophètes, les exhortèrent et les fortifièrent par plusieurs discours."}, {"numero": 33, "texto": "Au bout de quelque temps, les frères les laissèrent en paix retourner vers ceux qui les avaient envoyés."}, {"numero": 34, "texto": "Toutefois Silas trouva bon de rester."}, {"numero": 35, "texto": "Paul et Barnabas demeurèrent à Antioche, enseignant et annonçant, avec plusieurs autres, la bonne nouvelle de la parole du Seigneur."}, {"numero": 36, "texto": "Quelques jours s''''écoulèrent, après lesquels Paul dit à Barnabas: Retournons visiter les frères dans toutes les villes où nous avons annoncé la parole du Seigneur, pour voir en quel état ils sont."}, {"numero": 37, "texto": "Barnabas voulait emmener aussi Jean, surnommé Marc;"}, {"numero": 38, "texto": "mais Paul jugea plus convenable de ne pas prendre avec eux celui qui les avait quittés depuis la Pamphylie, et qui ne les avait point accompagnés dans leur oeuvre."}, {"numero": 39, "texto": "Ce dissentiment fut assez vif pour être cause qu''''ils se séparèrent l''''un de l''''autre. Et Barnabas, prenant Marc avec lui, s''''embarqua pour l''''île de Chypre."}, {"numero": 40, "texto": "Paul fit choix de Silas, et partit, recommandé par les frères à la grâce du Seigneur."}, {"numero": 41, "texto": "Il parcourut la Syrie et la Cilicie, fortifiant les Eglises."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 15, 'es', '[{"numero": 1, "texto": "ENTONCES algunos que venían de Judea enseñaban á los hermanos: Que si no os circuncidáis conforme al rito de Moisés, no podéis ser salvos."}, {"numero": 2, "texto": "Así que, suscitada una disensión y contienda no pequeña á Pablo y á Bernabé contra ellos, determinaron que subiesen Pablo y Bernabé á Jerusalem, y algunos otros de ellos, á los apóstoles y á los ancianos, sobre esta cuestión."}, {"numero": 3, "texto": "Ellos, pues, habiendo sido acompañados de la iglesia, pasaron por la Fenicia y Samaria, contando la conversión de los Gentiles; y daban gran gozo á todos los hermanos."}, {"numero": 4, "texto": "Y llegados á Jerusalem, fueron recibidos de la iglesia y de los apóstoles y de los ancianos: y refirieron todas las cosas que Dios había hecho con ellos."}, {"numero": 5, "texto": "Mas algunos de la secta de los Fariseos, que habían creído, se levantaron, diciendo: Que es menester circuncidarlos, y mandarles que guarden la ley de Moisés."}, {"numero": 6, "texto": "Y se juntaron los apóstoles y los ancianos para conocer de este negocio."}, {"numero": 7, "texto": "Y habiendo habido grande contienda, levantándose Pedro, les dijo: Varones hermanos, vosotros sabéis cómo ya hace algún tiempo que Dios escogió que los Gentiles oyesen por mi boca la palabra del evangelio, y creyesen."}, {"numero": 8, "texto": "Y Dios, que conoce los corazones, les dió testimonio, dándoles el Espíritu Santo también como á nosotros;"}, {"numero": 9, "texto": "Y ninguna diferencia hizo entre nosotros y ellos, purificando con la fe sus corazones."}, {"numero": 10, "texto": "Ahora pues, ¿por qué tentáis á Dios, poniendo sobre la cerviz de los discípulos yugo, que ni nuestros padres ni nosotros hemos podido llevar?"}, {"numero": 11, "texto": "Antes por la gracia del Señor Jesús creemos que seremos salvos, como también ellos."}, {"numero": 12, "texto": "Entonces toda la multitud calló, y oyeron á Bernabé y á Pablo, que contaban cuán grandes maravillas y señales Dios había hecho por ellos entre los Gentiles."}, {"numero": 13, "texto": "Y después que hubieron callado, Jacobo respondió, diciendo: Varones hermanos, oidme:"}, {"numero": 14, "texto": "Simón ha contado cómo Dios primero visitó á los Gentiles, para tomar de ellos pueblo para su nombre;"}, {"numero": 15, "texto": "Y con esto concuerdan las palabras de los profetas, como está escrito:"}, {"numero": 16, "texto": "Después de esto volveré y restauraré la habitación de David, que estaba caída; y repararé sus ruinas, y la volveré á levantar;"}, {"numero": 17, "texto": "Para que el resto de los hombres busque al Señor, y todos los Gentiles, sobre los cuales es llamado mi nombre, dice el Señor, que hace todas estas cosas."}, {"numero": 18, "texto": "Conocidas son á Dios desde el siglo todas sus obras."}, {"numero": 19, "texto": "Por lo cual yo juzgo, que los que de los Gentiles se convierten á Dios, no han de ser inquietados;"}, {"numero": 20, "texto": "Sino escribirles que se aparten de las contaminaciones de los ídolos, y de fornicación, y de ahogado, y de sangre."}, {"numero": 21, "texto": "Porque Moisés desde los tiempos antiguos tiene en cada ciudad quien le predique en las sinagogas, donde es leído cada sábado."}, {"numero": 22, "texto": "Entonces pareció bien á los apóstoles y á los ancianos, con toda la iglesia, elegir varones de ellos, y enviarlos á Antioquía con Pablo y Bernabé: á Judas que tenía por sobrenombre Barsabas, y á Silas, varones principales entre los hermanos;"}, {"numero": 23, "texto": "Y escribir por mano de ellos: Los apóstoles y los ancianos y los hermanos, á los hermanos de los Gentiles que están en Antioquía, y en Siria, y en Cilicia, salud:"}, {"numero": 24, "texto": "Por cuanto hemos oído que algunos que han salido de nosotros, os han inquietado con palabras, trastornando vuestras almas, mandando circuncidaros y guardar la ley, á los cuales no mandamos;"}, {"numero": 25, "texto": "Nos ha parecido, congregados en uno, elegir varones, y enviarlos á vosotros con nuestros amados Bernabé y Pablo,"}, {"numero": 26, "texto": "Hombres que han expuesto sus vidas por el nombre de nuestro Señor Jesucristo."}, {"numero": 27, "texto": "Así que, enviamos á Judas y á Silas, los cuales también por palabra os harán saber lo mismo."}, {"numero": 28, "texto": "Que ha parecido bien al Espíritu Santo, y á nosotros, no imponeros ninguna carga más que estas cosas necesarias:"}, {"numero": 29, "texto": "Que os abstengáis de cosas sacrificadas á ídolos, y de sangre, y de ahogado, y de fornicación; de las cuales cosas si os guardareis, bien haréis. Pasadlo bien."}, {"numero": 30, "texto": "Ellos entonces enviados, descendieron á Antioquía; y juntando la multitud, dieron la carta."}, {"numero": 31, "texto": "La cual, como leyeron, fueron gozosos de la consolación."}, {"numero": 32, "texto": "Judas también y Silas, como ellos también eran profetas, consolaron y confirmaron á los hermanos con abundancia de palabra."}, {"numero": 33, "texto": "Y pasando allí algún tiempo, fueron enviados de los hermanos á los apóstoles en paz."}, {"numero": 34, "texto": "Mas á Silas pareció bien el quedarse allí."}, {"numero": 35, "texto": "Y Pablo y Bernabé se estaban en Antioquía, enseñando la palabra del Señor y anunciando el evangelio con otros muchos."}, {"numero": 36, "texto": "Y después de algunos días, Pablo dijo á Bernabé: Volvamos á visitar á los hermanos por todas las ciudades en las cuales hemos anunciado la palabra del Señor, cómo están."}, {"numero": 37, "texto": "Y Bernabé quería que tomasen consigo á Juan, el que tenía por sobrenombre Marcos;"}, {"numero": 38, "texto": "Mas á Pablo no le parecía bien llevar consigo al que se había apartado de ellos desde Pamphylia, y no había ido con ellos á la obra."}, {"numero": 39, "texto": "Y hubo tal contención entre ellos, que se apartaron el uno del otro; y Bernabé tomando á Marcos, navegó á Cipro."}, {"numero": 40, "texto": "Y Pablo escogiendo á Silas, partió encomendado de los hermanos á la gracia del Señor."}, {"numero": 41, "texto": "Y anduvo la Siria y la Cilicia, confirmando á las iglesias."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 16, 'pt', '[{"numero": 1, "texto": "E ele veio a Derbe e Listra; e eis que estava ali um certo discípulo, de nome Timóteo, filho de uma certa mulher judia crente, mas de pai grego."}, {"numero": 2, "texto": "Do qual era [bem] testemunhado pelos irmãos [que estavam] em Listra e Icônio."}, {"numero": 3, "texto": "A este Paulo quis que fosse com ele; e tomando-o, circuncidou-o, por causa dos judeus, que estavam naqueles lugares; porque todos conheciam o pai dele, que era grego."}, {"numero": 4, "texto": "E eles, passando pelas cidades, entregavam-lhes as ordenanças que foram determinadas pelos apóstolos e anciãos em Jerusalém, para que [as] guardassem."}, {"numero": 5, "texto": "E assim as Igrejas eram firmadas na fé, e cada dia aumentavam em número."}, {"numero": 6, "texto": "E passando pela Frígia, e pela região da Galácia, foi-lhes impedido pelo Espírito Santo de falarem a palavra na Ásia."}, {"numero": 7, "texto": "[E] quando eles vieram a Mísia, tentaram ir à Bitínia; mas o Espírito não lhes permitiu."}, {"numero": 8, "texto": "E tendo passado por Mísia, desceram a Trôade."}, {"numero": 9, "texto": "E uma visão foi vista por Paulo durante a noite: um homem Macedônio se pôs [diante dele] ,rogando-lhe, e dizendo: Passa à Macedônia, e ajuda-nos!"}, {"numero": 10, "texto": "E quando ele viu a visão, logo procuramos partir para a Macedônia, concluindo que o Senhor estava nos chamando para anunciarmos o Evangelho a eles."}, {"numero": 11, "texto": "Então, tendo navegado desde Trôade, viemos correndo caminho direto a Samotrácia, e no [dia] seguinte a Neápolis."}, {"numero": 12, "texto": "E dali a Filipos, que é a primeira cidade desta parte da Macedônia, [e é] uma colônia; e estivemos naquela cidade [por] alguns dias."}, {"numero": 13, "texto": "E no dia de sábado saímos para fora da cidade, onde costumava ser feita oração; e tendo [nos] sentado, falamos às mulheres que tinham se ajuntado [ali] ."}, {"numero": 14, "texto": "E uma certa mulher, por nome Lídia, vendedora de púrpura, da cidade de Tiatira, que servia a Deus; [ela nos] ouviu; o coração da qual o Senhor abriu, para que prestasse atenção ao que Paulo dizia."}, {"numero": 15, "texto": "E quando ela foi batizada, e [também] sua casa, ela [nos] rogou, dizendo: Se vós tendes julgado que eu seja fiel ao Senhor, entrai em minha casa e ficai ali.E ela insistiu para conosco."}, {"numero": 16, "texto": "E aconteceu, que ao estarmos nós indo à oração, saiu ao nosso encontro uma moça que tinha espírito de pitonisa; a qual ao fazer adivinhações trazia grande lucro a seus senhores."}, {"numero": 17, "texto": "Esta, seguindo após Paulo e nós, clamava, dizendo: Estes homens são servos do Deus Altíssimo, que nos anunciam o caminho da salvação."}, {"numero": 18, "texto": "E ela fazia isto por muitos dias. Mas Paulo, estando descontente com isto, virou-se, e disse ao espírito: Em nome de Jesus Cristo eu te mando que saias dela.E na mesma hora [o espírito] saiu."}, {"numero": 19, "texto": "E os senhores dela, vendo que a esperança de lucro deles tinha ido embora, pegaram a Paulo e a Silas, e [os] levaram à praça, diante dos governantes."}, {"numero": 20, "texto": "E apresentando-os aos magistrados, disseram: Estes homens perturbam nossa cidade, sendo judeus;"}, {"numero": 21, "texto": "E eles anunciam costumes que não nos é lícito receber, nem fazer; pois somos romanos."}, {"numero": 22, "texto": "E a multidão se levantou juntamente contra eles; e os oficiais, rasgando suas roupas, mandaram que fossem açoitados."}, {"numero": 23, "texto": "E tendo sido lhes dado muitos açoites, os lançaram na prisão, mandando ao carcereiro que os guardasse em segurança."}, {"numero": 24, "texto": "O qual, tendo recebido tal ordem, lançou-os na cela mais interna, e prendeu-lhes os pés no tronco."}, {"numero": 25, "texto": "E perto da meia-noite, Paulo e Silas [estavam] orando, e cantando hinos a Deus; [e] os [outros] presos os escutavam."}, {"numero": 26, "texto": "E de repente houve um terremoto tão grande que os alicerces da prisão se moviam; e logo todas as portas se abriram, e todas as correntes [que prendiam] a todos se soltaram."}, {"numero": 27, "texto": "E o carcereiro, tendo acordado e visto abertas todas as portas da prisão; puxou a espada, [e] estava a ponto de se matar, pensando que os presos tinham fugido."}, {"numero": 28, "texto": "Mas Paulo clamou em alta voz, dizendo: Não te faças nenhum mal, porque todos nós estamos aqui."}, {"numero": 29, "texto": "E tendo pedido luzes, saltou para dentro, e termendo muito, ele se prostrou diante de Paulo e Silas."}, {"numero": 30, "texto": "E levando-os para fora, disse: Senhores, o que me é necessário fazer para eu me salvar?"}, {"numero": 31, "texto": "E eles [lhe] disseram: Crê no Senhor Jesus Cristo, e serás salvo, tu e a tua casa."}, {"numero": 32, "texto": "E lhe falaram da palavra do Senhor, e a todos os que estavam em sua casa."}, {"numero": 33, "texto": "E ele, tomando-os consigo, naquela mesma hora da noite, lavou [-lhes] as feridas dos açoites, e logo foi batizado, ele e todos os seus."}, {"numero": 34, "texto": "E tendo os levado a sua casa, pôs [comida] diante deles à mesa; e alegrou-se muito, tendo crido em Deus com toda a sua casa."}, {"numero": 35, "texto": "E sendo [já] de dia, os magistrados mandaram aos guardas, dizendo: Solta aqueles homens."}, {"numero": 36, "texto": "E o carcereiro anunciou estas palavras a Paulo, [dizendo] : Os magistrados têm mandado vos soltar; portanto agora saí, e ide em paz."}, {"numero": 37, "texto": "Mas Paulo lhes disse: Eles nos açoitaram publicamente, e sem sermos sentenciados, sendo nós homens romanos, lançaram-nos na prisão, e agora nos lançam fora às escondidas? [Assim] não! Mas que eles mesmos venham e nos tirem."}, {"numero": 38, "texto": "E os guardas voltaram para dizer aos magistrados estas palavras; e eles temeram ao ouvirem que eram romanos."}, {"numero": 39, "texto": "E tendo vindo, rogaram-lhes; e tirando-os, pediram [-lhes] que saíssem da cidade."}, {"numero": 40, "texto": "E eles, tendo saído da prisão, entraram [na casa] de Lídia; e vendo aos irmãos, consolaram-lhes; e saíram."}]'::jsonb, 'Almeida Livre'),
  ('At', 16, 'en', '[{"numero": 1, "texto": "Then came he to Derbe and Lystra: and, behold, a certain disciple was there, named Timotheus, the son of a certain woman, which was a Jewess, and believed; but his father was a Greek:"}, {"numero": 2, "texto": "Which was well reported of by the brethren that were at Lystra and Iconium."}, {"numero": 3, "texto": "Him would Paul have to go forth with him; and took and circumcised him because of the Jews which were in those quarters: for they knew all that his father was a Greek."}, {"numero": 4, "texto": "And as they went through the cities, they delivered them the decrees for to keep, that were ordained of the apostles and elders which were at Jerusalem."}, {"numero": 5, "texto": "And so were the churches established in the faith, and increased in number daily."}, {"numero": 6, "texto": "Now when they had gone throughout Phrygia and the region of Galatia, and were forbidden of the Holy Ghost to preach the word in Asia,"}, {"numero": 7, "texto": "After they were come to Mysia, they assayed to go into Bithynia: but the Spirit suffered them not."}, {"numero": 8, "texto": "And they passing by Mysia came down to Troas."}, {"numero": 9, "texto": "And a vision appeared to Paul in the night; There stood a man of Macedonia, and prayed him, saying, Come over into Macedonia, and help us."}, {"numero": 10, "texto": "And after he had seen the vision, immediately we endeavoured to go into Macedonia, assuredly gathering that the Lord had called us for to preach the gospel unto them."}, {"numero": 11, "texto": "Therefore loosing from Troas, we came with a straight course to Samothracia, and the next day to Neapolis;"}, {"numero": 12, "texto": "And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days."}, {"numero": 13, "texto": "And on the sabbath we went out of the city by a river side, where prayer was wont to be made; and we sat down, and spake unto the women which resorted thither."}, {"numero": 14, "texto": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}, {"numero": 15, "texto": "And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us."}, {"numero": 16, "texto": "And it came to pass, as we went to prayer, a certain damsel possessed with a spirit of divination met us, which brought her masters much gain by soothsaying:"}, {"numero": 17, "texto": "The same followed Paul and us, and cried, saying, These men are the servants of the most high God, which shew unto us the way of salvation."}, {"numero": 18, "texto": "And this did she many days. But Paul, being grieved, turned and said to the spirit, I command thee in the name of Jesus Christ to come out of her. And he came out the same hour."}, {"numero": 19, "texto": "And when her masters saw that the hope of their gains was gone, they caught Paul and Silas, and drew them into the marketplace unto the rulers,"}, {"numero": 20, "texto": "And brought them to the magistrates, saying, These men, being Jews, do exceedingly trouble our city,"}, {"numero": 21, "texto": "And teach customs, which are not lawful for us to receive, neither to observe, being Romans."}, {"numero": 22, "texto": "And the multitude rose up together against them: and the magistrates rent off their clothes, and commanded to beat them."}, {"numero": 23, "texto": "And when they had laid many stripes upon them, they cast them into prison, charging the jailor to keep them safely:"}, {"numero": 24, "texto": "Who, having received such a charge, thrust them into the inner prison, and made their feet fast in the stocks."}, {"numero": 25, "texto": "And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}, {"numero": 26, "texto": "And suddenly there was a great earthquake, so that the foundations of the prison were shaken: and immediately all the doors were opened, and every one''s bands were loosed."}, {"numero": 27, "texto": "And the keeper of the prison awaking out of his sleep, and seeing the prison doors open, he drew out his sword, and would have killed himself, supposing that the prisoners had been fled."}, {"numero": 28, "texto": "But Paul cried with a loud voice, saying, Do thyself no harm: for we are all here."}, {"numero": 29, "texto": "Then he called for a light, and sprang in, and came trembling, and fell down before Paul and Silas,"}, {"numero": 30, "texto": "And brought them out, and said, Sirs, what must I do to be saved?"}, {"numero": 31, "texto": "And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house."}, {"numero": 32, "texto": "And they spake unto him the word of the Lord, and to all that were in his house."}, {"numero": 33, "texto": "And he took them the same hour of the night, and washed their stripes; and was baptized, he and all his, straightway."}, {"numero": 34, "texto": "And when he had brought them into his house, he set meat before them, and rejoiced, believing in God with all his house."}, {"numero": 35, "texto": "And when it was day, the magistrates sent the serjeants, saying, Let those men go."}, {"numero": 36, "texto": "And the keeper of the prison told this saying to Paul, The magistrates have sent to let you go: now therefore depart, and go in peace."}, {"numero": 37, "texto": "But Paul said unto them, They have beaten us openly uncondemned, being Romans, and have cast us into prison; and now do they thrust us out privily? nay verily; but let them come themselves and fetch us out."}, {"numero": 38, "texto": "And the serjeants told these words unto the magistrates: and they feared, when they heard that they were Romans."}, {"numero": 39, "texto": "And they came and besought them, and brought them out, and desired them to depart out of the city."}, {"numero": 40, "texto": "And they went out of the prison, and entered into the house of Lydia: and when they had seen the brethren, they comforted them, and departed."}]'::jsonb, 'King James Version'),
  ('At', 16, 'fr', '[{"numero": 1, "texto": "Il se rendit ensuite à Derbe et à Lystre. Et voici, il y avait là un disciple nommé Timothée, fils d''''une femme juive fidèle et d''''un père grec."}, {"numero": 2, "texto": "Les frères de Lystre et d''''Icone rendaient de lui un bon témoignage."}, {"numero": 3, "texto": "Paul voulut l''''emmener avec lui; et, l''''ayant pris, il le circoncit, à cause des Juifs qui étaient dans ces lieux-là, car tous savaient que son père était grec."}, {"numero": 4, "texto": "En passant par les villes, ils recommandaient aux frères d''''observer les décisions des apôtres et des anciens de Jérusalem."}, {"numero": 5, "texto": "Les Eglises se fortifiaient dans la foi, et augmentaient en nombre de jour en jour."}, {"numero": 6, "texto": "Ayant été empêchés par le Saint-Esprit d''''annoncer la parole dans l''''Asie, ils traversèrent la Phrygie et le pays de Galatie."}, {"numero": 7, "texto": "Arrivés près de la Mysie, ils se disposaient à entrer en Bithynie; mais l''''Esprit de Jésus ne le leur permit pas."}, {"numero": 8, "texto": "Ils franchirent alors la Mysie, et descendirent à Troas."}, {"numero": 9, "texto": "Pendant la nuit, Paul eut une vision: un Macédonien lui apparut, et lui fit cette prière: Passe en Macédoine, secours-nous!"}, {"numero": 10, "texto": "Après cette vision de Paul, nous cherchâmes aussitôt à nous rendre en Macédoine, concluant que le Seigneur nous appelait à y annoncer la bonne nouvelle."}, {"numero": 11, "texto": "Etant partis de Troas, nous fîmes voile directement vers la Samothrace, et le lendemain nous débarquâmes à Néapolis."}, {"numero": 12, "texto": "De là nous allâmes à Philippes, qui est la première ville d''''un district de Macédoine, et une colonie. Nous passâmes quelques jours dans cette ville."}, {"numero": 13, "texto": "Le jour du sabbat, nous nous rendîmes, hors de la porte, vers une rivière, où nous pensions que se trouvait un lieu de prière. Nous nous assîmes, et nous parlâmes aux femmes qui étaient réunies."}, {"numero": 14, "texto": "L''''une d''''elles, nommée Lydie, marchande de pourpre, de la ville de Thyatire, était une femme craignant Dieu, et elle écoutait. Le Seigneur lui ouvrit le coeur, pour qu''''elle fût attentive à ce que disait Paul."}, {"numero": 15, "texto": "Lorsqu''''elle eut été baptisée, avec sa famille, elle nous fit cette demande: Si vous me jugez fidèle au Seigneur, entrez dans ma maison, et demeurez-y. Et elle nous pressa par ses instances."}, {"numero": 16, "texto": "Comme nous allions au lieu de prière, une servante qui avait un esprit de Python, et qui, en devinant, procurait un grand profit à ses maîtres, vint au-devant de nous,"}, {"numero": 17, "texto": "et se mit à nous suivre, Paul et nous. Elle criait: Ces hommes sont les serviteurs du Dieu Très-Haut, et ils vous annoncent la voie du salut."}, {"numero": 18, "texto": "Elle fit cela pendant plusieurs jours. Paul fatigué se retourna, et dit à l''''esprit: Je t''''ordonne, au nom de Jésus-Christ, de sortir d''''elle. Et il sortit à l''''heure même."}, {"numero": 19, "texto": "Les maîtres de la servante, voyant disparaître l''''espoir de leur gain, se saisirent de Paul et de Silas, et les traînèrent sur la place publique devant les magistrats."}, {"numero": 20, "texto": "Ils les présentèrent aux préteurs, en disant: Ces hommes troublent notre ville; ce sont des Juifs,"}, {"numero": 21, "texto": "qui annoncent des coutumes qu''''il ne nous est permis ni de recevoir ni de suivre, à nous qui sommes Romains."}, {"numero": 22, "texto": "La foule se souleva aussi contre eux, et les préteurs, ayant fait arracher leurs vêtements, ordonnèrent qu''''on les battît de verges."}, {"numero": 23, "texto": "Après qu''''on les eut chargés de coups, ils les jetèrent en prison, en recommandant au geôlier de les garder sûrement."}, {"numero": 24, "texto": "Le geôlier, ayant reçu cet ordre, les jeta dans la prison intérieure, et leur mit les ceps aux pieds."}, {"numero": 25, "texto": "Vers le milieu de la nuit, Paul et Silas priaient et chantaient les louanges de Dieu, et les prisonniers les entendaient."}, {"numero": 26, "texto": "Tout à coup il se fit un grand tremblement de terre, en sorte que les fondements de la prison furent ébranlés; au même instant, toutes les portes s''''ouvrirent, et les liens de tous les prisonniers furent rompus."}, {"numero": 27, "texto": "Le geôlier se réveilla, et, lorsqu''''il vit les portes de la prison ouvertes, il tira son épée et allait se tuer, pensant que les prisonniers s''''étaient enfuis."}, {"numero": 28, "texto": "Mais Paul cria d''''une voix forte: Ne te fais point de mal, nous sommes tous ici."}, {"numero": 29, "texto": "Alors le geôlier, ayant demandé de la lumière, entra précipitamment, et se jeta tout tremblant aux pieds de Paul et de Silas;"}, {"numero": 30, "texto": "il les fit sortir, et dit: Seigneurs, que faut-il que je fasse pour être sauvé?"}, {"numero": 31, "texto": "Paul et Silas répondirent: Crois au Seigneur Jésus, et tu seras sauvé, toi et ta famille."}, {"numero": 32, "texto": "Et ils lui annoncèrent la parole du Seigneur, ainsi qu''''à tous ceux qui étaient dans sa maison."}, {"numero": 33, "texto": "Il les prit avec lui, à cette heure même de la nuit, il lava leurs plaies, et aussitôt il fut baptisé, lui et tous les siens."}, {"numero": 34, "texto": "Les ayant conduits dans son logement, il leur servit à manger, et il se réjouit avec toute sa famille de ce qu''''il avait cru en Dieu."}, {"numero": 35, "texto": "Quand il fit jour, les préteurs envoyèrent les licteurs pour dire au geôlier: Relâche ces hommes."}, {"numero": 36, "texto": "Et le geôlier annonça la chose à Paul: Les préteurs ont envoyé dire qu''''on vous relâchât; maintenant donc sortez, et allez en paix."}, {"numero": 37, "texto": "Mais Paul dit aux licteurs: Après nous avoir battus de verges publiquement et sans jugement, nous qui sommes Romains, ils nous ont jetés en prison, et maintenant ils nous font sortir secrètement! Il n''''en sera pas ainsi. Qu''''ils viennent eux-mêmes nous mettre en liberté."}, {"numero": 38, "texto": "Les licteurs rapportèrent ces paroles aux préteurs, qui furent effrayés en apprenant qu''''ils étaient Romains."}, {"numero": 39, "texto": "Ils vinrent les apaiser, et ils les mirent en liberté, en les priant de quitter la ville."}, {"numero": 40, "texto": "Quand ils furent sortis de la prison, ils entrèrent chez Lydie, et, après avoir vu et exhorté les frères, ils partirent."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 16, 'es', '[{"numero": 1, "texto": "DESPUÉS llegó á Derbe, y á Listra: y he aquí, estaba allí un discípulo llamado Timoteo, hijo de una mujer Judía fiel, mas de padre Griego."}, {"numero": 2, "texto": "De éste daban buen testimonio los hermanos que estaban en Listra y en Iconio."}, {"numero": 3, "texto": "Este quiso Pablo que fuese con él; y tomándole, le circuncidó por causa de los Judíos que estaban en aquellos lugares; porque todos sabían que su padre era Griego."}, {"numero": 4, "texto": "Y como pasaban por las ciudades, les daban que guardasen los decretos que habían sido determinados por los apóstoles y los ancianos que estaban en Jerusalem."}, {"numero": 5, "texto": "Así que, las iglesias eran confirmadas en fe, y eran aumentadas en número cada día."}, {"numero": 6, "texto": "Y pasando á Phrygia y la provincia de Galacia, les fué prohibido por el Espíritu Santo hablar la palabra en Asia."}, {"numero": 7, "texto": "Y como vinieron á Misia, tentaron de ir á Bithynia; mas el Espíritu no les dejó."}, {"numero": 8, "texto": "Y pasando á Misia, descendieron á Troas."}, {"numero": 9, "texto": "Y fué mostrada á Pablo de noche una visión: Un varón Macedonio se puso delante, rogándole, y diciendo: Pasa á Macedonia, y ayúdanos."}, {"numero": 10, "texto": "Y como vió la visión, luego procuramos partir á Macedonia, dando por cierto que Dios nos llamaba para que les anunciásemos el evangelio."}, {"numero": 11, "texto": "Partidos pues de Troas, vinimos camino derecho á Samotracia, y el día siguiente á Neápolis;"}, {"numero": 12, "texto": "Y de allí á Filipos, que es la primera ciudad de la parte de Macedonia, y una colonia; y estuvimos en aquella ciudad algunos días."}, {"numero": 13, "texto": "Y un día de sábado salimos de la puerta junto al río, donde solía ser la oración; y sentándonos, hablamos á las mujeres que se habían juntado."}, {"numero": 14, "texto": "Entonces una mujer llamada Lidia, que vendía púrpura en la ciudad de Tiatira, temerosa de Dios, estaba oyendo; el corazón de la cual abrió el Señor para que estuviese atenta á lo que Pablo decía."}, {"numero": 15, "texto": "Y cuando fué bautizada, y su familia, nos rogó, diciendo: Si habéis juzgado que yo sea fiel al Señor, entrad en mi casa, y posad: y constriñónos."}, {"numero": 16, "texto": "Y aconteció, que yendo nosotros á la oración, una muchacha que tenía espíritu pitónico, nos salió al encuentro, la cual daba grande ganancia á sus amos adivinando."}, {"numero": 17, "texto": "Esta, siguiendo á Pablo y á nosotros, daba voces, diciendo: Estos hombres son siervos del Dios Alto, los cuales os anuncian el camino de salud."}, {"numero": 18, "texto": "Y esto hacía por muchos días; mas desagradando á Pablo, se volvió y dijo al espíritu: Te mando en el nombre de Jesucristo, que salgas de ella. Y salió en la misma hora."}, {"numero": 19, "texto": "Y viendo sus amos que había salido la esperanza de su ganancia, prendieron á Pablo y á Silas, y los trajeron al foro, al magistrado;"}, {"numero": 20, "texto": "Y presentándolos á los magistrados, dijeron: Estos hombres, siendo Judíos, alborotan nuestra ciudad,"}, {"numero": 21, "texto": "Y predican ritos, los cuales no nos es lícito recibir ni hacer, pues somos Romanos."}, {"numero": 22, "texto": "Y agolpóse el pueblo contra ellos: y los magistrados rompiéndoles sus ropas, les mandaron azotar con varas."}, {"numero": 23, "texto": "Y después que los hubieron herido de muchos azotes, los echaron en la cárcel, mandando al carcelero que los guardase con diligencia:"}, {"numero": 24, "texto": "El cual, recibido este mandamiento, los metió en la cárcel de más adentro; y les apretó los pies en el cepo."}, {"numero": 25, "texto": "Mas á media noche, orando Pablo y Silas, cantaban himnos á Dios: y los que estaban presos los oían."}, {"numero": 26, "texto": "Entonces fué hecho de repente un gran terremoto, de tal manera que los cimientos de la cárcel se movían; y luego todas las puertas se abrieron, y las prisiones de todos se soltaron."}, {"numero": 27, "texto": "Y despertado el carcelero, como vió abiertas las puertas de la cárcel, sacando la espada se quería matar, pensando que los presos se habían huído."}, {"numero": 28, "texto": "Mas Pablo clamó á gran voz, diciendo: No te hagas ningún mal; que todos estamos aquí."}, {"numero": 29, "texto": "El entonces pidiendo luz, entró dentro, y temblando, derribóse á los pies de Pablo y de Silas;"}, {"numero": 30, "texto": "Y sacándolos fuera, les dice: Señores, ¿qué es menester que yo haga para ser salvo?"}, {"numero": 31, "texto": "Y ellos dijeron: Cree en el Señor Jesucristo, y serás salvo tú, y tu casa."}, {"numero": 32, "texto": "Y le hablaron la palabra del Señor, y á todos los que estaban en su casa."}, {"numero": 33, "texto": "Y tomándolos en aquella misma hora de la noche, les lavó los azotes; y se bautizó luego él, y todos los suyos."}, {"numero": 34, "texto": "Y llevándolos á su casa, les puso la mesa: y se gozó de que con toda su casa había creído á Dios."}, {"numero": 35, "texto": "Y como fué de día, los magistrados enviaron los alguaciles, diciendo: Deja ir á aquellos hombres."}, {"numero": 36, "texto": "Y el carcelero hizo saber estas palabras á Pablo: Los magistrados han enviado á decir que seáis sueltos: así que ahora salid, é id en paz."}, {"numero": 37, "texto": "Entonces Pablo les dijo: Azotados públicamente sin ser condenados, siendo hombres Romanos, nos echaron en la cárcel; y ¿ahora nos echan encubiertamente? No, de cierto, sino vengan ellos y sáquennos."}, {"numero": 38, "texto": "Y los alguaciles volvieron á decir á los magistrados estas palabras: y tuvieron miedo, oído que eran Romanos."}, {"numero": 39, "texto": "Y viniendo, les rogaron; y sacándolos, les pidieron que se saliesen de la ciudad."}, {"numero": 40, "texto": "Entonces salidos de la cárcel, entraron en casa de Lidia; y habiendo visto á los hermanos, los consolaron, y se salieron."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 17, 'pt', '[{"numero": 1, "texto": "E viajando por Anfípolis e Apolônia, vieram a Tessalônica, onde havia uma sinagoga de judeus."}, {"numero": 2, "texto": "E Paulo, como era de [seu] costume, entrou a eles, e por três sábados argumentava com eles pelas Escrituras."}, {"numero": 3, "texto": "Declarando [-as] ,e propondo [-lhes] ,que era necessário que o Cristo morresse, e ressuscitasse dos mortos; e que ( [dizia ele] ) este Jesus é o Cristo, a quem eu vos anuncio."}, {"numero": 4, "texto": "E alguns deles creram, e se ajuntaram a Paulo e Silas; e dos gregos devotos grande multidão; e não poucas das mulheres principais."}, {"numero": 5, "texto": "Mas os judeus incrédulos, movidos de inveja, tomaram consigo alguns homens malignos dos mercados, e juntando uma multidão, tumultuaram a cidade; e atacando a casa de Jasão, procuravam trazê-los ao povo."}, {"numero": 6, "texto": "E não os achando, puxaram a Jasão, e a alguns irmãos às maiores autoridades da cidade, clamando: Estes que tem perturbado ao mundo também vieram até aqui."}, {"numero": 7, "texto": "Aos quais Jasão tem recolhido, e todos estes fazem contra as ordens de César, dizendo que há outro rei, [chamado] Jesus."}, {"numero": 8, "texto": "E eles tumultuaram a multidão, e às autoridades da cidade, que ouviam estas coisas."}, {"numero": 9, "texto": "Mas tendo recebido fiança de Jasão e dos demais, eles os soltaram."}, {"numero": 10, "texto": "E logo os irmãos enviaram de noite a Paulo e a Silas até Bereia; os quais, ao chegarem lá, foram à sinagoga dos judeus."}, {"numero": 11, "texto": "E estes foram mais nobres do que os que estavam em Tessalônica, [porque] os quais receberam a palavra com toda boa vontade, examinando a cada dia as escrituras, [para ver] se estas coisas eram assim."}, {"numero": 12, "texto": "Portanto muitos deles realmente creram, e das mulheres gregas honradas; e dos homens, não poucos."}, {"numero": 13, "texto": "Mas quando os judeus de Tessalônica souberam que também em Bereia a palavra de Deus era anunciada por Paulo, vieram também para lá, e incitaram as multidões."}, {"numero": 14, "texto": "Mas então no mesmo instante os irmãos despediram a Paulo, para que fosse ao mar; mas Silas e Timóteo continuaram ali."}, {"numero": 15, "texto": "E os que conduziram a Paulo, levaram-no até Atenas; e tendo recebido ordem para Silas e Timóteo, para que viessem a ele o mais rápido [que pudessem] ,eles foram embora."}, {"numero": 16, "texto": "E enquanto Paulo os esperava em Atenas, seu espírito se incomodava dentro dele, ao ver a cidade tão dedicada à idolatria."}, {"numero": 17, "texto": "Então ele disputava muito na sinagoga, com os judeus, e com os religiosos; e no mercado a cada dia, com os que vinham [até ele] ."}, {"numero": 18, "texto": "E alguns dos filósofos epicureus e estoicos discutiam com ele; e uns diziam: O que quer dizer este tagarela?E outros: Parece que ele é pregador de deuses estranhos.Porque ele lhes anunciava o Evangelho de Jesus e a ressurreição."}, {"numero": 19, "texto": "E tomando-o, trouxeram [-no] ao areópago, dizendo: Podemos nós saber que doutrina nova é esta que tu falas?"}, {"numero": 20, "texto": "Porque tu trazes coisas estranhas aos nossos ouvidos; então queremos saber o que isto quer dizer."}, {"numero": 21, "texto": "(E todos os atenienses e visitantes estrangeiros não se ocupavam de nenhuma outra coisa, a não ser em dizer e ouvir alguma novidade)."}, {"numero": 22, "texto": "E Paulo, estando no meio do areópago, disse: Homens atenienses, eu vejo em tudo como vós sois muito religiosos;"}, {"numero": 23, "texto": "Porque enquanto eu passava [pela cidade] e via vossos santuários, achei também um altar, em que estava escrito: AO DEUS DESCONHECIDO. Este a quem vós prestais devoção sem conhecer, [este é o que] eu vos anuncio;"}, {"numero": 24, "texto": "O Deus que fez o mundo, e todas as coisas que nele [há] ; este, sendo Senhor do céu e da terra, não habita em tempos feitos por mãos."}, {"numero": 25, "texto": "E nem também é servido por mãos humanas; [como que] necessitasse de alguma coisa; [porque] ele [é que] dá a todos vida, respiração, e todas as coisas;"}, {"numero": 26, "texto": "E de um sangue ele fez toda nação humana, para habitarem sobre a face da terra, determinando os tempos desde antes ordenados, e o limites da morada [deles] ;"}, {"numero": 27, "texto": "Para que buscassem ao Senhor, se talvez pudessem apalpá-lo e encontrá-lo,apesar dele não estar longe de cada um de nós."}, {"numero": 28, "texto": "Porque nele vivemos, e nos movemos, e somos; assim como também alguns de vossos poetas disseram; porque também nós somos descendência dele."}, {"numero": 29, "texto": "Sendo então descendência de Deus, nós não devemos pensar que a divindade seja semelhante a ouro, ou a prata, ou a pedra esculpida por artifício e imaginação humana."}, {"numero": 30, "texto": "Portanto Deus, tendo desconsiderado os tempos da [vossa] ignorância, agora anuncia a todos as pessoas, em todo lugar, para que se arrependam."}, {"numero": 31, "texto": "Porque ele tem estabelecido um dia em que ele julgará ao mundo em justiça por meio do homem a quem determinou; dando certeza a todos, tendo o ressuscitado dos mortos."}, {"numero": 32, "texto": "E ao ouvirem da ressurreição dos mortos, alguns zombavam; e outros diziam: Nós ouviremos sobre isto de ti na próxima vez."}, {"numero": 33, "texto": "E assim Paulo saiu do meio deles."}, {"numero": 34, "texto": "Porém, tendo chegado alguns homens até ele, creram; entre os quais estava também Dionísio o areopagita, e uma mulher de nome Dâmaris, e outros com eles."}]'::jsonb, 'Almeida Livre'),
  ('At', 17, 'en', '[{"numero": 1, "texto": "Now when they had passed through Amphipolis and Apollonia, they came to Thessalonica, where was a synagogue of the Jews:"}, {"numero": 2, "texto": "And Paul, as his manner was, went in unto them, and three sabbath days reasoned with them out of the scriptures,"}, {"numero": 3, "texto": "Opening and alleging, that Christ must needs have suffered, and risen again from the dead; and that this Jesus, whom I preach unto you, is Christ."}, {"numero": 4, "texto": "And some of them believed, and consorted with Paul and Silas; and of the devout Greeks a great multitude, and of the chief women not a few."}, {"numero": 5, "texto": "But the Jews which believed not, moved with envy, took unto them certain lewd fellows of the baser sort, and gathered a company, and set all the city on an uproar, and assaulted the house of Jason, and sought to bring them out to the people."}, {"numero": 6, "texto": "And when they found them not, they drew Jason and certain brethren unto the rulers of the city, crying, These that have turned the world upside down are come hither also;"}, {"numero": 7, "texto": "Whom Jason hath received: and these all do contrary to the decrees of Caesar, saying that there is another king, one Jesus."}, {"numero": 8, "texto": "And they troubled the people and the rulers of the city, when they heard these things."}, {"numero": 9, "texto": "And when they had taken security of Jason, and of the other, they let them go."}, {"numero": 10, "texto": "And the brethren immediately sent away Paul and Silas by night unto Berea: who coming thither went into the synagogue of the Jews."}, {"numero": 11, "texto": "These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so."}, {"numero": 12, "texto": "Therefore many of them believed; also of honourable women which were Greeks, and of men, not a few."}, {"numero": 13, "texto": "But when the Jews of Thessalonica had knowledge that the word of God was preached of Paul at Berea, they came thither also, and stirred up the people."}, {"numero": 14, "texto": "And then immediately the brethren sent away Paul to go as it were to the sea: but Silas and Timotheus abode there still."}, {"numero": 15, "texto": "And they that conducted Paul brought him unto Athens: and receiving a commandment unto Silas and Timotheus for to come to him with all speed, they departed."}, {"numero": 16, "texto": "Now while Paul waited for them at Athens, his spirit was stirred in him, when he saw the city wholly given to idolatry."}, {"numero": 17, "texto": "Therefore disputed he in the synagogue with the Jews, and with the devout persons, and in the market daily with them that met with him."}, {"numero": 18, "texto": "Then certain philosophers of the Epicureans, and of the Stoicks, encountered him. And some said, What will this babbler say? other some, He seemeth to be a setter forth of strange gods: because he preached unto them Jesus, and the resurrection."}, {"numero": 19, "texto": "And they took him, and brought him unto Areopagus, saying, May we know what this new doctrine, whereof thou speakest, is?"}, {"numero": 20, "texto": "For thou bringest certain strange things to our ears: we would know therefore what these things mean."}, {"numero": 21, "texto": "(For all the Athenians and strangers which were there spent their time in nothing else, but either to tell, or to hear some new thing.)"}, {"numero": 22, "texto": "Then Paul stood in the midst of Mars'' hill, and said, Ye men of Athens, I perceive that in all things ye are too superstitious."}, {"numero": 23, "texto": "For as I passed by, and beheld your devotions, I found an altar with this inscription, To The Unknown God. Whom therefore ye ignorantly worship, him declare I unto you."}, {"numero": 24, "texto": "God that made the world and all things therein, seeing that he is Lord of heaven and earth, dwelleth not in temples made with hands;"}, {"numero": 25, "texto": "Neither is worshipped with men''s hands, as though he needed any thing, seeing he giveth to all life, and breath, and all things;"}, {"numero": 26, "texto": "And hath made of one blood all nations of men for to dwell on all the face of the earth, and hath determined the times before appointed, and the bounds of their habitation;"}, {"numero": 27, "texto": "That they should seek the Lord, if haply they might feel after him, and find him, though he be not far from every one of us:"}, {"numero": 28, "texto": "For in him we live, and move, and have our being; as certain also of your own poets have said, For we are also his offspring."}, {"numero": 29, "texto": "Forasmuch then as we are the offspring of God, we ought not to think that the Godhead is like unto gold, or silver, or stone, graven by art and man''s device."}, {"numero": 30, "texto": "And the times of this ignorance God winked at; but now commandeth all men every where to repent:"}, {"numero": 31, "texto": "Because he hath appointed a day, in the which he will judge the world in righteousness by that man whom he hath ordained; whereof he hath given assurance unto all men, in that he hath raised him from the dead."}, {"numero": 32, "texto": "And when they heard of the resurrection of the dead, some mocked: and others said, We will hear thee again of this matter."}, {"numero": 33, "texto": "So Paul departed from among them."}, {"numero": 34, "texto": "Howbeit certain men clave unto him, and believed: among the which was Dionysius the Areopagite, and a woman named Damaris, and others with them."}]'::jsonb, 'King James Version'),
  ('At', 17, 'fr', '[{"numero": 1, "texto": "Paul et Silas passèrent par Amphipolis et Apollonie, et ils arrivèrent à Thessalonique, où les Juifs avaient une synagogue."}, {"numero": 2, "texto": "Paul y entra, selon sa coutume. Pendant trois sabbats, il discuta avec eux, d''''après les Ecritures,"}, {"numero": 3, "texto": "expliquant et établissant que le Christ devait souffrir et ressusciter des morts. Et Jésus que je vous annonce, disait-il, c''''est lui qui est le Christ."}, {"numero": 4, "texto": "Quelques-uns d''''entre eux furent persuadés, et se joignirent à Paul et à Silas, ainsi qu''''une grande multitude de Grecs craignant Dieu, et beaucoup de femmes de qualité."}, {"numero": 5, "texto": "Mais les Juifs, jaloux prirent avec eux quelques méchants hommes de la populace, provoquèrent des attroupements, et répandirent l''''agitation dans la ville. Ils se portèrent à la maison de Jason, et ils cherchèrent Paul et Silas, pour les amener vers le peuple."}, {"numero": 6, "texto": "Ne les ayant pas trouvés, ils traînèrent Jason et quelques frères devant les magistrats de la ville, en criant: Ces gens, qui ont bouleversé le monde, sont aussi venus ici,"}, {"numero": 7, "texto": "et Jason les a reçus. Ils agissent tous contre les édits de César, disant qu''''il y a un autre roi, Jésus."}, {"numero": 8, "texto": "Par ces paroles ils émurent la foule et les magistrats,"}, {"numero": 9, "texto": "qui ne laissèrent aller Jason et les autres qu''''après avoir obtenu d''''eux une caution."}, {"numero": 10, "texto": "Aussitôt les frères firent partir de nuit Paul et Silas pour Bérée. Lorsqu''''ils furent arrivés, ils entrèrent dans la synagogue des Juifs."}, {"numero": 11, "texto": "Ces Juifs avaient des sentiments plus nobles que ceux de Thessalonique; ils reçurent la parole avec beaucoup d''''empressement, et ils examinaient chaque jour les Ecritures, pour voir si ce qu''''on leur disait était exact."}, {"numero": 12, "texto": "Plusieurs d''''entre eux crurent, ainsi que beaucoup de femmes grecques de distinction, et beaucoup d''''hommes."}, {"numero": 13, "texto": "Mais, quand les Juifs de Thessalonique surent que Paul annonçait aussi à Bérée la parole de Dieu, ils vinrent y agiter la foule."}, {"numero": 14, "texto": "Alors les frères firent aussitôt partir Paul du côté de la mer; Silas et Timothée restèrent à Bérée."}, {"numero": 15, "texto": "Ceux qui accompagnaient Paul le conduisirent jusqu''''à Athènes. Puis ils s''''en retournèrent, chargés de transmettre à Silas et à Timothée l''''ordre de le rejoindre au plus tôt."}, {"numero": 16, "texto": "Comme Paul les attendait à Athènes, il sentait au dedans de lui son esprit s''''irriter, à la vue de cette ville pleine d''''idoles."}, {"numero": 17, "texto": "Il s''''entretenait donc dans la synagogue avec les Juifs et les hommes craignant Dieu, et sur la place publique chaque jour avec ceux qu''''il rencontrait."}, {"numero": 18, "texto": "Quelques philosophes épicuriens et stoïciens se mirent à parler avec lui. Et les uns disaient: Que veut dire ce discoureur? D''''autres, l''''entendant annoncer Jésus et la résurrection, disaient: Il semble qu''''il annonce des divinités étrangères."}, {"numero": 19, "texto": "Alors ils le prirent, et le menèrent à l''''Aréopage, en disant: Pourrions-nous savoir quelle est cette nouvelle doctrine que tu enseignes?"}, {"numero": 20, "texto": "Car tu nous fais entendre des choses étranges. Nous voudrions donc savoir ce que cela peut être."}, {"numero": 21, "texto": "Or, tous les Athéniens et les étrangers demeurant à Athènes ne passaient leur temps qu''''à dire ou à écouter des nouvelles."}, {"numero": 22, "texto": "Paul, debout au milieu de l''''Aréopage, dit: Hommes Athéniens, je vous trouve à tous égards extrêmement religieux."}, {"numero": 23, "texto": "Car, en parcourant votre ville et en considérant les objets de votre dévotion, j''''ai même découvert un autel avec cette inscription: A un dieu inconnu! Ce que vous révérez sans le connaître, c''''est ce que je vous annonce."}, {"numero": 24, "texto": "Le Dieu qui a fait le monde et tout ce qui s''''y trouve, étant le Seigneur du ciel et de la terre, n''''habite point dans des temples faits de main d''''homme;"}, {"numero": 25, "texto": "il n''''est point servi par des mains humaines, comme s''''il avait besoin de quoi que ce soit, lui qui donne à tous la vie, la respiration, et toutes choses."}, {"numero": 26, "texto": "Il a fait que tous les hommes, sortis d''''un seul sang, habitassent sur toute la surface de la terre, ayant déterminé la durée des temps et les bornes de leur demeure;"}, {"numero": 27, "texto": "il a voulu qu''''ils cherchassent le Seigneur, et qu''''ils s''''efforçassent de le trouver en tâtonnant, bien qu''''il ne soit pas loin de chacun de nous,"}, {"numero": 28, "texto": "car en lui nous avons la vie, le mouvement, et l''''être. C''''est ce qu''''ont dit aussi quelques-uns de vos poètes: De lui nous sommes la race..."}, {"numero": 29, "texto": "Ainsi donc, étant la race de Dieu, nous ne devons pas croire que la divinité soit semblable à de l''''or, à de l''''argent, ou à de la pierre, sculptés par l''''art et l''''industrie de l''''homme."}, {"numero": 30, "texto": "Dieu, sans tenir compte des temps d''''ignorance, annonce maintenant à tous les hommes, en tous lieux, qu''''ils aient à se repentir,"}, {"numero": 31, "texto": "parce qu''''il a fixé un jour où il jugera le monde selon la justice, par l''''homme qu''''il a désigné, ce dont il a donné à tous une preuve certaine en le ressuscitant des morts..."}, {"numero": 32, "texto": "Lorsqu''''ils entendirent parler de résurrection des morts, les uns se moquèrent, et les autres dirent: Nous t''''entendrons là-dessus une autre fois."}, {"numero": 33, "texto": "Ainsi Paul se retira du milieu d''''eux."}, {"numero": 34, "texto": "Quelques-uns néanmoins s''''attachèrent à lui et crurent, Denys l''''aréopagite, une femme nommée Damaris, et d''''autres avec eux."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 17, 'es', '[{"numero": 1, "texto": "Y PASANDO por Amphípolis y Apolonia, llegaron á Tesalónica, donde estaba la sinagoga de los Judíos."}, {"numero": 2, "texto": "Y Pablo, como acostumbraba, entró á ellos, y por tres sábados disputó con ellos de las Escrituras,"}, {"numero": 3, "texto": "Declarando y proponiendo, que convenía que el Cristo padeciese, y resucitase de los muertos; y que Jesús, el cual yo os anuncio, decía él, éste era el Cristo."}, {"numero": 4, "texto": "Y algunos de ellos creyeron, y se juntaron con Pablo y con Silas; y de los Griegos religiosos grande multitud, y mujeres nobles no pocas."}, {"numero": 5, "texto": "Entonces los Judíos que eran incrédulos, teniendo celos, tomaron consigo á algunos ociosos, malos hombres, y juntando compañía, alborotaron la ciudad; y acometiendo á la casa de Jasón, procuraban sacarlos al pueblo."}, {"numero": 6, "texto": "Mas no hallándolos, trajeron á Jasón y á algunos hermanos á los gobernadores de la ciudad, dando voces: Estos que alborotan el mundo, también han venido acá;"}, {"numero": 7, "texto": "A los cuales Jasón ha recibido; y todos estos hacen contra los decretos de César, diciendo que hay otro rey, Jesús."}, {"numero": 8, "texto": "Y alborotaron al pueblo y á los gobernadores de la ciudad, oyendo estas cosas."}, {"numero": 9, "texto": "Mas recibida satisfacción de Jasón y de los demás, los soltaron."}, {"numero": 10, "texto": "Entonces los hermanos, luego de noche, enviaron á Pablo y á Silas á Berea; los cuales habiendo llegado, entraron en la sinagoga de los Judíos."}, {"numero": 11, "texto": "Y fueron éstos más nobles que los que estaban en Tesalónica, pues recibieron la palabra con toda solicitud, escudriñando cada día las Escrituras, si estas cosas eran así."}, {"numero": 12, "texto": "Así que creyeron muchos de ellos; y mujeres Griegas de distinción, y no pocos hombres."}, {"numero": 13, "texto": "Mas como entendieron los Judíos de Tesalónica que también en Berea era anunciada la palabra de Dios por Pablo, fueron, y también allí tumultuaron al pueblo."}, {"numero": 14, "texto": "Empero luego los hermanos enviaron á Pablo que fuese como á la mar; y Silas y Timoteo se quedaron allí."}, {"numero": 15, "texto": "Y los que habían tomado á cargo á Pablo, le llevaron hasta Atenas; y tomando encargo para Silas y Timoteo, que viniesen á él lo más presto que pudiesen, partieron."}, {"numero": 16, "texto": "Y esperándolos Pablo en Atenas, su espíritu se deshacía en él viendo la ciudad dada á idolatría."}, {"numero": 17, "texto": "Así que, disputaba en la sinagoga con los Judíos y religiosos; y en la plaza cada día con los que le ocurrían."}, {"numero": 18, "texto": "Y algunos filósofos de los Epicúreos y de los Estóicos, disputaban con él; y unos decían: ¿Qué quiere decir este palabrero? Y otros: Parece que es predicador de nuevos dioses: porque les predicaba á Jesús y la resurrección."}, {"numero": 19, "texto": "Y tomándole, le trajeron al Areópago, diciendo: ¿Podremos saber qué sea esta nueva doctrina que dices?"}, {"numero": 20, "texto": "Porque pones en nuestros oídos unas nuevas cosas: queremos pues saber qué quiere ser esto."}, {"numero": 21, "texto": "(Entonces todos los Atenienses y los huéspedes extranjeros, en ninguna otra cosa entendían, sino ó en decir ó en oir alguna cosa nueva.)"}, {"numero": 22, "texto": "Estando pues Pablo en medio del Areópago, dijo: Varones Atenienses, en todo os veo como más supersticiosos;"}, {"numero": 23, "texto": "Porque pasando y mirando vuestros santuarios, hallé también un altar en el cual estaba esta inscripción: AL DIOS NO CONOCIDO. Aquél pues, que vosotros honráis sin conocerle, á éste os anuncio yo."}, {"numero": 24, "texto": "El Dios que hizo el mundo y todas las cosas que en él hay, éste, como sea Señor del cielo y de la tierra, no habita en templos hechos de manos,"}, {"numero": 25, "texto": "Ni es honrado con manos de hombres, necesitado de algo; pues él da á todos vida, y respiración, y todas las cosas;"}, {"numero": 26, "texto": "Y de una sangre ha hecho todo el linaje de los hombres, para que habitasen sobre toda la faz de la tierra; y les ha prefijado el orden de los tiempos, y los términos de la habitación de ellos;"}, {"numero": 27, "texto": "Para que buscasen á Dios, si en alguna manera, palpando, le hallen; aunque cierto no está lejos de cada uno de nosotros:"}, {"numero": 28, "texto": "Porque en él vivimos, y nos movemos, y somos; como también algunos de vuestros poetas dijeron: Porque linaje de éste somos también."}, {"numero": 29, "texto": "Siendo pues linaje de Dios, no hemos de estimar la Divinidad ser semejante á oro, ó á plata, ó á piedra, escultura de artificio ó de imaginación de hombres."}, {"numero": 30, "texto": "Empero Dios, habiendo disimulado los tiempos de esta ignorancia, ahora denuncia á todos los hombres en todos los lugares que se arrepientan:"}, {"numero": 31, "texto": "Por cuanto ha establecido un día, en el cual ha de juzgar al mundo con justicia, por aquel varón al cual determinó; dando fe á todos con haberle levantado de los muertos."}, {"numero": 32, "texto": "Y así como oyeron de la resurrección de los muertos, unos se burlaban, y otros decían: Te oiremos acerca de esto otra vez."}, {"numero": 33, "texto": "Y así Pablo se salió de en medio de ellos."}, {"numero": 34, "texto": "Mas algunos creyeron, juntándose con él; entre los cuales también fué Dionisio el del Areópago, y una mujer llamada Dámaris, y otros con ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 18, 'pt', '[{"numero": 1, "texto": "E depois disto ele partiu de Atenas, e veio a Corinto."}, {"numero": 2, "texto": "E achando a um certo judeu, de nome Áquila, natural de Ponto, que recentemente tinha vindo da Itália, e Priscila, sua mulher (porque Cláudio tinha mandado que todos os judeus saíssem de Roma), veio até eles."}, {"numero": 3, "texto": "E porque era do mesmo ofício, ficou com eles, e trabalhava; porque tinham o ofício de fazerem tendas."}, {"numero": 4, "texto": "E ele disputava na sinagoga a cada sábado; e persuadia a judeus e a gregos."}, {"numero": 5, "texto": "E quando Silas e Timóteo desceram da Macedônia, Paulo foi pressionado pelo Espírito, dando testemunho aos judeus [de que] o Cristo [era] Jesus."}, {"numero": 6, "texto": "Mas tendo eles resistido e blasfemado, ele sacudiu as roupas, e lhes disse: Vosso sangue [seja] sobre vossa cabeça; eu estou limpo; e a partir de agora irei aos gentios."}, {"numero": 7, "texto": "E tendo saído dali, entrou na cada de um, de nome Justo, que servia a Deus, cuja casa era vizinha à sinagoga."}, {"numero": 8, "texto": "E Crispo, o chefe da sinagoga, creu no Senhor com toda a sua casa; e muitos dos coríntios, tendo ouvido, creram e foram batizados."}, {"numero": 9, "texto": "E o Senhor disse em visão de noite a Paulo: Não temas, mas fala, e não te cales."}, {"numero": 10, "texto": "Porque eu estou contigo, e ninguém porá [mão] em ti para te fazer mal, porque eu tenho muito povo nesta cidade."}, {"numero": 11, "texto": "E ele ficou [ali por] um ano e seis meses, ensinando entre eles a palavra de Deus."}, {"numero": 12, "texto": "Mas sendo Gálio o procônsul da Acaia, os judeus se levantaram em concordância contra Paulo, e o trouxeram ao tribunal,"}, {"numero": 13, "texto": "Dizendo: Este persuade as pessoas a servirem a Deus contra a Lei."}, {"numero": 14, "texto": "E Paulo, querendo abrir a boca, Gálio disse aos judeus: Se houvesse algum mau ato ou crime grande, ó judeus, com razão eu vos suportaria;"}, {"numero": 15, "texto": "Mas se a questão é de palavra [s] , e de nomes, e da Lei que há entre vós, vede [-o] vós mesmos; porque destas coisas eu não quero ser juiz."}, {"numero": 16, "texto": "E ele os tirou do tribunal."}, {"numero": 17, "texto": "Mas todos os gregos, tomando a Sóstenes, o chefe da sinagoga, feriram [-no] diante do tribunal; e a nada destas coisas Gálio dava importância."}, {"numero": 18, "texto": "E Paulo, ficando ali ainda muitos dias, ele se despediu dos irmãos, e dali navegou para a Síria, e juntos com ele [estavam] Priscila e Áquila; tendo rapado a cabeça em Cencreia, porque ele tinha [feito] voto."}, {"numero": 19, "texto": "E chegou a Éfeso, e os deixou ali; mas ele, entrando na sinagoga, disputava com os judeus."}, {"numero": 20, "texto": "E eles, pedindo[-lhe] que continuasse com eles por mais [algum] tempo, ele não concordou."}, {"numero": 21, "texto": "Porém despediu-se deles, dizendo: De toda maneira tenho que estar na festa que vem em Jerusalém; mas outra vez, se Deus quiser, voltarei a vós.E ele saiu de Éfeso."}, {"numero": 22, "texto": "E tendo vindo a Cesareia, subiu e, saudando à igreja, desceu a Antioquia."}, {"numero": 23, "texto": "E passando [ali] algum tempo, ele partiu, passando em sequência pela região da Galácia e Frígia, firmando a todos os discípulos."}, {"numero": 24, "texto": "E chegou a Éfeso um certo judeu, de nome Apolo, natural de Alexandria, homem eloquente, bem capacitado nas Escrituras."}, {"numero": 25, "texto": "Este era instruído no caminho do Senhor; e fervoroso de espírito, falava e ensinava corretamente as coisas do Senhor; [ainda que] soubesse somente o batismo de João."}, {"numero": 26, "texto": "E este começou a falar ousadamente na sinagoga; e Áquila e Priscila, ao o ouvirem, tomaram-no consigo, e explicaram mais detalhadamente o caminho de Deus."}, {"numero": 27, "texto": "E ele, querendo passar a Acaia, os irmãos o exortaram, [e] escreveram aos discípulos que o recebessem; o qual, tendo chegado, auxiliou muito aos que tinham crido pela graça."}, {"numero": 28, "texto": "Porque vigorosamente ele provava publicamente os erros dos judeus, mostrando pelas Escrituras que Jesus era o Cristo."}]'::jsonb, 'Almeida Livre'),
  ('At', 18, 'en', '[{"numero": 1, "texto": "After these things Paul departed from Athens, and came to Corinth;"}, {"numero": 2, "texto": "And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them."}, {"numero": 3, "texto": "And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."}, {"numero": 4, "texto": "And he reasoned in the synagogue every sabbath, and persuaded the Jews and the Greeks."}, {"numero": 5, "texto": "And when Silas and Timotheus were come from Macedonia, Paul was pressed in the spirit, and testified to the Jews that Jesus was Christ."}, {"numero": 6, "texto": "And when they opposed themselves, and blasphemed, he shook his raiment, and said unto them, Your blood be upon your own heads; I am clean; from henceforth I will go unto the Gentiles."}, {"numero": 7, "texto": "And he departed thence, and entered into a certain man''s house, named Justus, one that worshipped God, whose house joined hard to the synagogue."}, {"numero": 8, "texto": "And Crispus, the chief ruler of the synagogue, believed on the Lord with all his house; and many of the Corinthians hearing believed, and were baptized."}, {"numero": 9, "texto": "Then spake the Lord to Paul in the night by a vision, Be not afraid, but speak, and hold not thy peace:"}, {"numero": 10, "texto": "For I am with thee, and no man shall set on thee to hurt thee: for I have much people in this city."}, {"numero": 11, "texto": "And he continued there a year and six months, teaching the word of God among them."}, {"numero": 12, "texto": "And when Gallio was the deputy of Achaia, the Jews made insurrection with one accord against Paul, and brought him to the judgment seat,"}, {"numero": 13, "texto": "Saying, This fellow persuadeth men to worship God contrary to the law."}, {"numero": 14, "texto": "And when Paul was now about to open his mouth, Gallio said unto the Jews, If it were a matter of wrong or wicked lewdness, O ye Jews, reason would that I should bear with you:"}, {"numero": 15, "texto": "But if it be a question of words and names, and of your law, look ye to it; for I will be no judge of such matters."}, {"numero": 16, "texto": "And he drave them from the judgment seat."}, {"numero": 17, "texto": "Then all the Greeks took Sosthenes, the chief ruler of the synagogue, and beat him before the judgment seat. And Gallio cared for none of those things."}, {"numero": 18, "texto": "And Paul after this tarried there yet a good while, and then took his leave of the brethren, and sailed thence into Syria, and with him Priscilla and Aquila; having shorn his head in Cenchrea: for he had a vow."}, {"numero": 19, "texto": "And he came to Ephesus, and left them there: but he himself entered into the synagogue, and reasoned with the Jews."}, {"numero": 20, "texto": "When they desired him to tarry longer time with them, he consented not;"}, {"numero": 21, "texto": "But bade them farewell, saying, I must by all means keep this feast that cometh in Jerusalem: but I will return again unto you, if God will. And he sailed from Ephesus."}, {"numero": 22, "texto": "And when he had landed at Caesarea, and gone up, and saluted the church, he went down to Antioch."}, {"numero": 23, "texto": "And after he had spent some time there, he departed, and went over all the country of Galatia and Phrygia in order, strengthening all the disciples."}, {"numero": 24, "texto": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus."}, {"numero": 25, "texto": "This man was instructed in the way of the Lord; and being fervent in the spirit, he spake and taught diligently the things of the Lord, knowing only the baptism of John."}, {"numero": 26, "texto": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly."}, {"numero": 27, "texto": "And when he was disposed to pass into Achaia, the brethren wrote, exhorting the disciples to receive him: who, when he was come, helped them much which had believed through grace:"}, {"numero": 28, "texto": "For he mightily convinced the Jews, and that publicly, shewing by the scriptures that Jesus was Christ."}]'::jsonb, 'King James Version'),
  ('At', 18, 'fr', '[{"numero": 1, "texto": "Après cela, Paul partit d''''Athènes, et se rendit à Corinthe."}, {"numero": 2, "texto": "Il y trouva un Juif nommé Aquilas, originaire du Pont, récemment arrivé d''''Italie avec sa femme Priscille, parce que Claude avait ordonné à tous les Juifs de sortir de Rome. Il se lia avec eux;"}, {"numero": 3, "texto": "et, comme il avait le même métier, il demeura chez eux et y travailla: ils étaient faiseurs de tentes."}, {"numero": 4, "texto": "Paul discourait dans la synagogue chaque sabbat, et il persuadait des Juifs et des Grecs."}, {"numero": 5, "texto": "Mais quand Silas et Timothée furent arrivés de la Macédoine, il se donna tout entier à la parole, attestant aux Juifs que Jésus était le Christ."}, {"numero": 6, "texto": "Les Juifs faisant alors de l''''opposition et se livrant à des injures, Paul secoua ses vêtements, et leur dit: Que votre sang retombe sur votre tête! J''''en suis pur. Dès maintenant, j''''irai vers les païens."}, {"numero": 7, "texto": "Et sortant de là, il entra chez un nommé Justus, homme craignant Dieu, et dont la maison était contiguë à la synagogue."}, {"numero": 8, "texto": "Cependant Crispus, le chef de la synagogue, crut au Seigneur avec toute sa famille. Et plusieurs Corinthiens, qui avaient entendu Paul, crurent aussi, et furent baptisés."}, {"numero": 9, "texto": "Le Seigneur dit à Paul en vision pendant la nuit: Ne crains point; mais parle, et ne te tais point,"}, {"numero": 10, "texto": "Car je suis avec toi, et personne ne mettra la main sur toi pour te faire du mal: parle, car j''''ai un peuple nombreux dans cette ville."}, {"numero": 11, "texto": "Il y demeura un an et six mois, enseignant parmi les Corinthiens la parole de Dieu."}, {"numero": 12, "texto": "Du temps que Gallion était proconsul de l''''Achaïe, les Juifs se soulevèrent unanimement contre Paul, et le menèrent devant le tribunal,"}, {"numero": 13, "texto": "en disant: Cet homme excite les gens à servir Dieu d''''une manière contraire à la loi."}, {"numero": 14, "texto": "Paul allait ouvrir la bouche, lorsque Gallion dit aux Juifs: S''''il s''''agissait de quelque injustice ou de quelque méchante action, je vous écouterais comme de raison, ô Juifs;"}, {"numero": 15, "texto": "mais, s''''il s''''agit de discussions sur une parole, sur des noms, et sur votre loi, cela vous regarde: je ne veux pas être juge de ces choses."}, {"numero": 16, "texto": "Et il les renvoya du tribunal."}, {"numero": 17, "texto": "Alors tous, se saisissant de Sosthène, le chef de la synagogue, le battirent devant le tribunal, sans que Gallion s''''en mît en peine."}, {"numero": 18, "texto": "Paul resta encore assez longtemps à Corinthe. Ensuite il prit congé des frères, et s''''embarqua pour la Syrie, avec Priscille et Aquilas, après s''''être fait raser la tête à Cenchrées, car il avait fait un voeu."}, {"numero": 19, "texto": "Ils arrivèrent à Ephèse, et Paul y laissa ses compagnons. Etant entré dans la synagogue, il s''''entretint avec les Juifs,"}, {"numero": 20, "texto": "qui le prièrent de prolonger son séjour. Mais il n''''y consentit point,"}, {"numero": 21, "texto": "et il prit congé d''''eux, en disant: Il faut absolument que je célèbre la fête prochaine à Jérusalem. Je reviendrai vers vous, si Dieu le veut. Et il partit d''''Ephèse."}, {"numero": 22, "texto": "Etant débarqué à Césarée, il monta à Jérusalem, et, après avoir salué l''''Eglise, il descendit à Antioche."}, {"numero": 23, "texto": "Lorsqu''''il eut passé quelque temps à Antioche, Paul se mit en route, et parcourut successivement la Galatie et la Phrygie, fortifiant tous les disciples."}, {"numero": 24, "texto": "Un Juif nommé Apollos, originaire d''''Alexandrie, homme éloquent et versé dans les Ecritures, vint à Ephèse."}, {"numero": 25, "texto": "Il était instruit dans la voie du Seigneur, et, fervent d''''esprit, il annonçait et enseignait avec exactitude ce qui concerne Jésus, bien qu''''il ne connût que le baptême de Jean."}, {"numero": 26, "texto": "Il se mit à parler librement dans la synagogue. Aquilas et Priscille, l''''ayant entendu, le prirent avec eux, et lui exposèrent plus exactement la voie de Dieu."}, {"numero": 27, "texto": "Comme il voulait passer en Achaïe, les frères l''''y encouragèrent, et écrivirent aux disciples de le bien recevoir. Quand il fut arrivé, il se rendit, par la grâce de Dieu, très utile à ceux qui avaient cru;"}, {"numero": 28, "texto": "Car il réfutait vivement les Juifs en public, démontrant par les Ecritures que Jésus est le Christ."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 18, 'es', '[{"numero": 1, "texto": "PASADAS estas cosas, Pablo partió de Atenas, y vino á Corinto."}, {"numero": 2, "texto": "Y hallando á un Judío llamado Aquila, natural del Ponto, que hacía poco que había venido de Italia, y á Priscila su mujer, (porque Claudio había mandado que todos los Judíos saliesen de Roma) se vino á ellos;"}, {"numero": 3, "texto": "Y porque era de su oficio, posó con ellos, y trabajaba; porque el oficio de ellos era hacer tiendas."}, {"numero": 4, "texto": "Y disputaba en la sinagoga todos los sábados, y persuadía á Judíos y á Griegos."}, {"numero": 5, "texto": "Y cuando Silas y Timoteo vinieron de Macedonia, Pablo estaba constreñido por la palabra, testificando á los Judíos que Jesús era el Cristo."}, {"numero": 6, "texto": "Mas contradiciendo y blasfemando ellos, les dijo, sacudiendo sus vestidos: Vuestra sangre sea sobre vuestra cabeza; yo, limpio; desde ahora me iré á los Gentiles."}, {"numero": 7, "texto": "Y partiendo de allí, entró en casa de uno llamado Justo, temeroso de Dios, la casa del cual estaba junto á la sinagoga."}, {"numero": 8, "texto": "Y Crispo, el prepósito de la sinagoga, creyó al Señor con toda su casa: y muchos de los Corintios oyendo creían, y eran bautizados."}, {"numero": 9, "texto": "Entonces el Señor dijo de noche en visión á Pablo: No temas, sino habla, y no calles:"}, {"numero": 10, "texto": "Porque yo estoy contigo, y ninguno te podrá hacer mal; porque yo tengo mucho pueblo en esta ciudad."}, {"numero": 11, "texto": "Y se detuvo allí un año y seis meses, enseñándoles la palabra de Dios."}, {"numero": 12, "texto": "Y siendo Galión procónsul de Acaya, los Judíos se levantaron de común acuerdo contra Pablo, y le llevaron al tribunal,"}, {"numero": 13, "texto": "Diciendo: Que éste persuade á los hombres á honrar á Dios contra la ley."}, {"numero": 14, "texto": "Y comenzando Pablo á abrir la boca, Galión dijo á los Judíos: Si fuera algún agravio ó algún crimen enorme, oh Judíos, conforme á derecho yo os tolerara:"}, {"numero": 15, "texto": "Mas si son cuestiones de palabras, y de nombres, y de vuestra ley, vedlo vosotros; porque yo no quiero ser juez de estas cosas."}, {"numero": 16, "texto": "Y los echó del tribunal."}, {"numero": 17, "texto": "Entonces todos los Griegos tomando á Sóstenes, prepósito de la sinagoga, le herían delante del tribunal: y á Galión nada se le daba de ello."}, {"numero": 18, "texto": "Mas Pablo habiéndose detenido aún allí muchos días, después se despidió de los hermanos, y navegó á Siria, y con él Priscila y Aquila, habiéndose trasquilado la cabeza en Cencreas, porque tenía voto."}, {"numero": 19, "texto": "Y llegó á Efeso, y los dejó allí: y él entrando en la sinagoga, disputó con los Judíos,"}, {"numero": 20, "texto": "Los cuales le rogaban que se quedase con ellos por más tiempo; mas no accedió,"}, {"numero": 21, "texto": "Sino que se despidió de ellos, diciendo: Es menester que en todo caso tenga la fiesta que viene, en Jerusalem; mas otra vez volveré á vosotros, queriendo Dios. Y partió de Efeso."}, {"numero": 22, "texto": "Y habiendo arribado á Cesarea subió á Jerusalem; y después de saludar á la iglesia, descendió á Antioquía."}, {"numero": 23, "texto": "Y habiendo estado allí algún tiempo, partió, andando por orden la provincia de Galacia, y la Phrygia, confirmando á todos los discípulos."}, {"numero": 24, "texto": "Llegó entonces á Efeso un Judío, llamado Apolos, natural de Alejandría, varón elocuente, poderoso en las Escrituras."}, {"numero": 25, "texto": "Este era instruído en el camino del Señor; y ferviente de espíritu, hablaba y enseñaba diligentemente las cosas que son del Señor, enseñando solamente en el bautismo de Juan."}, {"numero": 26, "texto": "Y comenzó á hablar confiadamente en la sinagoga: al cual como oyeron Priscila y Aquila, le tomaron, y le declararon más particularmente el camino de Dios."}, {"numero": 27, "texto": "Y queriendo él pasar á Acaya, los hermanos exhortados, escribieron á los discípulos que le recibiesen; y venido él, aprovechó mucho por la gracia á los que habían creído:"}, {"numero": 28, "texto": "Porque con gran vehemencia convencía públicamente á los Judíos, mostrando por las Escrituras que Jesús era el Cristo."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 19, 'pt', '[{"numero": 1, "texto": "E enquanto Apolo estava em Corinto, aconteceu que, tendo Paulo passado por todas as regiões altas, ele veio a Éfeso; e achando [ali] alguns discípulos,"}, {"numero": 2, "texto": "Disse-lhes: Vós [já] recebestes o Espírito Santo [desde que] crestes? E eles lhe disseram: Nós nem tínhamos ouvido falar que havia Espírito Santo."}, {"numero": 3, "texto": "E ele lhes disse: Em que vós fostes batizados? E eles disseram: No batismo de João."}, {"numero": 4, "texto": "Então Paulo disse: João verdadeiramente batizou [com] o batismo do arrependimento, dizendo ao povo que cressem naquele que viria após ele, isto é, em Jesus Cristo."}, {"numero": 5, "texto": "Ao ouvirem [isto] , eles foram batizados no nome do Senhor Jesus."}, {"numero": 6, "texto": "E Paulo, impondo-lhes as mãos, veio sobre eles o Espírito Santo; e falavam em línguas, e profetizavam."}, {"numero": 7, "texto": "E todos os homens eram cerca de doze."}, {"numero": 8, "texto": "E ele, entrando na sinagoga, falava ousadamente durante três meses, disputando e persuadindo as coisas do Reino de Deus."}, {"numero": 9, "texto": "Mas quando alguns se endureceram, e não creram, e falando mal do Caminho diante da multidão, ele se desviou deles; e separou aos discípulos, disputando a cada dia na escola de um certo Tirano."}, {"numero": 10, "texto": "E isto aconteceu durante dois anos; de tal maneira que todos os que habitavam na Ásia tinham ouvido a palavra do Senhor Jesus, tanto judeus como gregos."}, {"numero": 11, "texto": "E Deus fazia milagres extraordinários pelas mãos de Paulo,"}, {"numero": 12, "texto": "De tal maneira que até os lenços e aventais de seu corpo eram levados aos enfermos, e as doenças os deixavam, e os espíritos malignos saíam deles."}, {"numero": 13, "texto": "E alguns exorcistas dos judeus, itinerantes, tentaram invocar o nome do Senhor Jesus sobre os que tinham espíritos malignos, dizendo: Nós vos repreendemos por Jesus, a quem Paulo prega."}, {"numero": 14, "texto": "E eram sete filhos de Ceva, judeu, chefe dos sacerdotes, os que faziam isto."}, {"numero": 15, "texto": "Mas o espírito maligno respondeu: Eu conheço Jesus, e sei quem é Paulo; mas vós, quem sois?"}, {"numero": 16, "texto": "E o homem em quem estava o espírito maligno saltou sobre eles, e dominando-os, foi mais forte do que eles; de tal maneira que eles fugiram nus e feridos daquela casa."}, {"numero": 17, "texto": "E isto se fez conhecido a todos que habitavam em Éfeso, tanto a judeus como a gregos; e caiu temor sobre todos eles; e [assim] foi engrandecido o nome do Senhor Jesus."}, {"numero": 18, "texto": "E muitos dos que criam vinham, confessando e declararando as suas atitudes."}, {"numero": 19, "texto": "Também muitos dos que praticavam ocultismo trouxeram seus livros, e [os] queimaram na presença de todos; e calcularam o preço deles, e acharam que [custavam] cinquenta mil [moedas] de prata."}, {"numero": 20, "texto": "Assim a palavra do Senhor crescia e prevalecia poderosamente."}, {"numero": 21, "texto": "E quando se cumpriram estas coisas, Paulo propôs em espírito que, passando pela Macedônia e Acaia, ir até Jerusalém, dizendo: Depois de eu estar lá, também tenho que ver Roma."}, {"numero": 22, "texto": "E ele, tendo enviado à Macedônia dois daqueles que o serviam, Timóteo e Erasto, ele ficou por [algum] tempo na Ásia."}, {"numero": 23, "texto": "Mas naquele tempo aconteceu um não pequeno alvoroço quanto ao Caminho ."}, {"numero": 24, "texto": "Porque um certo artífice de prata, de nome Demétrio, que fazia objetos de prata para o templo de Diana , e dava não pouco lucro aos artesãos."}, {"numero": 25, "texto": "Aos quais, tendo os reunido com os trabalhadores de semelhantes coisas, disse: Homens, vós sabeis que deste ofício temos nossa prosperidade."}, {"numero": 26, "texto": "E vós estais vendo e ouvindo que este Paulo, não somente em Éfeso, mas até quase em toda a Ásia, tem persuadido e apartado uma grande multidão, dizendo que não são deuses os que são feitos com as mãos."}, {"numero": 27, "texto": "E não somente há perigo de que isto torne [nosso] ofício em desprezo, mas também que [até] o tempo da grande deusa Diana seja considerado inútil, e que a grandiosidade dela, a quem toda a Ásia e o mundo venera, venha a ser destruída."}, {"numero": 28, "texto": "E eles, ao ouvirem [estas coisas] ,encheram-se de ira, e clamaram, dizendo: Grande é a Diana dos efésios!"}, {"numero": 29, "texto": "E toda a cidade se encheu de tumulto, e em concordância eles invadiram ao teatro, tomando consigo Gaio e Aristarco, macedônios, companheiros de Paulo na viagem."}, {"numero": 30, "texto": "E Paulo, querendo comparecer diante do povo, os discípulos não o permitiram."}, {"numero": 31, "texto": "E também alguns dos líderes da Ásia, que eram amigos dele, enviaram-lhe [aviso] , rogando[-lhe] para que não se apresentasse no teatro."}, {"numero": 32, "texto": "Então gritavam, [alguns de uma maneira] , outros de outra; porque a aglomeração estava confusa; e a maioria não sabia por que causa estavam aglomerados."}, {"numero": 33, "texto": "E tiraram da multidão a Alexandre, os judeus o pondo para a frente. E Alexandre, acenando com a mão, queria [se] defender ao povo."}, {"numero": 34, "texto": "Mas ao saberem que ele era judeu, levantou-se uma voz de todos, clamando por cerca de duas horas: Grande é a Diana dos efésios!"}, {"numero": 35, "texto": "E o escrivão, tendo apaziguado a multidão, disse: Homens efésios, quem não sabe que a cidade dos efésios é a guardadora do templo da grande deusa Diana, e da [imagem] que desceu do céu?"}, {"numero": 36, "texto": "Portanto, sendo que estas coisas não podem ser contraditas, vós deveis vos acalmar, e nada façais precipitadamente;"}, {"numero": 37, "texto": "Porque vós trouxestes [aqui] estes homens, que nem são sacrílegos, nem blasfemam de vossa deusa."}, {"numero": 38, "texto": "Então se Demétrio e os artesãos que estão com ele tem algum assunto contra ele, os tribunais estão abertos, e há procônsules; que se acusem uns aos outros."}, {"numero": 39, "texto": "E se procurais alguma outra coisa, será decidido em uma reunião legalizada."}, {"numero": 40, "texto": "Porque corremos perigo de que hoje sejamos acusados de rebelião, tendo causa nenhuma para dar como explicação para este tumulto."}, {"numero": 41, "texto": "E tendo dito isto, despediu o ajuntamento."}]'::jsonb, 'Almeida Livre'),
  ('At', 19, 'en', '[{"numero": 1, "texto": "And it came to pass, that, while Apollos was at Corinth, Paul having passed through the upper coasts came to Ephesus: and finding certain disciples,"}, {"numero": 2, "texto": "He said unto them, Have ye received the Holy Ghost since ye believed? And they said unto him, We have not so much as heard whether there be any Holy Ghost."}, {"numero": 3, "texto": "And he said unto them, Unto what then were ye baptized? And they said, Unto John''s baptism."}, {"numero": 4, "texto": "Then said Paul, John verily baptized with the baptism of repentance, saying unto the people, that they should believe on him which should come after him, that is, on Christ Jesus."}, {"numero": 5, "texto": "When they heard this, they were baptized in the name of the Lord Jesus."}, {"numero": 6, "texto": "And when Paul had laid his hands upon them, the Holy Ghost came on them; and they spake with tongues, and prophesied."}, {"numero": 7, "texto": "And all the men were about twelve."}, {"numero": 8, "texto": "And he went into the synagogue, and spake boldly for the space of three months, disputing and persuading the things concerning the kingdom of God."}, {"numero": 9, "texto": "But when divers were hardened, and believed not, but spake evil of that way before the multitude, he departed from them, and separated the disciples, disputing daily in the school of one Tyrannus."}, {"numero": 10, "texto": "And this continued by the space of two years; so that all they which dwelt in Asia heard the word of the Lord Jesus, both Jews and Greeks."}, {"numero": 11, "texto": "And God wrought special miracles by the hands of Paul:"}, {"numero": 12, "texto": "So that from his body were brought unto the sick handkerchiefs or aprons, and the diseases departed from them, and the evil spirits went out of them."}, {"numero": 13, "texto": "Then certain of the vagabond Jews, exorcists, took upon them to call over them which had evil spirits the name of the Lord Jesus, saying, We adjure you by Jesus whom Paul preacheth."}, {"numero": 14, "texto": "And there were seven sons of one Sceva, a Jew, and chief of the priests, which did so."}, {"numero": 15, "texto": "And the evil spirit answered and said, Jesus I know, and Paul I know; but who are ye?"}, {"numero": 16, "texto": "And the man in whom the evil spirit was leaped on them, and overcame them, and prevailed against them, so that they fled out of that house naked and wounded."}, {"numero": 17, "texto": "And this was known to all the Jews and Greeks also dwelling at Ephesus; and fear fell on them all, and the name of the Lord Jesus was magnified."}, {"numero": 18, "texto": "And many that believed came, and confessed, and shewed their deeds."}, {"numero": 19, "texto": "Many of them also which used curious arts brought their books together, and burned them before all men: and they counted the price of them, and found it fifty thousand pieces of silver."}, {"numero": 20, "texto": "So mightily grew the word of God and prevailed."}, {"numero": 21, "texto": "After these things were ended, Paul purposed in the spirit, when he had passed through Macedonia and Achaia, to go to Jerusalem, saying, After I have been there, I must also see Rome."}, {"numero": 22, "texto": "So he sent into Macedonia two of them that ministered unto him, Timotheus and Erastus; but he himself stayed in Asia for a season."}, {"numero": 23, "texto": "And the same time there arose no small stir about that way."}, {"numero": 24, "texto": "For a certain man named Demetrius, a silversmith, which made silver shrines for Diana, brought no small gain unto the craftsmen;"}, {"numero": 25, "texto": "Whom he called together with the workmen of like occupation, and said, Sirs, ye know that by this craft we have our wealth."}, {"numero": 26, "texto": "Moreover ye see and hear, that not alone at Ephesus, but almost throughout all Asia, this Paul hath persuaded and turned away much people, saying that they be no gods, which are made with hands:"}, {"numero": 27, "texto": "So that not only this our craft is in danger to be set at nought; but also that the temple of the great goddess Diana should be despised, and her magnificence should be destroyed, whom all Asia and the world worshippeth."}, {"numero": 28, "texto": "And when they heard these sayings, they were full of wrath, and cried out, saying, Great is Diana of the Ephesians."}, {"numero": 29, "texto": "And the whole city was filled with confusion: and having caught Gaius and Aristarchus, men of Macedonia, Paul''s companions in travel, they rushed with one accord into the theatre."}, {"numero": 30, "texto": "And when Paul would have entered in unto the people, the disciples suffered him not."}, {"numero": 31, "texto": "And certain of the chief of Asia, which were his friends, sent unto him, desiring him that he would not adventure himself into the theatre."}, {"numero": 32, "texto": "Some therefore cried one thing, and some another: for the assembly was confused: and the more part knew not wherefore they were come together."}, {"numero": 33, "texto": "And they drew Alexander out of the multitude, the Jews putting him forward. And Alexander beckoned with the hand, and would have made his defence unto the people."}, {"numero": 34, "texto": "But when they knew that he was a Jew, all with one voice about the space of two hours cried out, Great is Diana of the Ephesians."}, {"numero": 35, "texto": "And when the townclerk had appeased the people, he said, Ye men of Ephesus, what man is there that knoweth not how that the city of the Ephesians is a worshipper of the great goddess Diana, and of the image which fell down from Jupiter?"}, {"numero": 36, "texto": "Seeing then that these things cannot be spoken against, ye ought to be quiet, and to do nothing rashly."}, {"numero": 37, "texto": "For ye have brought hither these men, which are neither robbers of churches, nor yet blasphemers of your goddess."}, {"numero": 38, "texto": "Wherefore if Demetrius, and the craftsmen which are with him, have a matter against any man, the law is open, and there are deputies: let them implead one another."}, {"numero": 39, "texto": "But if ye enquire any thing concerning other matters, it shall be determined in a lawful assembly."}, {"numero": 40, "texto": "For we are in danger to be called in question for this day''s uproar, there being no cause whereby we may give an account of this concourse."}, {"numero": 41, "texto": "And when he had thus spoken, he dismissed the assembly."}]'::jsonb, 'King James Version'),
  ('At', 19, 'fr', '[{"numero": 1, "texto": "Pendant qu''''Apollos était à Corinthe, Paul, après avoir parcouru les hautes provinces de l''''Asie, arriva à Ephèse. Ayant rencontré quelques disciples,"}, {"numero": 2, "texto": "il leur dit: Avez-vous reçu le Saint-Esprit, quand vous avez cru? Ils lui répondirent: Nous n''''avons pas même entendu dire qu''''il y ait un Saint-Esprit."}, {"numero": 3, "texto": "Il dit: De quel baptême avez-vous donc été baptisés? Et ils répondirent: Du baptême de Jean."}, {"numero": 4, "texto": "Alors Paul dit: Jean a baptisé du baptême de repentance, disant au peuple de croire en celui qui venait après lui, c''''est-à-dire, en Jésus."}, {"numero": 5, "texto": "Sur ces paroles, ils furent baptisés au nom du Seigneur Jésus."}, {"numero": 6, "texto": "Lorsque Paul leur eut imposé les mains, le Saint-Esprit vint sur eux, et ils parlaient en langues et prophétisaient."}, {"numero": 7, "texto": "Ils étaient en tout environ douze hommes."}, {"numero": 8, "texto": "Ensuite Paul entra dans la synagogue, où il parla librement. Pendant trois mois, il discourut sur les choses qui concernent le royaume de Dieu, s''''efforçant de persuader ceux qui l''''écoutaient."}, {"numero": 9, "texto": "Mais, comme quelques-uns restaient endurcis et incrédules, décriant devant la multitude la voie du Seigneur, il se retira d''''eux, sépara les disciples, et enseigna chaque jour dans l''''école d''''un nommé Tyrannus."}, {"numero": 10, "texto": "Cela dura deux ans, de sorte que tous ceux qui habitaient l''''Asie, Juifs et Grecs, entendirent la parole du Seigneur."}, {"numero": 11, "texto": "Et Dieu faisait des miracles extraordinaires par les mains de Paul,"}, {"numero": 12, "texto": "au point qu''''on appliquait sur les malades des linges ou des mouchoirs qui avaient touché son corps, et les maladies les quittaient, et les esprits malins sortaient."}, {"numero": 13, "texto": "Quelques exorcistes juifs ambulants essayèrent d''''invoquer sur ceux qui avaient des esprits malins le nom du Seigneur Jésus, en disant: Je vous conjure par Jésus que Paul prêche!"}, {"numero": 14, "texto": "Ceux qui faisaient cela étaient sept fils de Scéva, Juif, l''''un des principaux sacrificateurs."}, {"numero": 15, "texto": "L''''esprit malin leur répondit: Je connais Jésus, et je sais qui est Paul; mais vous, qui êtes-vous?"}, {"numero": 16, "texto": "Et l''''homme dans lequel était l''''esprit malin s''''élança sur eux, se rendit maître de tous deux, et les maltraita de telle sorte qu''''ils s''''enfuirent de cette maison nus et blessés."}, {"numero": 17, "texto": "Cela fut connu de tous les Juifs et de tous les Grecs qui demeuraient à Ephèse, et la crainte s''''empara d''''eux tous, et le nom du Seigneur Jésus était glorifié."}, {"numero": 18, "texto": "Plusieurs de ceux qui avaient cru venaient confesser et déclarer ce qu''''ils avaient fait."}, {"numero": 19, "texto": "Et un certain nombre de ceux qui avaient exercé les arts magiques, ayant apporté leurs livres, les brûlèrent devant tout le monde: on en estima la valeur à cinquante mille pièces d''''argent."}, {"numero": 20, "texto": "C''''est ainsi que la parole du Seigneur croissait en puissance et en force."}, {"numero": 21, "texto": "Après que ces choses se furent passées, Paul forma le projet d''''aller à Jérusalem, en traversant la Macédoine et l''''Achaïe. Quand j''''aurai été là, se disait-il, il faut aussi que je voie Rome."}, {"numero": 22, "texto": "Il envoya en Macédoine deux de ses aides, Timothée et Eraste, et il resta lui-même quelque temps encore en Asie."}, {"numero": 23, "texto": "Il survint, à cette époque, un grand trouble au sujet de la voie du Seigneur."}, {"numero": 24, "texto": "Un nommé Démétrius, orfèvre, fabriquait en argent des temples de Diane, et procurait à ses ouvriers un gain considérable."}, {"numero": 25, "texto": "Il les rassembla, avec ceux du même métier, et dit: O hommes, vous savez que notre bien-être dépend de cette industrie;"}, {"numero": 26, "texto": "et vous voyez et entendez que, non seulement à Ephèse, mais dans presque toute l''''Asie, ce Paul a persuadé et détourné une foule de gens, en disant que les dieux faits de main d''''homme ne sont pas des dieux."}, {"numero": 27, "texto": "Le danger qui en résulte, ce n''''est pas seulement que notre industrie ne tombe en discrédit; c''''est encore que le temple de la grande déesse Diane ne soit tenu pour rien, et même que la majesté de celle qui est révérée dans toute l''''Asie et dans le monde entier ne soit réduite à néant."}, {"numero": 28, "texto": "Ces paroles les ayant remplis de colère, ils se mirent à crier: Grande est la Diane des Ephésiens!"}, {"numero": 29, "texto": "Toute la ville fut dans la confusion. Ils se précipitèrent tous ensemble au théâtre, entraînant avec eux Gaïus et Aristarque, Macédoniens, compagnons de voyage de Paul."}, {"numero": 30, "texto": "Paul voulait se présenter devant le peuple, mais les disciples l''''en empêchèrent;"}, {"numero": 31, "texto": "quelques-uns même des Asiarques, qui étaient ses amis, envoyèrent vers lui, pour l''''engager à ne pas se rendre au théâtre."}, {"numero": 32, "texto": "Les uns criaient d''''une manière, les autres d''''une autre, car le désordre régnait dans l''''assemblée, et la plupart ne savaient pas pourquoi ils s''''étaient réunis."}, {"numero": 33, "texto": "Alors on fit sortir de la foule Alexandre, que les Juifs poussaient en avant; et Alexandre, faisant signe de la main, voulait parler au peuple."}, {"numero": 34, "texto": "Mais quand ils reconnurent qu''''il était Juif, tous d''''une seule voix crièrent pendant près de deux heures: Grande est la Diane des Ephésiens!"}, {"numero": 35, "texto": "Cependant le secrétaire, ayant apaisé la foule, dit: Hommes Ephésiens, quel est celui qui ignore que la ville d''''Ephèse est la gardienne du temple de la grande Diane et de son simulacre tombé du ciel?"}, {"numero": 36, "texto": "Cela étant incontestable, vous devez vous calmer, et ne rien faire avec précipitation."}, {"numero": 37, "texto": "Car vous avez amené ces hommes, qui ne sont coupables ni de sacrilège, ni de blasphème envers notre déesse."}, {"numero": 38, "texto": "Si donc Démétrius et ses ouvriers ont à se plaindre de quelqu''''un, il y a des jours d''''audience et des proconsuls; qu''''ils s''''appellent en justice les uns les autres."}, {"numero": 39, "texto": "Et si vous avez en vue d''''autres objets, ils se régleront dans une assemblée légale."}, {"numero": 40, "texto": "Nous risquons, en effet, d''''être accusés de sédition pour ce qui s''''est passé aujourd''''hui, puisqu''''il n''''existe aucun motif qui nous permette de justifier cet attroupement."}, {"numero": 41, "texto": "Après ces paroles, il congédia l''''assemblée."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 19, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que entre tanto que Apolos estaba en Corinto, Pablo, andadas las regiones superiores, vino á Efeso, y hallando ciertos discípulos,"}, {"numero": 2, "texto": "Díjoles: ¿Habéis recibido el Espíritu Santo después que creísteis? Y ellos le dijeron: Antes ni aun hemos oído si hay Espíritu Santo."}, {"numero": 3, "texto": "Entonces dijo: ¿En qué pues sois bautizados? Y ellos dijeron: En el bautismo de Juan."}, {"numero": 4, "texto": "Y dijo Pablo: Juan bautizó con bautismo de arrepentimiento, diciendo al pueblo que creyesen en el que había de venir después de él, es á saber, en Jesús el Cristo."}, {"numero": 5, "texto": "Oído que hubieron esto, fueron bautizados en el nombre del Señor Jesús."}, {"numero": 6, "texto": "Y habiéndoles impuesto Pablo las manos, vino sobre ellos el Espíritu Santo; y hablaban en lenguas, y profetizaban."}, {"numero": 7, "texto": "Y eran en todos como unos doce hombres."}, {"numero": 8, "texto": "Y entrando él dentro de la sinagoga, hablaba libremente por espacio de tres meses, disputando y persuadiendo del reino de Dios."}, {"numero": 9, "texto": "Mas endureciéndose algunos y no creyendo, maldiciendo el Camino delante de la multitud, apartándose Pablo de ellos separó á los discípulos, disputando cada día en la escuela de un cierto Tyranno."}, {"numero": 10, "texto": "Y esto fué por espacio de dos años; de manera que todos los que habitaban en Asia, Judíos y Griegos, oyeron la palabra del Señor Jesús."}, {"numero": 11, "texto": "Y hacía Dios singulares maravillas por manos de Pablo:"}, {"numero": 12, "texto": "De tal manera que aun se llevaban sobre los enfermos los sudarios y los pañuelos de su cuerpo, y las enfermedades se iban de ellos, y los malos espíritus salían de ellos."}, {"numero": 13, "texto": "Y algunos de los Judíos, exorcistas vagabundos, tentaron á invocar el nombre del Señor Jesús sobre los que tenían espíritus malos, diciendo: Os conjuro por Jesús, el que Pablo predica."}, {"numero": 14, "texto": "Y había siete hijos de un tal Sceva, Judío, príncipe de los sacerdotes, que hacían esto."}, {"numero": 15, "texto": "Y respondiendo el espíritu malo, dijo: A Jesús conozco, y sé quién es Pablo: mas vosotros ¿quiénes sois?"}, {"numero": 16, "texto": "Y el hombre en quien estaba el espíritu malo, saltando en ellos, y enseñoreándose de ellos, pudo más que ellos, de tal manera que huyeron de aquella casa desnudos y heridos."}, {"numero": 17, "texto": "Y esto fué notorio á todos, así Judíos como Griegos, los que habitaban en Efeso: y cayó temor sobre todos ellos, y era ensalzado el nombre del Señor Jesús."}, {"numero": 18, "texto": "Y muchos de los que habían creído, venían, confesando y dando cuenta de sus hechos."}, {"numero": 19, "texto": "Asimismo muchos de los que habían practicado vanas artes, trajeron los libros, y los quemaron delante de todos; y echada la cuenta del precio de ellos, hallaron ser cincuenta mil denarios."}, {"numero": 20, "texto": "Así crecía poderosamente la palabra del Señor, y prevalecía."}, {"numero": 21, "texto": "Y acabadas estas cosas, se propuso Pablo en espíritu partir á Jerusalem, después de andada Macedonia y Acaya, diciendo: Después que hubiere estado allá, me será menester ver también á Roma."}, {"numero": 22, "texto": "Y enviando á Macedonia á dos de los que le ayudaban, Timoteo y Erasto, él se estuvo por algún tiempo en Asia."}, {"numero": 23, "texto": "Entonces hubo un alboroto no pequeño acerca del Camino."}, {"numero": 24, "texto": "Porque un platero llamado Demetrio, el cual hacía de plata templecillos de Diana, daba á los artífices no poca ganancia;"}, {"numero": 25, "texto": "A los cuales, reunidos con los oficiales de semejante oficio, dijo: Varones, sabéis que de este oficio tenemos ganancia;"}, {"numero": 26, "texto": "Y veis y oís que este Pablo, no solamente en Efeso, sino á muchas gentes de casi toda el Asia, ha apartado con persuasión, diciendo, que no son dioses los que se hacen con las manos."}, {"numero": 27, "texto": "Y no solamente hay peligro de que este negocio se nos vuelva en reproche, sino también que el templo de la gran diosa Diana sea estimado en nada, y comience á ser destruída su majestad, la cual honra toda el Asia y el mundo."}, {"numero": 28, "texto": "Oídas estas cosas, llenáronse de ira, y dieron alarido, diciendo: ¡Grande es Diana de los Efesios!"}, {"numero": 29, "texto": "Y la ciudad se llenó de confusión; y unánimes se arrojaron al teatro, arrebatando á Gayo y á Aristarco, Macedonios, compañeros de Pablo."}, {"numero": 30, "texto": "Y queriendo Pablo salir al pueblo, los discípulos no le dejaron."}, {"numero": 31, "texto": "También algunos de los principales de Asia, que eran sus amigos, enviaron á él rogando que no se presentase en el teatro."}, {"numero": 32, "texto": "Y otros gritaban otra cosa; porque la concurrencia estaba confusa, y los más no sabían por qué se habían juntado."}, {"numero": 33, "texto": "Y sacaron de entre la multitud á Alejandro, empujándole los Judíos. Entonces Alejandro, pedido silencio con la mano, quería dar razón al pueblo."}, {"numero": 34, "texto": "Mas como conocieron que era Judío, fué hecha un voz de todos, que gritaron casi por dos horas: ¡Grande es Diana de los Efesios!"}, {"numero": 35, "texto": "Entonces el escribano, apaciguado que hubo la gente, dijo: Varones Efesios, ¿y quién hay de los hombres que no sepa que la ciudad de los Efesios es honradora de la gran diosa Diana, y de la imagen venida de Júpiter?"}, {"numero": 36, "texto": "Así que, pues esto no puede ser contradicho, conviene que os apacigüéis, y que nada hagáis temerariamente;"}, {"numero": 37, "texto": "Pues habéis traído á estos hombres, sin ser sacrílegos ni blasfemadores de vuestra diosa."}, {"numero": 38, "texto": "Que si Demetrio y los oficiales que están con él tienen negocio con alguno, audiencias se hacen, y procónsules hay; acúsense los unos á los otros."}, {"numero": 39, "texto": "Y si demandáis alguna otra cosa, en legítima asamblea se pueda decidir."}, {"numero": 40, "texto": "Porque peligro hay de que seamos argüidos de sedición por hoy, no habiendo ninguna causa por la cual podamos dar razón de este concurso. Y habiendo dicho esto, despidió la concurrencia."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 20, 'pt', '[{"numero": 1, "texto": "E tendo acabado o tumulto, Paulo chamou a si os discípulos e, abraçando-os, saiu para ir à Macedônia."}, {"numero": 2, "texto": "E tendo passado por aquelas regiões, e exortando-os com muitas palavras, ele veio à Grécia."}, {"numero": 3, "texto": "E ficando [ali] por três meses, e havendo contra ele uma cilada posta pelos judeus quando ele estava a ponto de navegar para a Síria, ele decidiu voltar pela Macedônia."}, {"numero": 4, "texto": "E o acompanhou até a Ásia Sópater, de Bereia; e dos tessalonicenses, Aristarco e Segundo, e Gaio de Derbe, e Timóteo; e dos da Ásia, Tíquico e Trófimo."}, {"numero": 5, "texto": "Estes, indo adiante, nos esperaram em Trôade."}, {"numero": 6, "texto": "E depois dos dias dos [pães] não fermentados, nós navegamos de Filipos, e em cinco dias viemos até eles, onde ficamos por sete dias."}, {"numero": 7, "texto": "E no primeiro [dia] da semana, tendo os discípulos se reunido para partir o pão, Paulo discutia com eles, estando para partir no dia seguinte; e ele estendeu a discussão até a meia noite."}, {"numero": 8, "texto": "E havia muitas luminárias no compartimento onde estavam reunidos."}, {"numero": 9, "texto": "E estando um certo rapaz, de nome Êutico, sentado em uma janela, tendo sido tomado por um sono profundo, [e] ,estando Paulo [ainda] falando por muito [tempo] ,[Êutico] ,derrubado pelo sono, caiu desde o terceiro andar abaixo; e foi levantado morto."}, {"numero": 10, "texto": "Mas Paulo, tendo descido, debruçou sobre ele e, abraçando [-o] ,disse: Não fiqueis perturbados, porque sua alma [ainda] está nele."}, {"numero": 11, "texto": "E [voltou] a subir, e tendo partido e experimentado o pão, ele falou longamente até o nascer do dia; e assim ele partiu."}, {"numero": 12, "texto": "E trouxeram o rapaz vivo, e ficaram não pouco consolados."}, {"numero": 13, "texto": "E nós, tendo ido adiante ao navio, navegamos até Assôs, onde estaríamos para receber a Paulo, porque assim ele tinha ordenado; e ele ia a pé."}, {"numero": 14, "texto": "E quando ele se encontrou conosco em Assôs, nós o tomamos, e fomos a Mitilene."}, {"numero": 15, "texto": "E navegando dali, chegamos no [dia] seguinte em frente a Quios; e no outro dia aportamos em Samos; e ficando em Trogílio, no dia seguinte viemos a Mileto."}, {"numero": 16, "texto": "Porque Paulo tinha decidido navegar [desviando-se] de Éfeso, para não lhe haver de gastar tempo na Ásia; porque ele se apressava para estar em Jerusalém do dia de Pentecostes, caso lhe fosse possível."}, {"numero": 17, "texto": "Mas ele enviou [mensagem] desde Mileto até Éfeso, chamando aos anciãos da igreja."}, {"numero": 18, "texto": "E quando vieram a [Paulo] ,ele lhes disse: Vós sabeis que desde o primeiro dia que entrei na Ásia, [o modo] como eu estive todo [aquele] tempo convosco;"}, {"numero": 19, "texto": "Servindo ao Senhor com toda humildade, muitas lágrimas, e tentações, que sobrevieram a mim pelas ciladas dos judeus;"}, {"numero": 20, "texto": "Como eu, daquilo que [vos] era proveitoso, nada deixei de anunciar a vós, e ensinar publicamente e pelas casas;"}, {"numero": 21, "texto": "Dando testemunho, tanto a judeus como a gregos, do arrependimento para [se converter] a Deus, e da fé em nosso Senhor Jesus Cristo."}, {"numero": 22, "texto": "E agora eis que, estando eu atado ao Espírito, estou indo a Jerusalém, não sabendo o que me acontecerá;"}, {"numero": 23, "texto": "A não ser pelo que o Espírito Santo em cada cidade [me] dá testemunho, dizendo que prisões e aflições me esperam."}, {"numero": 24, "texto": "Mas de nenhuma [dessas] coisas eu dou importância, nem tenho minha vida por preciosa, para que com alegria eu cumpra minha carreira, e o trabalho que recebi do Senhor Jesus, para dar testemunho do Evangelho da graça de Deus."}, {"numero": 25, "texto": "E agora, eis que eu sei que todos vós, a quem eu passei pregando o Reino de Deus, não vereis mais o meu rosto."}, {"numero": 26, "texto": "Portanto eu vos dou claro testemunho de que eu estou limpo do sangue de todos [vós] ;"}, {"numero": 27, "texto": "Porque eu não deixei de vos anunciar todo o conselho de Deus;"}, {"numero": 28, "texto": "Portanto prestai atenção por vós mesmos, e por todo o rebanho sobre os quais o Espírito Santo tem vos posto como supervisores, para apascentardes a igreja de Deus, a qual ele adquiriu por meio de seu próprio sangue."}, {"numero": 29, "texto": "Porque isto eu sei, que depois de minha partida, entrarão entre vós lobos cruéis, que não pouparão ao rebanho;"}, {"numero": 30, "texto": "E que dentre vós mesmos se levantarão homens a falarem coisas perversas, para atraírem após si aos discípulos."}, {"numero": 31, "texto": "Por isso vigiai, lembrando que por três anos, noite e dia eu não parei de vos alertar com lágrimas a cada um [de vós] ."}, {"numero": 32, "texto": "E agora, irmãos, eu vos entrego a Deus, e à palavra de sua graça; ele que é poderoso para vos edificar e vos dar herança entre todos os santificados."}, {"numero": 33, "texto": "Eu não cobicei de ninguém a prata, nem ouro, nem roupa."}, {"numero": 34, "texto": "E vós mesmos sabeis que, para as minhas necessidades e as dos que estavam comigo, estas [minhas] mãos me serviram."}, {"numero": 35, "texto": "Em tudo eu vos tenho mostrado que trabalhando assim, é necessário dar suporte aos enfermos; e lembrar-se das palavras do Senhor Jesus, que disse: Mais bem-aventurado é dar do que receber."}, {"numero": 36, "texto": "E tendo dito isto, pondo-se de joelhos, ele orou com todos eles."}, {"numero": 37, "texto": "E houve um grande pranto de todos; e reclinando-se sobre o pescoço de Paulo, beijavam-no;"}, {"numero": 38, "texto": "Entristecendo-se muito, principalmente pela palavra que ele tinha dito, que não mais veriam o rosto dele; e o acompanharam até o navio."}]'::jsonb, 'Almeida Livre'),
  ('At', 20, 'en', '[{"numero": 1, "texto": "And after the uproar was ceased, Paul called unto him the disciples, and embraced them, and departed for to go into Macedonia."}, {"numero": 2, "texto": "And when he had gone over those parts, and had given them much exhortation, he came into Greece,"}, {"numero": 3, "texto": "And there abode three months. And when the Jews laid wait for him, as he was about to sail into Syria, he purposed to return through Macedonia."}, {"numero": 4, "texto": "And there accompanied him into Asia Sopater of Berea; and of the Thessalonians, Aristarchus and Secundus; and Gaius of Derbe, and Timotheus; and of Asia, Tychicus and Trophimus."}, {"numero": 5, "texto": "These going before tarried for us at Troas."}, {"numero": 6, "texto": "And we sailed away from Philippi after the days of unleavened bread, and came unto them to Troas in five days; where we abode seven days."}, {"numero": 7, "texto": "And upon the first day of the week, when the disciples came together to break bread, Paul preached unto them, ready to depart on the morrow; and continued his speech until midnight."}, {"numero": 8, "texto": "And there were many lights in the upper chamber, where they were gathered together."}, {"numero": 9, "texto": "And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead."}, {"numero": 10, "texto": "And Paul went down, and fell on him, and embracing him said, Trouble not yourselves; for his life is in him."}, {"numero": 11, "texto": "When he therefore was come up again, and had broken bread, and eaten, and talked a long while, even till break of day, so he departed."}, {"numero": 12, "texto": "And they brought the young man alive, and were not a little comforted."}, {"numero": 13, "texto": "And we went before to ship, and sailed unto Assos, there intending to take in Paul: for so had he appointed, minding himself to go afoot."}, {"numero": 14, "texto": "And when he met with us at Assos, we took him in, and came to Mitylene."}, {"numero": 15, "texto": "And we sailed thence, and came the next day over against Chios; and the next day we arrived at Samos, and tarried at Trogyllium; and the next day we came to Miletus."}, {"numero": 16, "texto": "For Paul had determined to sail by Ephesus, because he would not spend the time in Asia: for he hasted, if it were possible for him, to be at Jerusalem the day of Pentecost."}, {"numero": 17, "texto": "And from Miletus he sent to Ephesus, and called the elders of the church."}, {"numero": 18, "texto": "And when they were come to him, he said unto them, Ye know, from the first day that I came into Asia, after what manner I have been with you at all seasons,"}, {"numero": 19, "texto": "Serving the Lord with all humility of mind, and with many tears, and temptations, which befell me by the lying in wait of the Jews:"}, {"numero": 20, "texto": "And how I kept back nothing that was profitable unto you, but have shewed you, and have taught you publicly, and from house to house,"}, {"numero": 21, "texto": "Testifying both to the Jews, and also to the Greeks, repentance toward God, and faith toward our Lord Jesus Christ."}, {"numero": 22, "texto": "And now, behold, I go bound in the spirit unto Jerusalem, not knowing the things that shall befall me there:"}, {"numero": 23, "texto": "Save that the Holy Ghost witnesseth in every city, saying that bonds and afflictions abide me."}, {"numero": 24, "texto": "But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God."}, {"numero": 25, "texto": "And now, behold, I know that ye all, among whom I have gone preaching the kingdom of God, shall see my face no more."}, {"numero": 26, "texto": "Wherefore I take you to record this day, that I am pure from the blood of all men."}, {"numero": 27, "texto": "For I have not shunned to declare unto you all the counsel of God."}, {"numero": 28, "texto": "Take heed therefore unto yourselves, and to all the flock, over the which the Holy Ghost hath made you overseers, to feed the church of God, which he hath purchased with his own blood."}, {"numero": 29, "texto": "For I know this, that after my departing shall grievous wolves enter in among you, not sparing the flock."}, {"numero": 30, "texto": "Also of your own selves shall men arise, speaking perverse things, to draw away disciples after them."}, {"numero": 31, "texto": "Therefore watch, and remember, that by the space of three years I ceased not to warn every one night and day with tears."}, {"numero": 32, "texto": "And now, brethren, I commend you to God, and to the word of his grace, which is able to build you up, and to give you an inheritance among all them which are sanctified."}, {"numero": 33, "texto": "I have coveted no man''s silver, or gold, or apparel."}, {"numero": 34, "texto": "Yea, ye yourselves know, that these hands have ministered unto my necessities, and to them that were with me."}, {"numero": 35, "texto": "I have shewed you all things, how that so labouring ye ought to support the weak, and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive."}, {"numero": 36, "texto": "And when he had thus spoken, he kneeled down, and prayed with them all."}, {"numero": 37, "texto": "And they all wept sore, and fell on Paul''s neck, and kissed him,"}, {"numero": 38, "texto": "Sorrowing most of all for the words which he spake, that they should see his face no more. And they accompanied him unto the ship."}]'::jsonb, 'King James Version'),
  ('At', 20, 'fr', '[{"numero": 1, "texto": "Lorsque le tumulte eut cessé, Paul réunit les disciples, et, après les avoir exhortés, prit congé d''''eux, et partit pour aller en Macédoine."}, {"numero": 2, "texto": "Il parcourut cette contrée, en adressant aux disciples de nombreuses exhortations. Puis il se rendit en Grèce,"}, {"numero": 3, "texto": "où il séjourna trois mois. Il était sur le point de s''''embarquer pour la Syrie, quand les Juifs lui dressèrent des embûches. Alors il se décida à reprendre la route de la Macédoine."}, {"numero": 4, "texto": "Il avait pour l''''accompagner jusqu''''en Asie: Sopater de Bérée, fils de Pyrrhus, Aristarque et Second de Thessalonique, Gaïus de Derbe, Timothée, ainsi que Tychique et Trophime, originaires d''''Asie."}, {"numero": 5, "texto": "Ceux-ci prirent les devants, et nous attendirent à Troas."}, {"numero": 6, "texto": "Pour nous, après les jours des pains sans levain, nous nous embarquâmes à Philippes, et, au bout de cinq jours, nous les rejoignîmes à Troas, où nous passâmes sept jours."}, {"numero": 7, "texto": "Le premier jour de la semaine, nous étions réunis pour rompre le pain. Paul, qui devait partir le lendemain, s''''entretenait avec les disciples, et il prolongea son discours jusqu''''à minuit."}, {"numero": 8, "texto": "Il y avait beaucoup de lampes dans la chambre haute où nous étions assemblés."}, {"numero": 9, "texto": "Or, un jeune homme nommé Eutychus, qui était assis sur la fenêtre, s''''endormit profondément pendant le long discours de Paul; entraîné par le sommeil, il tomba du troisième étage en bas, et il fut relevé mort."}, {"numero": 10, "texto": "Mais Paul, étant descendu, se pencha sur lui et le prit dans ses bras, en disant: Ne vous troublez pas, car son âme est en lui."}, {"numero": 11, "texto": "Quand il fut remonté, il rompit le pain et mangea, et il parla longtemps encore jusqu''''au jour. Après quoi il partit."}, {"numero": 12, "texto": "Le jeune homme fut ramené vivant, et ce fut le sujet d''''une grande consolation."}, {"numero": 13, "texto": "Pour nous, nous précédâmes Paul sur le navire, et nous fîmes voile pour Assos, où nous étions convenus de le reprendre, parce qu''''il devait faire la route à pied."}, {"numero": 14, "texto": "Lorsqu''''il nous eut rejoints à Assos, nous le prîmes à bord, et nous allâmes à Mytilène."}, {"numero": 15, "texto": "De là, continuant par mer, nous arrivâmes le lendemain vis-à-vis de Chios. Le jour suivant, nous cinglâmes vers Samos, et le jour d''''après nous vînmes à Milet."}, {"numero": 16, "texto": "Paul avait résolu de passer devant Ephèse sans s''''y arrêter, afin de ne pas perdre de temps en Asie; car il se hâtait pour se trouver, si cela lui était possible, à Jérusalem le jour de la Pentecôte."}, {"numero": 17, "texto": "Cependant, de Milet Paul envoya chercher à Ephèse les anciens de l''''Eglise."}, {"numero": 18, "texto": "Lorsqu''''ils furent arrivés vers lui, il leur dit: Vous savez de quelle manière, depuis le premier jour où je suis entré en Asie, je me suis sans cesse conduit avec vous,"}, {"numero": 19, "texto": "servant le Seigneur en toute humilité, avec larmes, et au milieu des épreuves que me suscitaient les embûches des Juifs."}, {"numero": 20, "texto": "Vous savez que je n''''ai rien caché de ce qui vous était utile, et que je n''''ai pas craint de vous prêcher et de vous enseigner publiquement et dans les maisons,"}, {"numero": 21, "texto": "annonçant aux Juifs et aux Grecs la repentance envers Dieu et la foi en notre Seigneur Jésus-Christ."}, {"numero": 22, "texto": "Et maintenant voici, lié par l''''Esprit, je vais à Jérusalem, ne sachant pas ce qui m''''y arrivera;"}, {"numero": 23, "texto": "seulement, de ville en ville, l''''Esprit-Saint m''''avertit que des liens et des tribulations m''''attendent."}, {"numero": 24, "texto": "Mais je ne fais pour moi-même aucun cas de ma vie, comme si elle m''''était précieuse, pourvu que j''''accomplisse ma course avec joie, et le ministère que j''''ai reçu du Seigneur Jésus, d''''annoncer la bonne nouvelle de la grâce de Dieu."}, {"numero": 25, "texto": "Et maintenant voici, je sais que vous ne verrez plus mon visage, vous tous au milieu desquels j''''ai passé en prêchant le royaume de Dieu."}, {"numero": 26, "texto": "C''''est pourquoi je vous déclare aujourd''''hui que je suis pur du sang de vous tous,"}, {"numero": 27, "texto": "car je vous ai annoncé tout le conseil de Dieu, sans en rien cacher."}, {"numero": 28, "texto": "Prenez donc garde à vous-mêmes, et à tout le troupeau sur lequel le Saint-Esprit vous a établis évêques, pour paître l''''Eglise du Seigneur, qu''''il s''''est acquise par son propre sang."}, {"numero": 29, "texto": "Je sais qu''''il s''''introduira parmi vous, après mon départ, des loups cruels qui n''''épargneront pas le troupeau,"}, {"numero": 30, "texto": "et qu''''il s''''élèvera du milieu de vous des hommes qui enseigneront des choses pernicieuses, pour entraîner les disciples après eux."}, {"numero": 31, "texto": "Veillez donc, vous souvenant que, durant trois années, je n''''ai cessé nuit et jour d''''exhorter avec larmes chacun de vous."}, {"numero": 32, "texto": "Et maintenant je vous recommande à Dieu et à la parole de sa grâce, à celui qui peut édifier et donner l''''héritage avec tous les sanctifiés."}, {"numero": 33, "texto": "Je n''''ai désiré ni l''''argent, ni l''''or, ni les vêtements de personne."}, {"numero": 34, "texto": "Vous savez vous-mêmes que ces mains ont pourvu à mes besoins et à ceux des personnes qui étaient avec moi."}, {"numero": 35, "texto": "Je vous ai montré de toutes manières que c''''est en travaillant ainsi qu''''il faut soutenir les faibles, et se rappeler les paroles du Seigneur, qui a dit lui-même: Il y a plus de bonheur à donner qu''''à recevoir."}, {"numero": 36, "texto": "Après avoir ainsi parlé, il se mit à genoux, et il pria avec eux tous."}, {"numero": 37, "texto": "Et tous fondirent en larmes, et, se jetant au cou de Paul, ils l''''embrassaient,"}, {"numero": 38, "texto": "affligés surtout de ce qu''''il avait dit qu''''ils ne verraient plus son visage. Et ils l''''accompagnèrent jusqu''''au navire."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 20, 'es', '[{"numero": 1, "texto": "Y DESPUÉS que cesó el alboroto, llamando Pablo á los discípulos habiéndoles exhortado y abrazado, se despidió, y partió para ir á Macedonia."}, {"numero": 2, "texto": "Y andado que hubo aquellas partes, y exhortádoles con abundancia de palabra, vino á Grecia."}, {"numero": 3, "texto": "Y después de haber estado allí tres meses, y habiendo de navegar á Siria, le fueron puestas asechanzas por los Judíos; y así tomó consejo de volverse por Macedonia."}, {"numero": 4, "texto": "Y le acompañaron hasta Asia Sopater Bereense, y los Tesalonicenses, Aristarco y Segundo; y Gayo de Derbe, y Timoteo; y de Asia, Tychîco y Trófimo."}, {"numero": 5, "texto": "Estos yendo delante, nos esperaron en Troas."}, {"numero": 6, "texto": "Y nosotros, pasados los días de los panes sin levadura, navegamos de Filipos y vinimos á ellos á Troas en cinco días, donde estuvimos siete días."}, {"numero": 7, "texto": "Y el día primero de la semana, juntos los discípulos á partir el pan, Pablo les enseñaba, habiendo de partir al día siguiente: y alargó el discurso hasta la media noche."}, {"numero": 8, "texto": "Y había muchas lámparas en el aposento alto donde estaban juntos."}, {"numero": 9, "texto": "Y un mancebo llamado Eutichô que estaba sentado en la ventana, tomado de un sueño profundo, como Pablo disputaba largamente, postrado del sueño cayó del tercer piso abajo, y fué alzado muerto."}, {"numero": 10, "texto": "Entonces descendió Pablo, y derribóse sobre él, y abrazándole, dijo: No os alborotéis, que su alma está en él."}, {"numero": 11, "texto": "Después subiendo, y partiendo el pan, y gustando, habló largamente hasta el alba, y así partió."}, {"numero": 12, "texto": "Y llevaron al mozo vivo, y fueron consolados no poco."}, {"numero": 13, "texto": "Y nosotros subiendo en el navío, navegamos á Assón, para recibir de allí á Pablo; pues así había determinado que debía él ir por tierra."}, {"numero": 14, "texto": "Y como se juntó con nosotros en Assón, tomándole vinimos á Mitilene."}, {"numero": 15, "texto": "Y navegando de allí, al día siguiente llegamos delante de Chîo, y al otro día tomamos puerto en Samo: y habiendo reposado en Trogilio, al día siguiente llegamos á Mileto."}, {"numero": 16, "texto": "Porque Pablo se había propuesto pasar adelante de Efeso; por no detenerse en Asia: porque se apresuraba por hacer el día de Pentecostés, si le fuese posible, en Jerusalem."}, {"numero": 17, "texto": "Y enviando desde Mileto á Efeso, hizo llamar á los ancianos de la iglesia."}, {"numero": 18, "texto": "Y cuando vinieron á él, les dijo: Vosotros sabéis cómo, desde el primer día que entré en Asia, he estado con vosotros por todo el tiempo,"}, {"numero": 19, "texto": "Sirviendo al Señor con toda humildad, y con muchas lágrimas, y tentaciones que me han venido por las asechanzas de los Judíos:"}, {"numero": 20, "texto": "Cómo nada que fuese útil he rehuído de anunciaros y enseñaros, públicamente y por las casas,"}, {"numero": 21, "texto": "Testificando á los Judíos y á los Gentiles arrepentimiento para con Dios, y la fe en nuestro Señor Jesucristo."}, {"numero": 22, "texto": "Y ahora, he aquí, ligado yo en espíritu, voy á Jerusalem, sin saber lo que allá me ha de acontecer:"}, {"numero": 23, "texto": "Mas que el Espíritu Santo por todas las ciudades me da testimonio, diciendo que prisiones y tribulaciones me esperan."}, {"numero": 24, "texto": "Mas de ninguna cosa hago caso, ni estimo mi vida preciosa para mí mismo; solamente que acabe mi carrera con gozo, y el ministerio que recibí del Señor Jesús, para dar testimonio del evangelio de la gracia de Dios."}, {"numero": 25, "texto": "Y ahora, he aquí, yo sé que ninguno de todos vosotros, por quien he pasado predicando el reino de Dios, verá más mi rostro."}, {"numero": 26, "texto": "Por tanto, yo os protesto el día de hoy, que yo soy limpio de la sangre de todos:"}, {"numero": 27, "texto": "Porque no he rehuído de anunciaros todo el consejo de Dios."}, {"numero": 28, "texto": "Por tanto mirad por vosotros, y por todo el rebaño en que el Espíritu Santo os ha puesto por obispos, para apacentar la iglesia del Señor, la cual ganó por su sangre."}, {"numero": 29, "texto": "Porque yo sé que después de mi partida entrarán en medio de vosotros lobos rapaces, que no perdonarán al ganado;"}, {"numero": 30, "texto": "Y de vosotros mismos se levantarán hombres que hablen cosas perversas, para llevar discípulos tras sí."}, {"numero": 31, "texto": "Por tanto, velad, acordándoos que por tres años de noche y de día, no he cesado de amonestar con lágrimas á cada uno."}, {"numero": 32, "texto": "Y ahora, hermanos, os encomiendo á Dios, y á la palabra de su gracia: el cual es poderoso para sobreedificar, y daros heredad con todos los santificados."}, {"numero": 33, "texto": "La plata, ó el oro, ó el vestido de nadie he codiciado."}, {"numero": 34, "texto": "Antes vosotros sabéis que para lo que me ha sido necesario, y á los que están conmigo, estas manos me han servido."}, {"numero": 35, "texto": "En todo os he enseñado que, trabajando así, es necesario sobrellevar á los enfermos, y tener presente las palabras del Señor Jesús, el cual dijo: Más bienaventurada cosa es dar que recibir."}, {"numero": 36, "texto": "Y como hubo dicho estas cosas, se puso de rodillas, y oró con todos ellos."}, {"numero": 37, "texto": "Entonces hubo un gran lloro de todos: y echándose en el cuello de Pablo, le besaban,"}, {"numero": 38, "texto": "Doliéndose en gran manera por la palabra que dijo, que no habían de ver más su rostro. Y le acompañaron al navío."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 21, 'pt', '[{"numero": 1, "texto": "E quando aconteceu de termos saído deles, e navegado, percorremos diretamente, e viemos a Cós, e [n] o [dia] seguinte a Rodes, e dali a Pátara."}, {"numero": 2, "texto": "E tendo achado um navio que passava para a Fenícia, nós embarcamos nele, e partimos."}, {"numero": 3, "texto": "E tendo Chipre à vista, e deixando-a à esquerda, navegamos para a Síria, e viemos a Tiro; porque o navio tinha de deixar ali sua carga."}, {"numero": 4, "texto": "E nós ficamos ali por sete dias; e achamos aos discípulos, os quais diziam pelo Espírito a Paulo, que não subisse a Jerusalém."}, {"numero": 5, "texto": "E tendo passado [ali] aqueles dias, nós saímos e seguimos nosso caminho, acompanhando-nos todos com [suas] mulheres e filhos até fora da cidade; e postos de joelhos na praia, oramos."}, {"numero": 6, "texto": "E saudando-nos uns aos outros, subimos ao navio; e eles voltaram para as [casas] deles."}, {"numero": 7, "texto": "E nós, acabada a navegação de Tiro, chegamos a Ptolemaida; e tendo saudado aos irmãos, ficamos com eles por um dia."}, {"numero": 8, "texto": "E [n] o [dia] seguinte, Paulo e nós que estávamos com ele, saindo dali, viemos a Cesareia; e entrando na casa de Filipe, o evangelista (que era [um] dos sete), nós ficamos com ele."}, {"numero": 9, "texto": "E este tinha quatro filhas, que profetizavam."}, {"numero": 10, "texto": "E ficando nós [ali] por muitos dias, desceu da Judeia um profeta, de nome Ágabo;"}, {"numero": 11, "texto": "E ele, tendo vindo a nós, e tomando a cinta de Paulo, e atando-se os pés e as mãos, disse: Isto diz o Espírito Santo: Assim os judeus em Jerusalém atarão ao homem a quem [pertence] esta cinta, e o entregarão nas mãos dos gentios."}, {"numero": 12, "texto": "E nós, tendo ouvido isto, rogamos a ele, tanto nós como os que eram daquele lugar, que ele não subisse a Jerusalém."}, {"numero": 13, "texto": "Mas Paulo respondeu: O que vós estais fazendo, ao chorarem e afligirem o meu coração? Porque eu estou pronto, não somente para ser atado, mas até mesmo para morrer em Jerusalém, pelo nome do Senhor Jesus."}, {"numero": 14, "texto": "E como ele não deixou ser persuadido, nós nos aquietamos, dizendo: Faça-se a vontade do Senhor."}, {"numero": 15, "texto": "E depois daqueles dias, nós nos arrumamos, e subimos a Jerusalém."}, {"numero": 16, "texto": "E foram também conosco [alguns] dos discípulos de Cesareia, trazendo [consigo] a um certo Mnáson, cipriota, discípulo antigo, com o qual íamos nos hospedar."}, {"numero": 17, "texto": "E quando chegamos a Jerusalém, os irmãos nos receberam com muito boa vontade."}, {"numero": 18, "texto": "E [n] o [dia] seguinte, Paulo entrou conosco a [casa de] Tiago, e todos os anciãos vieram ali."}, {"numero": 19, "texto": "E tendo os saudado, ele [lhes] contou em detalhes o que Deus tinha feito entre os gentios por meio do trabalho dele."}, {"numero": 20, "texto": "E eles, ao ouvirem, glorificaram ao Senhor, e lhe disseram: Tu vês, irmão, quantos milhares de judeus há que creem, e todos são zelosos da lei."}, {"numero": 21, "texto": "E foram informados quanto a ti, que a todos os judeus, que estão entre os gentios, [que] tu ensinas a se afastarem de Moisés, dizendo que não devem circuncidar [seus] filhos, nem andar segundo os costumes."}, {"numero": 22, "texto": "Então o que se fará? Em todo caso a multidão deve se ajuntar, porque ouvirão que tu [já] chegaste."}, {"numero": 23, "texto": "Portanto faça isto que te dizemos: temos quatro homens que fizeram voto."}, {"numero": 24, "texto": "Toma contigo a estes, e purifica-te com eles, e paga os gastos deles, para que rapem a cabeça, e todos saibam que não há nada do que foram informados sobre ti, mas sim, [que] tu mesmo andas guardando a Lei."}, {"numero": 25, "texto": "E quanto aos que creem dentre os gentios, nós já escrevemos, julgando que nada disto guardassem, a não ser somente que se abstenham do que se abstenham das coisas sacrificadas aos ídolos, e do sangue, e da [carne] sufocada, e do pecado sexual."}, {"numero": 26, "texto": "Então Paulo, tendo tomado consigo a aqueles homens, e purificando-se com eles no dia seguinte, entrou no Templo, anunciando que [já] estavam cumpridos dos dias da purificação, quando fosse oferecida por eles, cada um [sua] oferta."}, {"numero": 27, "texto": "E tendo os sete dias quase quase completados, os judeus da Ásia, vendo-o, tumultuaram a todo o povo, e lançaram as mãos sobre ele [para o deterem] ,"}, {"numero": 28, "texto": "Clamando: Homens israelitas, ajudai [-nos] ; este é o homem que por todos os lugares ensina a todos contra o [nosso] povo, e contra a Lei, e [contra] este lugar; e além disto, ele também pôs gregos dentro do Templo, e contaminou este santo lugar!"}, {"numero": 29, "texto": "(Porque antes eles tinham visto na cidade a Trófimo junto dele, ao qual pensavam que Paulo tinha trazido para dentro do Templo)."}, {"numero": 30, "texto": "E toda a cidade se tumultuou, e houve um ajuntamento do povo; e tendo detido a Paulo, trouxeram-no para fora do Templo; e logo as portas foram fechadas."}, {"numero": 31, "texto": "E eles, procurando matá-lo, a notícia chegou ao comandante e aos soldados, de que toda Jerusalém estava em confusão."}, {"numero": 32, "texto": "O qual, tendo tomado logo consigo soldados e centuriões, correu até eles. E eles, vendo ao comandante e aos soldados, pararam de ferir a Paulo."}, {"numero": 33, "texto": "Então o comandante, tendo se aproximado, prendeu-o, e mandou que ele fosse atado em duas correntes; e perguntou quem ele era, e o que ele tinha feito."}, {"numero": 34, "texto": "E na multidão clamavam [uns de uma maneira] ,e outros de outra maneira; mas [como] ele não podia saber com certeza por causa do tumulto, ele mandou que o levassem para a área fortificada."}, {"numero": 35, "texto": "E ele, tendo chegado às escadas, aconteceu que ele foi carregado pelos soldados, por causa da violência da multidão."}, {"numero": 36, "texto": "Porque a multidão do povo [o] seguia, gritando: Tragam-no para fora!"}, {"numero": 37, "texto": "E Paulo, estando perto de entrar na área fortificada, disse ao comandante: É permitido a mim te falar alguma coisa?E ele disse: Tu sabes grego?"}, {"numero": 38, "texto": "Por acaso não és tu aquele egípcio, que antes destes dias tinha levantando uma rebelião, e levou ao deserto quatro mil homens assassinos?"}, {"numero": 39, "texto": "Mas Paulo lhe disse: Na verdade eu sou um homem judeu de Tarso, cidade não pouca importância da Cilícia; mas eu te rogo para que tu me permitas falar ao povo."}, {"numero": 40, "texto": "E tendo [lhe] permitido, Paulo pôs-se de pé nas escadas, acenou com a mão ao povo; e tendo havido grande silêncio, falou [-lhes] em língua hebraica, dizendo:"}]'::jsonb, 'Almeida Livre'),
  ('At', 21, 'en', '[{"numero": 1, "texto": "And it came to pass, that after we were gotten from them, and had launched, we came with a straight course unto Coos, and the day following unto Rhodes, and from thence unto Patara:"}, {"numero": 2, "texto": "And finding a ship sailing over unto Phenicia, we went aboard, and set forth."}, {"numero": 3, "texto": "Now when we had discovered Cyprus, we left it on the left hand, and sailed into Syria, and landed at Tyre: for there the ship was to unlade her burden."}, {"numero": 4, "texto": "And finding disciples, we tarried there seven days: who said to Paul through the Spirit, that he should not go up to Jerusalem."}, {"numero": 5, "texto": "And when we had accomplished those days, we departed and went our way; and they all brought us on our way, with wives and children, till we were out of the city: and we kneeled down on the shore, and prayed."}, {"numero": 6, "texto": "And when we had taken our leave one of another, we took ship; and they returned home again."}, {"numero": 7, "texto": "And when we had finished our course from Tyre, we came to Ptolemais, and saluted the brethren, and abode with them one day."}, {"numero": 8, "texto": "And the next day we that were of Paul''s company departed, and came unto Caesarea: and we entered into the house of Philip the evangelist, which was one of the seven; and abode with him."}, {"numero": 9, "texto": "And the same man had four daughters, virgins, which did prophesy."}, {"numero": 10, "texto": "And as we tarried there many days, there came down from Judaea a certain prophet, named Agabus."}, {"numero": 11, "texto": "And when he was come unto us, he took Paul''s girdle, and bound his own hands and feet, and said, Thus saith the Holy Ghost, So shall the Jews at Jerusalem bind the man that owneth this girdle, and shall deliver him into the hands of the Gentiles."}, {"numero": 12, "texto": "And when we heard these things, both we, and they of that place, besought him not to go up to Jerusalem."}, {"numero": 13, "texto": "Then Paul answered, What mean ye to weep and to break mine heart? for I am ready not to be bound only, but also to die at Jerusalem for the name of the Lord Jesus."}, {"numero": 14, "texto": "And when he would not be persuaded, we ceased, saying, The will of the Lord be done."}, {"numero": 15, "texto": "And after those days we took up our carriages, and went up to Jerusalem."}, {"numero": 16, "texto": "There went with us also certain of the disciples of Caesarea, and brought with them one Mnason of Cyprus, an old disciple, with whom we should lodge."}, {"numero": 17, "texto": "And when we were come to Jerusalem, the brethren received us gladly."}, {"numero": 18, "texto": "And the day following Paul went in with us unto James; and all the elders were present."}, {"numero": 19, "texto": "And when he had saluted them, he declared particularly what things God had wrought among the Gentiles by his ministry."}, {"numero": 20, "texto": "And when they heard it, they glorified the Lord, and said unto him, Thou seest, brother, how many thousands of Jews there are which believe; and they are all zealous of the law:"}, {"numero": 21, "texto": "And they are informed of thee, that thou teachest all the Jews which are among the Gentiles to forsake Moses, saying that they ought not to circumcise their children, neither to walk after the customs."}, {"numero": 22, "texto": "What is it therefore? the multitude must needs come together: for they will hear that thou art come."}, {"numero": 23, "texto": "Do therefore this that we say to thee: We have four men which have a vow on them;"}, {"numero": 24, "texto": "Them take, and purify thyself with them, and be at charges with them, that they may shave their heads: and all may know that those things, whereof they were informed concerning thee, are nothing; but that thou thyself also walkest orderly, and keepest the law."}, {"numero": 25, "texto": "As touching the Gentiles which believe, we have written and concluded that they observe no such thing, save only that they keep themselves from things offered to idols, and from blood, and from strangled, and from fornication."}, {"numero": 26, "texto": "Then Paul took the men, and the next day purifying himself with them entered into the temple, to signify the accomplishment of the days of purification, until that an offering should be offered for every one of them."}, {"numero": 27, "texto": "And when the seven days were almost ended, the Jews which were of Asia, when they saw him in the temple, stirred up all the people, and laid hands on him,"}, {"numero": 28, "texto": "Crying out, Men of Israel, help: This is the man, that teacheth all men every where against the people, and the law, and this place: and further brought Greeks also into the temple, and hath polluted this holy place."}, {"numero": 29, "texto": "(For they had seen before with him in the city Trophimus an Ephesian, whom they supposed that Paul had brought into the temple.)"}, {"numero": 30, "texto": "And all the city was moved, and the people ran together: and they took Paul, and drew him out of the temple: and forthwith the doors were shut."}, {"numero": 31, "texto": "And as they went about to kill him, tidings came unto the chief captain of the band, that all Jerusalem was in an uproar."}, {"numero": 32, "texto": "Who immediately took soldiers and centurions, and ran down unto them: and when they saw the chief captain and the soldiers, they left beating of Paul."}, {"numero": 33, "texto": "Then the chief captain came near, and took him, and commanded him to be bound with two chains; and demanded who he was, and what he had done."}, {"numero": 34, "texto": "And some cried one thing, some another, among the multitude: and when he could not know the certainty for the tumult, he commanded him to be carried into the castle."}, {"numero": 35, "texto": "And when he came upon the stairs, so it was, that he was borne of the soldiers for the violence of the people."}, {"numero": 36, "texto": "For the multitude of the people followed after, crying, Away with him."}, {"numero": 37, "texto": "And as Paul was to be led into the castle, he said unto the chief captain, May I speak unto thee? Who said, Canst thou speak Greek?"}, {"numero": 38, "texto": "Art not thou that Egyptian, which before these days madest an uproar, and leddest out into the wilderness four thousand men that were murderers?"}, {"numero": 39, "texto": "But Paul said, I am a man which am a Jew of Tarsus, a city in Cilicia, a citizen of no mean city: and, I beseech thee, suffer me to speak unto the people."}, {"numero": 40, "texto": "And when he had given him licence, Paul stood on the stairs, and beckoned with the hand unto the people. And when there was made a great silence, he spake unto them in the Hebrew tongue, saying,"}]'::jsonb, 'King James Version'),
  ('At', 21, 'fr', '[{"numero": 1, "texto": "Nous nous embarquâmes, après nous être séparés d''''eux, et nous allâmes directement à Cos, le lendemain à Rhodes, et de là à Patara."}, {"numero": 2, "texto": "Et ayant trouvé un navire qui faisait la traversée vers la Phénicie, nous montâmes et partîmes."}, {"numero": 3, "texto": "Quand nous fûmes en vue de l''''île de Chypre, nous la laissâmes à gauche, poursuivant notre route du côté de la Syrie, et nous abordâmes à Tyr, où le bâtiment devait décharger sa cargaison."}, {"numero": 4, "texto": "Nous trouvâmes les disciples, et nous restâmes là sept jours. Les disciples, poussés par l''''Esprit, disaient à Paul de ne pas monter à Jérusalem."}, {"numero": 5, "texto": "Mais, lorsque nous fûmes au terme des sept jours, nous nous acheminâmes pour partir, et tous nous accompagnèrent avec leurs femmes et leurs enfants jusque hors de la ville. Nous nous mîmes à genoux sur le rivage, et nous priâmes."}, {"numero": 6, "texto": "Puis, ayant pris congé les uns des autres, nous montâmes sur le navire, et ils retournèrent chez eux."}, {"numero": 7, "texto": "Achevant notre navigation, nous allâmes de Tyr à Ptolémaïs, où nous saluâmes les frères, et passâmes un jour avec eux."}, {"numero": 8, "texto": "Nous partîmes le lendemain, et nous arrivâmes à Césarée. Etant entrés dans la maison de Philippe l''''évangéliste, qui était l''''un des sept, nous logeâmes chez lui."}, {"numero": 9, "texto": "Il avait quatre filles vierges qui prophétisaient."}, {"numero": 10, "texto": "Comme nous étions là depuis plusieurs jours, un prophète, nommé Agabus, descendit de Judée,"}, {"numero": 11, "texto": "et vint nous trouver. Il prit la ceinture de Paul, se lia les pieds et les mains, et dit: Voici ce que déclare le Saint-Esprit: L''''homme à qui appartient cette ceinture, les Juifs le lieront de la même manière à Jérusalem, et le livreront entre les mains des païens."}, {"numero": 12, "texto": "Quand nous entendîmes cela, nous et ceux de l''''endroit, nous priâmes Paul de ne pas monter à Jérusalem."}, {"numero": 13, "texto": "Alors il répondit: Que faites-vous, en pleurant et en me brisant le coeur? Je suis prêt, non seulement à être lié, mais encore à mourir à Jérusalem pour le nom du Seigneur Jésus."}, {"numero": 14, "texto": "Comme il ne se laissait pas persuader, nous n''''insistâmes pas, et nous dîmes: Que la volonté du Seigneur se fasse!"}, {"numero": 15, "texto": "Après ces jours-là, nous fîmes nos préparatifs, et nous montâmes à Jérusalem."}, {"numero": 16, "texto": "Quelques disciples de Césarée vinrent aussi avec nous, et nous conduisirent chez un nommé Mnason, de l''''île de Chypre, ancien disciple, chez qui nous devions loger."}, {"numero": 17, "texto": "Lorsque nous arrivâmes à Jérusalem, les frères nous reçurent avec joie."}, {"numero": 18, "texto": "Le lendemain, Paul se rendit avec nous chez Jacques, et tous les anciens s''''y réunirent."}, {"numero": 19, "texto": "Après les avoir salués, il raconta en détail ce que Dieu avait fait au milieu des païens par son ministère."}, {"numero": 20, "texto": "Quand ils l''''eurent entendu, ils glorifièrent Dieu. Puis ils lui dirent: Tu vois, frère, combien de milliers de Juifs ont cru, et tous sont zélés pour la loi."}, {"numero": 21, "texto": "Or, ils ont appris que tu enseignes à tous les Juifs qui sont parmi les païens à renoncer à Moïse, leur disant de ne pas circoncire les enfants et de ne pas se conformer aux coutumes."}, {"numero": 22, "texto": "Que faire donc? Sans aucun doute la multitude se rassemblera, car on saura que tu es venu."}, {"numero": 23, "texto": "C''''est pourquoi fais ce que nous allons te dire. Il y a parmi nous quatre hommes qui ont fait un voeu;"}, {"numero": 24, "texto": "prends-les avec toi, purifie-toi avec eux, et pourvois à leur dépense, afin qu''''ils se rasent la tête. Et ainsi tous sauront que ce qu''''ils ont entendu dire sur ton compte est faux, mais que toi aussi tu te conduis en observateur de la loi."}, {"numero": 25, "texto": "A l''''égard des païens qui ont cru, nous avons décidé et nous leur avons écrit qu''''ils eussent à s''''abstenir des viandes sacrifiées aux idoles, du sang, des animaux étouffés, et de l''''impudicité."}, {"numero": 26, "texto": "Alors Paul prit ces hommes, se purifia, et entra le lendemain dans le temple avec eux, pour annoncer à quel jour la purification serait accomplie et l''''offrande présentée pour chacun d''''eux."}, {"numero": 27, "texto": "Sur la fin des sept jours, les Juifs d''''Asie, ayant vu Paul dans le temple, soulevèrent toute la foule, et mirent la main sur lui,"}, {"numero": 28, "texto": "en criant: Hommes Israélites, au secours! Voici l''''homme qui prêche partout et à tout le monde contre le peuple, contre la loi et contre ce lieu; il a même introduit des Grecs dans le temple, et a profané ce saint lieu."}, {"numero": 29, "texto": "Car ils avaient vu auparavant Trophime d''''Ephèse avec lui dans la ville, et ils croyaient que Paul l''''avait fait entrer dans le temple."}, {"numero": 30, "texto": "Toute la ville fut émue, et le peuple accourut de toutes parts. Ils se saisirent de Paul, et le traînèrent hors du temple, dont les portes furent aussitôt fermées."}, {"numero": 31, "texto": "Comme ils cherchaient à le tuer, le bruit vint au tribun de la cohorte que tout Jérusalem était en confusion."}, {"numero": 32, "texto": "A l''''instant il prit des soldats et des centeniers, et courut à eux. Voyant le tribun et les soldats, ils cessèrent de frapper Paul."}, {"numero": 33, "texto": "Alors le tribun s''''approcha, se saisit de lui, et le fit lier de deux chaînes. Puis il demanda qui il était, et ce qu''''il avait fait."}, {"numero": 34, "texto": "Mais dans la foule les uns criaient d''''une manière, les autres d''''une autre; ne pouvant donc rien apprendre de certain, à cause du tumulte, il ordonna de le mener dans la forteresse."}, {"numero": 35, "texto": "Lorsque Paul fut sur les degrés, il dut être porté par les soldats, à cause de la violence de la foule;"}, {"numero": 36, "texto": "car la multitude du peuple suivait, en criant: Fais-le mourir!"}, {"numero": 37, "texto": "Au moment d''''être introduit dans la forteresse, Paul dit au tribun: M''''est-il permis de te dire quelque chose? Le tribun répondit: Tu sais le grec?"}, {"numero": 38, "texto": "Tu n''''es donc pas cet Egyptien qui s''''est révolté dernièrement, et qui a emmené dans le désert quatre mille brigands?"}, {"numero": 39, "texto": "Je suis Juif, reprit Paul, de Tarse en Cilicie, citoyen d''''une ville qui n''''est pas sans importance. Permets-moi, je te prie, de parler au peuple."}, {"numero": 40, "texto": "Le tribun le lui ayant permis, Paul, debout sur les degrés, fit signe de la main au peuple. Un profond silence s''''établit, et Paul, parlant en langue hébraïque, dit:"}]'::jsonb, 'Louis Segond 1910'),
  ('At', 21, 'es', '[{"numero": 1, "texto": "Y HABIENDO partido de ellos, navegamos y vinimos camino derecho á Coos, y al día siguiente á Rhodas, y de allí á Pátara."}, {"numero": 2, "texto": "Y hallando un barco que pasaba á Fenicia, nos embarcamos, y partimos."}, {"numero": 3, "texto": "Y como avistamos á Cipro, dejándola á mano izquierda, navegamos á Siria, y vinimos á Tiro: porque el barco había de descargar allí su carga."}, {"numero": 4, "texto": "Y nos quedamos allí siete días, hallados los discípulos, los cuales decían á Pablo por Espíritu, que no subiese á Jerusalem."}, {"numero": 5, "texto": "Y cumplidos aquellos días, salimos acompañándonos todos, con sus mujeres é hijos, hasta fuera de la ciudad; y puestos de rodillas en la ribera, oramos."}, {"numero": 6, "texto": "Y abrazándonos los unos á los otros, subimos al barco, y ellos se volvieron á sus casas."}, {"numero": 7, "texto": "Y nosotros, cumplida la navegación, vinimos de Tiro á Tolemaida; y habiendo saludado á los hermanos, nos quedamos con ellos un día."}, {"numero": 8, "texto": "Y otro día, partidos Pablo y los que con él estábamos, vinimos á Cesarea: y entrando en casa de Felipe el evangelista, el cual era uno de los siete, posamos con él."}, {"numero": 9, "texto": "Y éste tenía cuatro hijas, doncellas, que profetizaban."}, {"numero": 10, "texto": "Y parando nosotros allí por muchos días, descendió de Judea un profeta, llamado Agabo;"}, {"numero": 11, "texto": "Y venido á nosotros, tomó el cinto de Pablo, y atándose los pies y las manos, dijo: Esto dice el Espíritu Santo: Así atarán los Judíos en Jerusalem al varón cuyo es este cinto, y le entregarán en manos de los Gentiles."}, {"numero": 12, "texto": "Lo cual como oímos, le rogamos nosotros y los de aquel lugar, que no subiese á Jerusalem."}, {"numero": 13, "texto": "Entonces Pablo respondió: ¿Qué hacéis llorando y afligiéndome el corazón? porque yo no sólo estoy presto á ser atado, mas aun á morir en Jerusalem por el nombre del Señor Jesús."}, {"numero": 14, "texto": "Y como no le pudimos persuadir, desistimos, diciendo: Hágase la voluntad del Señor."}, {"numero": 15, "texto": "Y después de estos días, apercibidos, subimos á Jerusalem."}, {"numero": 16, "texto": "Y vinieron también con nosotros de Cesarea algunos de los discípulos, trayendo consigo á un Mnasón, Cyprio, discípulo antiguo, con el cual posásemos."}, {"numero": 17, "texto": "Y cuando llegamos á Jerusalem, los hermanos nos recibieron de buena voluntad."}, {"numero": 18, "texto": "Y al día siguiente Pablo entró con nosotros á Jacobo, y todos los ancianos se juntaron;"}, {"numero": 19, "texto": "A los cuales, como los hubo saludado, contó por menudo lo que Dios había hecho entre los Gentiles por su ministerio."}, {"numero": 20, "texto": "Y ellos como lo oyeron, glorificaron á Dios, y le dijeron: Ya ves, hermano, cuántos millares de Judíos hay que han creído; y todos son celadores de la ley:"}, {"numero": 21, "texto": "Mas fueron informados acerca de ti, que enseñas á apartarse de Moisés á todos los Judíos que están entre los Gentiles, diciéndoles que no han de circuncidar á los hijos, ni andar según la costumbre."}, {"numero": 22, "texto": "¿Qué hay pues? La multitud se reunirá de cierto: porque oirán que has venido."}, {"numero": 23, "texto": "Haz pues esto que te decimos: Hay entre nosotros cuatro hombres que tienen voto sobre sí:"}, {"numero": 24, "texto": "Tomando á éstos contigo, purifícate con ellos, y gasta con ellos, para que rasuren sus cabezas, y todos entiendan que no hay nada de lo que fueron informados acerca de ti; sino que tú también andas guardando la ley."}, {"numero": 25, "texto": "Empero cuanto á los que de los Gentiles han creído, nosotros hemos escrito haberse acordado que no guarden nada de esto; solamente que se abstengan de lo que fuere sacrificado á los ídolos, y de sangre, y de ahogado, y de fornicación."}, {"numero": 26, "texto": "Entonces Pablo tomó consigo aquellos hombres, y al día siguiente, habiéndose purificado con ellos, entró en el templo, para anunciar el cumplimiento de los días de la purificación, hasta ser ofrecida ofrenda por cada uno de ellos."}, {"numero": 27, "texto": "Y cuando estaban para acabarse los siete días, unos Judíos de Asia, como le vieron en el templo, alborotaron todo el pueblo y le echaron mano,"}, {"numero": 28, "texto": "Dando voces: Varones Israelitas, ayudad: Este es el hombre que por todas partes enseña á todos contra el pueblo, y la ley, y este lugar; y además de esto ha metido Gentiles en el templo, y ha contaminado este lugar santo."}, {"numero": 29, "texto": "Porque antes habían visto con él en la ciudad á Trófimo, Efesio, al cual pensaban que Pablo había metido en el templo."}, {"numero": 30, "texto": "Así que, toda la ciudad se alborotó, y agolpóse el pueblo; y tomando á Pablo, hiciéronle salir fuera del templo, y luego las puertas fueron cerradas."}, {"numero": 31, "texto": "Y procurando ellos matarle, fué dado aviso al tribuno de la compañía, que toda la ciudad de Jerusalem estaba alborotada;"}, {"numero": 32, "texto": "El cual tomando luego soldados y centuriones, corrió á ellos. Y ellos como vieron al tribuno y á los soldados, cesaron de herir á Pablo."}, {"numero": 33, "texto": "Entonces llegando el tribuno, le prendió, y le mandó atar con dos cadenas; y preguntó quién era, y qué había hecho."}, {"numero": 34, "texto": "Y entre la multitud, unos gritaban una cosa, y otros otra: y como no podía entender nada de cierto á causa del alboroto, le mandó llevar á la fortaleza."}, {"numero": 35, "texto": "Y como llegó á las gradas, aconteció que fué llevado de los soldados á causa de la violencia del pueblo;"}, {"numero": 36, "texto": "Porque multitud de pueblo venía detrás, gritando: Mátale."}, {"numero": 37, "texto": "Y como comenzaron á meter á Pablo en la fortaleza, dice al tribuno: ¿Me será lícito hablarte algo? Y él dijo: ¿Sabes griego?"}, {"numero": 38, "texto": "¿No eres tú aquel Egipcio que levantaste una sedición antes de estos días, y sacaste al desierto cuatro mil hombres salteadores?"}, {"numero": 39, "texto": "Entonces dijo Pablo: Yo de cierto soy hombre Judío, ciudadano de Tarso, ciudad no obscura de Cilicia: empero ruégote que me permitas que hable al pueblo."}, {"numero": 40, "texto": "Y como él se lo permitió, Pablo, estando en pie en las gradas, hizo señal con la mano al pueblo. Y hecho grande silencio, habló en lengua hebrea, diciendo:"}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 22, 'pt', '[{"numero": 1, "texto": "Homens irmãos, e pais, ouvi agora minha defesa para convosco."}, {"numero": 2, "texto": "E tendo ouvido que ele lhes falava em língua hebraica, fizeram ainda mais silêncio. E ele disse:"}, {"numero": 3, "texto": "Eu verdadeiramente sou um homem judeu, nascido em Tarso da Cilícia, e criado nesta cidade aos pés de Gamaliel, ensinado ao mais correto modo da Lei paterna [e] zeloso de Deus, assim como todos vós sois hoje."}, {"numero": 4, "texto": "[Eu] ,que persegui este caminho até a morte, atando tanto a homens como a mulheres, e [os] entregando a prisões."}, {"numero": 5, "texto": "Assim como também o sumo sacerdote me é testemunha, e todo o conselho dos anciãos; dos quais eu, tendo tomado cartas para os irmãos, fui a Damasco para que os que estivessem ali, eu também os trouxesse amarrados a Jerusalém, para que fossem castigados."}, {"numero": 6, "texto": "Mas aconteceu que, estando eu no caminho, e chegando perto de Damasco, quase ao meio dia, de repente uma grande luz do céu brilhou ao redor de mim."}, {"numero": 7, "texto": "Eu cai ao chão, e ouvi uma voz, que me dizia: Saulo, Saulo, por que me persegues?"}, {"numero": 8, "texto": "E eu respondi: Quem és, Senhor? E ele me disse: Eu sou Jesus, o nazareno, a quem tu persegues."}, {"numero": 9, "texto": "E os que estavam comigo verdadeiramente viram a luz, e ficaram muito atemorizados; mas eles não ouviram a voz daquele que falava comigo."}, {"numero": 10, "texto": "E eu disse: Que farei, Senhor? E o Senhor me disse: Levanta-te, e vai a Damasco, e ali te será dito tudo o que te é ordenado fazer."}, {"numero": 11, "texto": "E quando eu não [conseguia] ver, por causa da glória daquela luz, eu fui levado pela mão dos que estavam comigo, e [assim] cheguei a Damasco."}, {"numero": 12, "texto": "E um certo Ananias, homem devoto conforme a Lei, que tinha [bom] testemunho de todos os judeus que moravam [ali] ;"}, {"numero": 13, "texto": "Tendo vindo até mim, e ficando [diante de mim] ,ele me disse: Irmão Saulo, recupere a vista; E naquela mesma hora eu [pude] vê-lo."}, {"numero": 14, "texto": "E ele disse: O Deus de nossos pais te predeterminou para que tu conheças a vontade dele, e vejas aquele justo, e tu ouças a voz de sua boca."}, {"numero": 15, "texto": "Porque tu serás testemunha dele para com todos as pessoas, daquilo que tens visto e ouvido."}, {"numero": 16, "texto": "E agora, por que estás parado? Levanta-te, e sê batizado, e lava teus pecados, invocando o nome do Senhor."}, {"numero": 17, "texto": "E aconteceu a mim, tendo eu voltado a Jerusalém, e estando orando no Templo, veio-me um êxtase;"}, {"numero": 18, "texto": "E eu vi aquele que me dizia: Apressa-te, e sai logo de Jerusalém, porque não aceitarão teu testemunho sobre mim."}, {"numero": 19, "texto": "E eu disse: Senhor, eles sabem que eu prendia e açoitava nas sinagogas aqueles que criam em ti."}, {"numero": 20, "texto": "E quando o sangue de Estêvão, tua testemunha, se derramava, eu também estava presente, e consentia em sua morte, e guardava as roupas daqueles que o matavam."}, {"numero": 21, "texto": "E ele me disse: Vai, porque eu te enviarei para longe, aos gentios."}, {"numero": 22, "texto": "E eles o ouviram até esta palavra, e [em seguida] levantaram suas vozes, dizendo: Extermina-o da terra! Porque não é bom que ele viva."}, {"numero": 23, "texto": "E enquanto eles gritavam, tiravam [suas] capas, e lançavm pó ao ar,"}, {"numero": 24, "texto": "O comandante mandou que o levassem à área fortificada, dizendo que o interrogassem com açoites, para saber por que causa clamavam assim contra ele."}, {"numero": 25, "texto": "E quando estavam o atando com correias, Paulo disse ao centurião que estava ali: É lícito para vós açoitar a um homem romano, sem [ter sido] condenado?"}, {"numero": 26, "texto": "E o centurião, tendo ouvido [isto] ,foi e avisou ao comandante, dizendo: Olha o que estás a ponto de fazer, porque este homem é romano."}, {"numero": 27, "texto": "E o comandante, tendo se aproximado, disse-lhe: Dize-me, tu és romano?E ele disse: Sim."}, {"numero": 28, "texto": "E o comandante respondeu: Eu com muita soma [de dinheiro] obtive esta cidadania [romana] .E Paulo disse: E eu [a tenho] desde que nasci."}, {"numero": 29, "texto": "Então logo se afastaram dele aqueles que estavam para interrogá-lo; e até o comandante teve temor, ao entender que [Paulo] era romano, e que tinha o atado."}, {"numero": 30, "texto": "E no[dia] seguinte, querendo saber corretamente a causa de por que ele era acusado pelos judeus, ele o soltou das correntes, e mandou vir aos chefes dos sacerdotes e todo o supremo conselho deles; e tendo trazido a Paulo, apresentou [-o] diante deles."}]'::jsonb, 'Almeida Livre'),
  ('At', 22, 'en', '[{"numero": 1, "texto": "Men, brethren, and fathers, hear ye my defence which I make now unto you."}, {"numero": 2, "texto": "(And when they heard that he spake in the Hebrew tongue to them, they kept the more silence: and he saith,)"}, {"numero": 3, "texto": "I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day."}, {"numero": 4, "texto": "And I persecuted this way unto the death, binding and delivering into prisons both men and women."}, {"numero": 5, "texto": "As also the high priest doth bear me witness, and all the estate of the elders: from whom also I received letters unto the brethren, and went to Damascus, to bring them which were there bound unto Jerusalem, for to be punished."}, {"numero": 6, "texto": "And it came to pass, that, as I made my journey, and was come nigh unto Damascus about noon, suddenly there shone from heaven a great light round about me."}, {"numero": 7, "texto": "And I fell unto the ground, and heard a voice saying unto me, Saul, Saul, why persecutest thou me?"}, {"numero": 8, "texto": "And I answered, Who art thou, Lord? And he said unto me, I am Jesus of Nazareth, whom thou persecutest."}, {"numero": 9, "texto": "And they that were with me saw indeed the light, and were afraid; but they heard not the voice of him that spake to me."}, {"numero": 10, "texto": "And I said, What shall I do, Lord? And the Lord said unto me, Arise, and go into Damascus; and there it shall be told thee of all things which are appointed for thee to do."}, {"numero": 11, "texto": "And when I could not see for the glory of that light, being led by the hand of them that were with me, I came into Damascus."}, {"numero": 12, "texto": "And one Ananias, a devout man according to the law, having a good report of all the Jews which dwelt there,"}, {"numero": 13, "texto": "Came unto me, and stood, and said unto me, Brother Saul, receive thy sight. And the same hour I looked up upon him."}, {"numero": 14, "texto": "And he said, The God of our fathers hath chosen thee, that thou shouldest know his will, and see that Just One, and shouldest hear the voice of his mouth."}, {"numero": 15, "texto": "For thou shalt be his witness unto all men of what thou hast seen and heard."}, {"numero": 16, "texto": "And now why tarriest thou? arise, and be baptized, and wash away thy sins, calling on the name of the Lord."}, {"numero": 17, "texto": "And it came to pass, that, when I was come again to Jerusalem, even while I prayed in the temple, I was in a trance;"}, {"numero": 18, "texto": "And saw him saying unto me, Make haste, and get thee quickly out of Jerusalem: for they will not receive thy testimony concerning me."}, {"numero": 19, "texto": "And I said, Lord, they know that I imprisoned and beat in every synagogue them that believed on thee:"}, {"numero": 20, "texto": "And when the blood of thy martyr Stephen was shed, I also was standing by, and consenting unto his death, and kept the raiment of them that slew him."}, {"numero": 21, "texto": "And he said unto me, Depart: for I will send thee far hence unto the Gentiles."}, {"numero": 22, "texto": "And they gave him audience unto this word, and then lifted up their voices, and said, Away with such a fellow from the earth: for it is not fit that he should live."}, {"numero": 23, "texto": "And as they cried out, and cast off their clothes, and threw dust into the air,"}, {"numero": 24, "texto": "The chief captain commanded him to be brought into the castle, and bade that he should be examined by scourging; that he might know wherefore they cried so against him."}, {"numero": 25, "texto": "And as they bound him with thongs, Paul said unto the centurion that stood by, Is it lawful for you to scourge a man that is a Roman, and uncondemned?"}, {"numero": 26, "texto": "When the centurion heard that, he went and told the chief captain, saying, Take heed what thou doest: for this man is a Roman."}, {"numero": 27, "texto": "Then the chief captain came, and said unto him, Tell me, art thou a Roman? He said, Yea."}, {"numero": 28, "texto": "And the chief captain answered, With a great sum obtained I this freedom. And Paul said, But I was free born."}, {"numero": 29, "texto": "Then straightway they departed from him which should have examined him: and the chief captain also was afraid, after he knew that he was a Roman, and because he had bound him."}, {"numero": 30, "texto": "On the morrow, because he would have known the certainty wherefore he was accused of the Jews, he loosed him from his bands, and commanded the chief priests and all their council to appear, and brought Paul down, and set him before them."}]'::jsonb, 'King James Version'),
  ('At', 22, 'fr', '[{"numero": 1, "texto": "Hommes frères et pères, écoutez ce que j''''ai maintenant à vous dire pour ma défense!"}, {"numero": 2, "texto": "Lorsqu''''ils entendirent qu''''il leur parlait en langue hébraïque, ils redoublèrent de silence. Et Paul dit:"}, {"numero": 3, "texto": "je suis Juif, né à Tarse en Cilicie; mais j''''ai été élevé dans cette ville-ci, et instruit aux pieds de Gamaliel dans la connaissance exacte de la loi de nos pères, étant plein de zèle pour Dieu, comme vous l''''êtes tous aujourd''''hui."}, {"numero": 4, "texto": "J''''ai persécuté à mort cette doctrine, liant et mettant en prison hommes et femmes."}, {"numero": 5, "texto": "Le souverain sacrificateur et tout le collège des anciens m''''en sont témoins. J''''ai même reçu d''''eux des lettres pour les frères de Damas, où je me rendis afin d''''amener liés à Jérusalem ceux qui se trouvaient là et de les faire punir."}, {"numero": 6, "texto": "Comme j''''étais en chemin, et que j''''approchais de Damas, tout à coup, vers midi, une grande lumière venant du ciel resplendit autour de moi."}, {"numero": 7, "texto": "Je tombai par terre, et j''''entendis une voix qui me disait: Saul, Saul, pourquoi me persécutes-tu?"}, {"numero": 8, "texto": "Je répondis: Qui es-tu, Seigneur? Et il me dit: Je suis Jésus de Nazareth, que tu persécutes."}, {"numero": 9, "texto": "Ceux qui étaient avec moi virent bien la lumière, mais ils n''''entendirent pas la voix de celui qui parlait."}, {"numero": 10, "texto": "Alors je dis: Que ferai-je, Seigneur? Et le Seigneur me dit: Lève-toi, va à Damas, et là on te dira tout ce que tu dois faire."}, {"numero": 11, "texto": "Comme je ne voyais rien, à cause de l''''éclat de cette lumière, ceux qui étaient avec moi me prirent par la main, et j''''arrivai à Damas."}, {"numero": 12, "texto": "Or, un nommé Ananias, homme pieux selon la loi, et de qui tous les Juifs demeurant à Damas rendaient un bon témoignage,"}, {"numero": 13, "texto": "vint se présenter à moi, et me dit: Saul, mon frère, recouvre la vue. Au même instant, je recouvrai la vue et je le regardai."}, {"numero": 14, "texto": "Il dit: Le Dieu de nos pères t''''a destiné à connaître sa volonté, à voir le Juste, et à entendre les paroles de sa bouche;"}, {"numero": 15, "texto": "car tu lui serviras de témoin, auprès de tous les hommes, des choses que tu as vues et entendues."}, {"numero": 16, "texto": "Et maintenant, que tardes-tu? Lève-toi, sois baptisé, et lavé de tes péchés, en invoquant le nom du Seigneur."}, {"numero": 17, "texto": "De retour à Jérusalem, comme je priais dans le temple, je fus ravi en extase,"}, {"numero": 18, "texto": "et je vis le Seigneur qui me disait: Hâte-toi, et sors promptement de Jérusalem, parce qu''''ils ne recevront pas ton témoignage sur moi."}, {"numero": 19, "texto": "Et je dis: Seigneur, ils savent eux-mêmes que je faisais mettre en prison et battre de verges dans les synagogues ceux qui croyaient en toi,"}, {"numero": 20, "texto": "et que, lorsqu''''on répandit le sang d''''Etienne, ton témoin, j''''étais moi-même présent, joignant mon approbation à celle des autres, et gardant les vêtements de ceux qui le faisaient mourir."}, {"numero": 21, "texto": "Alors il me dit: Va, je t''''enverrai au loin vers les nations...."}, {"numero": 22, "texto": "Ils l''''écoutèrent jusqu''''à cette parole. Mais alors ils élevèrent la voix, disant: Ote de la terre un pareil homme! Il n''''est pas digne de vivre."}, {"numero": 23, "texto": "Et ils poussaient des cris, jetaient leurs vêtements, lançaient de la poussière en l''''air."}, {"numero": 24, "texto": "Le tribun commanda de faire entrer Paul dans la forteresse, et de lui donner la question par le fouet, afin de savoir pour quel motif ils criaient ainsi contre lui."}, {"numero": 25, "texto": "Lorsqu''''on l''''eut exposé au fouet, Paul dit au centenier qui était présent: Vous est-il permis de battre de verges un citoyen romain, qui n''''est pas même condamné?"}, {"numero": 26, "texto": "A ces mots, le centenier alla vers le tribun pour l''''avertir, disant: Que vas-tu faire? Cet homme est Romain."}, {"numero": 27, "texto": "Et le tribun, étant venu, dit à Paul: Dis-moi, es-tu Romain? Oui, répondit-il."}, {"numero": 28, "texto": "Le tribun reprit: C''''est avec beaucoup d''''argent que j''''ai acquis ce droit de citoyen. Et moi, dit Paul, je l''''ai par ma naissance."}, {"numero": 29, "texto": "Aussitôt ceux qui devaient lui donner la question se retirèrent, et le tribun, voyant que Paul était Romain, fut dans la crainte parce qu''''il l''''avait fait lier."}, {"numero": 30, "texto": "Le lendemain, voulant savoir avec certitude de quoi les Juifs l''''accusaient, le tribun lui fit ôter ses liens, et donna l''''ordre aux principaux sacrificateurs et à tout le sanhédrin de se réunir; puis, faisant descendre Paul, il le plaça au milieu d''''eux."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 22, 'es', '[{"numero": 1, "texto": "VARONES hermanos y padres, oid la razón que ahora os doy."}, {"numero": 2, "texto": "(Y como oyeron que les hablaba en lengua hebrea, guardaron más silencio.) Y dijo:"}, {"numero": 3, "texto": "Yo de cierto soy Judío, nacido en Tarso de Cilicia, mas criado en esta ciudad á los pies de Gamaliel, enseñado conforme á la verdad de la ley de la patria, celoso de Dios, como todos vosotros sois hoy."}, {"numero": 4, "texto": "Que he perseguido este camino hasta la muerte, prendiendo y entregando en cárceles hombres y mujeres:"}, {"numero": 5, "texto": "Como también el príncipe de los sacerdotes me es testigo, y todos los ancianos; de los cuales también tomando letras á los hermanos, iba á Damasco para traer presos á Jerusalem aun á los que estuviesen allí, para que fuesen castigados."}, {"numero": 6, "texto": "Mas aconteció que yendo yo, y llegando cerca de Damasco, como á medio día, de repente me rodeó mucha luz del cielo:"}, {"numero": 7, "texto": "Y caí en el suelo, y oí una voz que me decía: Saulo, Saulo, ¿por qué me persigues?"}, {"numero": 8, "texto": "Yo entonces respondí: ¿Quién eres, Señor? Y me dijo: Yo soy Jesús de Nazaret, á quien tú persigues."}, {"numero": 9, "texto": "Y los que estaban conmigo vieron á la verdad la luz, y se espantaron; mas no oyeron la voz del que hablaba conmigo."}, {"numero": 10, "texto": "Y dije: ¿Qué haré, Señor? Y el Señor me dijo: Levántate, y ve á Damasco, y allí te será dicho todo lo que te está señalado hacer."}, {"numero": 11, "texto": "Y como yo no viese por causa de la claridad de la luz, llevado de la mano por los que estaban conmigo, vine á Damasco."}, {"numero": 12, "texto": "Entonces un Ananías, varón pío conforme á la ley, que tenía buen testimonio de todos los Judíos que allí moraban,"}, {"numero": 13, "texto": "Viniendo á mí, y acercándose, me dijo: Hermano Saulo, recibe la vista. Y yo en aquella hora le miré."}, {"numero": 14, "texto": "Y él dijo: El Dios de nuestros padres te ha predestinado para que conocieses su voluntad, y vieses á aquel Justo, y oyeses la voz de su boca."}, {"numero": 15, "texto": "Porque has de ser testigo suyo á todos los hombres, de lo que has visto y oído."}, {"numero": 16, "texto": "Ahora pues, ¿por qué te detienes? Levántate, y bautízate, y lava tus pecados, invocando su nombre."}, {"numero": 17, "texto": "Y me aconteció, vuelto á Jerusalem, que orando en el templo, fuí arrebatado fuera de mí."}, {"numero": 18, "texto": "Y le vi que me decía: Date prisa, y sal prestamente fuera de Jerusalem; porque no recibirán tu testimonio de mí."}, {"numero": 19, "texto": "Y yo dije: Señor, ellos saben que yo encerraba en cárcel, y hería por las sinagogas á los que creían en ti;"}, {"numero": 20, "texto": "Y cuando se derramaba la sangre de Esteban tu testigo, yo también estaba presente, y consentía á su muerte, y guardaba las ropas de los que le mataban."}, {"numero": 21, "texto": "Y me dijo: Ve, porque yo te tengo que enviar lejos á los Gentiles."}, {"numero": 22, "texto": "Y le oyeron hasta esta palabra: entonces alzaron la voz, diciendo: Quita de la tierra á un tal hombre, porque no conviene que viva."}, {"numero": 23, "texto": "Y dando ellos voces, y arrojando sus ropas y echando polvo al aire,"}, {"numero": 24, "texto": "Mandó el tribuno que le llevasen á la fortaleza, y ordenó que fuese examinado con azotes, para saber por qué causa clamaban así contra él."}, {"numero": 25, "texto": "Y como le ataron con correas, Pablo dijo al centurión que estaba presente: ¿Os es lícito azotar á un hombre Romano sin ser condenado?"}, {"numero": 26, "texto": "Y como el centurión oyó esto, fué y dió aviso al tribuno, diciendo: ¿Qué vas á hacer? porque este hombre es Romano."}, {"numero": 27, "texto": "Y viniendo el tribuno, le dijo: Dime, ¿eres tú Romano? Y él dijo: Sí."}, {"numero": 28, "texto": "Y respondió el tribuno: Yo con grande suma alcancé esta ciudadanía. Entonces Pablo dijo: Pero yo lo soy de nacimiento."}, {"numero": 29, "texto": "Así que, luego se apartaron de él los que le habían de atormentar: y aun el tribuno también tuvo temor, entendido que era Romano, por haberle atado."}, {"numero": 30, "texto": "Y al día siguiente, queriendo saber de cierto la causa por qué era acusado de los Judíos, le soltó de las prisiones, y mandó venir á los príncipes de los sacerdotes, y á todo su concilio: y sacando á Pablo, le presentó delante de ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 23, 'pt', '[{"numero": 1, "texto": "E Paulo, olhando fixamente para o supremo conselho, disse: Homens irmãos, com toda boa consciência eu tenho andado diante de Deus até o dia de hoje."}, {"numero": 2, "texto": "Mas o sumo sacerdote Ananias mandou aos que estavam perto dele, que o espancassem na boca."}, {"numero": 3, "texto": "Então Paulo lhe disse: Deus vai te espancar, parede caiada! Estás tu [aqui] sentado para me julgar conforme a Lei, e contra a Lei mandas me espancarem?"}, {"numero": 4, "texto": "E os que estavam ali disseram: Tu insultas ao sumo sacerdote de Deus?"}, {"numero": 5, "texto": "E Paulo disse: Eu não sabia, irmãos, que ele era o sumo sacerdote; porque está escrito: Não falarás mal do chefe do teu povo."}, {"numero": 6, "texto": "E Paulo, sabendo que uma parte era de saduceus, e outra de fariseus, ele clamou no supremo conselho: Homens irmãos, eu sou fariseu, filho de fariseu; pela esperança e ressurreição dos mortos eu estou sendo julgado."}, {"numero": 7, "texto": "E ele, tendo dito isto, houve uma confusão entre os fariseus e saduceus; e a multidão se dividiu;"}, {"numero": 8, "texto": "Porque os saduceus dizem que não há ressurreição, nem anjo ou espírito; mas os fariseus declaram ambas."}, {"numero": 9, "texto": "E houve uma grande gritaria; e levantando-se os escribas da parte dos fariseus, disputavam, dizendo: Nenhum mal achamos neste homem; e se algum espírito ou anjo falou com ele, não briguemos contra Deus."}, {"numero": 10, "texto": "E havendo grande confusão, o comandante, temendo que Paulo não fosse despedaçado por eles, mandou descer a tropa, e tirá-lo do meio deles, e levá-lo à área fortificada."}, {"numero": 11, "texto": "E [n] a noite seguinte o Senhor, aparecendo-lhe, disse: Tem bom ânimo, Paulo! Porque assim como deste testemunho de mim em Jerusalém, assim é necessário que tu dês testemunho também em Roma."}, {"numero": 12, "texto": "E tendo vindo o dia, alguns dos judeus fizeram uma conspiração, e prestaram juramento sob pena de maldição, dizendo que não comeriam nem beberiam enquanto não matassem a Paulo."}, {"numero": 13, "texto": "E eram mais de quarenta os que fizeram este juramento."}, {"numero": 14, "texto": "Os quais foram até os chefes dos sacerdotes e os anciãos, [e] disseram: Fizemos juramento sob pena de maldição, de que nada experimentaremos enquanto não matarmos a Paulo."}, {"numero": 15, "texto": "Agora, pois, vós, com o supremo conselho, informai ao comandante que amanhã ele o traga perante vós, como se fosse para que investigueis mais detalhadamente; e antes que ele chegue, estaremos prontos para o matar."}, {"numero": 16, "texto": "E o filho da irmã de Paulo, tendo ouvido esta cilada, veio e entrou na área fortificada, e avisou a Paulo."}, {"numero": 17, "texto": "E Paulo, tendo chamado a si um dos centuriões, disse: Leva este rapaz ao comandante, porque ele tem algo para lhe avisar."}, {"numero": 18, "texto": "Então ele o tomou, levou ao comandante, e disse: O prisioneiro Paulo, tendo me chamado, rogou [-me] que eu te trouxesse este rapaz, que tem algo a te dizer."}, {"numero": 19, "texto": "E o comandante, tomando-o pela mão, e indo para um lugar reservado, perguntou [-lhe] : O que tens para me avisar?"}, {"numero": 20, "texto": "E ele disse: Os judeus combinaram de te pedirem que amanhã tu leves a Paulo ao supremo conselho, como se fosse para que lhe perguntem mais detalhadamente;"}, {"numero": 21, "texto": "Porém tu, não acredites neles; porque mais de quarenta homens deles estão lhe preparando cilada, os quais sob pena de maldição fizeram juramento para não comerem nem beberem enquanto não o tiverem matado; e eles já estão preparados, esperando de ti a promessa."}, {"numero": 22, "texto": "Então o comandante despediu ao rapaz, mandando [-lhe] : A ninguém digas que tu me revelaste estas coisas."}, {"numero": 23, "texto": "E ele, chamando a si certos dois dos centuriões, disse: Aprontai duzentos soldados para irem até Cesareia; e setenta cavaleiros, e duzentos arqueiros, a partir das terceira hora da noite."}, {"numero": 24, "texto": "E preparem animais para cavalgarem, para que pondo neles a Paulo, levem [-no] a salvo ao governador Félix."}, {"numero": 25, "texto": "E ele [lhe] escreveu uma carta, que continha este aspecto:"}, {"numero": 26, "texto": "Cláudio Lísias, a Félix, excelentíssimo governador, saudações."}, {"numero": 27, "texto": "Este homem foi preso pelos judeus, e estando já a ponte de o matarem, eu vim com a tropa e [o] tomei, ao ser informado que ele era romano."}, {"numero": 28, "texto": "E eu, querendo saber a causa por que o acusavam, levei-o ao supremo conselho deles."}, {"numero": 29, "texto": "O qual eu achei que acusavam de algumas questões da Lei deles; mas que nenhum crime digno de morte ou de prisão havia contra ele."}, {"numero": 30, "texto": "E tendo sido avisado de que os judeus estavam para pôr uma cilada contra este homem, logo eu [o] enviei a ti, mandando também aos acusadores que diante de ti digam o que [tiverem] contra ele. Que tu estejas bem."}, {"numero": 31, "texto": "Tendo então os soldados tomado a Paulo, assim como lhes tinha sido ordenado, trouxeram-no durante a noite a Antipátride."}, {"numero": 32, "texto": "E no [dia] seguinte, deixando irem com ele os cavaleiros, voltaram à área fortificada."}, {"numero": 33, "texto": "Os quais, tendo chegado a Cesareia, e entregado a carta ao governador, apresentaram-lhe também a Paulo."}, {"numero": 34, "texto": "E o governador, tendo lido [a carta] , perguntou de que província ele era; e ao entender que [era] da Cilícia,"}, {"numero": 35, "texto": "disse: “Eu te ouvirei quando também chegarem os teus acusadores”. E mandou que o guardassem no palácio de Herodes."}]'::jsonb, 'Almeida Livre'),
  ('At', 23, 'en', '[{"numero": 1, "texto": "And Paul, earnestly beholding the council, said, Men and brethren, I have lived in all good conscience before God until this day."}, {"numero": 2, "texto": "And the high priest Ananias commanded them that stood by him to smite him on the mouth."}, {"numero": 3, "texto": "Then said Paul unto him, God shall smite thee, thou whited wall: for sittest thou to judge me after the law, and commandest me to be smitten contrary to the law?"}, {"numero": 4, "texto": "And they that stood by said, Revilest thou God''s high priest?"}, {"numero": 5, "texto": "Then said Paul, I wist not, brethren, that he was the high priest: for it is written, Thou shalt not speak evil of the ruler of thy people."}, {"numero": 6, "texto": "But when Paul perceived that the one part were Sadducees, and the other Pharisees, he cried out in the council, Men and brethren, I am a Pharisee, the son of a Pharisee: of the hope and resurrection of the dead I am called in question."}, {"numero": 7, "texto": "And when he had so said, there arose a dissension between the Pharisees and the Sadducees: and the multitude was divided."}, {"numero": 8, "texto": "For the Sadducees say that there is no resurrection, neither angel, nor spirit: but the Pharisees confess both."}, {"numero": 9, "texto": "And there arose a great cry: and the scribes that were of the Pharisees'' part arose, and strove, saying, We find no evil in this man: but if a spirit or an angel hath spoken to him, let us not fight against God."}, {"numero": 10, "texto": "And when there arose a great dissension, the chief captain, fearing lest Paul should have been pulled in pieces of them, commanded the soldiers to go down, and to take him by force from among them, and to bring him into the castle."}, {"numero": 11, "texto": "And the night following the Lord stood by him, and said, Be of good cheer, Paul: for as thou hast testified of me in Jerusalem, so must thou bear witness also at Rome."}, {"numero": 12, "texto": "And when it was day, certain of the Jews banded together, and bound themselves under a curse, saying that they would neither eat nor drink till they had killed Paul."}, {"numero": 13, "texto": "And they were more than forty which had made this conspiracy."}, {"numero": 14, "texto": "And they came to the chief priests and elders, and said, We have bound ourselves under a great curse, that we will eat nothing until we have slain Paul."}, {"numero": 15, "texto": "Now therefore ye with the council signify to the chief captain that he bring him down unto you to morrow, as though ye would enquire something more perfectly concerning him: and we, or ever he come near, are ready to kill him."}, {"numero": 16, "texto": "And when Paul''s sister''s son heard of their lying in wait, he went and entered into the castle, and told Paul."}, {"numero": 17, "texto": "Then Paul called one of the centurions unto him, and said, Bring this young man unto the chief captain: for he hath a certain thing to tell him."}, {"numero": 18, "texto": "So he took him, and brought him to the chief captain, and said, Paul the prisoner called me unto him, and prayed me to bring this young man unto thee, who hath something to say unto thee."}, {"numero": 19, "texto": "Then the chief captain took him by the hand, and went with him aside privately, and asked him, What is that thou hast to tell me?"}, {"numero": 20, "texto": "And he said, The Jews have agreed to desire thee that thou wouldest bring down Paul to morrow into the council, as though they would enquire somewhat of him more perfectly."}, {"numero": 21, "texto": "But do not thou yield unto them: for there lie in wait for him of them more than forty men, which have bound themselves with an oath, that they will neither eat nor drink till they have killed him: and now are they ready, looking for a promise from thee."}, {"numero": 22, "texto": "So the chief captain then let the young man depart, and charged him, See thou tell no man that thou hast shewed these things to me."}, {"numero": 23, "texto": "And he called unto him two centurions, saying, Make ready two hundred soldiers to go to Caesarea, and horsemen threescore and ten, and spearmen two hundred, at the third hour of the night;"}, {"numero": 24, "texto": "And provide them beasts, that they may set Paul on, and bring him safe unto Felix the governor."}, {"numero": 25, "texto": "And he wrote a letter after this manner:"}, {"numero": 26, "texto": "Claudius Lysias unto the most excellent governor Felix sendeth greeting."}, {"numero": 27, "texto": "This man was taken of the Jews, and should have been killed of them: then came I with an army, and rescued him, having understood that he was a Roman."}, {"numero": 28, "texto": "And when I would have known the cause wherefore they accused him, I brought him forth into their council:"}, {"numero": 29, "texto": "Whom I perceived to be accused of questions of their law, but to have nothing laid to his charge worthy of death or of bonds."}, {"numero": 30, "texto": "And when it was told me how that the Jews laid wait for the man, I sent straightway to thee, and gave commandment to his accusers also to say before thee what they had against him. Farewell."}, {"numero": 31, "texto": "Then the soldiers, as it was commanded them, took Paul, and brought him by night to Antipatris."}, {"numero": 32, "texto": "On the morrow they left the horsemen to go with him, and returned to the castle:"}, {"numero": 33, "texto": "Who, when they came to Caesarea and delivered the epistle to the governor, presented Paul also before him."}, {"numero": 34, "texto": "And when the governor had read the letter, he asked of what province he was. And when he understood that he was of Cilicia;"}, {"numero": 35, "texto": "I will hear thee, said he, when thine accusers are also come. And he commanded him to be kept in Herod''s judgment hall."}]'::jsonb, 'King James Version'),
  ('At', 23, 'fr', '[{"numero": 1, "texto": "Paul, les regards fixés sur le sanhédrin, dit: Hommes frères, c''''est en toute bonne conscience que je me suis conduit jusqu''''à ce jour devant Dieu..."}, {"numero": 2, "texto": "Le souverain sacrificateur Ananias ordonna à ceux qui étaient près de lui de le frapper sur la bouche."}, {"numero": 3, "texto": "Alors Paul lui dit: Dieu te frappera, muraille blanchie! Tu es assis pour me juger selon la loi, et tu violes la loi en ordonnant qu''''on me frappe!"}, {"numero": 4, "texto": "Ceux qui étaient près de lui dirent: Tu insultes le souverain sacrificateur de Dieu!"}, {"numero": 5, "texto": "Et Paul dit: Je ne savais pas, frères, que ce fût le souverain sacrificateur; car il est écrit: Tu ne parleras pas mal du chef de ton peuple."}, {"numero": 6, "texto": "Paul, sachant qu''''une partie de l''''assemblée était composée de sadducéens et l''''autre de pharisiens, s''''écria dans le sanhédrin: Hommes frères, je suis pharisien, fils de pharisiens; c''''est à cause de l''''espérance et de la résurrection des morts que je suis mis en jugement."}, {"numero": 7, "texto": "Quand il eut dit cela, il s''''éleva une discussion entre les pharisiens et les sadducéens, et l''''assemblée se divisa."}, {"numero": 8, "texto": "Car les sadducéens disent qu''''il n''''y a point de résurrection, et qu''''il n''''existe ni ange ni esprit, tandis que les pharisiens affirment les deux choses."}, {"numero": 9, "texto": "Il y eut une grande clameur, et quelques scribes du parti des pharisiens, s''''étant levés, engagèrent un vif débat, et dirent: Nous ne trouvons aucun mal en cet homme; peut-être un esprit ou un ange lui a-t-il parlé."}, {"numero": 10, "texto": "Comme la discorde allait croissant, le tribun craignant que Paul ne fût mis en pièces par ces gens, fit descendre les soldats pour l''''enlever du milieu d''''eux et le conduire à la forteresse."}, {"numero": 11, "texto": "La nuit suivante, le Seigneur apparut à Paul, et dit: Prends courage; car, de même que tu as rendu témoignage de moi dans Jérusalem, il faut aussi que tu rendes témoignage dans Rome."}, {"numero": 12, "texto": "Quand le jour fut venu, les Juifs formèrent un complot, et firent des imprécations contre eux-mêmes, en disant qu''''ils s''''abstiendraient de manger et de boire jusqu''''à ce qu''''ils eussent tué Paul."}, {"numero": 13, "texto": "Ceux qui formèrent ce complot étaient plus de quarante,"}, {"numero": 14, "texto": "et ils allèrent trouver les principaux sacrificateurs et les anciens, auxquels ils dirent: Nous nous sommes engagés, avec des imprécations contre nous-mêmes, à ne rien manger jusqu''''à ce que nous ayons tué Paul."}, {"numero": 15, "texto": "Vous donc, maintenant, adressez-vous avec le sanhédrin au tribun, pour qu''''il l''''amène devant vous, comme si vous vouliez examiner sa cause plus exactement; et nous, avant qu''''il approche, nous sommes prêts à le tuer."}, {"numero": 16, "texto": "Le fils de la soeur de Paul, ayant eu connaissance du guet-apens, alla dans la forteresse en informer Paul."}, {"numero": 17, "texto": "Paul appela l''''un des centeniers, et dit: Mène ce jeune homme vers le tribun, car il a quelque chose à lui rapporter."}, {"numero": 18, "texto": "Le centenier prit le jeune homme avec lui, le conduisit vers le tribun, et dit: Le prisonnier Paul m''''a appelé, et il m''''a prié de t''''amener ce jeune homme, qui a quelque chose à te dire."}, {"numero": 19, "texto": "Le tribun, prenant le jeune homme par la main, et se retirant à l''''écart, lui demanda: Qu''''as-tu à m''''annoncer?"}, {"numero": 20, "texto": "Il répondit: Les Juifs sont convenus de te prier d''''amener Paul demain devant le sanhédrin, comme si tu devais t''''enquérir de lui plus exactement."}, {"numero": 21, "texto": "Ne les écoute pas, car plus de quarante d''''entre eux lui dressent un guet-apens, et se sont engagés, avec des imprécations contre eux-mêmes, à ne rien manger ni boire jusqu''''à ce qu''''ils l''''aient tué; maintenant ils sont prêts, et n''''attendent que ton consentement."}, {"numero": 22, "texto": "Le tribun renvoya le jeune homme, après lui avoir recommandé de ne parler à personne de ce rapport qu''''il lui avait fait."}, {"numero": 23, "texto": "Ensuite il appela deux des centeniers, et dit: Tenez prêts, dès la troisième heure de la nuit, deux cents soldats, soixante-dix cavaliers et deux cents archers, pour aller jusqu''''à Césarée."}, {"numero": 24, "texto": "Qu''''il y ait aussi des montures pour Paul, afin qu''''on le mène sain et sauf au gouverneur Félix."}, {"numero": 25, "texto": "Il écrivit une lettre ainsi conçue:"}, {"numero": 26, "texto": "Claude Lysias au très excellent gouverneur Félix, salut!"}, {"numero": 27, "texto": "Cet homme, dont les Juifs s''''étaient saisis, allait être tué par eux, lorsque je survins avec des soldats et le leur enlevai, ayant appris qu''''il était Romain."}, {"numero": 28, "texto": "Voulant connaître le motif pour lequel ils l''''accusaient, je l''''amenai devant leur sanhédrin."}, {"numero": 29, "texto": "J''''ai trouvé qu''''il était accusé au sujet de questions relatives à leur loi, mais qu''''il n''''avait commis aucun crime qui mérite la mort ou la prison."}, {"numero": 30, "texto": "Informé que les Juifs lui dressaient des embûches, je te l''''ai aussitôt envoyé, en faisant savoir à ses accusateurs qu''''ils eussent à s''''adresser eux-mêmes à toi. Adieu."}, {"numero": 31, "texto": "Les soldats, selon l''''ordre qu''''ils avaient reçu, prirent Paul, et le conduisirent pendant la nuit jusqu''''à Antipatris."}, {"numero": 32, "texto": "Le lendemain, laissant les cavaliers poursuivre la route avec lui, ils retournèrent à la forteresse."}, {"numero": 33, "texto": "Arrivés à Césarée, les cavaliers remirent la lettre au gouverneur, et lui présentèrent Paul."}, {"numero": 34, "texto": "Le gouverneur, après avoir lu la lettre, demanda de quelle province était Paul. Ayant appris qu''''il était de la Cilicie:"}, {"numero": 35, "texto": "Je t''''entendrai, dit-il, quand tes accusateurs seront venus. Et il ordonna qu''''on le gardât dans le prétoire d''''Hérode."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 23, 'es', '[{"numero": 1, "texto": "ENTONCES Pablo, poniendo los ojos en el concilio, dice: Varones hermanos, yo con toda buena conciencia he conversado delante de Dios hasta el día de hoy."}, {"numero": 2, "texto": "El príncipe de los sacerdotes, Ananías, mandó entonces á los que estaban delante de él, que le hiriesen en la boca."}, {"numero": 3, "texto": "Entonces Pablo le dijo: Herirte ha Dios, pared blanqueada: ¿y estás tú sentado para juzgarme conforme á la ley, y contra la ley me mandas herir?"}, {"numero": 4, "texto": "Y los que estaban presentes dijeron: ¿Al sumo sacerdote de Dios maldices?"}, {"numero": 5, "texto": "Y Pablo dijo: No sabía, hermanos, que era el sumo sacerdote; pues escrito está: Al príncipe de tu pueblo no maldecirás."}, {"numero": 6, "texto": "Entonces Pablo, sabiendo que la una parte era de Saduceos, y la otra de Fariseos, clamó en el concilio: Varones hermanos, yo soy Fariseo, hijo de Fariseo: de la esperanza y de la resurrección de los muertos soy yo juzgado."}, {"numero": 7, "texto": "Y como hubo dicho esto, fué hecha disensión entre los Fariseos y los Saduceos; y la multitud fué dividida."}, {"numero": 8, "texto": "Porque los Saduceos dicen que no hay resurrección, ni ángel, ni espíritu; mas los Fariseos confiesan ambas cosas."}, {"numero": 9, "texto": "Y levantóse un gran clamor: y levantándose los escribas de la parte de los Fariseos, contendían diciendo: Ningún mal hallamos en este hombre; que si espíritu le ha hablado, ó ángel, no resistamos á Dios."}, {"numero": 10, "texto": "Y habiendo grande disensión, el tribuno, teniendo temor de que Pablo fuese despedazado de ellos, mandó venir soldados, y arrebatarle de en medio de ellos, y llevarle á la fortaleza."}, {"numero": 11, "texto": "Y la noche siguiente, presentándosele el Señor, le dijo: Confía, Pablo; que como has testificado de mí en Jerusalem, así es menester testifiques también en Roma."}, {"numero": 12, "texto": "Y venido el día, algunos de los Judíos se juntaron, é hicieron voto bajo de maldición, diciendo que ni comerían ni beberían hasta que hubiesen muerto á Pablo."}, {"numero": 13, "texto": "Y eran más de cuarenta los que habían hecho esta conjuración;"}, {"numero": 14, "texto": "Los cuales se fueron á los príncipes de los sacerdotes y á los ancianos, y dijeron: Nosotros hemos hecho voto debajo de maldición, que no hemos de gustar nada hasta que hayamos muerto á Pablo."}, {"numero": 15, "texto": "Ahora pues, vosotros, con el concilio, requerid al tribuno que le saque mañana á vosotros como que queréis entender de él alguna cosa más cierta; y nosotros, antes que él llegue, estaremos aparejados para matarle."}, {"numero": 16, "texto": "Entonces un hijo de la hermana de Pablo, oyendo las asechanzas, fué, y entró en la fortaleza, y dió aviso á Pablo."}, {"numero": 17, "texto": "Y Pablo, llamando á uno de los centuriones, dice: Lleva á este mancebo al tribuno, porque tiene cierto aviso que darle."}, {"numero": 18, "texto": "El entonces tomándole, le llevó al tribuno, y dijo: El preso Pablo, llamándome, me rogó que trajese á ti este mancebo, que tiene algo que hablarte."}, {"numero": 19, "texto": "Y el tribuno, tomándole de la mano y retirándose aparte, le preguntó: ¿Qué es lo que tienes que decirme?"}, {"numero": 20, "texto": "Y él dijo: Los Judíos han concertado rogarte que mañana saques á Pablo al concilio, como que han de inquirir de él alguna cosa más cierta."}, {"numero": 21, "texto": "Mas tú no los creas; porque más de cuarenta hombres de ellos le acechan, los cuales han hecho voto debajo de maldición, de no comer ni beber hasta que le hayan muerto; y ahora están apercibidos esperando tu promesa."}, {"numero": 22, "texto": "Entonces el tribuno despidió al mancebo, mandándole que á nadie dijese que le había dado aviso de esto."}, {"numero": 23, "texto": "Y llamados dos centuriones, mandó que apercibiesen para la hora tercia de la noche doscientos soldados, que fuesen hasta Cesarea, y setenta de á caballo, y doscientos lanceros;"}, {"numero": 24, "texto": "Y que aparejasen cabalgaduras en que poniendo á Pablo, le llevasen en salvo á Félix el Presidente."}, {"numero": 25, "texto": "Y escribió una carta en estos términos:"}, {"numero": 26, "texto": "Claudio Lisias al excelentísimo gobernador Félix: Salud."}, {"numero": 27, "texto": "A este hombre, aprehendido de los Judíos, y que iban ellos á matar, libré yo acudiendo con la tropa, habiendo entendido que era Romano."}, {"numero": 28, "texto": "Y queriendo saber la causa por qué le acusaban, le llevé al concilio de ellos:"}, {"numero": 29, "texto": "Y hallé que le acusaban de cuestiones de la ley de ellos, y que ningún crimen tenía digno de muerte ó de prisión."}, {"numero": 30, "texto": "Mas siéndome dado aviso de asechanzas que le habían aparejado los Judíos, luego al punto le he enviado á ti, intimando también á los acusadores que traten delante de ti lo que tienen contra él. Pásalo bien."}, {"numero": 31, "texto": "Y los soldados, tomando á Pablo como les era mandado, lleváronle de noche á Antipatris."}, {"numero": 32, "texto": "Y al día siguiente, dejando á los de á caballo que fuesen con él, se volvieron á la fortaleza."}, {"numero": 33, "texto": "Y como llegaron á Cesarea, y dieron la carta al gobernador, presentaron también á Pablo delante de él."}, {"numero": 34, "texto": "Y el gobernador, leída la carta, preguntó de qué provincia era; y entendiendo que de Cilicia,"}, {"numero": 35, "texto": "Te oiré, dijo, cuando vinieren tus acusadores. Y mandó que le guardasen en el pretorio de Herodes."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 24, 'pt', '[{"numero": 1, "texto": "E cinco dias depois, desceu o sumo sacerdote Ananias, com os anciãos e um certo orador Tértulo; os quais compareceram diante do governador contra Paulo."}, {"numero": 2, "texto": "E sendo chamado, Tértulo começou a acusá [-lo] , dizendo:"}, {"numero": 3, "texto": "[Visto que] há muita paz por causa de ti, e que por teu governo muitos bons serviços estão sendo feitos a esta nação, excelentíssimo Félix, totalmente e em todo lugar, com todo agradecimento o reconhecemos."}, {"numero": 4, "texto": "Mas para que eu não gaste muito o teu tempo, rogo [-te] que tu nos ouças brevemente, conforme a tua clemência."}, {"numero": 5, "texto": "Porque nós temos achado que este homem [é] uma peste, e levantador de rebeliões entre todos os judeus pelo mundo, e o principal defensor da seita dos nazarenos."}, {"numero": 6, "texto": "O qual também tentou profanar o Templo; ao qual também prendemos, e quisemos julgar conforme a nossa Lei."}, {"numero": 7, "texto": "Mas tendo vindo sobre [nós] o comandante Lísias, com grande violência, tirou [-o] das nossas mãos;"}, {"numero": 8, "texto": "investigando-o tu mesmo, poderás entender todas estas coisas das quais o acusamos."}, {"numero": 9, "texto": "E os judeus também concordaram, dizendo serem estas coisas assim."}, {"numero": 10, "texto": "Mas Paulo, fazendo gesto ao governador para que falasse, respondeu: Sabendo eu que por muitos anos tu tens sido juiz desta nação, com maior ânimo eu me defendo."}, {"numero": 11, "texto": "Pois tu podes entender que há não mais que doze dias, eu tinha subido a Jerusalém para adorar."}, {"numero": 12, "texto": "E nem me acharam falando com alguém no Templo, nem incitando ao povo, nem nas sinagogas, nem na cidade."}, {"numero": 13, "texto": "E nem podem provar as coisas das quais agora estão me acusando."}, {"numero": 14, "texto": "Mas isto eu te confesso, que conforme o Caminho que eles chamam de seita, assim eu sirvo ao Deus dos [meus] pais, crendo em tudo que está escrito na Lei e nos profetas;"}, {"numero": 15, "texto": "Tendo esperança em Deus, ao qual estes mesmos também esperam, que vai haver ressurreição dos mortos, tanto dos justos como dos injustos."}, {"numero": 16, "texto": "E nisto eu pratico, [em que] tanto para com Deus como para com os seres humanos eu sempre tenha uma consciência limpa."}, {"numero": 17, "texto": "E muitos anos depois, vim para fazer doações e ofertas à minha nação."}, {"numero": 18, "texto": "Nisto, tendo eu me purificado, nem com multidões, nem com tumulto, alguns judeus da Ásia me acharam,"}, {"numero": 19, "texto": "Os quais era necessário que estivessem [aqui] presentes diante de ti, se tivessem alguma coisa contra mim."}, {"numero": 20, "texto": "Ou digam estes mesmos, se eles acharam alguma má ação em mim quando eu estava perante o supremo conselho;"}, {"numero": 21, "texto": "A não ser somente esta palavra com que, quando eu estava entre eles, clamei, que pela ressurreição dos mortos eu estou sendo julgado hoje por vós."}, {"numero": 22, "texto": "Tendo ouvido estas coisas, Félix, que sabia mais detalhadamente sobre o Caminho, adiou-lhes, dizendo: Quando o comandante Lísias descer, eu procurarei saber melhor de vossos assuntos."}, {"numero": 23, "texto": "E ele mandou ao centurião que guardassem a Paulo, e estivesse com [alguma] liberdade, e impedir a ninguém dos seus [amigos] lhe prestasse serviço, ou vir até ele."}, {"numero": 24, "texto": "E alguns dias depois, tendo vindo Félix com a mulher dele Drusila, que era judia, mandou chamar a Paulo, e o ouviu sobre a fé em Cristo."}, {"numero": 25, "texto": "E ele, tendo discursado sobre a justiça, o domínio próprio, e o julgamento que está por vir, Félix temeu, [e] respondeu: Por agora vai; e tendo [outra] oportunidade, eu te chamarei."}, {"numero": 26, "texto": "Ele também esperava que lhe fosse dado [algum] dinheiro por Paulo, para que o soltasse; por isso ele também muitas vezes o mandava chamar, e conversava com ele."}, {"numero": 27, "texto": "Mas tendo completado dois anos, Félix teve por sucessor a Pórcio Festo. E Félix, querendo agradar dos judeus, deixou Paulo preso."}]'::jsonb, 'Almeida Livre'),
  ('At', 24, 'en', '[{"numero": 1, "texto": "And after five days Ananias the high priest descended with the elders, and with a certain orator named Tertullus, who informed the governor against Paul."}, {"numero": 2, "texto": "And when he was called forth, Tertullus began to accuse him, saying, Seeing that by thee we enjoy great quietness, and that very worthy deeds are done unto this nation by thy providence,"}, {"numero": 3, "texto": "We accept it always, and in all places, most noble Felix, with all thankfulness."}, {"numero": 4, "texto": "Notwithstanding, that I be not further tedious unto thee, I pray thee that thou wouldest hear us of thy clemency a few words."}, {"numero": 5, "texto": "For we have found this man a pestilent fellow, and a mover of sedition among all the Jews throughout the world, and a ringleader of the sect of the Nazarenes:"}, {"numero": 6, "texto": "Who also hath gone about to profane the temple: whom we took, and would have judged according to our law."}, {"numero": 7, "texto": "But the chief captain Lysias came upon us, and with great violence took him away out of our hands,"}, {"numero": 8, "texto": "Commanding his accusers to come unto thee: by examining of whom thyself mayest take knowledge of all these things, whereof we accuse him."}, {"numero": 9, "texto": "And the Jews also assented, saying that these things were so."}, {"numero": 10, "texto": "Then Paul, after that the governor had beckoned unto him to speak, answered, Forasmuch as I know that thou hast been of many years a judge unto this nation, I do the more cheerfully answer for myself:"}, {"numero": 11, "texto": "Because that thou mayest understand, that there are yet but twelve days since I went up to Jerusalem for to worship."}, {"numero": 12, "texto": "And they neither found me in the temple disputing with any man, neither raising up the people, neither in the synagogues, nor in the city:"}, {"numero": 13, "texto": "Neither can they prove the things whereof they now accuse me."}, {"numero": 14, "texto": "But this I confess unto thee, that after the way which they call heresy, so worship I the God of my fathers, believing all things which are written in the law and in the prophets:"}, {"numero": 15, "texto": "And have hope toward God, which they themselves also allow, that there shall be a resurrection of the dead, both of the just and unjust."}, {"numero": 16, "texto": "And herein do I exercise myself, to have always a conscience void to offence toward God, and toward men."}, {"numero": 17, "texto": "Now after many years I came to bring alms to my nation, and offerings."}, {"numero": 18, "texto": "Whereupon certain Jews from Asia found me purified in the temple, neither with multitude, nor with tumult."}, {"numero": 19, "texto": "Who ought to have been here before thee, and object, if they had ought against me."}, {"numero": 20, "texto": "Or else let these same here say, if they have found any evil doing in me, while I stood before the council,"}, {"numero": 21, "texto": "Except it be for this one voice, that I cried standing among them, Touching the resurrection of the dead I am called in question by you this day."}, {"numero": 22, "texto": "And when Felix heard these things, having more perfect knowledge of that way, he deferred them, and said, When Lysias the chief captain shall come down, I will know the uttermost of your matter."}, {"numero": 23, "texto": "And he commanded a centurion to keep Paul, and to let him have liberty, and that he should forbid none of his acquaintance to minister or come unto him."}, {"numero": 24, "texto": "And after certain days, when Felix came with his wife Drusilla, which was a Jewess, he sent for Paul, and heard him concerning the faith in Christ."}, {"numero": 25, "texto": "And as he reasoned of righteousness, temperance, and judgment to come, Felix trembled, and answered, Go thy way for this time; when I have a convenient season, I will call for thee."}, {"numero": 26, "texto": "He hoped also that money should have been given him of Paul, that he might loose him: wherefore he sent for him the oftener, and communed with him."}, {"numero": 27, "texto": "But after two years Porcius Festus came into Felix'' room: and Felix, willing to shew the Jews a pleasure, left Paul bound."}]'::jsonb, 'King James Version'),
  ('At', 24, 'fr', '[{"numero": 1, "texto": "Cinq jours après, arriva le souverain sacrificateur Ananias, avec des anciens et un orateur nommé Tertulle. Ils portèrent plainte au gouverneur contre Paul."}, {"numero": 2, "texto": "Paul fut appelé, et Tertulle se mit à l''''accuser, en ces termes:"}, {"numero": 3, "texto": "Très excellent Félix, tu nous fais jouir d''''une paix profonde, et cette nation a obtenu de salutaires réformes par tes soins prévoyants; c''''est ce que nous reconnaissons en tout et partout avec une entière gratitude."}, {"numero": 4, "texto": "Mais, pour ne pas te retenir davantage, je te prie d''''écouter, dans ta bonté, ce que nous avons à dire en peu de mots."}, {"numero": 5, "texto": "Nous avons trouvé cet homme, qui est une peste, qui excite des divisions parmi tous les Juifs du monde, qui est chef de la secte des Nazaréens,"}, {"numero": 6, "texto": "et qui même a tenté de profaner le temple. Et nous l''''avons arrêté. Nous avons voulu le juger selon notre loi;"}, {"numero": 7, "texto": "mais le tribun Lysias étant survenu, l''''a arraché de nos mains avec une grande violence,"}, {"numero": 8, "texto": "en ordonnant à ses accusateurs de venir devant toi. Tu pourras toi-même, en l''''interrogeant, apprendre de lui tout ce dont nous l''''accusons."}, {"numero": 9, "texto": "Les Juifs se joignirent à l''''accusation, soutenant que les choses étaient ainsi."}, {"numero": 10, "texto": "Après que le gouverneur lui eut fait signe de parler, Paul répondit: Sachant que, depuis plusieurs années, tu es juge de cette nation, c''''est avec confiance que je prends la parole pour défendre ma cause."}, {"numero": 11, "texto": "Il n''''y a pas plus de douze jours, tu peux t''''en assurer, que je suis monté à Jérusalem pour adorer."}, {"numero": 12, "texto": "On ne m''''a trouvé ni dans le temple, ni dans les synagogues, ni dans la ville, disputant avec quelqu''''un, ou provoquant un rassemblement séditieux de la foule."}, {"numero": 13, "texto": "Et ils ne sauraient prouver ce dont ils m''''accusent maintenant."}, {"numero": 14, "texto": "Je t''''avoue bien que je sers le Dieu de mes pères selon la voie qu''''ils appellent une secte, croyant tout ce qui est écrit dans la loi et dans les prophètes,"}, {"numero": 15, "texto": "et ayant en Dieu cette espérance, comme ils l''''ont eux-mêmes, qu''''il y aura une résurrection des justes et des injustes."}, {"numero": 16, "texto": "C''''est pourquoi je m''''efforce d''''avoir constamment une conscience sans reproche devant Dieu et devant les hommes."}, {"numero": 17, "texto": "Après une absence de plusieurs années, je suis venu pour faire des aumônes à ma nation, et pour présenter des offrandes."}, {"numero": 18, "texto": "C''''est alors que quelques Juifs d''''Asie m''''ont trouvé purifié dans le temple, sans attroupement ni tumulte."}, {"numero": 19, "texto": "C''''était à eux de paraître en ta présence et de se porter accusateurs, s''''ils avaient quelque chose contre moi."}, {"numero": 20, "texto": "Ou bien, que ceux-ci déclarent de quel crime ils m''''ont trouvé coupable, lorsque j''''ai comparu devant le sanhédrin,"}, {"numero": 21, "texto": "moins que ce ne soit uniquement de ce cri que j''''ai fait entendre au milieu d''''eux: C''''est à cause de la résurrection des morts que je suis aujourd''''hui mis en jugement devant vous."}, {"numero": 22, "texto": "Félix, qui savait assez exactement ce qui concernait cette doctrine, les ajourna, en disant: Quand le tribun Lysias sera venu, j''''examinerai votre affaire."}, {"numero": 23, "texto": "Et il donna l''''ordre au centenier de garder Paul, en lui laissant une certaine liberté, et en n''''empêchant aucun des siens de lui rendre des services."}, {"numero": 24, "texto": "Quelques jours après, Félix vint avec Drusille, sa femme, qui était Juive, et il fit appeler Paul. Il l''''entendit sur la foi en Christ."}, {"numero": 25, "texto": "Mais, comme Paul discourait sur la justice, sur la tempérance, et sur le jugement à venir, Félix, effrayé, dit: Pour le moment retire-toi; quand j''''en trouverai l''''occasion, je te rappellerai."}, {"numero": 26, "texto": "Il espérait en même temps que Paul lui donnerait de l''''argent; aussi l''''envoyait-il chercher assez fréquemment, pour s''''entretenir avec lui."}, {"numero": 27, "texto": "Deux ans s''''écoulèrent ainsi, et Félix eut pour successeur Porcius Festus. Dans le désir de plaire aux Juifs, Félix laissa Paul en prison."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 24, 'es', '[{"numero": 1, "texto": "Y CINCO días después descendió el sumo sacerdote Ananías, con algunos de los ancianos, y un cierto Tértulo, orador; y parecieron delante del gobernador contra Pablo."}, {"numero": 2, "texto": "Y citado que fué, Tértulo comenzó á acusar, diciendo: Como por causa tuya vivamos en grande paz, y muchas cosas sean bien gobernadas en el pueblo por tu prudencia,"}, {"numero": 3, "texto": "Siempre y en todo lugar lo recibimos con todo hacimiento de gracias, oh excelentísimo Félix."}, {"numero": 4, "texto": "Empero por no molestarte más largamente, ruégote que nos oigas brevemente conforme á tu equidad."}, {"numero": 5, "texto": "Porque hemos hallado que este hombre es pestilencial, y levantador de sediciones entre todos los Judíos por todo el mundo, y príncipe de la secta de los Nazarenos:"}, {"numero": 6, "texto": "El cual también tentó á violar el templo; y prendiéndole, le quisimos juzgar conforme á nuestra ley:"}, {"numero": 7, "texto": "Mas interviniendo el tribuno Lisias, con grande violencia le quitó de nuestras manos,"}, {"numero": 8, "texto": "Mandando á sus acusadores que viniesen á ti; del cual tú mismo juzgando, podrás entender todas estas cosas de que le acusamos."}, {"numero": 9, "texto": "Y contendían también los Judíos, diciendo ser así estas cosas."}, {"numero": 10, "texto": "Entonces Pablo, haciéndole el gobernador señal que hablase, respondió: Porque sé que muchos años ha eres gobernador de esta nación, con buen ánimo satisfaré por mí."}, {"numero": 11, "texto": "Porque tú puedes entender que no hace más de doce días que subí á adorar á Jerusalem;"}, {"numero": 12, "texto": "Y ni me hallaron en el templo disputando con ninguno, ni haciendo concurso de multitud, ni en sinagogas, ni en la ciudad;"}, {"numero": 13, "texto": "Ni te pueden probar las cosas de que ahora me acusan."}, {"numero": 14, "texto": "Esto empero te confieso, que conforme á aquel Camino que llaman herejía, así sirvo al Dios de mis padres, creyendo todas las cosas que en la ley y en los profetas están escritas;"}, {"numero": 15, "texto": "Teniendo esperanza en Dios que ha de haber resurrección de los muertos, así de justos como de injustos, la cual también ellos esperan."}, {"numero": 16, "texto": "Y por esto, procuro yo tener siempre conciencia sin remordimiento acerca de Dios y acerca de los hombres."}, {"numero": 17, "texto": "Mas pasados muchos años, vine á hacer limosnas á mi nación, y ofrendas,"}, {"numero": 18, "texto": "Cuando me hallaron purificado en el templo (no con multitud ni con alboroto) unos Judíos de Asia;"}, {"numero": 19, "texto": "Los cuales debieron comparecer delante de ti, y acusarme, si contra mí tenían algo."}, {"numero": 20, "texto": "O digan estos mismos si hallaron en mí alguna cosa mal hecha, cuando yo estuve en el concilio,"}, {"numero": 21, "texto": "Si no sea que, estando entre ellos prorrumpí en alta voz: Acerca de la resurrección de los muertos soy hoy juzgado de vosotros."}, {"numero": 22, "texto": "Entonces Félix, oídas estas cosas, estando bien informado de esta secta, les puso dilación, diciendo: Cuando descendiere el tribuno Lisias acabaré de conocer de vuestro negocio."}, {"numero": 23, "texto": "Y mandó al centurión que Pablo fuese guardado, y aliviado de las prisiones; y que no vedase á ninguno de sus familiares servirle, ó venir á él."}, {"numero": 24, "texto": "Y algunos días después, viniendo Félix con Drusila, su mujer, la cual era Judía, llamó á Pablo, y oyó de él la fe que es en Jesucristo."}, {"numero": 25, "texto": "Y disertando él de la justicia, y de la continencia, y del juicio venidero, espantado Félix, respondió: Ahora vete; mas en teniendo oportunidad te llamaré:"}, {"numero": 26, "texto": "Esperando también con esto, que de parte de Pablo le serían dados dineros, porque le soltase; por lo cual, haciéndole venir muchas veces, hablaba con él."}, {"numero": 27, "texto": "Mas al cabo de dos años recibió Félix por sucesor á Porcio Festo: y queriendo Félix ganar la gracia de los Judíos, dejó preso á Pablo."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 25, 'pt', '[{"numero": 1, "texto": "Então Festo, tendo entrado na província, subiu dali três dias depois de Cesareia a Jerusalém."}, {"numero": 2, "texto": "E o sumo sacerdote e os líderes dos judeus compareceram diante dele contra Paulo, e lhe rogaram;"}, {"numero": 3, "texto": "Pedindo favor contra ele, para que o fizesse vir a Jerusalém, preparando cilada para o matarem no caminho."}, {"numero": 4, "texto": "Mas Festo respondeu que Paulo estava guardado em Cesareia, e que ele logo estava indo [para lá] ."}, {"numero": 5, "texto": "Ele disse: Então aqueles dentre vós que podem, desçam com [igo] , e se houver alguma coisa errada neste homem, acusem-no."}, {"numero": 6, "texto": "E ele, tendo ficado entre eles mais de dez dias, desceu a Cesareia; e tendo se sentado no tribunal no [dia] seguinte, mandou que trouxessem a Paulo."}, {"numero": 7, "texto": "E tendo ele vindo, os judeus que haviam descido de Jerusalém [o] rodearam, trazendo contra Paulo muitas e graves acusações, que não podiam provar."}, {"numero": 8, "texto": "Ele, disse em sua defesa: Eu não pequei nem contra a Lei dos judeus, nem contra o Templo, nem contra César, em coisa alguma."}, {"numero": 9, "texto": "Mas Festo, querendo agradar aos judeus, respondendo a Paulo, disse: Tu queres subir a Jerusalém e ser julgado sobre estas coisas diante de mim?"}, {"numero": 10, "texto": "E Paulo disse: Eu estou diante do tribunal de César, onde eu tenho que ser julgado; a nenhum dos judeus eu fiz mal, assim como também tu sabes muito bem."}, {"numero": 11, "texto": "Porque se eu fiz algum mal, ou cometi algo digno de morte, eu não recuso morrer; mas se nada há das coisas que este me acusam, ninguém pode me entregar a eles. Eu apelo a César."}, {"numero": 12, "texto": "Então Paulo, tendo conversado com o Conselho, respondeu: Tu apelaste a César; a César irás."}, {"numero": 13, "texto": "E passados alguns dias, o Rei Agripa e Berenice vieram a Cesareia para saudar a Festo."}, {"numero": 14, "texto": "E quando tinham ficado ali muitos dias, Festo contou ao rei os assuntos de Paulo, dizendo: Um certo homem foi deixado [aqui] preso por Félix;"}, {"numero": 15, "texto": "Por causa do qual, estando eu em Jerusalém, os chefes dos sacerdotes e os anciãos dos judeus compareceram [a mim] , pedindo julgamento contra ele."}, {"numero": 16, "texto": "Aos quais eu respondi não ser costume dos romanos entregar a algum homem à morte, antes que o acusado tenha seus acusadores face a face, e tenha oportunidade para se defender da acusação."}, {"numero": 17, "texto": "Portanto, tendo eles se reunido aqui, fazendo nenhum adiamento, no [dia] seguinte, estando eu sentado no tribunal, mandei trazer ao homem."}, {"numero": 18, "texto": "Do qual os acusadores estando [aqui] presentes, trouxeram como acusação nenhuma das coisas que eu suspeitava."}, {"numero": 19, "texto": "Mas tinham contra ele algumas questões relativas às próprias crenças deles, e de um certo morto Jesus, o qual Paulo afirmava estar vivo."}, {"numero": 20, "texto": "E eu, estando em duvida sobre [como] interrogar esta causa, disse, [perguntando] se ele queria ir a Jerusalém, e lá ser julgado sobre estas coisas."}, {"numero": 21, "texto": "Porém Paulo, tendo apelado para ser guardado ao interrogatório do imperador, mandei que o guardassem, até que eu o enviasse a César."}, {"numero": 22, "texto": "E Agripa disse a Festo: Eu também queria ouvir a este homem.E ele disse: E amanhã tu o ouvirás."}, {"numero": 23, "texto": "Então no dia seguinte, tendo vindo Agripa e Berenice, com muita pompa, e entrando no auditório com os comandantes e os homens mais importantes da cidade, trouxeram a Paulo por ordem de Festo."}, {"numero": 24, "texto": "E Festo disse: Rei Agripa, e todos os homens que estais presentes [aqui] conosco, vós vedes este [homem] , a quem toda a multidão dos judeus, tanto em Jerusalém como aqui, tem apelado a mim, clamando que ele não deve mais viver."}, {"numero": 25, "texto": "Mas tendo eu achado nada que ele tenha feito que fosse digno de morte, e também tendo ele mesmo apelado ao imperador, eu decidi enviá-lo."}, {"numero": 26, "texto": "Do qual eu não tenho coisa alguma certa para escrever ao [meu] senhor; por isso que eu o trouxe diante de vós; e principalmente diante de ti, rei Agripa, para que, sendo feita a investigação, eu tenha algo para escrever."}, {"numero": 27, "texto": "Porque não me parece razoável enviar a um prisioneiro, sem também informar as acusações contra ele."}]'::jsonb, 'Almeida Livre'),
  ('At', 25, 'en', '[{"numero": 1, "texto": "Now when Festus was come into the province, after three days he ascended from Caesarea to Jerusalem."}, {"numero": 2, "texto": "Then the high priest and the chief of the Jews informed him against Paul, and besought him,"}, {"numero": 3, "texto": "And desired favour against him, that he would send for him to Jerusalem, laying wait in the way to kill him."}, {"numero": 4, "texto": "But Festus answered, that Paul should be kept at Caesarea, and that he himself would depart shortly thither."}, {"numero": 5, "texto": "Let them therefore, said he, which among you are able, go down with me, and accuse this man, if there be any wickedness in him."}, {"numero": 6, "texto": "And when he had tarried among them more than ten days, he went down unto Caesarea; and the next day sitting on the judgment seat commanded Paul to be brought."}, {"numero": 7, "texto": "And when he was come, the Jews which came down from Jerusalem stood round about, and laid many and grievous complaints against Paul, which they could not prove."}, {"numero": 8, "texto": "While he answered for himself, Neither against the law of the Jews, neither against the temple, nor yet against Caesar, have I offended any thing at all."}, {"numero": 9, "texto": "But Festus, willing to do the Jews a pleasure, answered Paul, and said, Wilt thou go up to Jerusalem, and there be judged of these things before me?"}, {"numero": 10, "texto": "Then said Paul, I stand at Caesar''s judgment seat, where I ought to be judged: to the Jews have I done no wrong, as thou very well knowest."}, {"numero": 11, "texto": "For if I be an offender, or have committed any thing worthy of death, I refuse not to die: but if there be none of these things whereof these accuse me, no man may deliver me unto them. I appeal unto Caesar."}, {"numero": 12, "texto": "Then Festus, when he had conferred with the council, answered, Hast thou appealed unto Caesar? unto Caesar shalt thou go."}, {"numero": 13, "texto": "And after certain days king Agrippa and Bernice came unto Caesarea to salute Festus."}, {"numero": 14, "texto": "And when they had been there many days, Festus declared Paul''s cause unto the king, saying, There is a certain man left in bonds by Felix:"}, {"numero": 15, "texto": "About whom, when I was at Jerusalem, the chief priests and the elders of the Jews informed me, desiring to have judgment against him."}, {"numero": 16, "texto": "To whom I answered, It is not the manner of the Romans to deliver any man to die, before that he which is accused have the accusers face to face, and have licence to answer for himself concerning the crime laid against him."}, {"numero": 17, "texto": "Therefore, when they were come hither, without any delay on the morrow I sat on the judgment seat, and commanded the man to be brought forth."}, {"numero": 18, "texto": "Against whom when the accusers stood up, they brought none accusation of such things as I supposed:"}, {"numero": 19, "texto": "But had certain questions against him of their own superstition, and of one Jesus, which was dead, whom Paul affirmed to be alive."}, {"numero": 20, "texto": "And because I doubted of such manner of questions, I asked him whether he would go to Jerusalem, and there be judged of these matters."}, {"numero": 21, "texto": "But when Paul had appealed to be reserved unto the hearing of Augustus, I commanded him to be kept till I might send him to Caesar."}, {"numero": 22, "texto": "Then Agrippa said unto Festus, I would also hear the man myself. To morrow, said he, thou shalt hear him."}, {"numero": 23, "texto": "And on the morrow, when Agrippa was come, and Bernice, with great pomp, and was entered into the place of hearing, with the chief captains, and principal men of the city, at Festus'' commandment Paul was brought forth."}, {"numero": 24, "texto": "And Festus said, King Agrippa, and all men which are here present with us, ye see this man, about whom all the multitude of the Jews have dealt with me, both at Jerusalem, and also here, crying that he ought not to live any longer."}, {"numero": 25, "texto": "But when I found that he had committed nothing worthy of death, and that he himself hath appealed to Augustus, I have determined to send him."}, {"numero": 26, "texto": "Of whom I have no certain thing to write unto my lord. Wherefore I have brought him forth before you, and specially before thee, O king Agrippa, that, after examination had, I might have somewhat to write."}, {"numero": 27, "texto": "For it seemeth to me unreasonable to send a prisoner, and not withal to signify the crimes laid against him."}]'::jsonb, 'King James Version'),
  ('At', 25, 'fr', '[{"numero": 1, "texto": "Festus, étant arrivé dans la province, monta trois jours après de Césarée à Jérusalem."}, {"numero": 2, "texto": "Les principaux sacrificateurs et les principaux d''''entre les Juifs lui portèrent plainte contre Paul. Ils firent des instances auprès de lui, et,"}, {"numero": 3, "texto": "dans des vues hostiles, lui demandèrent comme une faveur qu''''il le fît venir à Jérusalem. Ils préparaient un guet-apens, pour le tuer en chemin."}, {"numero": 4, "texto": "Festus répondit que Paul était gardé à Césarée, et que lui-même devait partir sous peu."}, {"numero": 5, "texto": "Que les principaux d''''entre vous descendent avec moi, dit-il, et s''''il y a quelque chose de coupable en cet homme, qu''''ils l''''accusent."}, {"numero": 6, "texto": "Festus ne passa que huit à dix jours parmi eux, puis il descendit à Césarée. Le lendemain, s''''étant assis sur son tribunal, il donna l''''ordre qu''''on amenât Paul."}, {"numero": 7, "texto": "Quand il fut arrivé, les Juifs qui étaient venus de Jérusalem l''''entourèrent, et portèrent contre lui de nombreuses et graves accusations, qu''''ils n''''étaient pas en état de prouver."}, {"numero": 8, "texto": "Paul entreprit sa défense, en disant: Je n''''ai rien fait de coupable, ni contre la loi des Juifs, ni contre le temple, ni contre César."}, {"numero": 9, "texto": "Festus, désirant plaire aux Juifs, répondit à Paul: Veux-tu monter à Jérusalem, et y être jugé sur ces choses en ma présence?"}, {"numero": 10, "texto": "Paul dit: C''''est devant le tribunal de César que je comparais, c''''est là que je dois être jugé. Je n''''ai fait aucun tort aux Juifs, comme tu le sais fort bien."}, {"numero": 11, "texto": "Si j''''ai commis quelque injustice, ou quelque crime digne de mort, je ne refuse pas de mourir; mais, si les choses dont ils m''''accusent sont fausses, personne n''''a le droit de me livrer à eux. J''''en appelle à César."}, {"numero": 12, "texto": "Alors Festus, après avoir délibéré avec le conseil, répondit: Tu en as appelé à César; tu iras devant César."}, {"numero": 13, "texto": "Quelques jours après, le roi Agrippa et Bérénice arrivèrent à Césarée, pour saluer Festus."}, {"numero": 14, "texto": "Comme ils passèrent là plusieurs jours, Festus exposa au roi l''''affaire de Paul, et dit: Félix a laissé prisonnier un homme"}, {"numero": 15, "texto": "contre lequel, lorsque j''''étais à Jérusalem, les principaux sacrificateurs et les anciens des Juifs ont porté plainte, en demandant sa condamnation."}, {"numero": 16, "texto": "Je leur ai répondu que ce n''''est pas la coutume des Romains de livrer un homme avant que l''''inculpé ait été mis en présence de ses accusateurs, et qu''''il ait eu la faculté de se défendre sur les choses dont on l''''accuse."}, {"numero": 17, "texto": "Ils sont donc venus ici, et, sans différer, je m''''assis le lendemain sur mon tribunal, et je donnai l''''ordre qu''''on amenât cet homme."}, {"numero": 18, "texto": "Les accusateurs, s''''étant présentés, ne lui imputèrent rien de ce que je supposais;"}, {"numero": 19, "texto": "ils avaient avec lui des discussions relatives à leur religion particulière, et à un certain Jésus qui est mort, et que Paul affirmait être vivant."}, {"numero": 20, "texto": "Ne sachant quel parti prendre dans ce débat, je lui demandai s''''il voulait aller à Jérusalem, et y être jugé sur ces choses."}, {"numero": 21, "texto": "Mais Paul en ayant appelé, pour que sa cause fût réservée à la connaissance de l''''empereur, j''''ai ordonné qu''''on le gardât jusqu''''à ce que je l''''envoyasse à César."}, {"numero": 22, "texto": "Agrippa dit à Festus: Je voudrais aussi entendre cet homme. Demain, répondit Festus, tu l''''entendras."}, {"numero": 23, "texto": "Le lendemain donc, Agrippa et Bérénice vinrent en grande pompe, et entrèrent dans le lieu de l''''audience avec les tribuns et les principaux de la ville. Sur l''''ordre de Festus, Paul fut amené."}, {"numero": 24, "texto": "Alors Festus dit: Roi Agrippa, et vous tous qui êtes présents avec nous, vous voyez cet homme au sujet duquel toute la multitude des Juifs s''''est adressée à moi, soit à Jérusalem, soit ici, en s''''écriant qu''''il ne devait plus vivre."}, {"numero": 25, "texto": "Pour moi, ayant reconnu qu''''il n''''a rien fait qui mérite la mort, et lui-même en ayant appelé à l''''empereur, j''''ai résolu de le faire partir."}, {"numero": 26, "texto": "Je n''''ai rien de certain à écrire à l''''empereur sur son compte; c''''est pourquoi je l''''ai fait paraître devant vous, et surtout devant toi, roi Agrippa, afin de savoir qu''''écrire, après qu''''il aura été examiné."}, {"numero": 27, "texto": "Car il me semble absurde d''''envoyer un prisonnier sans indiquer de quoi on l''''accuse."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 25, 'es', '[{"numero": 1, "texto": "FESTO pues, entrado en la provincia, tres días después subió de Cesarea á Jerusalem."}, {"numero": 2, "texto": "Y vinieron á él los príncipes de los sacerdotes y los principales de los Judíos contra Pablo; y le rogaron,"}, {"numero": 3, "texto": "Pidiendo gracia contra él, que le hiciese traer á Jerusalem, poniendo ellos asechanzas para matarle en el camino."}, {"numero": 4, "texto": "Mas Festo respondió, que Pablo estaba guardado en Cesarea, y que él mismo partiría presto."}, {"numero": 5, "texto": "Los que de vosotros pueden, dijo, desciendan juntamente; y si hay algún crimen en este varón, acúsenle."}, {"numero": 6, "texto": "Y deteniéndose entre ellos no más de ocho ó diez días, venido á Cesarea, el siguiente día se sentó en el tribunal, y mandó que Pablo fuese traído."}, {"numero": 7, "texto": "El cual venido, le rodearon los Judíos que habían venido de Jerusalem, poniendo contra Pablo muchas y graves acusaciones, las cuales no podían probar;"}, {"numero": 8, "texto": "Alegando él por su parte: Ni contra la ley de los Judíos, ni contra el templo, ni contra César he pecado en nada."}, {"numero": 9, "texto": "Mas Festo, queriendo congraciarse con los Judíos, respondiendo á Pablo, dijo: ¿Quieres subir á Jerusalem, y allá ser juzgado de estas cosas delante de mí?"}, {"numero": 10, "texto": "Y Pablo dijo: Ante el tribunal de César estoy, donde conviene que sea juzgado. A los Judíos no he hecho injuria ninguna, como tú sabes muy bien."}, {"numero": 11, "texto": "Porque si alguna injuria, ó cosa alguna digna de muerte he hecho, no rehuso morir; mas si nada hay de las cosas de que éstos me acusan, nadie puede darme á ellos. A César apelo."}, {"numero": 12, "texto": "Entonces Festo, habiendo hablado con el consejo, respondió: ¿A César has apelado? á César irás."}, {"numero": 13, "texto": "Y pasados algunos días, el rey Agripa y Bernice vinieron á Cesarea á saludar á Festo."}, {"numero": 14, "texto": "Y como estuvieron allí muchos días, Festo declaró la causa de Pablo al rey, diciendo: Un hombre ha sido dejado preso por Félix,"}, {"numero": 15, "texto": "Sobre el cual, cuando fuí á Jerusalem, vinieron á mí los príncipes de los sacerdotes y los ancianos de los Judíos, pidiendo condenación contra él:"}, {"numero": 16, "texto": "A los cuales respondí, no ser costumbre de los Romanos dar alguno á la muerte antes que el que es acusado tenga presentes sus acusadores, y haya lugar de defenderse de la acusación."}, {"numero": 17, "texto": "Así que, habiendo venido ellos juntos acá, sin ninguna dilación, al día siguiente, sentado en el tribunal, mandé traer al hombre;"}, {"numero": 18, "texto": "Y estando presentes los acusadores, ningún cargo produjeron de los que yo sospechaba:"}, {"numero": 19, "texto": "Solamente tenían contra él ciertas cuestiones acerca de su superstición, y de un cierto Jesús, difunto, el cual Pablo afirmaba que estaba vivo."}, {"numero": 20, "texto": "Y yo, dudando en cuestión semejante, dije, si quería ir á Jerusalem, y allá ser juzgado de estas cosas."}, {"numero": 21, "texto": "Mas apelando Pablo á ser guardado al conocimiento de Augusto, mandé que le guardasen hasta que le enviara á César."}, {"numero": 22, "texto": "Entonces Agripa dijo á Festo: Yo también quisiera oir á ese hombre. Y él dijo: Mañana le oirás."}, {"numero": 23, "texto": "Y al otro día, viniendo Agripa y Bernice con mucho aparato, y entrando en la audiencia con los tribunos y principales hombres de la ciudad, por mandato de Festo, fué traído Pablo."}, {"numero": 24, "texto": "Entonces Festo dijo: Rey Agripa, y todos los varones que estáis aquí juntos con nosotros: veis á éste, por el cual toda la multitud de los Judíos me ha demandado en Jerusalem y aquí, dando voces que no conviene que viva más;"}, {"numero": 25, "texto": "Mas yo, hallando que ninguna cosa digna de muerte ha hecho, y él mismo apelando á Augusto, he determinado enviarle:"}, {"numero": 26, "texto": "Del cual no tengo cosa cierta que escriba al señor; por lo que le he sacado á vosotros, y mayormente á tí, oh rey Agripa, para que hecha información, tenga yo qué escribir."}, {"numero": 27, "texto": "Porque fuera de razón me parece enviar un preso, y no informar de las causas."}]'::jsonb, 'Reina-Valera 1909')
